Object.assign(window.__TXT,{"7500": "二诊疏泄肺邪，咳仍不减，痰气带秽。脉大。风邪与浊交蒸，肺胃热郁。厥阴之病，在藏为肝，在色为苍，而风气通肝，所以痰带青绿也。", "7501": "四诊痰色仍带青绿，心中空豁。脉象虚细，舌红苔心霉黑。痰热上盛，真水下虚。再上下分治。", "7502": "孙（孩）咳嗽甚则呕吐。脉濡滑，舌白。童质泄泻之后，脾运不及，生痰聚湿。复感暑风，邪与痰合，肺胃因而失降。宜降宜下。", "7503": "二诊用三拗汤以搜太阴深伏之寒，咳嗽大退。然脉形仍然沉细。不入虎穴，焉得虎子。", "7504": "四诊搜散太阴伏寒，咳嗽渐定。然三日来不寒而热，汗不畅达。脉数，右寸关独大。此外感新邪，与本病两途。拟用疏泄，不致引动伏气为上。", "7505": "马（左）寒束于外，热伏于中，咳嗽痰黄。脉形滑大，拟辛温寒合方。", "7506": "孙（左）咳嗽已退，然肺气一时难复，有无之间，尚带微呛，时或耳鸣头痛，咽中火冲。脉细虚软。良以金令不行，木邪易动。补其不足，此时正属机缘也，仿介宾金水六君法", "7507": "贾（左）大失血后，瘀血散入肺络，咳嗽凛寒发热，腹满作痛。脉象细弦。病实本虚，恐传入损途。", "7508": "陆（右）咽痒呛咳，日久不止，屡次见红，甚至盈口。今血虽暂定，左卧咽痒气冲，暮热少寐。脉细弦微数。肝火内烁，阴分日亏，阳气偏亢。金水并调，参以滋肝。", "7509": "萧（左）久咳曾经见红，两月前吐血盈碗。今血虽止住，而咳嗽暮甚，必致呕吐而咳方减，音塞不扬。脉形细数。经云、胃咳之状，咳而呕。良由肺肾并伤，中气亦损，损而难复，不可不防。", "7510": "唐（左）咳嗽半载不愈，咳则火升轰热，曾经见红。脉形虚细。不能收摄，其标在上，其本在下。拟金水双调法。", "7511": "二诊火升轰然已定，咳嗽略减。然每晨必咳尽稠痰，方得舒畅。脉象虚细。肾虚液炼成痰，上阻肺降。再作缓兵之计。", "7512": "四诊咳虽递减，而每至清晨，其咳必甚，寐则口干咽燥。脉形濡细苔黄中心浊腻。阴虚于下，痰甚于上。拟和阴清金，兼化痰热。", "7513": "三诊清肺气而化燥风，天时寒暄，封固不密，咳嗽转甚。脉形虚细，舌红苔糙。阴分亏损，不问可知。宜舍其标而治其本。", "7514": "张（左）哮喘多年，肺伤吐血，渐至咳嗽痰多，痰色黄稠，兼带青绿，有时腹满，运化迟钝。脉形濡细，左部带涩。肺胃并亏，而湿滞中州。且作缓兵之计。", "7515": "二诊痰饮凭凌于上，肾阴亏损于下，饮聚则成痰，阴虚则生热，热痰交蒸，所以咳血频来，痰黄青绿，热蒸痰郁，痰带臭秽。脉细濡数。腹中不和。将成肺痿重症，再作缓兵之计。", "7516": "沈（左）咳嗽不时带血，缠绵数载，肺肾久虚。兹以感受风温，咳遂增剧。今身热已退，而每至寅卯之交，辄咽痒咳甚，口渴咽干，舌燥痰稠厚，纳少胃呆。脉形虚细，舌红苔糙。风邪虽解，而肺肾更虚，遂致冲阳挟痰上逆，证属本原，与痰饮攸殊也。拟金水双调法。", "7517": "二诊寅卯之交，咽痒呛咳已止，然胃气呆钝。脉象濡弦。口燥咽干，犹未全定。肾阴不复，中气下根于肾，所以肾愈虚则胃愈弱也。", "7518": "丁（左）咳嗽时轻时重，肺气久伤，以致窃盗母气，脾土因而不振，大便不时溏泄。脉细，苔白少华。拟培土生金法。", "7519": "夏（左）湿热熏蒸不解，化火伤阴，虚火挟浊上炎，咳嗽暮甚，痰色青绿，而其气甚秽。脉数，两关滑大，不能重按。清化不应勉拟壮水以制阳光，以希造化。", "7520": "某咳嗽日轻夜重，痰黄稠厚，便坚带黑。脉数，舌光。无非阴虚火炎，金水并损，惟痰厚而带黄色，胃中必有湿热留恋。再从清养之中，兼导湿热下行。", "7521": "陈（左）肝郁气滞，病从左胁作痛而起，加以火灸络热动血，屡进阴柔之药，阴分固赖以渐复，然湿热由此而生，发为浊症。湿热逗留，风邪外触，遂致咳嗽。先以燥药伤气，致气虚不能鼓舞旋运，饮食悉化为痰。又以柔药滋其阴，酸寒收涩，痰湿之气，尽行郁遏。以致痰带腥秽，色尽黄稠，黄为土色，是湿痰也今内热咳嗽，痰仍腥秽。脉数濡弦，左部虚弦，舌苔薄白而滑。此气阴两亏，而湿热逗留之象，从实变虚，从假变真，殊难措手。前人谓因虚致病者，补其虚而病自除，因病致虚者，去其病而阴自复。八年之病，虽有成例可遵，恐鞭长之莫及耳。拟导其湿热下行，而不涉戕伐，俾得熏蒸之焰息，即所以保其阴气之消耗也。", "7522": "左咳嗽痰红，痰气腥浊，内热连绵。脉数而滑。此痰热内迫，势成痈痿，鞭长莫及。", "7523": "又咳嗽痰秽吐血。脉象急数。湿热蒸腾伤肺，肺痿情形也。病在高年，难以许治。", "7524": "顾石泉肺感风邪，久恋不解，前月中旬作课熬夜，凉气复袭，卫气为邪所阻，以致阳气屈曲不舒，而为身热，热则痰湿尽行蒸动，营卫循环失度，以致寒热纷争，有如疟状。痰既阻遏，则浊气不能下降，清津不能上升，以致津乏来源，舌光口渴。痰湿熏蒸，以致溱溱汗出。胃为十二经之总司，主束筋骨而利机关，所以内经治痿有独取阳明之说。今湿痰蕴遏，阳明不主流利筋骨，所以两足忽然痿强。此皆未发气喘时之情形也。今咳嗽反止，而气喘难卧，冷汗直出，四肢厥冷。是肺气但主于出，而不能下纳，自然有此等一虚难挽之象。然所以致虚者喘也，其所以致喘者何哉。盖肺主右降，胃府居于肺下，肺胃之分，久为痰湿占踞之区，一朝而塞其右降之路，所以暴喘不止，而所吐之痰，反不若平日之多矣。一嗳则喘略松，即是胃实。丹溪云、气有余便是火。气火上逆，浊邪化燥，口起白腐矣。脉象无神，脱兆已著。至于治法，则李士材云、因虚致病者，当治虚其病可退，因病致虚者，当治病其虚可保。挥蚊掠汗，作此梦语以备商榷。", "7525": "右肾虚不克收藏，每至冬藏之令，辄发痰喘。去冬天暖之极，收藏不固，再以春令地气发泄，根气失于摄纳，喘呼不能坐卧。黑锡丹招纳肾阳，虽属中病，而肾阴久亏，不能胜任温纳，致虚阳上浮，脱帽露顶，唇焦颧红。六脉细涩，苔淡黄，心毛而糙。气不摄纳。有汗脱之虞。拟补肾阴以摄肾气。能否应手，恐难必也。", "7526": "左肾本空虚，闭藏不固，冬令气不收摄，燥气外袭，干咳无痰。去冬阳气升动，由咳而喘，不过行动气逆，片时即定，初未当太甚也。乃春分节令，阳气发泄已甚，肾气不能藏纳，气喘大剧。耳聋作胀，咽中如阻，二便不利，口渴咽干，形神消夺，偶有微痰咯吐，色带灰黑。脉细少情，舌红苔白干毛。冲阳挟龙相上逆，遂令肺气不能下通于肾，肾气不能仰吸肺气下行，所谓在肾为虚也。恐阳气泄越，再加汗出。勉拟交通肺肾，参以丸药入下，以免腻药壅滞胃口，即请商裁。", "7527": "二诊交通肺肾，丸药入下，耳聋转聪，小溲通利，气喘稍有休止之时。然仍口渴咽干，身体不能行动，动则依然喘甚。脉象细数少情，右尺尤觉细涩。其为根本空虚，不能摄纳，略见一斑。昨药进后，不觉滞闷，勉从前意扩充。但草木之功，未识能与造化争权否。", "7528": "陈（左）肺合皮毛，毫有空窍，风邪每易乘入，必得封固闭密，风邪不能侵犯。谁为之封，谁为之固哉，肾是也。经云、肾者主蛰，封藏之本，精之处也。则知精气闭蛰于内，表气封固于外，所以肾本空虚，往往一至秋冬，气不收藏，为咳为喘者多矣。今稍一感触，即觉伤风，表气不固已甚。肺在上主气之出，肾在下主气之纳，肾虚封藏不固，则肾气不能仰吸肺气下行，气少归纳，所以体稍运动，即觉气急。素有之痰饮，为冲气挟之而上，咽痒咳嗽，甚至见红。特是肾之阴虚，与肾之阳虚，皆令气不收藏。左脉弦大，且有数意，断无命阳不振，寒饮上泛，而脉不沉郁，转见弦大之理。所以脉大而左部为甚，以肝肾之脉皆居于左，其为肾阴虚不能收摄无疑。况所吐之痰，牵丝不断，并非水饮。饮之所以为痰者，热炼之也。仲景小青龙汤真武汤，为痰饮之要方。汤曰青龙，为其行水也。真武水神名，为其治水也。足见饮即水类，与痰浊绝不相同。下虚如此，断勿存观望之心，而使根蒂日近空乏。用介宾先生左归饮法。", "7529": "某痰喘劳碌，感寒触发，呀呷有声，胸膺先觉不舒而病作，其痰阻气坠，已非一日矣。阅苔满白，脉来沉弦。于法当宗小青龙加减。姑宗仲景之意，不拘其方，俾得肺气宣通，则痰自下降。", "7530": "右阴虚木郁，冲气挟痰水上升，左少腹烙热，则其气从下直上，头痛面红，咽中如阻，以少阳之脉循喉咙，而胆为肝之外府也。阳气逆上，阳络被损，渐致吐血频来，肢困力乏。然吐血屡发，则喘发转疏，以郁阳从血发泄，则冲逆之威稍平，亦属定理。脉濡弦，苔白质红。肝肾阴虚，为致病之源，冲阳逆上，为传病之地若作痰饮主治，则青龙苓桂真武等方，无一与症情恰合。惟有滋水养肝，摄纳肾阴，水不上泛，则痰即为津为液，不可不知。拟介宾左归饮加味。", "7531": "三疹用喻氏法初服甚验，再服气喘复甚，其喘时重时轻，经月已来，浊精自出。脉沉弦，右部虚软下。虚上实，用雷少逸法。", "7532": "过（左）喘之一证，在肺为实，在肾为虚此指气而言，非仅关于痰也。今痰多盈碗，喘咳声嘶，背脊恶寒，口腻不渴。脉象右部细弱而滞，左部弦大。良由气弱生痰，肝肾素亏之人，木失涵养，因于启蛰之时，气上升发，宿饮停痰，尽从上逆，肺降之道路蔽阻，出纳皆失其常。深恐其上愈实，其下愈虚，阴阳有离决之虞。夫痰浊水沫，皆属阴类，所以饮家有当以温药和之之例。然浊阴弥漫，断无颧红能食之理。则是肺欲其温。而肾欲其清也。拟辛温寒合方。", "7533": "邱（左）痰湿素盛，而年过花甲，肝肾日亏，木少滋涵，于一阳来复之后，骤然气喘，痰随气上，漉漉有声。其病在上，而其根在下，所以喘定之后，依然眩晕心悸，肢体倦乏，肝木之余威若此。下焦空乏，不足以涵养肝木，略见一斑。脉象左大少情，右濡细软。诚恐摄纳失职，复至暴厥。", "7534": "二诊补纳肝肾，症尚和平，然左脉仍觉弦搏。下焦空乏，根本之区，不易图复，理所宜然。", "7535": "三诊左脉稍敛，心悸眩晕俱减。再摄纳下焦。", "7536": "四诊脉象较前柔静，饮食亦复如常。虚能受补，当扬鞭再进。", "7537": "某肝肾素亏，脾土亦弱，水谷之气，生痰聚饮，饮阻肺下，气喘痰多盈碗。脉象沉弦，舌苔白腻。五饮中之支饮也。仲景云、饮家当以温药和之。仿此立方。", "7538": "侯（左）先感风寒，既饮火酒，寒热互阻于肺，痰饮因而上升，致肺气不能下通于肾。气喘痰鸣，胸次窒闷异常，卧著尤甚。脉象沉弦，左尺尚觉有神。尚非肾气不能仰吸肺气下行之劣症。时自汗出。拟开太阳之表。弄斧班门，即请主裁。", "7539": "陈向有痰饮，咳嗽痰多，习为常事。兹以感冒新风，肺气失肃，发热咳甚，兼以肝木郁结，风气通肝，肝木从而勃动，腹痛泄泻。此初起之情形也。乃热减痛止泻定，转见神志摸糊，喉有痰声，而不得吐，气喘不能著枕，四肢搐动，面色红亮，汗出溱溱。舌苔灰滞，而脉象濡滑。良由痰饮之邪，随外感所余之热，肝经郁勃之气，蒸腾而上，迷蒙清窍，阻塞肺气。清窍被蒙，则神机不运，而神识模糊。肺气阻塞，则出纳失常，而气喘不能著枕，肺气不能下通于肾，则肾气立见空虚，肾为封藏之本，肾虚则封固不密，而为汗出。本虚标实，恐成必败之局。勉拟扶正化痰，降胃纳肾即请商裁。", "7540": "又补泻兼施，上下兼顾，如油如珠之汗已止，神志稍清，痰出较多，而稠腻如胶，牵丝不断，汗虽止而不时懊烦。脉见歇止，舌苔浊腻灰滞。无形之气火，有形之浊痰，蕴聚胸中，肺出肾纳之道路，为之阻塞，肾气虽欲仰吸肺气下行，而无路可通。此时欲降肺气，莫如治痰。标实本虚，元气能否胜任，实非人事所能为也。勉再议方。", "7541": "某天下无倒行之水，因风而方倒行，人身无逆行之血，因火而即逆上。湿热有余，肝阳偏亢，肺胃之络。为阳气所触，遂致络损不固，吐血频来，时易汗出，阳气发泄太过，不言可喻。脉象弦，两关微滑，亦属火气有余之象。清养肺胃益水之上源，方可不涉呆滞而助湿生痰，特王道无近功耳。", "7542": "汪（右）幼时曾有血症，血膜已有破绽。去秋燥气加临，咳嗽不已，金气暗伤，不能制木，当一阳来复之际，厥阳从而上逆，失血满碗而来。数月之中或涌或夹带，竟无全止之时，胸中隐隐掣痛。脉象细弦，右部兼滑。良以厥阳逆冲，肺胃之络，为之激损，一时络难扃固，所以夹杂而不能净尽也。若不急急图治，深恐络之损处日甚，而致暴涌，不可不慎。", "7543": "俞（左）吐血四日不止，昨晚胸闷恶心，有似痧秽之象，非痧也，木旺而清肃不行，肺肝气逆故也。人身之津液，流布者即为清津，凝滞者即为痰湿，痰湿内阻，升降之机，不循常度，气火上逆，载血逆行，是失血之因于胃中寒湿，原属至理。特寒湿而致阻塞升降，甚至失血盈碗，则是非寻常之湿矣。可疑者，初无痞满等象，而此时转觉气阻脘痞，呃忒频频，连宵不寐。脉象细数不调，而右关独见弦滑。良由肝升太过，胃府之气，为之耸涌，不能通降，所以血之出于胃者，愈出愈多，浊之聚于胃者，愈聚愈满。自觉胸中有物窒塞，大便不行，九窍不和，皆属胃病。经云、六腑以通为补。前方专主通降者为此。拟方如左，以急降其胃气，总期呃止血止，方可续商。", "7544": "又吐血之症，或出于肺，或出于肝，各经不同。人身喉属肺，主气之出，咽属胃，主气之入，所以各经之血，其出于口也，莫不假道于胃，而溢于喉。今吐血九日不止，左脉并不浮露，病非肝肾而来。虽倾吐之时，足冷面赤，未始无龙相上越之象。然倾吐之时，气血紊乱，虽有见象，难为定凭。多饮多溲，其肺气能通调水道，下输膀胱，其病不由于肺可知。间有一二呛咳，亦由肝火上烁，木叩之而金偶鸣耳。下不由于肝肾，上不由于心肺，推诸两胁不舒。中脘自喜挫磨等象，则是病之由于肝胃，已可显见。良由平素郁结，郁则伤肝，木为火母，阳明胃府居肝之上，为多气多血之乡，肝郁而气火上浮，则阳明独当其冲，胃络损破，血即外溢。胃府以通为用，九日以来，所进实胃滞胃之品多，降胃通胃之物少，胃不降而独欲其气之与血皆从下行，不能也。于此而曰血无止法，医无确见，遂曰天也命也。岂理也哉。曰、前论未及于心，而不关心肺。何所见而与心无涉哉。夫心为君主，凡血出于心，断无成口之多，虽有不寐，则胃不和耳。世无伯乐，何必言马，子诚真伯乐也，言者谆谆，未识听者何如。", "7545": "某心中似有气冲，则咯吐全红。今血虽止住，而气冲未定。脉来弦大。肝火撼胃，胃气逆，血因之而上矣。", "7546": "祝（左）血仍不止，头胀少寐，吸气短促。脉象左弦。无非阳气上逆，载血妄行。还恐涌溢。", "7547": "顾（左）风温袭肺，由咳而致见红，至今时来时止。脉象浮芤。恐其复涌。", "7548": "顾（左）咽痛过食甘寒，风热内郁，激损肺络，由呛咳而致带红，痰稠而厚，颧红火升，血来每在清晨。脉象数大。宜泄膈热。", "7549": "顾（左）咳经数月，渐至吐血盈盆，至今仍然夹带。脉象细弦，舌红少苔。阴虚木火上凌，营络损破，而气火仍然不平。还恐暴涌。", "7550": "王（右）吐血大势虽定，痰中仍然带红，气冲呛咳。脉细弦而数。阴虚木火凌金，冲气从而上逆。拟育阴以制冲阳上逆之盛。", "7551": "二诊痰红已止，咳亦略减。脉细弦数稍缓。冲阳稍平，肺肾阴伤不复。再金水双调。", "7552": "陈（左）屡次失血，渐致呛咳咽痒，气从上升，而痰中时仍带红，痰稠而厚。脉细弦数。是肾水不足，木火上凌损肺，遂令络血外溢，血去阴伤，气不收摄，出纳因而失常。恐入损门。", "7553": "二诊血已止住，略能右卧然仍咽痒呛咳，气从上升。脉细弦数，气口独大。血去既多，肾阴安得不伤，然上焦定然未肃。再清其上。", "7554": "五诊清金润肺，暮夜呛咳已定，而每晨咳甚，痰不爽出，色带青绿，脉数内热。血去过多，阴伤难复，阳升凌犯肺金。拟育阴以平阳气之逆。", "7555": "王（左）水亏木旺，虚火上凌，咳嗽不已，吐血时止时来。冲阳逆上，咳甚则呕，以冲脉在下，而布散于胸中也。症入损门，何易言治。", "7556": "三诊咳嗽大退，腰酸稍减，脉亦渐和。然肺肾皆虚，何能遽复，调理之计，非旦夕间事也。诸宜自卫。", "7557": "五诊金水双调，脉症相安，惟胸次时觉窒闷。冲脉气逆，亦属阴亏所致。", "7558": "金类疟之后，湿热未清，蕴结膀胱。溲血两次，咳恋不止，旋即咯吐见红。今虽止住，咳嗽仍然未尽。脉濡微数。良由湿热熏蒸肺胃，遂致络损血溢。拟开肺气以导湿热下行。", "7559": "又咳嗽咯血之后，元气未复，阳虚肝旺，脐下漉漉鸣响，两目干涩。脉沉而弦，苔白而腻。膀胱之湿，为风所激，所以鼓动成声。宜分利水湿，参以养肝。", "7560": "钱（左）屡次失血，血止之后，神色淡白，动辄气逆带咳，大便溏行。脉形沉细。夫脾为统血之脏，以阳为运，脾阳不振，则统摄无权，血遂得而妄行矣。病久不复为损，损久不复为劳，恐涉不复之虞耳。", "7561": "左失血盈口而来，血止之后，腰背作酸，火时上升。脉象两关弦滑。此由中气不足，痰湿内阻，胆胃之气不能下降。宜调中降胃，而益肝肾。", "7562": "戴（左）吐血成盆成碗今虽大势已定，而仍气冲咽痒。脉形沉细，舌淡苔白。胃钝纳减据述临涌之际，四肢厥逆。良由感寒不解，与湿相合，脾阳遏郁，遂致统摄无权。还恐涌溢。", "7563": "尤（左）喘咳者久。兹则肺胃络损，血来如涌。脉气口浮弦。有涌溢之虞。", "7564": "孙（左）失血一症，由于阴虚阳亢者多，而此症血来盈口，继发痧疹，其风温迫损肺胃，显然可见。脉细而不耐重按。伏风未清，则新风易入。急宜微苦辛凉，以澈其根蒂。若漫投育阴补益，恐犯薛氏成劳之例不可不辨。", "7565": "右血之涌溢者已定。然咯吐犹然带红，色兼紫晦，离宫之物也。气逆较定，脉象亦略柔敛，种属转机之兆。无如心中仍有灼热之意，咳嗽随气而来，舌红苔白而糙。此由肝升太过，肺降无权。所恐血止之后，咳不得定，而缠入损门。拟清金平木，降气育阴。", "7566": "又清养肺胃，平肝降气，咳嗽稍减。然血室尚未扃，固痰中夹带粉红，热势虽退，心中尚觉热辣，纳食之后，仍复饥𩠎，寐中汗出。脉细软弱，而两寸动数。体稍转动，气辄上冲，大势较前虽称平定，而阳气犹升动不息。其上愈甚，其下愈虚，所以摄纳无权，肺降失职。非有情有质之物，不足以达其病所也。从前法进而扩充之。", "7567": "左痰饮而致咯血，中州痞满不舒，噫出腐气。脉象沉弦。此脾土为湿痰困乏，不能统血。恐损而难复。", "7568": "左肝肾素亏，分节之后，阳气上升，鼓击损络，络血外溢，以致吐血盈口而来。今血虽止住，而腰府作痛。此由血去之后，肝肾愈形空乏。脉象细弱，尤属不足之征。宜益肝肾而清肺胃。", "7569": "又腰痛稍减，脉象稍振。的是吐血之后，肝肾空虚。效方再为扩充。", "7570": "俞（左）失血之后，火升内热，而脐下自觉有形坚满。脉数细沉。足膝欠暖。此由气虚而脾不统摄，阳气不能转旋于下，则虚火尽越于上。将入损途。", "7571": "又腹偏左较舒，然结块未化。脉形濡细。太阴无旋运之权。效方出入主治。", "7572": "张（左）先自木火刑金吐血，继而火郁胸中，胃口刮痛，旋至木克土而脾虚发胀，甚至吐血频年迄无止期。良以脾土虚极，不能统摄，致谷气所生之血，渐长渐吐，所以吐血无止时，而亦并未冲溢也。兹以温助命火，致肝火逆上，血溢盈口，由此而脾土益衰，大便作泻。六脉细涩，按之无神，苔红黄糙露底。重地深入。勉拟仲圣柏叶汤意，合理中理阴两方，以备采择。", "7573": "左温邪两候，热迫阳明，屡投辛甘寒合方，大热甫定。而素体木旺阴虚，昨晚偶触怒火，遂致肝火逆冲，肺胃络损，今晨呕吐鲜血，竟有盈碗之多。胃与大肠，两相联续，所以呕吐之后，继以便血。今血虽暂定，而心中漾漾，尚有欲涌之势，寐则汗出。脉形左大，寸浮关弦尺涩，右部濡弱，气口带搏，舌干无津。皆由木火久郁，触之即发，以致急速之性，损络动血，阳浮阴弱，肾水不能滋涵，封藏因而不固，所以寐则汗出。中气下根于肾，肾水愈亏，则木火愈旺，而中气愈弱，所以胃呆少纳。病中变病，花甲之年，何堪经此一波再折也。勉与叔涛先生共议养肝滋肾，兼益水之上源，略参凉营收固。即请崇山先生裁夺。", "7574": "二诊养肝滋肾，木得水涵，气火之逆冲者已平，阳气之泄越者渐固，血未复来，汗出大减。舌边尖转润，然中心仍然干燥。胃为阳土，脏阴皆虚，胃液安得不耗，有气无液，胃气安得调和，所以胃纳仍然不旺，实与中气不振者迥然不同。脉左弦大，右部大而濡软。肾水肺津，肝阴胃液，一齐耗损，然胃府以通为用。再拟滋水养液，而择其不滞者投之。即请叔涛先生商进。", "7575": "五诊清津渐回，舌质润泽，寐醒燥渴亦定。然平素痰多，此届病后，咯吐之痰绝无仅有。今日形体恶寒，沉沉欲寐。脉濡微滑。良以谷气渐增，水谷之气，生痰酿浊，弥漫胸中，以致阳气不能流布，神机不能转运。前法参以化痰。留候商进。", "7576": "六诊痰稍爽利，神情略振，然胸次气郁不舒，前番呕血之始，亦由此而起。脉形右大，舌干少津。良以气分久郁，上焦不行，则下脘不通。拟开展上焦气化，参以甘凉救津。即请叔涛先生商进。", "7577": "某溢血之后，未及三日，即起咳嗽，晨汗不寐内热，渐至痰多盈碗，痰味带咸。脉细弱而数，左关微弦，尺中小涩。此血去太多，火来克金，肾本空虚，失于摄纳。恐延入损途。", "7578": "某血未复来，痛亦稍安，火之上升者，亦得稍平，脉两关略柔，不可不为起色。无如气口之脉，大于关部，咳嗽较血涌之时反觉增甚。昨日本已虑及。所以然者，都缘血溢之时，血多喉小，卒不得出，以致瘀血散入肺络之中，肺气逆而不降。恐由此而入损途。", "7579": "扬（左）努力损伤肺络，络血外溢，不时见红，左胁作痛，咽燥舌干。宜清养肺胃，以和脉络。", "7580": "脉细涩而沉，左关带弦。内伤重症，若得息心静养，或能带病支持。", "7581": "又养肝益肾，脉症相安，带下腰足酸弱，咯血凝厚，有时气冲作呛。肝肾阴虚，奇脉不固。仍守肝肾并调，兼固奇脉。", "7582": "朱（左）吐血频来，不时嗳噫，大便数日方行。未吐之先，觉胸腹作痛，既吐之后，其痛转定。脉濡而弦。踊跻损伤肝胃之络。拟降胃而除陈补新。", "7583": "严（左）性情躁急，肝经之气火上凌，吐血屡屡，气升呛咳。脉象细弦。气为血帅，降血尤当降气也。", "7584": "二诊熄肝降气，呛咳较平，脉亦略缓。此无根之木，上凌肺金。前法参以育阴。", "7585": "李（左）鼻衄盈碗而来。脉形弦大。此肝火积于内，风热袭于外，以致阳络损破，不能扃固。还恐有复涌之势。", "7586": "李（左）鼻衄如注。脉象弦大。肺胃风热内迫。恐致厥脱。", "7587": "朱（左）任重受伤，营血瘀滞，蓄而暴决，呕血盈盆，大便紫黑，由此面黄力乏，腹中结块。脉涩两关独弦。蓄者虽去，新者复瘀，势必复为呕下。临时汗脱，不可不虑。", "7588": "陈（左）肠红日久不止。脉细濡弱，而右关独觉弦滑。此风湿热袭入大肠营分，非沉阴苦降，不足以达肠中也。", "7589": "某便血四溅如筛。脉形浮大。此风邪袭入肠胃，所谓肠风是也。宜泄热化风。", "7590": "郑（左）阴有二窍，一窍通精，一窍通水，水窍开则精窍常闭。无梦而泄，二十余年，而起居如常。其兼证也，上则鼻红，下则便血。其脉也，滑而实。其苔也，白而腻。此皆湿热盛极，致湿扰精宫，渐至阴络内伤。经云、阴络伤则血内溢，血内溢则后血。其病虽殊其源则一。", "7591": "洪（左）肛门烙热稍退，然便血仍然不止。脉象细数。的是湿热损伤营分，阴络内伤。再拟养肝滋阴壮水。", "7592": "叶（右）向有肠红，春末夏初，渐觉肿胀，日来肠红大发，血出稀淡，脘痞腹胀，难于饮食。脉形沉细，苔白质淡。肝为藏血之海，脾为统血之帅，今脾阳不能统摄，所以血溢下注，脾难旋运。恐肿胀日甚。", "7593": "二诊用苍术理中，便血大减，而便泄腹痛，胸脘痞满气分攻撑，腹膨肤肿。脉沉细，苔淡白，脾稍统摄，而旋运无权，遂致肝木偏亢，气湿不能分化。前法再参以分化。", "7594": "四诊运土利湿，便血未来，而脘腹满胀，仍然不减，小溲不利，大便泄泻，两足厥逆。脉形沉细。肢体虚浮。阳气不能敷布，以致水湿之气，泛溢肌肤。再宣布五阳，以望转机。", "7595": "二诊尿血不止，尿管并不作痛。脉形细弱。肾虚湿热内袭，实少虚多之象也。", "7596": "四诊尿血渐减，脉亦稍缓。痛者为火，不痛者为虚。再益肾之阴。", "7597": "五诊尿血递减，尚未能止。脉象微数。肾虚而虚火内迫。再育阴泄热。", "7598": "左溲血已止，而脉象尚觉弦硬。的是肝肾两亏，不能固摄，湿热乘袭其地。再从壮水之中，参以坚阴。", "7599": "许（左）天气温和，头晕辄剧，曾经见红，知系火风。甘凉频进，以胃药治肝，火风虽得稍杀，而脾阳为之暗损，旋运不及，遂致胃中之水湿停留，胃脘痞阻，甚则呕吐。脉象沉弦。停饮之兆，久恐延膈。", "7600": "杨（左）停饮内阻，火被水抑，不能蒸变，以致谷食不化，涌吐而出。土为火子，命火不治，则脾土不运，大便频泄。脉沉细，右尺更甚。宜理中汤。", "7601": "虞（左）水饮停留，控之不出，攻之不行，刻下食入倒饱，中脘痞胀，汩汩作酸，欲吐不吐，小溲短少，便不畅行。脉象濡软。良由久病脾胃气虚，不能运旋，水谷之气，不能变化，清浊不克分渗。用介宾先生五君子煎，以补脾胃而振中阳，参分化清浊，以观动静。", "7602": "二诊温运脾胃，而分清浊痛胀不退，欲吐不吐，胸中有窒闷莫名之状，大便不行，小溲涩少。脉沉细微数，舌红前半少苔。停饮日聚于上，胃液日耗于下，攻之不行，执是之故。木为水子，用刚体柔，营液既虚，则木失涵养，横暴之气，挟痰攻冲。脾胃皆受其困。再养营液，参苦辛酸以制强肝，冀其气平而痰饮默化。", "7603": "四诊肝气挟饮内阻，吐出痰涎甚多。所有痰涎，当从涌出，而胸膈仍然不舒，噫出腐气。脉象濡弱。良由屡次挖之使呕，胃中之气阴安得不亏，谷气不能变化，酿为腐气。未可漫投消导，用金匮大半夏汤，以通补阳明，而推扬谷气，参重以镇逆，咸以软痞。", "7604": "朱（左）停饮感寒复发，由脘痛而致呕吐，间日必发，发则脘中不舒，或觉作痛，呕出涎水，方得暂舒。胃无通降之权，饮食因而递减，股肉因而消瘦。脉象沉弦，舌苔白腻，中心浮浊。水饮不化，阳气不能旋运。", "7605": "三诊呕吐暂定，而水气不化，中阳不旋，中脘作痛。脉沉细，苔白质腻。温理中阳，固是定局，然水饮盘踞，阳气何由得宣。再从温化之中，稍寓攻逐之意。", "7606": "六诊呕吐未作，胃纳渐增。然中脘时仍作痛，大便六日不行。脉行沉细。脾为阴土，主健运而恶湿，今水久停，则脾土不能运旋，腐气因而阻痹。当再通阳。", "7607": "毛向有肝气旧恙，秋季肢厥，胸闷头晕，有似发痧，盖气道闭塞，阳气上升，即肝木勃动之先声也。平复未久，忽复身热腹痛，右半胸腹尤甚，当脐坚硬跳动，缠绵已久，咳嗽痰多，经日盈碗。今痛势虽定，而遍右尚觉不舒，所最甚者，中宫窒塞，谷食难容，大便不解。六脉濡软，沉候俱弦，右关尤甚，寸细尺沉，左尺小涩。此肝木纵横，挟内伏之痰饮，乘于土位，肝脏居左，而土位居右，木既乘土，所以痛甚于右也。中脘属胃，胃为戊土，脐居一身之中，亦土位也，金匮当脐动气，有水邪干土之例，正与痰饮一层吻合。夫土中之木，木即气也，气乃无形之物，饮为有质之邪，事楚事齐，则是有形者急，无形者缓。欲治有形，可攻可下，可燥可劫，但可施之于壮实之躯，断难施之于尺脉小涩之体。今食喜暖热，舌苔薄白，而色淡质腻。长沙云、饮家当以温药和之差。饮为阴邪，阴霾闭塞，非阳光煦照，安能雾散云收。况胃为阳土，水谷至此，顷刻即消，吾身之一丹灶也。今气停于是，湿停于是，痰停于是，饮停于是，然则水谷之海，岂是停气停湿停痰停饮之所。特温以煦之，其气既虚，血亦不足，刚燥之品，未免伤阴。拟用长沙栝蒌薤白汤出入，取辛润滑利，以开胃阳。而辛温大热之品，另制为丸，飞渡上焦，免致伤液。药能应手，尚有可为，特气弱年高，胜负之数，不能预决耳。管窥所见，尚乞高正。", "7608": "二诊伐肝通阳，脐腹之痛大减，中脘痞胀略松，稍思纳谷，大便畅行，然每至食后，中州仍觉不舒。数日之间，先寒后热者再，以胆主开合，为肝之外府，藏病于内，府应于外，则开合为之失度，胆病实肝病也。高年久病，断无破泄之理。然食能知味，非无胃也，食入必胀，土中有木也，木在土中则有胃若无胃矣。胃府以通为用。又肝无补法，前人谓泻肝即所以补肝，则是破泄一层，未便过馁。今右关弦滑，尺脉较前稍起，左关仍弦，沉候尚觉有力。伐肝泻木，虽经病久，尚在急需。拟从辛通之中，参以化痰调气。正之。", "7609": "翁（媪）痰饮内阻，肺气失降，咳嗽痰多气逆，卧著尤甚，食入胀满。脉象沉弦，舌苔白腻。宜温开饮邪，用重药轻服法。", "7610": "陈（左）素体湿盛，日前感受风寒，致风在于上，湿袭于下，上为咳嗽，下为足肿。兹则寒湿之邪，蔓延及上中脘痞满，胸中作痛，中州格截，上焦之气，尽壅于上，不能下降。日来咳甚气升，不能著卧，痰多成块，肌肤带肿，面色黄浮。脉细沉弦，舌苔薄白。三焦升降之机，悉为寒痰所阻，深恐升降不通而喘甚致脱，不得不为预告也。勉拟开降上中，作背城之一战。", "7611": "陈（左）肺有伏寒，咳绵不止者已经两载，去秋复感凉燥，咳遂日剧，气逆不平，不能著枕。数日以来，更带中脘作痛，小腹胀满，大便六日不行。脉形弦滑，苔白口腻。此痰气交阻，土滞木郁，肝木从而不平。深恐元气难支。", "7612": "朱（左）停饮凝痰，聚于胃府，胃府之气，升多降少，五七日辄呕黏痰涎水，二便不利。脉象沉弦。夫痰之与津，木属同类，清气化、则随气布而上供，清气不化、则液滞为痰而中阻，气之化与不化，悉视脾阳之转运如何，所以金匮有饮家当以温药和之之例也。然刚燥之药，多服劫阴，攻逐之剂正虚难任，惟有分其清浊，使清津上升，浊液下降，虽难霍愈，或可减轻耳。", "7613": "王（左）昔肥今瘦，病发则吐呕痰水，倾盆而出，呕至竭尽，往往微呕而带出紫血。夫饮食不为肌肤，而凝聚痰水，及时而发，其为蓄饮略见一斑。惟是痰饮之证，都成于中气虚微，脾阳不运。夫既阳虚气弱，何至呕辄见红。若谓阳明为多气多血之乡，呕动胃络，而血从络溢，亦顷刻间耳，何至随动随出之血，而辄变紫瘀哉。先哲有言，人受气于水谷，水谷之气，流则为津为液，滞则为饮为痰，盖流者气化之流，滞者气化之滞也。尊体丰伟，断非阳虚之比，参诸脉象，左部柔和，右部沉弦而滑。此由肝木之气，失于条达，木郁则土滞，土滞而水湿不行，渐成蓄饮，呕则胃逆，胃逆则肝藏郁勃之气，挟火冲胃，胃络之血溢出，已经火烁，色即变瘀，此实饮病而兼木郁者也。主治之法金匮云、心下有支饮，小半夏汤主之。又云、呕吐心下痞，膈间有水，眩悸者，小半夏加茯苓汤主之。盖取半夏散结除湿，茯苓益脾消水，生姜利气止呕，今以此方为君。以半夏厚朴汤分其浊气下出而为之臣。参入橘皮疏胃，合以上诸药即寓二陈之意，而为之佐。气降即火降，参入沉香调和中气降气平肝，而为之使。二十剂后则于晚间服本方，清晨服香砂六君子丸三钱，以微顾其本。当否正之。", "7614": "钟（左）心下虚悸，脉细濡而右关滑，此由痰水聚于胸中，阴湿弥漫于下，则心阳浮越于上，长沙独得其旨，故玉函经中一则曰心下悸者为有水气，再则曰水停心下则心下悸。近医每以心营不足目之未知圣训耳。", "7615": "某胃有停饮，胃阳不展，至暮辄作呕吐。脉象沉弦。恐延反胃之证。", "7616": "李（右）中脘不舒，按之漉漉，于结聚之处自觉寒冷，肢厥头面畏风。脉象沉弦。此由寒饮停于胃府，阳气窒塞不宣，阳气所不到之处，即畏风厥逆之处也。症属停饮，饮家当以温药和之。", "7617": "刘（左）痰饮根深，脾阳不运，津液凝滞酿痰，阻于肺下发，则喘咳。肺气不降甲木上逆，眉棱骨痛。脉象沉细濡软。饮家本当以温药和之，但本质既亏，未便过投猛剂，疏理痰气，取其减轻，勿期霍愈可耳。", "7618": "王（左）久咳痰多，数日来中脘结聚有形，食入痞阻，痰喘气逆。脉象沉弦，舌苔淡白。此带病感寒。寒湿痰交阻肺胃。大节在迩，有喘脱之虞。用金匮桂枝加厚朴杏子汤。", "7619": "薛（左）迭经温化痰饮，咳逆已止，然脉象尚带沉弦。脾为生痰之源，以阳为运。再补其气而助其鼓舞运旋。", "7620": "某痰饮而致咯血，中州痞满不舒，噫出腐气。脉象沉弦。此脾土为湿痰困乏，不能统血。恐损而难复。", "7621": "某痰饮已久，向则每发必喘，兹则不时呕吐，吐后神始清爽。脉象沉弦。此饮邪泛逆，驾熟走轻，势难杜截，惟有相机行事而已。", "7622": "胡（左）脉缓有力，颇得充和，惟右关部稍见滑象，是得天独厚，痰湿亦属有余。大便常带溏行，是中气足以鼓舞，不能僭踞，与火衰脾泄迥殊。至于阳道不与，花甲之年，已不为病，而况古稀者乎。津液二字，俗每并称，殊不知浊中之清者，上升而为津，清中之浊者，下行而为液。寐醒辄觉口渴，然并不引饮，片刻即回，若以清津有亏，何以不饮而渴自解，亦何以除寐醒之余，并无燥渴之见象。盖湿随气化，卧则气闭而湿聚，阻遏清气，不能上升，虽有清津，无从供给，醒则气行湿散，浊者不阻，清者自得上行矣。宜补气运湿，以杜其湿盛生痰。痰热生风之渐，然古稀之年，阴分亦不能不预为之地。仿古匮药法上下分治。即请指正。", "7623": "王（左）经云、饮入于胃，游溢精气，上输于脾，脾气散津，上归于肺，通调水道，下输膀胱，水精四布，五经并行。此于后天生化之机，宛然如绘者也。脉象濡细，而右部软滑。其平时伏有痰饮，发必致喘，投金匮苓桂术甘汤，屡如鼓桴，是内饮治脾之主方，自必投之辄效。特辛温之品，久恐伤阴，则必有和平中正之方，为先事预防之计。窃维精神气血，所以奉生，其次则津与液焉。何为津，浊中之清而上升者也，何为液，清中之浊而下降者也。然津不自生，得气化而口鼻濡润，液不自降，得气化而水道宣通，气化者，足太阴脾气、手太阴肺气也。体丰则中虚，中虚则气弱，气弱则脾土少鼓旋之力，肺金乏清肃之权，于是而向之流布为津为液者，遂凝滞而酿湿为痰，隐匿于中，乘机而发。虽喘咳不过偶作，未必为目前之累，实足为后日之忧也。调理之策，维有补脾降胃，鼓动气机，使气得流化，则不治痰而痰默消，不理湿而湿胥化，经旨之上输于脾而归于肺者，即此意也。兹从外台茯苓汤六君资生等参合丸剂，当否政之。", "7624": "沈（左）向有痰饮，兹于春夏之交，神情委顿，形体恶寒，胃呆少纳。右脉濡滑，舌苔滑润。此由湿痰蕴阻，脾阳不能鼓舞，所以阳气敷布不周。以六君加味。", "7625": "二诊中虚湿痰内阻，缠绵日久，胃气既虚，胃阴亦损。脾为阴土，胃为阳土，阴土固非阳不运，阳土则非阴不和。今不纳不饥，恶心欲吐，痰黏而稠。脉细弦，右部较大于左，左部略觉细软，且有数意，舌少苔，中心光红。良由病久胃气不复，胃阴连类而虚，遂致阳明不和，失于通降。拟甘凉益胃法。", "7626": "师云、若浅视之，似人参益智半夏泻心橘皮竹茹之证，今舌见光红脉见弦数，胃阴之虚显然，故宜甘凉养胃矣。（正蒙志）", "7627": "吕（左）癖染紫霞，日久伤气，气弱不能输运，聚饮生痰，上阻肺降，咳嗽痰多盈碗。脉象沉弦。虽属饮象，每先干咳，然后痰多。肺金渐燥，将成痰火之症。", "7628": "二诊用石顽老人法，咳嗽痰多，尚复如是，寅卯为甚，甚则心烦汗出。脉象甚弦，而带微数。阴精不足于下，痰气凭凌于上，冲阳挟痰上升，所以寅卯为甚。然腻药难投，宜上下分治。", "7629": "某痰气交阻阳明，纳食中脘痞胀，每至病发，诸气闭郁，上不得吐，下不得便。脉象弦滑。口燥烦渴，火从气化，气由痰阻。宜化痰开郁。", "7630": "某肝肾空虚，不能藏纳，阴精未复，中气复虚，以致旋运无权。湿痰难运，阻于肺下，气逆短促。痰阻于上，湿趋于下，两胫为之肿胀。频进补肾镇纳之方，病不少退。良以归纳之药，不能化痰，肾欲纳而肺不降，殊多掣肘之处。如竟改投降肺化痰之剂，深恐开其上者，更虚其下。脉象虚弦，右部濡滑。正与石顽先生所云痰火之症吻合，深恐介于两大，不克制其滋蔓耳。", "7631": "金（右）抑郁伤肝，肝强土弱，胃失通降。食入胀满，漾漾欲吐，腹中偏右聚形，月事不行，往来寒热。脉细弦而数。胆为肝之外府，木旺太过，则少阳之机杼不转。宜平肝调气，参以散郁。", "7632": "金（左）先自木郁土中，中脘有形作胀。脾与胃以膜相连，胃土受侮，脾土亦虚，渐致腹笥胀大，肢肿面浮，目眦带黄，如是者已经数月，兹交立冬节令，忽然下利，澼澼不爽，脓血相杂，上则恶心呕吐，呕出亦带黑色，四肢厥逆。脉沉如伏。肝强土弱已极，肝为藏血之海，肝经之气纵横逆扰，则肝经之血，不克归藏有发厥之虞。金匮厥阴篇中每以苦辛酸合方，即师其法，能否应手，非敢知也。", "7633": "再诊前用金匮苦辛酸法，脓血已退，便利大减，卧得安眠，胃亦略起，胀势稍得宽松。而气仍下坠，呕痰仍黑，目畏火光，小溲红赤，舌干口燥，两手稍温，两足仍厥。脉稍起而细弦无力。阴虚木旺，气火尽越于外，经谓热胜则肿也。虽见转机，尚未足恃。拟养肝柔肝，以平气火，气行火平，治肿治胀之道，寓乎其中矣。", "7634": "三诊四肢转温，面肿大退，胀势亦减，上冲之气亦平，小溲渐畅。然便利仍然不止。昨日停药一天，今又脓血相杂。脉象细弦。肝强土弱，营不收摄，湿热蹈暇乘隙，更复伤营。再养血和营，兼清湿热。", "7635": "四诊改方参用白头翁汤，脓血大为减少，便利较疏，胀松呕退，痰色转白，略能进谷。然利仍不止，两足肿胀尤甚，有时恶心。脉象细弦。肝强土弱，湿热伤营，虽屡见转机，而于大局终无所济，不得不预告也。再泄脾胃湿热，参以分化。", "7636": "左情志久郁，肝木失疏。冲脉为肝之属，冲脉起于气街，夹脐上行，至胸中而散，以致气冲脘痞咽阻。姑舒郁结而苦辛降开。", "7637": "徐（右）情怀郁结，胸中之阳气，郁痹不舒，胸次窒塞不开，不纳不饥，耳胀头巅烙热，大便不行。脉细弦微滑。仿胸痹例治。", "7638": "金（右）情怀郁结，肝木失疏，以致肝阳冲侮胃土，中脘有形，不时呕吐，眩晕不寐。脉细弦，苔白质红。全是风木干土之象。拟两和肝胃法。", "7639": "再诊气分攻撑稍平，中脘聚形亦化，呕吐亦减，寐亦渐安，略能安谷。但胸中有时微痛，所进水谷，顷刻作酸，眩晕带下，脉两关俱弦。肝胃欲和未和。再从厥阴阳明主治。", "7640": "毕（左）抑郁伤肝，肝气纵横，木来克土，上吐下泻，有似痧气。如此严寒，何来痧秽，其为木土相仇，显然可见。匝月以来，腹中有形，不时攻筑肝脏郁怒冲突之气也。此时极宜舒郁，而失于调治，以致气滞腹满，脾土不能运旋，浊痰因而难化，遂令弥漫神机，神情呆钝。脉象沉郁，重取带弦，而尺中无力。深入险地不能言治。勉拟化痰以通神机，木旺正虚，无暇过问矣。", "7641": "张（右）胆为甲木，肝为乙木，胃为戊土，脾为己土，五行之中，木本土之所胜，人身内景，胆附于肝叶之内。惊动胆木，又以年迈正虚，不能制伏，遂致肝脏之气，亦随之而动。抑而下者为气，气克己土，则撑满不和，甚至便溏欲泄。浮而上者为阳，阳犯戊土，则呕吐痰涎，甚至有气逆行至巅，为酸为胀。脉象弦滑，按之少力，苔白质腻。此皆厥阳犯脾胃致病，胃中之浊，悉行泛动。若久缠不已，恐入衰惫之途。治之之法，补则恐滞而气壅，平肝又恐迂阔而远于事情，惟有先降其胃府，和其中气，能得呕止安谷再商。正之。", "7642": "左心中热辣，少腹有气上冲，至胸而散则尤甚。经云、冲脉者起于气街，并少阴之经，挟脐上行，至胸中而散。龙相不潜，冲脉不和，良有以也。", "7643": "二诊脉症相安，然中脘不时痞满，经络抽掣。脉细关弦。营血不足，肝阳冲侮胃土。再育阴熄肝，参以调气。", "7644": "倪（右）肝胃不和，挟痰内阻。中脘不舒，甚则呕吐痰涎。脉形弦滑，重按空虚。血虚胆火犯中。姑和中而泄胆木。", "7645": "二诊和中气，泄少阳，脉象相安。舌苔薄白，底质带红。痰多中脘不舒，迷沉欲寐，甚则呕吐，其痰更觉胶腻。胃为水谷之海，胃受谷气，则化津化气，以调和于五脏，洒陈于六腑也。西河抱痛，则木郁生火，木火扰中，则脘痞不舒，水谷之气，为火所炼，则不能化津化气，而反凝浊成痰，阳明遂失其通降之常，太阴亦失其清肃之令，所以呛咳痰多，咽中干毛也。伤寒六经中惟少阴有欲寐之条，既非肾阳虚而浊阴弥漫胸中，即是肾阴虚而真阴不能上潮于心矣，所以一则主以四逆，一则主以复脉也。姑循序进之。", "7646": "张（左）身热已退，而咽次仍然哽阻。脉象弦滑。还是痰气交滞。再为清化。", "7647": "康（右）木郁生火，肝火散越。内热日久不退，咽中热冲，头目昏晕。脉弦大而数，舌红无苔，满布裂纹。肝火灼烁，阴津日耗，水源有必尽之势。草木无情，恐难回情志之病。拟黄连阿胶汤以救厥少二阴之阴，而泻厥少二阴之火。", "7648": "胡（右）诸恙较前稍轻，而阳气化风，鼓动不熄，唇口蠕动，即颊车牵掣，舌强难言。左脉弦大，右脉濡细。夫脾胃开窍于口，唇为脾之华，阳明之脉，环口而交于人中。今肝风所犯部位，皆脾胃两经所辖之区。", "7649": "钟（左）少腹居中为冲脉，两旁属肝。少腹胀满，按之坚硬，大便旬日方得一解，坚燥异常。每至午后，先厥后热，气从上冲，冲则痰涎上涌，头痛苦厥，刻许方苏。脉细弦而数，舌红苔白少津，寐醒则口燥咽干。此由气质薄弱，水不涵木，冲气从而上逆，气火升动，则液炼成痰，所以痰升苦厥。恐瘛疭发痉。拟养肝之阴，柔肝之体，以平冲气。", "7650": "二诊大便通行，然冲气时仍上逆，气冲则中脘聚形，恶心痰涌，头痛发厥，厥则肢强不语，心中仍然明事，良久方苏，腹中烙热，饮食不思。脉形弦数，苔黄质红。冲气逆上，皆化为火，气火上升，煎熬津液，悉化为痰，所谓痰即有形之火也。拟直清气火，以望厥定胃开，再商调理。", "7651": "二诊大便未行，灼热依然不退，寅卯之交，体作振痉，而脉并不数。无非肝胆之火内炽，不得不暂排其势。", "7652": "五诊中脘不舒，两胁下胀满，妨碍饮食，不能馨进，气逆不平。脉象沉弦。此肝藏之气，挟痰阻胃，胃气不降，则肺气不能独向下行，所以气逆而如喘也。", "7653": "左病后自汗，咽中牵腻，有时火从上升，则肌肤灼热。脉数软滑。此由甲木与戊土不降，而乙木独升。恐损久不复。", "7654": "费统帅肾虚则生火，木燥则生风，水亏木旺，肝风鸱张，风乃阳化，故主上旋。阳明胃土，适当其冲，所以中脘不时作痛。木侮不已，胃土日虚，而风阳震撼，所以左乳下虚里穴动跃不平。肝风上旋至巅，所以头昏目重，一身如坐舟中。肝为藏血之海，肝脏既病，则荣血不和，遍体肌肤作麻。吾人脏腑阴阳，一升必配一降。肝、脏也，本主左升。胆腑也，本主右降。升者太过，则化火化风，降者太过，则生沦陷诸疾，必得升降控制，而后可以和平。今肝升太过，则胆降不及，胆木漂拔，所以决断无权，多疑妄恐，面色并不虚浮，而自觉面肿，阳气壅重于上故也。舌苔白腻，冷气从咽中出，以肝胆内寄相火，阳气升腾，龙相上逆，寒湿阴气，随风泛动。倘实以寒湿盛极，而致咽中冷气直冲，断无能食如平人之理。丹溪谓上升之气，自肝而出，中挟相火。夫邪火不能杀谷，而胃虚必求助于食，可知胃虚乃胃之阴液空虚，非胃之气虚也。脉象细弦而带微数，亦属阴虚阳亢之征，为今之计，惟有静药以滋水养肝，甘以补中，重以镇摄。阳气得潜，则阴气自收，盗汗亦自止也。特内因之症，不能急切图功耳。", "7655": "邪与痰合，咳愈不止。猝受惊恐，震动胆木，胆为肝之外府，附于肝叶之内，此响彼应，肝火上犯，致咳剧而吐秽痰。斯时当作痰治，导肝火湿热下行。乃漫进参耆壅补，肝火痰热，阻肺不出，如油入面，莫之能泄。咳热痰秽，经年以来，日就沉困，脐上有形动跃。夫脐上为太阴脾土部位，此时肺金久损，金水无由相生，炎上之火日炽，似非壮水滋其化源，不足以制其燎原之势。然水邪干犯土位，脐上如此悸动，稠腻之药，势难尝试。脉右寸小涩，关部带滑，尺部细沉，而左寸关俱弦，尺部微弱。病属肝火挟痰蒸肺，蔓延而至气阴皆虚，滋肾益肺，则碍于脾土，理湿化痰，则碍于肝木。勉拟益水之上源，而兼泄热化痰。请正。", "7656": "陈子岩向有肝阳，时发时止。兹则少腹胀硬，大腹胀满，中脘胀痛，势不可忍，恶心泛呕，其味甚酸，心胸𩠎杂，大便不行。脉象细弦而数，苔黄质腻。骨热皮寒，气逆短促。少腹居中为冲脉。两旁属肝。考冲脉部位，起于气街，夹脐上行，至胸中而散，足见下则少腹，上则胸脘，皆冲脉所辖之区。今冲气逆行，冲阳逆上，胃为中枢，适受其侮，所以为痛为𩠎杂为恶心，诸恙俱作矣。胆为肝之外府，为阴阳开合之枢纽，肝病则少阳甲木开合失常，为寒为热，似与外感不同。所虑者气冲不已，致肾气亦动，转成奔豚之候。兹议两和肝胃，参以镇逆。方备商裁。", "7657": "二诊两和肝胃，参以镇逆，中脘胀痛已止，恶心𩠎杂吞酸亦定。然大便未行，痰气欲降无由，遂致气窜入络，两季胁异常作痛，牵引腰膂背肋，不能转侧。更加烟体失瘾，气不运行，其势益甚，竟至发厥。幸吐出稠痰数口，方得稍定。脉象细弦，重按带滑。络气痹阻，恐其复厥。勉与荫棠先生同议逐痰通府宣络。非敢率尔，实逼处此也。方备商裁。", "7658": "三诊投剂后季胁腰膂痛止，大便一次甚畅，日前之所谓痛胀阻隔，快然若失，不可不为转机。惟气时上逆，甚至如喘，胸闷酸涎上泛，头昏眩晕，虽频频吐痰。自觉欲出未出者尚多。脉象弦滑而数，重按少力。络气之滞，虽得宣通，而木火不平，与浊痰相合，蒸腾于上，消烁阴津，所以舌苔黄掯干毛，恐起糜腐。拟清泄木火，化痰救津。留候荫棠兄裁夺。", "7659": "四诊清泄木火，化痰救津，颇能安寐。舌苔边尖较化，干毛转润，脉数较缓，神情略为振卓，但时带呛咳，咳则气从上升。两季胁吊痛，略闻食臭，辄增𩠎杂头晕。丹溪云、上升之气，自肝而出。经云、诸逆冲上，皆属于火。良由厥气纵横之余，余威尚盛遂至气化为火，逆犯肺金，消烁津液，其水源之不能涵养肝木，略见一斑。若肝胆之火，挟龙雷上逆，便是喘汗之局。兹与荫棠先生同议滋水养肝，兼泄气火。前人谓痰即有形之火，火即无形之痰，冀其火降，痰亦自化，然非易事也。", "7660": "五诊舌黄大化，润泽有津，口渴自减，渐能安谷。但气火不平，挟痰上逆，肺为华盖，适当其冲，频频呛咳，痰虽欲出，碍于两胁之痛，不能用力推送，致喘呼不宁，欲寐不得，神情烦懊。脉象细弦。咽中燥痛，一派气火升浮之象，非济之以水，不足以制其火。然壮水之品，无不腻滞，痰热阻隔，不能飞渡而下，经谓虚则补其母，肺金者，肾之母气也。拟益水之上源，仍参清泄气火，而化痰热。", "7661": "六诊益水之上源，参以化痰，胃纳渐起，诸恙和平。然时仍呛咳，咳嗽引动，气即上冲，咽中微痛。脉象细弦。肝经之气火升浮，遂致在上之肺气不降，在下之肾阴不摄。拟益肾水以涵肝木，使阴气收纳于下，略参化痰，使不涉呆滞。", "7662": "唐（右）湿痰素盛，每至春升之际，往往神情迷倦。平时精神不振，耳鸣如蝉。脉象细弦。虽有湿痰，而营分更虚，风阳上逆，所以舌心剥脱也。拟养营而不涉柔腻。", "7663": "孙（左）向有遗精，肾水空乏，肝阳上升，扰神则心悸，外越则为汗，上升则头眩耳鸣。脉象虚弦。非壮水不足以涵木也。", "7664": "程（右）肝阳上升不熄，眩晕目昏，四肢作酸。脉弦而滑。此肝风与湿相合，风主动摇，所以身如舟行也。", "7665": "徐（左）中脘之下，有形攻撑跳动，寤难成寐。脉象左弦。此由肝气抑郁，肝阳上扰。急宜开怀颐养，不可专恃药力。", "7666": "严（左）体丰湿痰素盛，熬夜劳神。阳不收藏，致肝阳挟痰上升。头昏眩晕，恶心欲呕，胸闷不舒。脉象糊滑，关部带弦，舌苔浊腻。痰火交炽。恐风旋不熄，而致发痉。", "7667": "张（右）产后月事不来，血虚火炽，春升之际，忽发呕吐，味带酸苦，口渴咽燥气从上升，少腹先满，中脘气冲。脉细弦少力。血不养肝，遂致冲气肝阳逆上。拟和肝胃之阴。", "7668": "二诊向有肝厥，肝气化火，劫烁阴津，致营液不能营养。遍身筋骨作痛，眩晕心悸耳鸣，颧红火升，热熏胸中，胸次窒闷，肾水不能上潮于心，时常倦睡。脉细弦尺涩。宜滋肾之液，以熄风木。", "7669": "三诊生气通天论曰、阳气者精则养神，柔则养筋。又曰、阳气者烦劳则张，精绝，辟积于夏，使人煎厥。内经极言阳火内燃，气血煎熬，阴不含抱，阳火浊炎，一时阴阳几离，遂为煎厥，经义如此。原属大概。今诊脉象细弦，左尺小涩，右尺不藏。病起于数年前，屡屡发厥，旋即经事迟行，甚至一年之中仅来两次，其阳气之吸灼，阴液之消耗，略见一斑。兹则肩背腰膂股腨皆痛，火时上升，心悸耳鸣头晕。据述操持烦劳，甚于平人。显由烦劳激动阳气，壮火食气，遂致阳明络空，风阳乘虚入络，营血不能荣养筋络，是失其柔则养筋之常也。心为阳，心之神为阳中之阳，然神机转运，则神气灵明，神机不运，则神气蒙昧，所以离必中虚，其足以转运阳神者，阴津而已矣。今风阳亢盛，阴津日亏，虽有阳神，而机枢不运，所以迷沉善寐，是失其精则养神之常也。舌苔或黄或白，或厚腻异常，有似阴虚之中，复夹湿邪为患。殊不知人必有胃，胃必有浊，浊随虚火升浮，舌苔自然变异，从可知浊乃假浊，虚乃真虚也。治之之法，惟有甘以益胃，滋肾祛热，以熄风木。然必安静勿劳，方能奏功，不可不知。", "7670": "杨（左）阴分久虚，下虚上实，风阳上逆，腹中极热，眩晕火升，精水不固。脉象细弦，尺部带涩。水亏木旺。宜介类潜伏阳气。", "7671": "吴（右）血虚木旺，肝阳上升。头胀眩晕，发则𩠎杂易饥，心神扰乱。脉濡细，关弦尺涩。养肝以和阳气。", "7672": "李（左）脉渐耐按。头晕似有漂浮之意。阳升不熄。当助其所以制伏阳气者。", "7673": "褚（右）体丰多湿，湿盛生痰，痰在胸脘，甚则呕吐。吾人肝胆表里相应，肝上升则化心营，胆下降则化相火，胃居于中，为升降之中道，胆宜降，胃亦宜降。今胃中为痰气所阻，胃气不能通降，则胆木之气不能独向下行，于是但有肝之升，而无胆之降，遂成一有升无降之局，所以一身如坐舟中，有似虚空提起，目常带赤，即是胆中之气火，挟命阳浮逆于上也。脉象弦滑。为中风之根。所进一派黏腻阴柔之药，是抱薪而救火也。吾见愈者亦罕矣。", "7674": "又脉稍柔缓，躯体之升浮荡漾，亦减于前。水不涵木，固令阳气上升，殊不知胃胆不降，亦能使之上逆。药既应手，无庸更章。", "7675": "某由脘胁阻窒，而致火冲不寐，肌肤发疹，面目带肿。脉细弦滑，此肝火挟痰内阻，水火升降之道不通，坎离不相交济。宜清气化痰。", "7676": "凌（右）便血之后，血虚不复，肝阳上僭。眩晕心悸，面浮肢肿，带下连绵，经事涩少。一派内亏见证。拟养肝熄肝，兼摄奇脉。", "7677": "虞（左）自幼风痰入络，每至发痉，辄呕出痰涎而愈。兹当一阳来复，肝阳暴升，肝气横逆，发痉之后，气撑脘痛呕恶。风木干犯胃土，胃土不能下降，肝经之气，渐化为火。以致发热头胀，连宵不能交睫，口渴欲饮，大便不行。脉细弦数，舌红苔白浮糙，中心带灰。木犯胃而胃阴暗伤之象。恐复致厥。拟甘凉益胃，参以平木。", "7678": "王（右）向有痰饮，兹则心悸不宁，遍身筋脉动跃，背脊寒冷，渐即汗出。脉象弦滑，舌胖苔腻。此肝阴不足，脾胃湿痰悉随肝阳鼓舞，君火为水气所干，以致摇撼震动。无性命之忧，有频年之累。", "7679": "高（右）两和肝胃之阴，肃肺以通肠痹，肺与大肠本相表里，清肃之令一行，府气自然通降，所以药进之后，如鼓应桴，大便即解。甘以养胃，阳土得和，风木之气，不能动辄摇撼，所以烦𩠎之状已定，身热退清，面红赤转淡。脉弦大转柔，舌苔浮腐顿化。惟不易酣寐，而易汗出，还是阳不藏敛之兆。其为伏邪之后，肝胃阴伤，可谓毫发不爽矣。若踵余邪蕴湿论治，则阴愈伤而热愈甚，热愈甚则邪愈不敢撤，真有不堪设想者。今药既平反应验，无庸再事更章。方草正之。", "7680": "杨（左）向有肝阳，迩来神气不能自持，言语错杂，健忘善悲。脉弦虚大，右部歇止。此心肾交亏，水火不能交接。八秩大年，何敢言治。", "7681": "蒋（右）左腹向有积聚，每至一阳将复，辄心悸耳鸣，四肢烙热，一阴来复，诸病渐安。今咳逆虽止，四肢烙热如昨，食不馨增。肢体困乏。脉象沉涩，右关独弦。此由肝气失疏，肝阳逆犯阳气未能遽敛。拟和中醒胃，兼养肝阴，阴生则阳自长也。", "7682": "左偏枯三载，饮食如常。五六日前大拇指忽发疔疮，阳明湿热之盛，略见一斑。前晚恶热，欲去衣被，昨晨复食面包，胃气壅实，甲木之气，不能下降，遂致肝风挟痰上升，清窍为之蒙闭，神昏不语，喉有痰声，脘腹饱满，头汗溱溱，而汗有秽气。脉象弦滑，舌红苔黄，中心霉黑。唇口蠕动。痰火蒙闭于内，湿热熏蒸于上。恐蒙闭不开，风阳震动，而致厥脱，勉拟清泄痰火，芳开蒙闭。请商。", "7683": "右营阴不足，肝火风上旋。由头痛而至口眼㖞斜，舌强言謇。脉细弦数。此风火蒸痰，袭入少阳阳明之络。拟化痰平肝泄热。", "7684": "王（左）向有肝阳，一阳来复之时，加以情怀怫郁，以致甲木不降，乙木勃升，心悸不寐，肉𥆧筋惕，肢震头摇。脉细而沉取弦搏，苔浊厚腻。此由肝火风震撼，津液凝痰，痰转化热，遂与风火彼此相煽，而有莫御之势矣。拟化痰熄风，参以宁神镇肝。", "7685": "二诊化痰熄肝，脉证相安。然仍筋惕肉𥆧，悸眩不寐。脉象弦滑，舌苔腻浊。痰火风鼓旋不熄。再化痰熄肝。", "7686": "某向有肝气，不时胀满。兹则头眩旋晕，心悸火升不寐，痰多𩠎杂。脉细而沉取带滑。此气弱生痰，胆胃不降，肝木独升。欲平其肝，当降其胆，欲降其胆，当降其胃，欲降其胃，当化其痰。", "7687": "马（右）疏肝化痰，脘胁痛胀未止，竟至神识迷乱，两手引动，频转矢气，大便不行。良由气滞不宣，浊痰因而弥漫，神机被阻，胆阳上逆，风阳勃动，有昏痉喘厥之虞。疏府涤痰，势不容缓。脉象弦滑而濡。病实正虚，恐成必败之局，然人力不能不尽，非敢孟浪，聊竭割股之忱。录方备商，立候荫棠先生正是。（首案未录）", "7688": "三诊投剂之后，呕出黏痰，继以畅解，皆属胶黏稠腻之物，其为痰积下达，确然可征。蒙阻由此得开，神识迷乱大退，脘胁胀痛亦松。但时多倦寐遍身作痛，背腧尤甚。脉象弦滑舌苔满布白腻，渴不欲饮，还是浊痰弥漫之象。年及古稀，正虚病实，虽得转机，恐不足恃。再拟化痰而宣泄气火之郁，以防化燥生风。方备商裁，并候荫棠兄正是。", "7689": "四诊疏气之滞，泄火之郁，而开浊痰，神情清爽，迷睡较退，痰吐爽利大便续解，脘胁胀痛全定。右脉稍觉有力，舌苔大化，皆转机之象。但火时上升，升则两颧红赤，遍身作痛，有时恶心。良由痰积虽达，而胃土少降，阳明脉络失和，胆阳从而上逆。再降胆胃而化痰浊。", "7690": "五诊神情慧爽，火升较平，恶心亦止。然时带呛咳，咳则胸膺背肋牵掣作痛，头旋眩晕，目不能开，胸中似有冷物搏聚。脉象弦滑，舌苔前半已化，根尚厚腻。还是痰邪未清，甲木少降，肝风上旋，络气阻痹。再拟化痰熄肝宣络。", "7691": "六诊遍身掣痛已定，眩晕大减，渐能安谷。惟胸中时仍窒闷，呛咳痰多。脉象弦滑。胆胃之气下降，则风阳自平，痰气之郁渐开，则脉络自和。然肺胃之间，痰饮不能遽澈，所以咳逆痰多。再和中降气化痰。", "7692": "郭（右）清化痰热，育阴和阳，神渐守舍，怔悸大减，𩠎杂亦定。虚里仍然动跃。脉弦滑而软。阳明脉络空虚，厥阳上扰未熄。前法出入。", "7693": "严（右）腹时㽲痛，眩晕头昏，心中跳荡，带下舌光，脉象虚弦。此液虚不能涵养，致阳气升腾不熄。拟平肝而熄风木。", "7694": "龚（右）热气随处攻注，经脉跳动，脘胁皮肤板滞。木旺阳升气滞。再和阴以涵肝木，兼化热痰。", "7695": "二诊大便解出黏痰，烦扰顿然宁静，恶心口渴亦止。乃日晡又复烦渴，吮乳口中虽热，却不甚盛，涕泪俱无，头摇不定，面有青色。舌光无苔，脉象细软。胸中之结痰稍开，而脾气胃阴并虚，肝风因而震动。慢惊情形，仍在险境。姑养肺胃之阴，而培脾土以熄肝木。", "7696": "六诊惊搐已定，面青色续退，然犹涕泪不下。舌上转润，而上下唇犹然干燥。脉象细数。其为阴虚气弱，木旺生风，显然可见。既略转机，自宜从效方扩充。", "7697": "八诊扶正气以御肝木，益荣血以涵肝木，风木已平，惊搐自不复发，津液回而涕泪下，面青既退，脉亦柔缓。足见慢惊究属虚症，然又有阳衰阴弱之辨耳。", "7698": "右调气熄肝，眩晕不定。左脉弦大，尺部空虚。下虚上实。拟介类潜阳，为进一层治。", "7699": "钱（左）肾水不足，不能涵养肝木，肝经之气，横扰不平，则腹胀胸闷。在下则为气，上旋则为风，风阳上旋，则为眩晕。今大势虽定，而根柢不除，牙龈胀痛，亦属风阳阻于胃络也。脉象细弦。宜为柔养。", "7700": "叶（右）但寒不热，渐致腹满作痛，头昏目眩，饮食少思。脉弱而弦。气滞于下，阳升于上。宜调气熄肝。", "7701": "茅（右）脉细濡而右关带滑。叠进育阴潜阳，昏晕依然不定，有时汩汩作酸。良以清津为阳气所炼，渐欲成痰，致浊阻清位，所以昏晕不能定也。再以退为进。", "7702": "金（右）眩晕呕吐，舌本牵强，脉滑苔腻，火升右太阳作痛。肝阳挟痰上升。宜化痰熄肝。", "7703": "杨（左）白疹已化，热亦渐轻。而四肢欠温，痰多频咳，有时自觉热冲至巅，则头昏眩晕。脉象沉弦。良由痰饮内阻，阳气不克宣通，所谓无痰不作眩也。拟化痰以通阳气。", "7704": "六诊痰多咳逆气喘。脉象沉弦，左部细弱。脾胃肾皆虚，气不收摄。拟摄纳阳气。", "7705": "林（右）营血久亏，肝木失养，风阳大动，窜入经络，遍身酸楚。兹当风木司令，阳气弛张，叠次痉厥，厥回而神识昏迷。脉细涩如丝。深有阴阳相决之虞，未可视为惯常也。拟护神潜阳法。备请商定。", "7706": "三诊痉厥之后，身发白疹，是病久中虚之极也。屡次发热，脉象虚微，阴不足而阳有余。当气阴兼顾。", "7707": "蒋（右）体质素亏，春升之际，风阳大动，以致骤然痉厥。甲木不能下降，胆无决断之权，惊悸善恐，有形之痰，为之鼓动，所以脉弦而滑，舌红而苔黄浊也。拟化痰宁神，潜阳熄肝。", "7708": "唐（右）每至心悸，辄气冲至咽喉，呛咳呕吐，顿即色夺出汗，有欲厥之状。发厥之后，耳鸣头晕，脉尺涩关弦。此厥阳上升太过。拟调气而潜伏之。", "7709": "某酒性既升且热，醉酒太过，复当君火行令之时，心火肝阳，为之鼓动，致火风热尽行内闭，神昏口噤不语，甚则搐搦发痉。虽痉定而仍昏闭不省，手足扬掷，目赤颧红便闭。脉数弦大。火风热内炽，此厥症也，急险之至。急应泄热降火，兼通络窍。", "7710": "某素有痰喘旧证，前以辛温开饮，极著成效。又以劳勚感邪，于九日前忽先寒后热，继但热不寒，刻今热势虽衰，而淋淋汗出，欲寐未寐之际，讝如梦语，肢搐引动，咽中作痛，喉关偏右白糜星布。脉数濡滑，舌绛赤，苔黄罩灰。此由邪湿内蒸，所有浊痰，悉化为火，致肺胃之阴津消灼。阴分愈亏，则火热愈炽，有虚脱之虞。勉拟泄热和阴一法。谋事在人，成事在天。", "7711": "雷（左）脾肾两亏，饮食生痰，痰阻为喘者久。兹值春升之际，痰凭木火之势而化为热，以致竟夜不能交睫。脉左尺不藏，苔黄舌红。龙相亦动。拟潜阳和阴，参以苦泄。", "7712": "左平素痰多，交夏君火行令，火与痰合，遂致弥漫心窍，言语不能自如。今神识虽清，而健忘胃钝，左关脉滑。此痰阻于中，心肾不相交通。欲交心肾，当祛浊痰。", "7713": "某中虚挟痰，痰热化风，撼扰神舍。心中跳动，则火从上升。脉象虚弦。填补其下，以涵濡肝木，碍于在上之痰热，而利不胜弊。惟介类以潜之。", "7714": "又补中以御木，育阴以柔肝，神呆如昨，时多恐怖，心中自觉窒而不开。脉左寸沉滞，关部细弦，尺中小涩，右寸滑而濡软，关部滑而带弦，尺脉较劲。皆中气脏阴有亏，挟痰内蔽之象。夫既亏矣，何复生痰。盖肝禀将军之性，其刚柔之用，正施之则主一身之生发，逆施之则为火风之厉阶。今当产后未满百日，血虚气弱，肝木偏亢，遂为虚里跳动。厥阳上旋，则清津浊液，悉为阳气所炼，凝结成痰。心为离火，火本下降，与水相交者也。今阳气且从上旋，心火何能独降，心胸清旷之区，转为阳火燔蒸之地，窒闷之由实在于此。譬如酷暑之时，独居斗室，虽旷达之士，亦且闷不能堪，所谓闷者，皆阳之闷也。夫至阳闷于中，灼液成痰，神明为痰火所扰，便是不能自主之局。所最难者，阳可以熄，火可以降，痰可以豁，而三者之药，无不戕贼元气。今以水亏不能涵濡，气虚不能制伏，然后有肝阳之升，痰热之蔽。消之降之，前者未定，后者又来。若补之涵之，则远水不能济急也。大药之似乎虚设者为此。兹从补养之中，参入治痰之品，标本并顾。未识勃然欲发之阳，能得渐平否。备正。", "7715": "又每至动作，虚里辄大跳动，内经谓其动应衣，宗气泄也。病之著眼处，当在于此，所以前诊脉细弦而并不洪大，与病相应，直认其为中气虚而不能制木，致魂不安谧，神不守舍。欲遵经训，似非补其中气，交其心神不可也。乃投之罔效，其中必有曲折。此次偶服攻劫之方，大吐大下。今诊右部之脉转滑微大，寸脉依然细滞。因思肝用在左在于胠胁，肝郁之极，气结不行，由胠胁而蔓及虚里，气郁则痰滞，滞则机窍不宣，是神机不运，在乎痰之多寡，痰踞机窍之要地，是以阻神明、乱魂魄。然而吐下之后，神志而未灵爽者，盖肠胃直行之道，积痰虽一扫而空，至窍络纡回之处，非郁开气行，痰不得动也。今才经吐下，理应休息数日，乘此以四七汤开其郁结，参入芳香以宣窍络。旬日之后，再用攻法。即请裁夺行之。", "7716": "方（左）头胀眩晕火升，频带燥渴，痰多脉滑此痰湿化火生风，与阴虚阳亢者有间也。", "7717": "左昨进化痰护神，多言呼唱，较昨稍定，然犹未能寐，腹中气满不舒。脉两关弦滑。良以肝火挟痰内扰，肝经之气，亦散漫不平，心神为之摇撼。既得应手，再守前意出入。", "7718": "某痰火交炽，曾经糊乱。今神识虽清，而左脉弦大。肝胆之火，尚未宁静。", "7719": "顾（左）向有痰饮，兹感风温，先发咽痛，风化为火，与痰相合，以致痰火交炽，肺肾之气不能相通。气喘难卧，痰声漉漉，心胸烦闷异常，常欲露胸泄闷，两颧红赤。而脉象濡细，舌苔浮红罩霉。气阴已亏，而痰火独盛，恐难以草木为功。勉拟育阴化痰，以通肺肾。即请商裁。", "7720": "张（左）中脘渐舒，痰多脉滑。由湿生痰，由痰生火，由火生风，以知痰为火之本，风为火之媒。治病必求其本。", "7721": "某神情昏愦，言语无伦，唇朱兼紫。脉滑而弦。此痰火肝阳交炽。拟泄热化痰。", "7722": "江（右）怒火如狂，六脉弦数。肝火扰攘，心神为之不宁。拟护神化痰熄肝。", "7723": "某（右）头痛偏右，痰时带红。二者今虽暂安，然眩晕心悸，火从上逆。脉弦带滑。无非肝肾之阴精不足，而脾胃之痰湿有余，胆胃之气，不克下降，则肝脏之阳，上升太过。拟熄肝和阳。", "7724": "二诊寐得稍安，轰热亦减，然仍头偏作痛。左关脉大，还是阴涵不足，阳升有余。前法再参和阴。", "7725": "三诊略能就寐，而热气时从上冲。脉象细弦。阴分不足，阳气不潜。前法再进一筹。", "7726": "张（左）头痛眩晕。苔白厚腻，脉濡缓微滑。肝阳挟痰上腾。拟熄肝化痰。", "7727": "二诊化痰泄热，眩晕稍减未止。脉象细弦。经云、头痛巅疾，下虚上实。原因肾水内亏，阳气上冒。再拟育阴潜阳法。", "7728": "邵（右）头晕渐致作痛，痛引耳后，恶心欲吐。两关脉弦。少阳阳明不降也。", "7729": "刘（右）经云、真头痛，头痛甚，脑尽痛，手足寒至节，不治。头痛连脑一症，从来殊少专方。前诊脉象细沉，久按带弦。据述病剧之时，头脑苦痛，痛则遍身经络抽掣，数日渐退。夫脑为髓之海，病入骨髓，已属不可救药，何况乎苦痛之地，而在于髓之海乎。病及髓海，则虽疗治，尚苦无方，安有数日而能渐退之理乎。其所以如此者，必有至理存乎其中，在临症者未之深思耳。考十二经中，维太阳膀胱经为水府，其脉络脑。又痰与湿皆水类也，痰湿遏伏，则水寒而脉道不行，脑痛之由，实出于此。刻下头痛虽不甚发，而每晨辄心中泛泛漾漾，至午才得如常。盖卧则气闭，气闭则痰湿不行，清晨初起之时，正是痰湿欲行未行之际，阳气浮越于上，故体为之疲软，心胸为之不舒。夫营出于中焦。又中焦受气，取汁变化而赤，是为血。今中焦所受水谷之气，不化为血，而酿为痰，故未至七七之年，而经水断绝。拟药如下，即希高正。", "7730": "孙（右）头痛减而复盛。昨进清震汤以泄木火之势，痛势随退，大便亦行。无如脚膝腿股之间，随处刺痛。脉缓而关部仍弦。还是火风未熄，流窜经络犹恐上腾致变。拟清泄以锉其锋。", "7731": "王（左）始由太阳内伏寒邪，乘阳气发泄而动，头痛如破，甚至神情迷乱。幸松云先生随症施治，大势得平，经月以来，独胃气未能稍苏，浆粒全不入口。历投和中化湿、温理中阳、导浊下行诸法，于胃纳一边，无微不至，独胃气仍然不醒。今细察病情，除不食之外，惟苦头晕不能左转，吞酸恶心，中脘有气攻撑，腹中㽲痛。脉微数，右关带弦，尺中较柔略大，舌苔黄浊。此盖由头痛之余，肝木未平，胃土为之所侮，致阳明失通降之权。兹与松云先生议定，依前法参入理气平肝。当否即请正之。", "7732": "某（右）头痛如破，一转机于消风，再转机于升发。发者何，发其火之郁也。风以何据，龈肿是也。岂以消风之剂，始效而终不效，乃度其为火乎。非也。初次头痛，神识清灵，继而痛甚，时兼讝语。惟火足以乱我神明，风虽甚，不能扰我之方寸，经谓火郁者发之，升柴之所以敢于尝试也。幸皆应手。实堪相庆。特头痛虽定，而遍体游行作痛，若系血不濡经，则痛有定，痛势亦略缓，今游行甚速，还是风火之余威，窜入于络隧之间。脉数，重按细弦，轻取微浮，与所审证据，亦属相符。拟泄热祛风，以消余烬。", "7733": "钱（右）向有胃痛，不时举发，偏左腹硬，头痛右甚，甚则引及目痛。脉形尺涩。肝火风上旋。宜清以泄之。", "7734": "二诊脉弦尺涩。偏右头痛，引及目珠，稍涉辛劳，咽中燥痛。肝火风不熄。养不足之阴，泄独胜之热。", "7735": "二诊头痛减而少腹有气上冲，直抵咽喉，寤难成寐。脉洪大稍敛，而关脉仍弦。肝火风未能尽平，厥气从而附和。前法再参调气。", "7736": "右导火下行。寐得略安，而头痛仍盛，呕吐咳逆。脉细涩，左部带弦，无非阳气未能下潜。再反佐以进。", "7737": "孙（在）头痛在额为甚，鼻窍不利。右脉弦大。阴分素亏，外风引动内风。用选奇汤进退。", "7738": "某脉象沉弦。中脘有形作痛，此中阳不足，寒浊阻于胃府也。", "7739": "沈（右）中脘有形，食入痞阻。苔白罩霉，脉沉弦细。此痰气郁结胃中。当为宣通。", "7740": "二诊苔霉全化，中脘渐舒。然脉象尚带沉弦。宜肝胃两和，疏通痰气。", "7741": "杨（左）中脘作痛，每至呕吐，寒热交作。脉象关滑，而沉候濡缓。此饮停于内，遂致土滞木郁。难杜根株。", "7742": "某脉形细弱背腧作胀，中脘作痛不纳不饥。此由先天不足，气弱失运，运迟则生湿，气弱则生寒，寒湿交阻，宜乎其脘痛不纳矣。急则治标，宗此立方。", "7743": "洪（左）中脘作胀，而且剧痛，呕吐涎水。脉象沉弦。此寒饮停阻胃中。恐致痛厥。", "7744": "徐（左）中脘作痛，腹满气撑，便阻不爽。脉两关俱弦。厥气挟痰，阻于胃府，久则成膈。", "7745": "席（右）中脘作痛。脉形弦滑，独尺部濡细而沉。此由命火衰微，在下之蒸变无力，在上之痰气停留。遍体作酸，以胃病则不能束筋骨而利机关也。宜辛以通之。", "7746": "虞（右）木郁土中，中脘作痛，胃脘之间，时有烘热之象。脉细关弦。肝经之气，火冲侮胃土。急宜开展襟怀，使木气条达。", "7747": "二诊脘痛已止，胸闷呕吐亦减。两关脉弦。还是肝阳犯胃未平也。", "7748": "左胸痛脉弦，当舒气郁，用葛仙翁颠倒木金散法加减主治。", "7749": "钟（左）右胁作痛。脉象沉弦。饮悬胁下，脾肺之络在右也。", "7750": "二诊胁下之痛，仍然未定。左脉弦大，右关带滑。气湿郁阻不宣。再为宣通。", "7751": "阙（左）烟体痰浊素盛，痰湿下注，发为泻痢，痢止而痰湿不行，升降开合之机，皆为之阻，以致右胁作痛，痛势甚剧，按之坚硬有形，中脘板滞，不时呃忒，气坠欲便，而登圊又不果行。苔白罩霉，脉形濡细。此痰湿气三者互聚，脾肺之道路，阻隔不通，以致流行之气，欲升不能，欲降不得，所以痛甚不止矣。气浊既阻，中阳安能旋运，挟浊上逆，此呃之所由来也。在法当控逐痰涎，使之宣畅。然脉见濡细，正气已虚，病实正虚，深恐呃甚发厥，而致汗脱。拟疏通痰气，旋运中阳，以希万一。即请明哲商进。", "7752": "柳（右）腹痛脉沉。气寒而肝横也。", "7753": "二诊腹痛稍减，脉形沉细。前年大便解出长虫。良由木失条达，东方之生气，挟肠胃之湿热，郁而生虫矣。调气温中。参以劫虫。", "7754": "三诊脉症相安，但腹痛仍未全定。前法进退，以图徐愈。", "7755": "王（左）痛从少腹上冲，日久不止。脉细虚软。夫少腹两旁属肝，居中为冲脉冲脉布散胸中。今自下冲上，显属奇脉空虚，厥气肆扰也。", "7756": "沈（左）由胁痛而致吐下皆血，血去之后，络隧空虚，风阳入络，胸膺腰膂两胁皆痛，时或眩晕。脉象虚弦。宜育阴以熄肝，养营以和络。", "7757": "右腰府作痛。脉形沉细。肝肾虚而湿寒乘袭也。", "7758": "席（左）痛胀退而复甚，腰膂作酸，大便不调。痰湿之闭阻虽开，而肝肾之络暗损。宜舍标治本，而通和奇脉。", "7759": "二诊通和奇脉，脉症相安，惟腰府仍然作酸，大便涩滞营络不和。前法进退。", "7760": "三诊脉症相安，腰府作酸。还是络虚气滞。效方扩充。", "7761": "沈（右）脾虚木旺，木侮胃土。中脘作痛，甚则呕吐，大便时泻时止。脉左关弦。木郁土中，久恐延膈。", "7762": "陈（左）食入辄作呕吐。脉两关俱弦。肝阳冲侮胃土，久恐成膈。拟苦辛通降法。", "7763": "二诊脉弦稍平，呕吐略减。的属肝阳逆犯胃土。再和中镇逆，苦降辛开。", "7764": "左中脘作痛，甚则呕吐。脉象沉弦。此水饮停聚胃府。当缓以攻之。", "7765": "二诊呕吐不止，中脘板滞。脉象沉弦。还是痰阻胃府，不能通降。再拟苦辛开降，参以芳香化浊。", "7766": "左胃有停痰，胃阳不展。至暮辄作呕吐。脉象沉弦。恐延反胃之证。", "7767": "张（左）脉证相安。至暮腹满，酸水上涌。营滞不行，土郁湿困。不能急切图功。", "7768": "姚（右）头痛眩晕，甚则呕吐涎水，腰胁酸楚。脉濡左滑。此肝阳挟痰上冲胃土也。", "7769": "廉（左）呕吐数日，至昨忽然偏右胀满，上则中脘，下则少腹，尽行板硬，一时之间，气从上逆。幸未几即平。然食入仍呕，并吐出蛔虫，口渴频饮。舌苔糙白，脉象虚弦。肝木横逆之余，胃土有升无降，阳明之液暗亏。恐呃忒致厥。", "7770": "胡云台方伯年逾花甲，阴液已亏，加以肝气不和，乘于胃土，胃中之阳气不能转旋。食入哽阻，甚则涎沫上涌。脉两关俱弦。噎膈根源，未可与寻常并论。姑转旋胃阳，略参疏风，以清新感。", "7771": "二诊辛开苦降，噎塞稍轻然。左臂作痛，寐醒辄觉燥渴。脉细关弦，舌红苔黄心剥。人身脾为阴土，胃为阳土，阴土喜燥，阳土喜润譬诸平人，稍一不慎，饮食噎塞，则饮汤以润之，噎塞立止，此即胃喜柔润之明证。今高年五液皆虚，加以肝火内燃，致胃阴亏损，不能柔润，所以胃口干涩，食不得入矣。然胃既干涩痰从何来。不知津液凝滞，悉酿为痰，痰愈多则津液愈耗。再拟条达肝木，而泄气火，泄气火即所以保津液也。然否即请正之。", "7772": "蒋嗜饮损伤中阳，气不施化。食入哽阻，痰涎上涌。脉滞，苔白质腻。噎膈重证，图治维艰。", "7773": "郭（左）肠红痔坠日久，营液大亏。食入于胃，辄哽阻作痛。脉两关弦滑。此胃阴枯槁。噎膈重证，何易言治。", "7774": "二诊脉滑而弦。舌心作痛，食入胃中，仍觉哽痛。胃阴枯槁，未可泛视再拟金匮大半夏汤法。", "7775": "三诊脉左大于右，阴伤不复之证。食入哽阻，胃阴尤为枯槁，未可泛视。前拟金匮大半夏汤法，当无不合，即其意而扩充之。", "7776": "四诊食入哽痛渐定，脉弦稍平，而肠红连日不止。肝火内燃，胃阴枯槁，肝胆内藏相火，肾开窍于二阴，铜山西鸣，洛钟东应矣。", "7777": "孙（右）中脘不舒，按之坚硬胀满，甚则气逆如喘。脉两关弦滑。此抑郁动肝，肝气冲入胃中，将成噎膈重证，非旷怀不能为功。", "7778": "右朝食暮吐，物不变化。脉沉细，苔白质腻。中阳不旋，反胃重证也。", "7779": "章（左）向有肠红，兹则每晨便泄之后，仍见干粪胃气日行困顿。脉左虚弦，右濡滑，关部三十余至一动。此由肝阴不足，脾气虚损，肝不足则血不收藏，脾亏损则鼓旋乏力。由是而水湿之气，不能分泄，混入肠中，所以每至黎明，阳气发动之时，水湿之气，傍流而下。脾与胃以膜相连，脾虚则胃弱，理固然也。拟连理汤出入。", "7780": "二诊温脏清腑，注泄已止。右脉濡滑较退。的是中气虚而脾土之阳气不足，肝阴亏而大肠之湿热有余。刻下大便溏燥不调。脾气未复耳。前法参入分消，盖祛湿即所以崇土也。", "7781": "三诊右脉滑象渐退，溲亦渐利。湿热有外泄之机。特胃纳不醒，当和中芳运。", "7782": "左外寒束缚里热，挟积不化。由头痛发热，而至腹痛水泻，每在清晨。至今泻虽暂定，而腹痛未止，浊积必然未化。脉细关弦。拟调气运中以磨化之。", "7783": "某嗜饮多湿，湿困脾阳。大便泻利。脉象濡软，舌苔淡白。宜理脾温中。", "7784": "右脉滑便泄如前，小溲欲解不爽。湿郁腑中，水液渗入大肠。再参分利。", "7785": "某木郁不克条达，气分攻撑不平。土被木克，运化无权，寅卯之交，依然便泄内热。脉细弦数。营液日耗，恐入损途。", "7786": "汪（幼）久泻不止，阳气不运，以致四肢逆冷，神迷如寐，呕吐咬牙。脉形沉细。土虚木旺，将成慢惊，切勿轻视。方请儿科先生商政。", "7787": "聂（左）素体湿甚，兹则由胀满而致便泄，色如败酱，得泄转松，然中脘有形，气冲嗳噫，胃呆少纳，时易汗出。脉象濡软而滑，苔白质腻，口味带甜。此由湿热内蕴，脾土不能转旋，水谷不能分化，尽注于肠，肝木从而暗动。恐致呃忒。拟和中运脾，兼泄府浊。", "7788": "二诊投剂之后，解出极为秽臭，府中之浊，得从外泄，而自利仍不稀疏。昨尚和平，今又腹中胀满，甚致有形上冲，直抵中脘，则恶心嗳噫，最为难堪，抚之摩之，其形方能降下。口甜干腻，苔白转黄，脉象转滑，关部独弦。湿热内蕴，清浊之气，不司升降，土气既滞，木气遂郁，致横暴之气，肆逆莫制。望六之年，恐正不胜病。金匮厥阴篇中每用苦辛酸，即遵其旨。", "7789": "林少筠太守肾泄又名晨泄，每至黎明，辄暴迫而注者是也。然肝病亦有至晨而泄者，以寅卯属木，木气旺时，辄乘土位也。疑似之症，将何以辨之哉。盖肾泄是命火衰微，而无抑郁之气，故暴注而不痛。肝病而木旺克土，则木气抑郁，多痛而不暴注。以此为辨，可了然矣。诊见脉象右尺细弱，左尺小涩，两关右弱左弦，两寸右微左部略搏。是水亏木旺，心肺阴液不足之象。数载以来，常带晨泄，泄必作痛。今泄止而至寅卯木旺时，犹尚作痛。此以近时借烟性提挈，肝木虽不致克土，而气虚不克鼓舞，故肝木升发之令，未复其原，仍是一屈曲抑郁之局。人身法天地，水火阴阳升降而已。阴中无阳，是谓独阴。阳中无阴，是谓独阳。独阴不生，独阳不长，所以脏阴而腑阳，脏升而腑降。肝、藏也，阴也体阴者其用阳，故其气宜升。脾、藏也，亦阴也惟肝升而脾藏之气得与俱升。肝藏之气上升，则与少阳胆木交合，而心血以生。脾藏之气上升，则与阳明胃土交合，而胃液以长。于是胆府之气，下交于厥阴肝脏，而相火以化。胃府之气，下交于太阴脾土，而脾阳以资。今木克脾土，日以郁陷，升生之令不行，其气不能上交于少阳，而反抑伏于太阳，太阳膀胱为寒水之府，水中有木，其屈曲郁勃之气，与寒水之气相激，宜为痛矣。然木不升发而抑伏太阳，似不当有头晕耳鸣目昏肝阳上升之候。曰、不然。肝木之气，不能上升，而与胆交，则胆不降矣。胆为甲木，甲木逆，亦化风也。总之，木不升发，则心血不生，脾不能为胃行其津液，胆不能下化相火，胃不能下降而资盛纳。心血亏，胃液薄，脾阳虚，相火微，能无于腹痛而外，诸病百出哉。调治之计，必使水中之木遂其升发，上与少阳交合，于是脏腑之介降，皆复其常，而生生之机不息。拟以青皮引至厥阴之分，而以柴胡升发木郁，使肝经之气条达上行。而又恐升动胆木，故以白芍酸收之品，摄入肝经。青皮引之入其地，白芍摄之不使出其地，自与胆无涉矣。青皮破气柴胡散气，故以人参坐镇，制其破性散性。第取青皮之引入厥阴，柴胡之升发木气，俾之扶疏条达，而无偏胜之弊。当否正之。", "7790": "沈（右）痛泄者久。今年风木在泉，秋冬以来，正当旺气在木，痛痢日剧。自夏徂冬，泄痢辄带鲜血，五日来腹痛尤甚，痛起之时，竟有不能支撑之势。饮食入胃，上则痞阻，下则欲泄，心中怔悸，有难以名言之苦，其尤甚之时，似觉心神蒙混，耳鸣头晕。其痛于少腹为重。脉细而两关俱弦。按少腹两旁属肝，居中为冲脉。今冲气不和，肝木偏亢，其横暴之气，郁怒冲突于中，所以一痛而其重若此也。夫抑而下者为气，升而上者为阳，阳气鼓荡，则心神为之摇撼，所以有懊𢙐莫名之状也。惟于夏秋之间，便中带血，此必有湿热参杂其间。此时痛势剧盛若是，惟有伐肝和营，或足以制其暴戾之性。向有喉证，药难飞渡。仿徐氏上下分治之法，汤丸并进，冀其不致痛极发厥为幸。", "7791": "二诊昨投温脏清腑，伐肝和营，自夜间至午，痛稍和平，而不能大定。其痛甚之时，以手按之，则势稍缓，显不在实痛之列。大便自利，犹然带血，心中热辣，时有难名之苦，𩠎杂而不能食。脉两关俱弦，左寸虚微，尺部细涩，苔白浮糙。良以血去太多，木失涵养，致虚肝肆横，下克脾土，上撼神舍，中流渐无砥柱，木乘土位，久而不复，延致入损之症也。再拟柔肝之体，而以和胃兼之。", "7792": "三诊投阿胶梅连汤出入，痛势减轻，利下较爽，圊数亦疏。苔虽稠厚，而苔上之糙尽化，脉缓热退。其为脾阴亏损，肝木势横，可以概见。药既应手，再扩充之。", "7793": "五诊叠进补益脾阴，柔和肝木，下痢顿止，痛亦若失，胃亦渐开。半截病魔，却于旬日，殊出望外，可庆可庆。惟舌苔未化，心中仍似有烦热之意，脉细弦微数。还是湿热未清之象。再从育阴之中，兼清湿热。", "7794": "二诊升泄陷里之邪，痛痢仍然不止，里结后重，色白如冻，间带赤腻，脐下拒按不纳不饥，热退不楚。脉象滑数，舌红苔白。停食阻气，遂令风邪湿热，尽趋于下，转成痢疾。两次病伤，何堪经此波折。再拟苦辛开通法。", "7795": "三诊疏通府气，兼清湿热，解出碎杂散粪。有形之积，已得疏化，理应痛止痢减。乃痢稍减疏，而少腹作痛，有加无已，且从白转红，黏腻之血，鲜紫杂下，火升颧红，唇色如朱，神情委顿，谷粒不食。脉滑数转为细弱，舌红苔黄，近根脱液。有形之积虽化，而风湿热从气入血，血液耗残，木失柔养，虚肝肆横，所以少腹作痛更甚，以少腹居中为冲脉，两旁属肝也。拟酸甘柔润养血。", "7796": "五诊开通大肠怫郁，痢数稍减，红腻略退。但临圊仍然腹痛，后重气坠，不纳不饥。脉数不爽，舌红苔黄，唇口糜碎。肠胃湿热郁阻，胃浊蒸腾于上，所以不思纳谷。肠中屈曲之处，亦为湿热所阻，府气不能宣通，所以后重气坠不爽也。再苦辛通以开肠胃怫郁。", "7797": "六诊疏通肠胃，胸中闭结之浊稍开，渐思纳食，痢亦减疏。然仍腹痛后重，色赤仍如膏冻。脉象细数。厥阴伏热乘脾，肠胃气机皆阻。再拟苦辛开通，而泄厥阴伏热。必得逐步退轻，方为顺象也。", "7798": "七诊赤积大退，痛坠略减。所下黄腻起沫者居多，沫属于气，黄属于湿，还是湿热怫郁，欲开不开，蒸腾于胃。发热颧红，小溲浑浊。脉数，舌红苔黄。泄化湿热，疏通肠胃怫郁，是目前之定局也。", "7799": "八诊赤积渐退，腹痛稍轻，痢数略减，后重气坠亦松，胃气苏醒，颇思饮食，山根青色亦退，皆属转轻之象。然痢虽减轻，身复发热，一昼夜不能熟寐。脉数右大，舌红苔黄。痧后少腹先觉不舒，山根色青，遂借饮食过节而成下痢，厥阴必有伏热，其上中湿热，因内虚而陷入于下。今肠胃怫郁稍开，而湿热充斥于三焦，所以熏蒸为热。再仿协热下痢治之。", "7800": "左便利虽止，而肛门如坠，迸迫不舒。服升补之药，下坠不退，脉濡且滑。此湿热压滞，府气下坠。宜苦泄法。", "7801": "赵（左）下痢气坠后重略松，右脉结代较和。其色犹带赤腻。的属湿热之邪尚盛。虽见转机，尚不足恃。", "7802": "席（左）疏补兼施，百次以外之痢，渐减至二十余行，脐下按痛，已得全化，不可不谓起色。无如气怯懒言，频频哕恶，不能饮食。脉细无神，大有雀啄之意。良以食滞通行，而暑湿热冲斥三焦，致胃气遏伏不宣，脾气因而涩滞。较昨虽有起色，正虚病实，犹于大局无裨。", "7803": "三诊痢渐减疏，肛门涩滞，亦已爽利，里急亦松，恶心亦定，脉亦起。", "7804": "左疟后下痢，腹痛甚剧。脉细，苔白质掯。有形之积，无形之气，郁阻府中。宜为温通。", "7805": "高痢疾之后，脾虚湿滞。腰脊不舒，面带微肿。兹则食入运迟，时多沉睡。脉细不爽。此皆脾为湿困，脾土旋运不及。久恐有胀满之虞。", "7806": "王（左）数年前曾经下痢，虽经治愈，然每至夏秋，湿热蒸动，其痢辄发。脉沉而滑。此湿热伏留肠胃，根蒂未清，所以触之即动也。当以通为止。", "7807": "裘（右）休息痢迁延数载，临圊作痛。此湿热伏留肠胃屈曲之处，血液由里耗损，天癸自然不行，恐难以此而便为孕象也。脉细不爽。先为疏通。", "7808": "邹（左）痢成休息，色赤黏腻。脉濡微滑，苔白心黄。此湿热郁阻大肠屈曲之处。病久邪深，不能一蹴而几也。", "7809": "陈（右）痢成休息，临圊仍痛。脉濡而滑。此湿积伏留大肠屈曲之处。暂为疏通。", "7810": "方维卿投剂之后，合夜甚安，至今午后呃忒又盛，下痢肛门火热滞坠，小溲热痛。脉数左尺坚硬，苔白质红。痰滞较化，故得胃中之热气暂平。而下焦之火挟热上冲，所以肺胃之气，欲从下降而不能降，至成彼此鼓激之局。忌款未退仍在危地也。", "7811": "二诊宣肺气之痹，原欲行其上而下脘通降也。乃呃忒仍然不止，中脘结痹不舒，沃出痰涎，呃方暂定。下痢频频。脉数，右关沉糊。良以暑湿热三气郁阻肠胃不化，热迫于下，致湿热之气，俱结于上。胃中之阳气不通。痢证之忌象频见，敢云治乎。不得已仿附子泻心法。", "7812": "三诊呃逆较疏，仍然不止，下痢较爽，溲略通利。脉象稍稍有神。木邪素旺，暑湿热郁阻肠中，胃府失于通降，遂失清升浊降之常。仍在险途。", "7813": "四诊呃忒下痢俱减，神情亦略起色，脉沉略起，然脘中时仍阻塞，并有酸水泛出。良以平素所有之寒，阻遏中阳，致气血鼓激，胃气逆冲。既稍有转机，不得不竭人力，以希造化。", "7814": "五诊呃止两日，而下痢仍然不减，腹痛溲少，糜黄甚臭。脉微数。上寒下热，而又未便苦寒。姑以轻剂扩清火府。", "7815": "左休息痢疾，每因湿热逗留而成，其红赤之物，都缘湿热迫伤营分。然邪郁大肠，安有久而不去，不腹痛、不后重之理。今并不身热，不腹痛、不后重，其血液时止时来，而脉象常带细数，又安有不发热而脉数之理。所以然者，以痢伤脾阴，脾为统血之帅，脾阴不能统摄，血液渗溢，其红腻之物，即随时而见。前用补益藏阴，服之颇适，药既应手，毋庸更张。", "7816": "三诊脉症相安，再守效方出入。", "7817": "张（右）气撑腹痛下痢。湿热化燥伤阴，脉虚喉舌起腐。深入重地，图治为难。", "7818": "某噤口大势，较前虽减，然临圊依然痛坠，节骱作烧，糜饮入口，辄欲反出上腭两腮唇口糜腐满布。然又并不甚浊。脉数滑。久按少情。此湿热内郁，下则压坠府气，上则熏灼伤阴。有厥脱之虞。拟清燥并行，甘苦合化法。备请商进。", "7819": "章（左）下痢赤腻，里急后重。苔黄糙掯，脉滞不爽。暑湿热郁阻肠胃。烟体当此，未可与寻常并论。", "7820": "庞（左）下痢不止，所下皆属紫瘀之色，口燥舌干。脉细数，舌苔灰滞。湿热伤营，清津不司流布。恐元气难支，虚中生变。", "7821": "左每至便后，辄下血淋漓。脉形濡滑。湿热郁于大肠。宜苦燥湿，寒胜热。", "7822": "四诊肠澼不止，肛门下坠。脉象滑大。此湿热不化，大肠府气压坠。拟和营兼清湿热。", "7823": "卫（左）向有便血，阴分久亏。复以寒饮伤脾，脾不统摄，肠澼日久不止，脏阴愈亏，则腑阳愈燥，所以时有燥粪杂下。脉象虚弦。养阴之中，参以培脾，兼清湿热。", "7824": "左大便闭结，身热痰多。脉象弦大，舌干无津。此由痉搐之后，痰热内滞，清津不升，浊液不降。衰羸情形也。", "7825": "某年近古稀，腿股软弱，兹则大便不解。六脉细涩。血液枯燥。宜养血润肠。", "7826": "贾（左）便不畅行，胸次不舒，每至便阻，头面辄发㾦瘰。脉濡不爽。此湿热有余，脾土不能鼓舞运旋。拟和中泄浊，参以分利。", "7827": "奚用介宾先生化肝煎法，原欲其化气化火，化有为无也。乃下坠之气，依然不松。脉关弦，右部微滑。良以浊在府中，浊不得泄，致肝木之气不能和协。暂为破泄府浊，以觇动静如何。", "7828": "四诊泄浊之后，坠气较松。然肛门微觉不能收摄，气冲作呛。脉细带涩。府浊虽得稍泄，而病久肾虚，阴不固摄，以此而呛咳不退。再摄其阴。", "7829": "储（左）胀势既松之后，适交春令，肝藏之气，勃然升发。流行之机，皆为之阻。大腹仍胀，寅卯木旺，气觉攻撑。脉细而弦。恐成气胀大症。", "7830": "左至暮不能纳食，食即胀满，至天明其满始退。脉象沉弦。此由脾阳不振，所以至暮则阳无以化，而胀满辄甚。鼓胀根源，未可忽视。", "7831": "冯（左）肿势不增不减，气急痰鸣，大便溏行，小便涓滴，心中灼热懊烦。脉沉弦重按带滑。此水气逆射于肺，而痰火交炽于胸中，势恐喘脱。", "7832": "周（左）由肢体疲软，渐至食入运迟，腹笥胀满，脐下尤甚，咳嗽痰多。脉形沉细，苔白少华。此由脾肾阳衰，不足以运旋鼓舞，土为火子，真阳不治，则土德愈衰，木邪愈肆。补火生土，一定之理也，特王道无近功耳。饮食一切，必须谨慎，以盛纳在胃，运化在脾也。知者当能察之。", "7833": "二诊体半以下，肿势渐消，而体半以上，仍肿不退。脉沉细，舌苔黄滑。湿热溢于皮肤肌肉，用金匮越婢汤，以发越脾土之湿邪。", "7834": "朱（幼）遍体虚浮，肿满窒塞，小溲不利，气逆喘促。脉沉，苔黄质腻。此脾虚而湿热泛滥莫制。将至喘脱。", "7835": "范（左）目窠先肿，渐至腿足俱胀，脘腹不舒。脉细沉迟。此湿寒泛滥，水气重症，方兴未艾之际也。", "7836": "二诊导水下行，气喘虚浮，一毫不退。脉沉细如丝。此由命火式微，水气泛滥，而逆射于肺。恐逆甚而喘而厥而脱，不可不慎。", "7837": "王由足肿而至遍体虚浮，两胫红赤，二便不利。脉形沉滑。此脾虚而湿热泛滥，水气重症。为势正盛也。", "7838": "曹（左）胃脘作痛，渐至腹大，泄泻之后，痛势虽止，面目肢体俱肿，朝则面甚，暮则足甚。脉细沉弦。此水饮之气，郁遏脾阳，水从泻去，而脾以泻虚。致水气泛溢。水胀根源也，不可轻视。", "7839": "某养肝之体，疏肝之用，参以苦辛而泄肝浊，胀势仍然不减，以前偏左为甚，今则中脘偏右为甚，恶心频呕痰水，喉间痰声漉漉。左脉细弦，右脉滑大。此由肝横太过，无形之气，挟停痰积水内阻，致脾肺升降之道，窒塞不通耳。再拟行水气，散痞结，参入芳化，以流气机而开郁阻。", "7840": "邹（左）由气逆痰升，而致面浮足肿，朝则面甚，暮则足甚。脉滑苔白质腻。此外感风邪，与内湿相合，遂致风湿相搏，风旋则面浮，湿坠则足肿。恐成肿胀之症。", "7841": "二诊降气除湿合方，两胫肿胀大退，而足跗仍肿，面色带浮。脉象濡滑。风旋于上，湿坠于下，再培土利湿。", "7842": "邵由足肿而致遍体虚浮，二便不利。脉象沉弦，舌苔白滑。脾虚湿邪不运，溢入肌肤，名曰饮肿。恐水气逆射而致气喘。拟开鬼门法。", "7843": "陈岳林平人清气上升，浊气下降，气机施化，无一息之停者也。吸烟之体，湿痰必盛。况食百合，百合性寒黏腻，寒则伤脾，腻则助湿，脾土不运，湿滞不行，清浊升降，因而失司。浊气在上，则生䐜胀，以致大腹胀满，绷急如鼓，中脘尤甚，常觉火热，以湿郁则生热也。浊气不降，则清津不升，所以湿热甚而转生口渴。小溲红赤，且觉热痛，大便不克畅行，所以胀满更甚，噫气酸浊。良由土滞则木郁，土中有木，方能为胀，前人有肿属于脾，胀属于肝之说为此。脉象沉郁，而且带数。一派湿热闭郁情形，鼓胀之症也。为今之计，惟有泄化湿热，以舒脾困，兼泄府浊，以望气机流行。", "7844": "孙（左）情志抑郁，气机不运，湿热从而闭阻，三焦升降失司，以致大腹胀满，腿股肿胀，肢体面目发黄。脉糊滑，苔白罩灰。鼓胀重症。勉拟辛开淡渗苦泄。", "7845": "储（左）似疟之后，湿恋未清，而服血肉大补之剂，致令湿热壅滞，压坠府气，少腹作胀。再服养血以助湿，甘寒以伐气，遂致湿热充斥三焦，大腹膨胀，延及胸脘，二便不利。脉数，舌红苔腻。鼓胀重症也。欲止其胀，当疏其气，欲疏其气，当运其脾，欲运其脾，当泄其湿，以脾为坤土，土恶湿也。特谋事在人，成事不在人耳。", "7846": "宣（左）脉象弦大，久按濡滑腹满不舒，而并无胀大情形，足跗带肿。此气虚脾不运旋，湿寒内阻。中满之症，图治非易。", "7847": "二诊投剂之后，脉症尚属和平，未便遽事更张。", "7848": "三诊胀满较松，欲嗳不爽。右关脉尚带弦搏。木旺土衰，木旺则其气冲突，土衰则运化无权。再疏肝之用，柔肝之体。", "7849": "四诊脉象柔软，左关部久按才见弦象。两日内胸腹舒泰，并不胀满，起病以来，未有之境。药既应手，踵效方消息之。", "7850": "龚（左）面色目眦带黄，腹笥胀大，渐至便利色赤，半载有余，胀势并未以利见消。脉数带滑。良以湿热充斥三焦。鼓胀重症，不能许治也。", "7851": "陈（左）瘕块久而散漫，大腹胀大如鼓，二便不利。脉滞苔白。此脾虚而湿热壅滞三焦。鼓腹重症，勉方图幸。", "7852": "陆（左）大腹胀大，按之坚硬，阴囊肿胀。脉形濡滞。此脾虚木旺，鼓胀重症，恐难以人力而与造化争功。勉仿经旨工在疾泻之意。谋事在人，成事在天。", "7853": "范（左）身热大势虽退，脉仍未静，溏泄之后，转为便闭腹笥胀满，按之不柔。此邪少湿多，邪去湿留，湿困脾土，鼓舞运旋不及，则大肠传化失司，所谓湿闭是也。宜调气泄浊。", "7854": "江（左）痰饮咳逆多年，气血逆乱，痰每带红。日来兼感风邪，风与湿合，溢入肌肤，面浮肤肿，喘咳不平，腹胀脘痞，小便不利。脉数浮滑，舌苔白腻。有喘胀之虞。", "7855": "三诊开上疏中，适交节令，痰气郁阻不开，痰出不爽，腹胀面浮足肿，小溲不利。脉形细沉。夫痰饮而致随风四溢，都缘脾肾阳虚，不能旋运，所以泛滥横行。有喘胀之虞。拟千缗汤出入以开痰，真武以温肾而行水。", "7856": "施芷园嗜饮湿热素盛，湿酿为浊，浊阻清道。先起鼻塞，经治而愈。于是湿酿成饮，饮阻肺胃。呛咳多痰，停饮在胃，中州痞阻，壅极而决，上吐下泻者屡。然虽经吐泻，而饮邪之根蒂未除。脾肺胃二脏一腑之气，已是暗损，遂致痰饮化水，渗入肌肤，火必炎上，水必就下，所以先从足肿，渐及胫股，玉茎阴囊一皆肿胀，今则腹满脘硬，食入发喘，脉象沉弦，此痰饮而变成水气之症也。花甲之年，舌光无苔，病实正虚，恐水气逆射于肺，而致喘势暴盛。拟降肺疏胃，运脾利湿，兼进牡蛎泽泻散使之入下。", "7857": "邱景林痰饮多年，痰多咳嗽，气从上升。迩来两足虚肿，纳减无味，小溲短少，寐中汗出，而往往遗尿不禁。脉沉弦。重按少力，苔白质腻。脾肺肾三脏均虚，命阳不能化水外出，遂致水溢肌肤，蒸变无权，致胃纳日以呆顿。开太阳，逐痰水，原属痰饮必效之方，惟久病多虚，姑以阳气为重。", "7858": "蒋（左）四肢面目俱黄。脉形糊滑。此湿热蕴遏，为五瘅中之谷瘅。", "7859": "章（右）谷多气少，面色浮黄，肢倦体乏。脉涩，舌淡。产后劳伤，血虚营滞不和也。", "7860": "江（左）嗜饮中虚，气失旋运，水谷之气，不化为津，转化为痰。痰阻营卫，寒热交作，必得便解黏腻，痰尽方舒。食入后中脘久痞。脉形濡弱。脾胃愈亏，则浊痰愈甚，前人有见痰休治痰之说，宜以脾胃为本。", "7861": "李（左）肝木不和，腹胀脘痞不纳，时发时止，甚则心神恍惚。脉左关独弦。此厥气失疏，风阳扰攘也。", "7862": "某不纳不饥，稍稍纳食，中焦如阻，泛酸欲吐，寤难成寐。脉细濡，关部带滑。此湿热郁阻中州，致脾清不升，胃浊不降。六腑以通为用，宜辛以开之。", "7863": "二诊辛开苦降，中脘较舒，泛酸呕吐之势稍缓。然犹杳不思纳，略进稀糜，尚觉胀满，腹中攻撑不和，大便不解，寤难成寐。脉右部弦滑。胃府之气，略得通降，而肝肠暗动，遂令木郁土中。前法再参平肝泄木。", "7864": "三诊胀满较舒，痞阻稍松，吐出稠痰，寤得成寐，饮食得以渐进。但脉象尚带弦滑，舌红苔黄。肝胃不能和洽，从效方再望应手。", "7865": "四诊两和肝胃之气，似觉稍和，而胸脘仍然胀满，心胸之间，时觉烙热，痰中带红。脉左寸关带弦，尺部数细，右寸关弦滑，尺部坚硬，舌苔白腻，而底质带红。前人谓气有余、便是火，所以心胸烙热者，良由肝胃之气不和，气郁生火，气之所在，即火之所在也。再理肝胃之气，而和肝胃之阴。", "7866": "五诊脉左寸关弦象稍退，右关脉弦滑亦稍柔和。胀满渐舒，略能安谷。再从肝胃调和。", "7867": "某中气虚弱，不饥不纳，二便不利，中脘痞阻，卧难成寐。脉细而滑，口腻苔浊。湿热郁阻，升降失司。拟开上焦。", "7868": "二诊中脘痞阻，饮食不进，口腻痰多。脉象濡滑。浊阻胃中。先为通降。", "7869": "三诊通降胃府，仍然不纳，略一进谷，辄中脘不舒，味变酸浊。脉象濡滑。痰湿闭阻胃口。再降胃化痰，而宣气郁。", "7870": "四诊脉象濡细，重按少力，舌苔白腻不化。不纳不饥。中气不足，不能化浊。再扶持中气，而展胃阳。", "7871": "六诊胃气虽得稍醒，然略一多纳，气辄上冲。脉濡细，右关带滑。中气不足，不能运化，以致湿热结聚，通降无权。拟苦辛开通。", "7872": "马（左）少腹偏左聚形，食入胀满，色夺形衰。脉迟苔白。此情志抑郁，木不条达也。致气湿瘀滞，酒积不行，名曰积聚。恐元气耗损而入损门。", "7873": "左少腹结聚有形，按之坚硬。脉沉而弦。此气寒交阻，恐成胀病。", "7874": "某中脘结块，按之不甚痛。脉象沉滑。此痰湿流入分肉之间。", "7875": "郁（左）时病之后，左胁下癖块胀大，腹满不舒。脉弦滑，苔白。脾土不运，胃络阻滞。拟宣通气血，参以运土。", "7876": "右腹中作痛，少腹聚形，经事当至不至，面色萎黄。脉形沉迟。此寒入胞门，与肠外之汁相抟，石瘕之属也。须耐心善调，勿得急切攻夺。", "7877": "潘（左）两足软弱，步履不便，肌肤作麻，中脘痞满，恶心欲呕。脉象糊滑，苔白微腻。湿郁胃中，胃为十二经之总司，胃病则不能束筋骨而利机关，所以足膝软弱，痿症之情形也。当取阳明。", "7878": "二诊寒湿停阻胃中，呕吐恶心，频渴欲饮，咳嗽则少腹两旁牵痛，四肢脉络不舒。盖寒湿内阻，则清津不升，故口渴。阳明病则脉络不和。再温运湿邪，而降阳明。", "7879": "三诊脉络稍和，略能安卧，恶心呕吐口渴俱觉减轻，胸中如有物阻。脉象沉弦。寒湿停饮，阻于阳明，大便不行，不得不暂为控逐也。", "7880": "四诊脉沉弦稍起，呕吐大减，施化得行，口渴较定。然胃病则土难御木，风木大动，机关脉络失和，四肢痿软。急为柔养脉络，而和营液。", "7881": "曾（左）由面肿而发赤瘰作痒，渐致腿股带肿，恶心呕吐，手臂筋脉抽掣。此风湿相搏，阳明脉络失和。拟祛风理湿。", "7882": "二诊脉象糊滑苔白心黄。恶心呕吐，频渴欲饮，随饮随吐，手臂筋脉抽掣。湿痰蕴阻胃中，致清津不升，浊液不降。拟苦辛通降法。", "7883": "三诊呕恶大减，未能尽止。形体恶寒，头巅觉冷，自汗淋漓，筋脉抽掣。脉形沉细。湿寒郁阻阳明，阳气不能敷布，而从外卫。再温化湿寒。", "7884": "四诊温化湿痰，呕吐复盛，中脘胀满，痞阻不舒。恶风自汗筋脉抽掣。沉细之脉，两关转大，颇带弦象。良由胃病则土难御木风阳从而扰胃。再从肝胃主治。", "7885": "又温化湿痰，呕吐不定，频吐频渴，想吃甘甜，自汗恶风。右脉转大而觉濡软。良由频吐损伤胃阴，湿寒成燥。再甘凉以和胃阴。", "7886": "洪（左）湿热淋浊之后，髀关不时作痛，遍身作痒。脉象滑数。湿热流入络隧，恐成痿痹。", "7887": "三诊脉症相安，然屈伸行动，髀关仍痛。风寒湿阻络未宣。", "7888": "二诊痹痛稍减。再宣通脉络，理湿祛风。", "7889": "二诊遍身作痛渐平，而右腿骱仍然酸痛。脉象沉细。风寒湿三气内袭，遂致经络阻痹，营卫气不宣通，不通则痛，势必然也。", "7890": "席（左）每至寅卯之交，辄腹中胀满，蔓及腰膂，髀关亦觉重著作痛。脉沉而滑，苔白腻浊。此肝气夹痰内阻。用太无神术散法。", "7891": "五诊尾闾作痛，而腰膂髀关经脉牵掣，步履不便。脉象沉郁，重按带滑。湿痰留络，恐成痹症。", "7892": "李（左）遍身络隧不舒，动辄作痛。脉形沉滑。感寒夹湿，阻痹络隧。宜为温通。", "7893": "左痰湿有余于上，肾水空虚于下，木失水涵，横暴之气，克脾则胀。营卫不克宣通，四肢脉络不和，阳气上升，神不归舍，将寐之际，心中难过，胸膺甚觉不舒，亦由卫气上逆，清肃之令不行。先降胆胃，使神能归舍再议。", "7894": "毕万花膏方始则湿毒流入筋骨，继则邪去络空，叠投肝肾并调，通补脉络，渐次而愈。惟每至卧著，则肢节作痛。人身气血周流贯通，本无一息之停。气中有血，血所以丽气也。血中有气，气所以统血也。卧著肢节作痛，是血中之气不行。宜养血和络，仍参宣通祛风之品。", "7895": "孙（右）腰膂髀关腿股俱觉作痛，肩臂难以举动。脉象弦滑。血虚肝风入络，络热则机关为之不利。不易图治也。", "7896": "二诊宣络以清蕴热，仍难步履，腰膂髀关，酸多痛少。病从血崩之后，由渐而来。的属血虚奇脉纲维失护。再通补奇脉，而益肝肾。", "7897": "经（右）遍体经络作痛，头旋掉眩，鼻流清涕，脉细弦而数。时辄不寐。血虚肝风袭入络隧，热气上冲，逼液为涕。拟养血荣经。", "7898": "二诊节骱仍然作痛，头旋掉眩，少寐多涕，频渴欲饮。脉象细弦。皆由营血不足，肝风袭入经络。拟养血化风。", "7899": "四诊脉弦稍柔，经络掣痛较退。再养血宣络。", "7900": "王（右）营血久亏，血不养经，手足经络作痛，脉弦头晕。养血熄风为治。", "7901": "苏（右）由腹中作痛胀，而致经络作痛，腿膝尤甚，大便不行。脉象细数。阳明脉虚，风阳乘入。宜养血熄肝。", "7902": "经（右）节骱作痛，两膝尤甚，背腧板胀，必得捶久方舒。人之一身，必赖气血营养，惟营血不足，斯络隧空虚，而诸病俱作。背腧为诸脉所辖。皆由木旺水亏，少阴之真阴愈少，则少阳之木火愈盛，逼液为涕，烁金则喑。其病虽殊，其源则一。", "7903": "陈（左）熄风养血，臂痛稍轻，脉缓微弦，重按少力。从前法兼补阳明。", "7904": "二诊脉渐柔软，臂痛略轻。仍守调补气血，气血一充，则调理自和。", "7905": "二诊遍身酸痛大退。然仍肝阳上升，𩠎杂气冲，经脉抽掣，四肢厥逆。良以阳明脉络空虚，肝阳乘袭。再通补阳明，参以熄肝。", "7906": "左肩项四肢麻木，麻少木多。脉形濡滑，舌心灰润。胃中湿痰闭郁。拟二术二陈进退。", "7907": "张（右）高年营血既亏，中气复弱。血虚则木失涵养，而虚风内动。气弱则阳明络空，风阳遂得袭入筋络。筋络既阻，则营卫之气，滞而不行，四肢麻木不遂，腹中板滞不和。盖脾主运旋，木旺则脾土不能旋运，所以气机从而凝滞也。脉象濡而带弦，舌胖心剥。湿痰素盛。宜通补阳明，舒筋养血，而不涉呆滞。古稀之年，聊冀得尺得寸而已。", "7908": "费（左）人之一身，营卫气血而已。血所以丽气，气所以统血。非血之足以丽气也，营血所到之处，则气无不丽焉。非气之足以统血也，卫气所到之处，则血无不统焉，气为血帅故也。经云卫气昼日行于阳，夜行于阴，行于阳二十五度，行于阴亦二十五度，其所以能二十五度者，为其营能行，卫亦能行也。今年逾大衍，气血暗衰，风寒湿久伏，乘瑕蹈隙，袭入经络，遂令营卫之气滞而不行，四肢酸麻，厥逆恶寒。营不行则营不足用，有营若无营矣。卫不行则卫不足用，有卫若无卫矣。譬之久坐倚著，则麻木不得行动，此理甚明。脉细沉濡，舌胖质腻，尤为风寒湿之明证。为今之计，欲治酸麻，必先行其营卫之滞而后可。欲行营卫之滞，必先祛其所以阻我营卫者而后可。谁阻之。风寒与湿是也。拟理湿祛风法。风湿既去，营卫自行，则厥热恶寒，不治自愈。但邪湿既久，其来也渐，其退也必迟。知者以为然否。", "7909": "某偏左麻木不用，咳嗽气逆痰多。脉形软滑。痰湿阻肺，兼袭经络，图治不易也。", "7910": "杨（左）偏左麻木，不能运动，胸腹常有热气注射。脉形弦滑。此气虚而痰热内阻，类中之根也。", "7911": "谭（左）向有气撑，兹则胸次作闷，中脘不舒。右关脉滑。此胃中之痰气交阻，阳明为经脉之长，阳明病，则四肢作麻矣。", "7912": "吴（左）遍身麻木，小溲结而不爽，中州不舒，目盲失明。脉象糊滑。此湿痰内滞，络隧不宣，脏腑之精气，不能上注也。", "7913": "吴（左）麻木大退，渐能步履，两目略能隐约见物，不可不为转机。但脉仍弦滑，湿痰尚盛。再祛湿疏风。", "7914": "二诊脉濡而滑，痰不爽利，每至睡卧，四肢作麻。气虚夹湿夹痰，营卫流行为之所阻。再补气化痰，所谓气旺则痰行水消也。", "7915": "俞（右）四肢作麻，脉形细弱。营卫不足，风与湿袭留不解。势难急切图功。", "7916": "谢（左）起居如常，惟手小指常觉麻木，右膝腘微痛。素体丰盛，湿痰有余。考小指之端，为手太阳之脉起处，而足太阳之脉从外廉下合腘中，循京骨至小指外侧，则是所病之地，皆太阳部位。良以太阳为寒水之藏，痰湿有余，则太阳之经气不宣。东垣有丸药养之之法，即宗其意，而参太阳引经之药。", "7917": "王（左）消渴虽减于前，而肌肉仍然消瘦，舌干少津，溲多浑浊。脉象沉细。水亏之极，损及命火，以致不能蒸化清津上升。汤药气浮，难及病所，宜以丸药入下。", "7918": "三诊脉症俱见起色。效方出入，再望转机。", "7919": "陈（左）败精失道，精浊久而不止。兹则旧咳复发，每至寅卯，气辄上升，不能著卧，痰色有时灰黑，脉形濡细。肾水不足于下，痰热凭凌于上。尚可抵御，难望霍全。", "7920": "二诊每至寅卯，气辄上升，不能著卧。脉象细弦。肾虚冲阳挟痰上逆，并有精浊。法宜兼顾。", "7921": "周（左）无梦泄精，腰府作酸。脉象虚濡。精道滑而不固。宜固精益肾。", "7922": "三诊固肾气而益脾胃，脉证相安。前法扩充之。", "7923": "王（左）肾为阴主藏精，肝为阳主疏泄，肾之阴虚则精不藏，肝之阳强则气不固。久病气阴皆虚，精不能藏，不时滑泄。少阴为开阁之枢，枢病则开阁失度，往来寒热。肾主骨，骨髓空虚，腰酸足软。大便艰难，以脏阴愈亏，则腑阳愈燥也。脉虚形虚，虚损之证，何易言治。且先固摄其下，以节其流。", "7924": "二诊摄肾固精，精气稍固，饮食略为馨旺。但精髓空虚，开阁失度，脏阴不足以济燥金，倏寒倏热，大便旬日不行，阳升筋掣。脉形虚大。前法参滋润养脏。", "7925": "三诊滋肾固精养脏，大便颇通，滑泄之期稍远，胃纳略觉馨旺。脉神较振。药既应手，无用更章。", "7926": "五诊脉虽细弱，渐觉有神，形色亦渐华泽。然遗泄有时仍作。还是肾气不固。再为固补。", "7927": "严摄纳肾阴，脉证相安。然无梦泄精，亦属肾阴不固。前法参以固摄。", "7928": "左遗浊相兼。昨投分利湿邪，脉仍濡滑。若水湿不克分清，其精窍何从扃固。但湿为黏腻之邪，非一蹴所能几耳。拟汤丸并进，上下分治。", "7929": "郁（左）梦遗频来。脉象濡细，左尺涩弱，左寸浮大。心肾两亏，水火不能相济。从心肾主治。", "7930": "俞（左）有梦而遗，渐至咳嗽，往来寒热，汗出方解。脉细数少力。此由气血并亏，阴阳不护，恐损而不复。用仲圣二加桂枝龙牡汤，以觇动静如何。", "7931": "钱（左）浊经两月，小溲甚畅，而马口不净，时有渗溢。脉大不耐重按。此气虚矣。", "7932": "左小溲淋痛，痛甚则闭结不宣，欲解难解。脉数洪滑。此湿热蕴结膀胱，磅胱不能化气，所谓气淋者是也。", "7933": "徐（左）下坠之气，仍不见松，气一下注，直入尿管，辄痛不能忍，有时由尿管而抵及肛门，亦然作痛小溲滴沥不爽。右脉濡滑，左部细弱无力。良以肾气亏损，不能收摄。再咸润摄下。", "7934": "四诊小溲已能约束，惟水道尚在窒塞，理宜逐步进逼。然天暑脉虚，不若暂为退守，乘机进治。", "7935": "左小溲淋痛，脉形弦滑。此肝火湿热，郁阻膀胱。先为疏泄。", "7936": "李（左）脉证相安，惟小便仍有牵腻之物。良以瘀腐未清。宜重药轻投。", "7937": "丁（左）脉象濡弱，腰府作酸，久而不止，每晨咽喉作痛。夫腰为肾府，少阴之脉循喉咙，参合病情，是肾气虚、肾阴衰、阴阳交亏之象，理宜填补下元。然而淋浊之后，必有湿热，当于补药中仍带流利可耳。", "7938": "廖（左）久浊色带黄稠，茎中有时作痛，每晨目带红赤，腿股酸楚，步履维艰。脉细弦微滑。肾虚湿热伏留未楚，精水混淆不分，精关遂难扃固。拟理湿泄热，而化败浊。", "7939": "戴（左）脉濡不滑，右尺鼓指。小溲虽不作痛，而马口仍带干结。下焦湿热逗留，驾轻就熟，不能霍全者为此。", "7940": "左小溲漩脚起沫，有时作痛。脉象左大。此肾虚而湿热留恋。拟苦以泄之，咸以化之。", "7941": "唐（左）小溲淋痛，闭癃不爽，甚至涓滴不通。脉细而沉候弦硬。此湿热蕴结膀胱。恐至癃闭。", "7942": "朱（左）肾气不足，暮夜溲多，脾胃气虚，纳少胃钝。脉濡，苔白少华。宜补气益肾。", "7943": "邱（左）小溲频数而不作痛。脉滑，苔黄质腻。此痰湿有余，膀胱之气，为湿所压。证已年余，驾轻走熟，恐难一蹴而几。", "7944": "庄（左）命门相火，为生身之本，真阳亏损则火衰，湿痰郁遏，火不用事，则火亦衰。脉滑而大。痰多阳痿，火之式微，湿之有余也。取舍之间，自有明辨。", "7945": "左体丰多湿，加以大病之后，余蕴未清，以致湿邪流行入络，髀关及左腿膝作酸，麻木不仁，艰于步履，腰背作痛，卧著尤甚。湿邪久困，则相火为之郁遏，阳道不举。脉象濡滑，苔白微黄，质腻。皆由络隧之中，为湿所阻，则无形之气，有形之血，不能宣畅流布。而历来所服之药，皆是补滞之品，未免为敌树帜，名曰中湿，非久药不为功。", "7946": "二诊祛湿和络，脉象稍觉流畅，相火有燃动之机，足见湿邪抑遏，虽有真阳，无从发露。药既应手，再扩充以进。", "7947": "潘（左）前年二次眩晕，几至发厥。兹则腿股作酸，阳道痿顿。脉形濡滑，舌苔白腻。湿酸郁遏，致命火不能用事。欲助命阳，当先去其遏我命阳者。", "7948": "某（左）子和论七疝都隶于肝，以少腹前阴，皆厥阴经部位故也。盖筋者肝之合，睪丸者筋之所聚也，偏左者肝生于左也。劳倦奔走，则元气下陷，所以肾囊之间，筋肿甚大，每觉上冲心胸，非攻心也，夫中脘季胁，乃肝脉游行之地也。大凡治法，不越辛温苦泄。然劳碌气陷者，苦泄则气益陷。今先举其陷下之气，稍佐辛温，是亦标本兼治之意。另案即请方家正之。", "7949": "左大病之后，脉象时常带数，右三部微滑，左三部并无数象。此气分湿热逗留，湿热润下，压坠府气，所以有疝气情形。拟理气泄湿。", "7950": "徐（左）右脉濡细，左脉细弦。少腹偏右筋突痛胀，必得平卧，痛胀方平。考少腹两旁属肝，居中为冲脉，冲任虚寒，湿压气坠，所以为痛为胀。至平卧则压坠之势稍衰，所以其痛略减。拟导湿外泄，湿得泄则不坠，水窍常开，则精窍常闭，而遗泄亦可以免矣。", "7951": "李（左）寒痰内阻，络气不宣，胸胁肋游行作痛睪丸痛胀。经云、冲脉为病，男子内结七疝。又云、冲脉者，起于气街，并少阴之经，挟脐上行，至胸中而散。所以上则胸痛，下则疝痛，病虽悬殊，其源则一。", "7952": "荣（左）由睪丸痛胀，而致从上攻冲，直抵中脘，痛不可忍。恶心呕吐，倏寒倏热，大便不行，小溲浑赤。舌红苔白。湿热流入厥阴，而冲隶于肝，又属阳明，起于气街，而布散胸中，所以肝病不退，冲脉之气，挟湿热之气，上冲犯胃，的属冲疝重症。拟苦辛酸合方。", "7953": "二诊苦辛酸合方，呕吐稍减，痛势略缓。然腹中时觉攻撑，愈撑愈痛，痛处以热物摩熨，其势即缓，而热汤入口，其痛即甚，吐出均系痰涎。脉左部细弦，右部沉郁。肝经之气，横扰充斥，标热本寒。与甘仁先生同议温脏而泄气火之郁，化痰而降胃府之气。逸山先生意见相同。录方以备商用。", "7954": "三诊苦降辛通，痛势渐轻，大便虽行未畅，呕恶不止，吐出之物，气甚酸秽。右脉沉郁稍起，渐见滑象。肝木之纵横肆扰，虽得略平，而厥气逆冲，胃土不降，气即为火，痰即为浊，酿成酸秽之味，逆从上出。与逸山甘仁两兄同议清泄郁结，降浊镇逆。", "7955": "四诊痛势大减，略能安寐，大便不行，仍然恶心呕吐，吐出不堪秽臭，胃中窒闷异常，面色晦浊，目有红光。脉左弦右滑。良由疝气上冲，胃之下口，即小肠上口，火府之气，不克下行，转从上逆，令糟粕从胃底翻出，胃浊不降，痰聚胸中，胆阳上逆，面晦目红不寐，宜有种种现象矣。夫大肠居小肠之下，与肺相表里。兹与逸山甘仁两先生同议，控逐胸中之结聚，使肺气下通于大肠，肠痹得开，则火府之气，或从下行，冀糟粕亦转旋顺下。未识能如愿否。", "7956": "五诊攻逐胸中结聚之痰，使肺气下通于大肠，大肠居然开通，屡次畅下，糟粕之逆出于胃者，亦从下行，呕吐臭秽已定，胸中窒闷亦开，疝气痛胀大减，渐能安谷，脉数转缓，出险履夷，诚为幸事。再拟调和中气，疏泄肝木，分化湿热，以善其后。同逸山甘仁两兄商用。", "7957": "钱（左）睪丸偏左作痛，牵引腰府，中脘不舒。脉濡而滑。此肝肾湿热内伏。先调气利湿。", "7958": "支（左）少腹偏右作胀，大便艰涩，时常紫黑，卧难成寐，气冲嗳噫。脉细弦数。此湿热内郁，致血气结滞不宣，𤻊疝情形也。极难图治。", "7959": "朱（左）少腹有气上冲，支脘作痛。脉沉而弦。肝肾湿寒。治宜温化。", "7960": "邵（左）肺痈之后，湿热下趋大肠，每至大便，痔坠下血。日来胃钝少纳，中脘不舒。脉象微滑，舌苔黏腻。似不在阴虚之极、阴络损伤之例。良以湿热伤营，营络不固。非苦温不足以胜湿，非大苦不足以泄热而入肠中也。", "7961": "七诊阳气上逆不平，面色浮黄，筋脉跳跃。此由血去阴伤，不能涵养。再培土养肝。", "7962": "杨（媪）心悸跳荡，时为不寐，偏左头痛，腰股作酸。脉弦尺涩。阳升不熄。拟熄肝宁神。", "7963": "居（左）惊动胆木，神情扰乱，幸而循止。脉形左大。肝火尚未平靖。重以镇之，清以泄之。", "7964": "某脉症相安，然阳气仍复上升，皆由木失滋涵。再滋肾养肝，宁神熄木。", "7965": "三诊腰为肾府，腿股为奇脉所辖，腰股作酸，肾虚已著。厥阴之脉上额交巅，肝用在左而主血，偏左头痛，血虚木旺，亦属显然。心悸跳荡，时为不寐，水亏风阳撼扰，所谓曲直动摇，风之象也。滋肾水以熄风，治之定理。", "7966": "沈（右）便泄稍减，土中之木稍泄，而肝木究未疏和，左脉沉弦，腹仍㽲痛。木旺则胃土失降，胸脘窒闷。入夜不寐，所谓胃不和则寐不安也。", "7967": "经莲山太守体丰于外，气瘠于内，气弱则脾土少运，生湿生痰。痰生于脾，贮于胃，胃为中枢，升降阴阳，于此交通。心火俯宅坎中，肾水上注离内，此坎离之既济也。水火不济，不能成寐，人尽知之。不知水火之不济，非水火之不欲济也，有阻我水火相交之道者，中枢是也。肝木左升，胆木右降，两相配合。今中虚挟痰，则胃土少降，胆木不能飞渡中枢而从下行，于是肝木升多，胆木降少，肝升太过矣。太过而不生风、不鼓动阳气也得乎。胆木升浮，上为耳聋等症。病绪虽繁，不越气虚挟痰也。脉左弱缓大，右关带滑。问与切亦属相符。治法当务其要，不寐是也。经云、胃不和则卧不安。古圣于不寐之病，不曰心肾，独曰胃不和，岂无意哉。中枢之论，非臆说也。明者当能察之。", "7968": "又惊动胆木，致乙木上升，甲木不降。一身之气，升多降少，则离火不能下行，自致坎水不能上承，离不中虚，坎不中满，是为未济，未有水火不济而能安寐者。风阳既盛，所有湿痰，鼓击上行，袭入脾络，言语謇涩，以脾脉散舌下故也。前法兼化风痰。", "7969": "龙宗师人有阳气，阴之使也。人有阴气，阳之守也。故阳气常升，水吸之而下行，阳气无炎上之忧。阴气常降，阳挈之而上升，阴气无下泄之患。心为离火，肾为坎水，离在上而坎在下，离抱坎而中虚，坎承离而中满，太过者病，不及者亦病，阴阳配合，本不得一毫偏胜于其间也。姜附过剂以耗阴气，则在下之水，不克吸阳以下行，病遂以不寐始。阳胜于阴，由此而基。夫阳乃火之属，容易化风，经谓风善行而数变，阳之性毋乃类是。阴伤不能制伏其阳，致阳气游行背部及腹，时有热气注射，而热却不甚，但觉温温液液。以阳邻于火，而究非火也，故曰背为阳，腹为阴，以阳从阳，背热宜也。而涉于腹也何居，则以阴弱而阳乘之也。惟逢得寐，其热暂平，以水火既济，阴阳相纽，足以收其散越也。若阳气久亢无制，从阳化风，恐贻痱中之忧。差喜右脉濡缓，左寸关虽弦大，左尺细微，沉候有神，乃阴气足以内守之征。历进育阴酸收之品，所见甚高。惟是花甲之年，肾经之水，能保不虚，已属不易，何易言盈。况阳之有余，即是阴之不足，以酸收之，阳虽暂敛，未必常能潜伏。兹拟前人取气不取味之法，专以水介至阴之属，吸引阳气下行，使升降各得其常，病当循愈。特春升雷且发声之际，势难遽奏全功，一阴来复，当占勿药也。", "7970": "复诊昨引阳气下行，原欲其阳伏阴中，而成既济。乃地气升发，昨为惊蛰，阳气正在勃动，晚间依然未睡，胸中不舒，稍稍咳痰，顿觉爽适，阳气两昼一夜未潜，右寸关脉顿洪大，沉取甚滑。夫以阳升之故，脉象遽随之而大，此阳系是虚阳无疑。而关部独滑，滑则为痰，盖津液为阳气所炼，凝成胶浊，胃中有痰，一定之理。心在上，肾在下，上下相交，惟胃中为交通之路，然后可以接合。今潜之而未能潜，必以交通之路，有所窒碍。拟从前意兼泄痰热，通其道以成水火既济之功。", "7971": "郁（左）夜不成寐，脉细左关微弦右关带滑。心、离火也，肾、坎水也，离在上，坎在下，上下交通，其枢在胃，胃中为湿痰所据，则坎离相交之道路阻梗，遂致水火不能相媾，所有湿痰，悉借肝火而鼓动。欲媾阴阳，当通胃府，欲通胃府，当化湿痰，特黏腻之物，断难立予荡除，探手成功耳。", "7972": "复诊惊动胆木，甲木漂拔，乙木过升，致阳气有升无降。日久不寐，脉弦肤肿，经所谓热胜则肿也。升降乖违，而欲其水火相济也得乎。拟专降胆木，使升降各得其常。", "7973": "孙（左）脾肾两虚，饮食生痰，痰阻为喘者久。兹值春升之际，痰凭木火之势而化为热，以致竟夜不能交睫。脉左尺不藏，苔黄舌红，龙相亦动。拟潜阳和阳，参以苦泄。", "7974": "又滋水宁神，脉症相安。前法扩充之。", "7975": "某大病之后，元气未复。兹以惊动肝胆，心悸少寐。脉细左弦。宜宁神以潜阳气。", "7976": "周（左）肾本封藏不固，秋冬收藏之令，阴气不能收摄，辄痰多咳嗽。兹以外感湿热之后，痰多咳甚，寤难成寐。脉象弦滑。此由病后湿化为痰，痰在胃中，则胆寒肝热。拟化痰宁神。", "7977": "杨（左）阳升不潜，介类所以潜阳，升水即以降火，投剂之后，竟能安睡。肾为封藏之本，腠理不密，动辄多汗。偶或遗泄，即发腰痛，以腰为肾府也。恶寒两足尤甚。阳甚于内，逼阴于外，自觉汗者，非真汗也。自幼头痛目疾，禀先不足。久坐尾闾作痛，尾闾为督脉起处，肾虚则空及奇脉，亦属定理。但痰湿素盛，宜从阴柔药中，参以和平蠲饮。", "7978": "王（右）隔宿之事，尚能记忆，神不昏也。神既不昏，而终日酣眠，呼之不应，断无如此睡状也。面青，脉左大，舌无华。此中气无权，阳气尽从上冒，则肾阴不能上交，阳气浮而少阴病矣。金匮惟少阴有但欲寐之条，兹用桂枝汤以和阳，参介类潜伏，但阴不与阳交，阳不与阴接，再进一层，即是阴阳脱离之局，可忧者在此。", "7979": "二诊蒙昧稍清，面青较退，左脉稍敛，而仍神迷如睡，时带错语。阳气上冒未平，炼液成痰，神机愈蔽。拟潜阳之中，参开郁化痰，必得绩效，方能许治。", "7980": "三诊阳气稍潜，上则耳鸣大减，下则大便通行，坎离稍济，蒙昧略清，面色青晦稍退，舌稍华泽。惟中脘尚觉作痛，右关脉稍觉沉实。中虚宿垢未清，阴阳稍通，坎离仍未互抱。拟从阳引阴，从阴引阳，仍参磨滞之品，合于胃府以通为降之旨。", "7981": "曹子藩六脉濡细，而模糊不爽，舌苔薄白，中心带黄，而颇觉黏腻稍一动作，辄易汗出。若果阳虚，何得酬应纷繁，不存畏葸。岂卫外之阳，与运用之阳，一而二耶。无此理也。所以然者，汗为心液，液贵收藏。今体中之湿有余，兼复嗜饮，酒性升热，遂致胃中之湿热熏蒸，迫液外泄，汗出过多，实不在自汗盗汗之例。如护卫其阳，固表益气，则湿不能泄。若敛摄其阴，壮水益肾，则湿滞不行。两者皆足以生他变也。治汗之法，惟祛其热不使熏蒸，兼引导其湿热下行，使熏蒸于胃者，从膀胱而渗泄，则不止其汗而汗自止矣。", "7982": "梁（左）叠进黄耆建中汤，咳嗽盗汗俱减。然痰涩不爽，每至半饥，其咳即甚，形体恶寒，脉象细弱。阴伤及阳，以甘药补中。", "7983": "二诊吐血之后，阴伤及阳，盗汗虽止，而形体恶寒，咽中如阻，即欲呛咳，胃纳不起。投以建中，中气仍然不振，脉象细弱。良由阴阳并虚，少阴之脉贯喉，中气下根于肾，所以肾阴虚而咽中不舒胃气不振也。汤丸并进，上下分治。", "7984": "四诊脉细弱少神，咳甚不减，痰多白腻。食入运化迟钝。阴伤及阳，肺脾肾俱损。再摄其下。", "7985": "张向有肝气，腹时胀满。春升之际，更起呛咳，痰黏而稠，寐则泠泠汗出。脉数细弦。肝藏之气，逆犯太阴，肺为水之上源，恐水源失化，而入损门。", "7986": "三诊咳嗽盗汗俱减，脉仍细数。阴虚不复。效方进退再期应手。", "7987": "右潜阳宁神，轰热盗汗犹然不退，手指带肿，口燥欲饮。适在经前，乳房作痛。脉数而弦。阳气不收。再育阴泻火固表。", "7988": "吴（左）病后自汗，咽中牵腻，有时火从上升，则肌肤灼热。脉数软滑。此甲木与戊土不降，而乙木独升。恐损久不复。", "7989": "徐（右）先发肝厥，既而𩠎杂脘痛，涌涎少寐。皆木郁之极，致肝阳冲胃。刻当经行之后，带下如注，以奇脉隶于肝，肝病则奇脉不能固摄矣。先从肝胃主治。", "7990": "右涎下略少，仍然不止，𩠎杂易饥，足软腰酸，腹时胀满。冲气不和，冲脉不固。再摄奇脉，兼参调气。", "7991": "右产后血虚不复，收藏不固，不时咳嗽。兹则寅卯之交，咳呛更甚，心𩠎头晕腹满。脉虚弦，左尺细涩。阳气升多降少，拟育阴封固。", "7992": "周（右）火时上升，不寐头痛𩠎杂，甚则脘痛。脉弦舌光。阳升不熄。拟宁神和阳。", "7993": "宋（女）脘痛偏左为甚，时为𩠎杂，脉象细弦。肝胃不和。当平肝和胃。", "7994": "许（右）中脘作痛，两胁胀满，𩠎杂而不能食。两关脉弦。肝胃不和。拟平肝调气和胃。", "7995": "郑惊风之后，风痰入络，舌强不语，步履举动，状如傀儡。兹则不时痉厥，厥则颧红火升，目斜口开手撒，四肢厥逆。脉细弦少力。络隧之中，虽有风痰内阻，而肝阴肾液已亏，以致风邪升动。拟育阴潜阳。", "7996": "三诊脉象弦滑，痫厥仍至。风痰入络，不易图治。", "7997": "汤（左）稍涉忿怒，肝阳逆上，阳气不入于阴，寤不成寐。脉弦，苔白心黄。恐浊痰随时上逆，而致癫痫也。", "7998": "二诊降火化痰，寐得稍安。然胸次尚觉窒闷，时作烦𩠎。脉象弦滑。阴分素亏，而少阳之火挟痰内扰，春升之际，势多周折也。", "7999": "三诊不寐𩠎杂大退，脉象亦觉柔和。的是痰热内扰，效方再进一筹。", "8000": "朱（左）不寐神烦大退，脉亦稍觉柔和。然左寸尚觉弦大，还是心火未宁。再宁神泄热，心火下行，则肾水自固。", "8001": "某湿热之后，痰湿未清，肝火挟痰上升，哭泣发厥，厥回脉仍弦数。痰火尚未平靖。宜清以泄之。", "8002": "二诊下痢呃忒，投温补中阳，呃仍不止，沃出涎水。脉象弦滑。胃中夹杂痰食。勉方图幸。", "8003": "某呃忒每至咳痰，呃即稍止。脉浮带滑。此肺气闭郁，清阳不展。恐致变痉。", "8004": "曹（左）久虚不复，肾气不能收摄，气觉短促，冲气上逆，嗳噫作呛。病由遗滑而来。脉象细弦。拟气血并调以图徐复。", "8005": "二诊久虚不复，气短自觉上下不续，虽能安谷，实非馨进。脉象细弱如丝，舌滑少苔。中气肾阴皆虚，所以俯仰失职，胃气不能鼓舞。拟气阴并调。", "8006": "孙（左）向有痰嗽，去冬感受风温，以致热与痰合，蒸腾损肺，咽喉作痛，音喑声嘶，内热连绵，痰稠如胶，而色带青绿。脉象细数。气火尽从上凌，太阴肺津，悉为痰热所耗，金水不能相生，肾藏之水，日形亏乏。虚劳喉痹，恐非草木可以为功。", "8007": "二诊清化痰热，咽痛音喑，仍然不减。脉象细数，颇有促意。足见痰热虽壅于上，而肾水内亏，虚阳亦从上逆。再上下分治，以觇造化如何。", "8008": "某不时咽痛，甚则吐血。脉气口带浮。此风热迫损肺络。宜微苦辛凉。", "8009": "邵（左）冬令过温，少阴之热，循经而发，喉痛数日，势虽不甚，今交戌亥时，肢节筋脉，忽作牵掣两次，而无表邪见症。夫少阴，属肾，内藏相火，相火寄于肝胆，胆为少阳而属风，木火动则风生，风煽则火炽。经云、一阴一阳结，谓之喉痹。即风火相合之意。今肢节掣引少阳之风从内而鼓，诚恐火势因之暴炽，胡可再投表散，以张其焰。惟有甘凉镇润，为合古人治法。", "8010": "二诊投剂后喉痛大定，筋脉牵掣亦未复作，饮食自调。诚以火风从内而发。镇之则风平，润之则火熄，火与风合，其来也勃然，火与风分，其去也倏然。脉形沉弱，面色青黄。脉经谓营气不足面色青，卫气不足面色黄。肝为营之源，肾为卫之本，平日肝肾之不足，略见一斑。仍从前法出入。", "8011": "四诊咽赤肿痛大退，脉静身凉。邪势已解，出险履夷。幸至极矣。但腹中气觉呆钝。热化湿动。再清余炎，兼理湿邪。", "8012": "费毓卿夫人由瘀化水，水性就下，流入足三阴经，郁而生热，遂致腿股赤肿。肝胆之火，亦因之而起，火既用事，阴分愈烁，不特分利泄湿，不能却病，即育阴之剂，未见全功。足肿赤痛，口碎咽疼，知是阴虚之极，阴不藏阳，阳气炽于阴分之中，而浮越于外。随进金匮肾气以导火归原，散越之火，应手而伏，两足赤痛顿定，肿大如瓜之状，什消五六，可谓冒险逢生。理宜渐渐和平，徐徐图复，岂期散越之火，一扫而尽，而咽中之痛，稍缓复盛。脉数右寸关较大，而不耐重按。窃思少阴肾脏，是藏精之地，为乙癸之源。考少阴之脉系舌本，循喉咙，诸经之火既收，何独咽痛不与偕退。良由肾液燥涸之甚，阴气不能下吸，则虚阳难以潜伏。诚恐糜腐大起，阴阳不相抱负，而致虚脱，兹与屐莓仁兄先生商用仲景猪肤汤，以救少阴之燥，合阿胶鸡子地黄汤，以救肝肾之阴。转变百出而致于此，得失之数，在此一举，若得应手，便是转危为安也。", "8013": "右面发泡疮，目胞赤肿，身热脉大而数。此风湿热壅于阳络。先为清泄。", "8014": "郁（左）左目红赤，目胞肿胀，泪下多眵，脉形浮滑。风热内郁。先为清解。", "8015": "某（左）两目并不红赤，多眵模糊，视物少神，睛脉不清。素体湿痰，此非风火为恙。", "8016": "徐（右）目为肝窍，为脏腑精气之所聚。目疾之后，眦痒多泪，脉数微弦。此风热未清，风为阳邪，其气通肝，所以风即为热。拟养血清肝熄风，俾不致伤精气为上。", "8017": "二诊脉症相安，但右目不赤不痛，不因见风亦时常流泪。是肝胆气弱，肾水不足，虽有风邪，不能自越。以丸药缓图之。", "8018": "二诊化浊熄肝，脉症相安。前法出入，再望应手。", "8019": "左左脉虚弦。牙疼胸闷，肝阳走于胃络也。", "8020": "王（左）左偏齿痛微肿，先觉脚冷，火升则其痛益剧，其为阴虚火痛无疑。脉滑而数，苔薄白，治宜养阴降火，略参清疏之法。", "8021": "江（右）阴分素亏，虚阳上亢。牙缝出血，时觉浮动。脉弦带数。虚热走于胃络，此谓齿衄，又谓牙宣。当育阴以制其阳。", "8022": "李（右）牙龈肿胀，牙缝出脓，畏风肢体疲软。脉象细涩，关部独弦。厥阳走于胃络。拟清胃泄肝。", "8023": "沈（左）下则遗精，上则眩晕，甚致呕吐欲仆，耳鸣失聪。脉弦尺虚。此肾本空虚，木失涵养，致阳气化风，尽从上越。拟滋水潜阳法。", "8024": "二诊遗精眩晕，耳鸣渐聋，右目翳障。脉弦尺涩且数。阴虚火盛。拟滋水清肝。", "8025": "四诊耳鸣窍闭，头胀眩晕，滋肾养肝。脉弦且带滑数。稠痰灰黑，目翳障不化。肾水不足，木火上腾，炼液成痰，痰随火生，清空之地，遂为痰火所占。急则治标，缓则治本，经训如此。", "8026": "五诊清火豁痰，脉弦滑转为细弱，浊火已退三舍。而眩晕呕吐，咽燥口干。经谓头痛巅疾，下虚上实。再填实其下，以治其本。", "8027": "洪（左）耳鸣不止，耳窍闭塞。脉象弦滑。此肝风挟痰上逆，致浊邪阻塞清窍。病已经年，恐草木不能遽然奏效。", "8028": "范（左）肝火熏蒸，上逼于脑，致鼻渊久漏不止，气味臭秽。脉细弦，左尺小涩。深恐脂液枯槁，而致难支。", "8029": "杨（左）浊涕从脑而下。脉象细弦。此阳明湿热，熏蒸于肺。姑导湿下行。", "8030": "左鼻窍窒塞，而咳嗽却不甚盛。脉形滑大。此肺热内郁，浊火上蒸也。", "8031": "卢（左）火风已解，而平素动辄鼻塞。脉气口独大。此浊火上蒸于肺。宜清宜泄。", "8032": "右阳明脉络空虚，风阳窜络。背痛不止，偏右头痛。去年咯吐见红。亦属木火亢甚。平肝泄热勿望一蹴而几也。", "8033": "孔（左）背腧牵掣不舒，不时眩晕。脉象细弦，舌红苔白而渴。阳明络虚，风阳上僭。宜通补阳明，参以熄肝。", "8034": "恽（左）肝气偏旺，湿痰复盛，以致肝气挟痰入络，左肩臂酸痛。脉象弦滑。宜化痰以宣络隧。", "8035": "二诊宣通络隧，搜逐湿痰，浊气下行，大便畅解，右肩臂酸痛大退。脉弦稍柔。药既应手，宜再扩充。", "8036": "三诊肩臂作痛渐定，而湿痰不能悉化，肺气为痰所阻，行动气觉短促。脉象沉弦。痰饮内盛，不流于彼，即聚于此，其病虽殊，其源则一。", "8037": "杨（左）平素每易呕痰，兹则腿股作痛牵掣，腰膂亦觉不舒。两关脉滑。此痰湿流入经络。", "8038": "孙（左）热势递减，头痛仿佛止住，然右足作痛异常，色带赤肿。脉数细弦。肝火湿热袭入足三阳经，脚气情形。况从湿温传变而来，恐有冲心等患。", "8039": "荣（左）左足膝仍然作痛。脉数滑，苔白质腻。风湿热袭入足三阳之络，为势尚盛。", "8040": "邵（左）上春两膝作痛，几成鹤膝。今则外寒束缚里热，致风湿热袭入络隧。腿前廉两肩臂作痛，不能举动，痛后经络烙热，内经所谓脉痹，即热痹也。拟辛温寒以通络泄热。", "8041": "左两足肿胀，按之坚硬，肌肤麻木不仁，肢体头面亦觉微肿。脉弦微滑。此风与湿袭入脾脏。急宜疏泄。", "8042": "某腹痛甚剧，时痛时止。脉关弦，右部带滑。此由湿热内郁，肝木不克疏，泄蛔动情形也。", "8043": "二诊脉象虚软，气口及左关俱带浮弦，其为气血亏损，风邪乘虚而入，略见一斑。前法参以祛风。", "8044": "梁（左）湿热流入筋骨，遍身作痛。脉象弦紧。宜祛风理湿。", "8045": "二诊脉弦紧稍柔。肩胛腿膝酸楚，步履疲软。湿热未楚，肝肾已虚。再从厥少二阴主治。", "8046": "三诊培补肝肾，兼清湿热，脉证相安。然两手腿股广痘未消。前法仍参清化。", "8047": "余（左）脉细弱，重按微滑。下疳虽愈，而阴茎短缩，近根带肿，溺有余沥。此湿热袭入肝肾，易入难出，不易图治，拟以丸药入下。", "8048": "陈（左）湿毒深伏于肾，曾经淋浊，横痃下疳，虽经治愈，而喉间糜碎，经久不除，舌下肿胀。脉细而左尺坚硬鼓指。以少阴之脉系舌本、循喉咙，此响而彼应也。拟方请专门名家采择。", "8049": "左湿火深伏于肾，少阴之脉上循喉咙，以致咽辄哽痛，背脊轰热，直至头巅，脉象细弦。极难奏效，以病久而且深也。", "8050": "唐（左）气血两亏，肝火挟痰，窜入少阳阳明之络。颈项结核坚硬，按之不移。脉虚弦滑。恐虚痰不化，而延入损途。", "8051": "张（左）盘颈疬痰已久，兹则内热连绵，时见咯血，胸膺酸痛，日来腹痛便泄。脉细弦而数。阴虚木旺，虚火上炎，木乘土位。虚损情形，何易言治。", "8052": "二诊酸甘制木，以养脾阴，腹痛便泄已止。然虚火上炎，血虽未来，而咽痛音闪。脉数细弦。脏阴皆损，何易言治。", "8053": "三诊音声已开，咽痛亦止，而中脘犹复作痛。脉象细弦，舌质纹裂。疬痰既久，气血并亏，不能制伏肝木，致强肝克土乘脾则腹痛便泄，犯胃则脘痛呕吐。急者先治之。", "8054": "七诊胸膺作痛稍轻，不自觉热，而脉形带数，阴伤火炽。然痰核随处结聚，恐其流窜。再熄少阳木火，参以化痰而和藏络。", "8055": "八诊脉象稍缓，舌红苔腻。左胸膺作痛，牵引背肋，络隧不和。再宣通化痰和中。", "8056": "二诊脉数转缓，内热已退，而滑泄频来，环口常发疹㾦。阴虚挟湿，混淆精窍。前法参以分清。", "8057": "三诊分清精水，滑泄未来，而右半体仍觉牵掣。良由痰阻络中，脉络从而不和。拟化痰宣络。", "8058": "三诊宣通营滞，大解带黑，脘痛呕吐俱减。然咽中常觉哽阻，中脘仍然坚硬。脉象弦紧。效方扩充，再望应手。", "8059": "二诊咽中如阻，中脘不舒，筋脉跳动，甚至欲厥，经一月再行。营血久亏，风阳震动。再育阴以涵肝木。", "8060": "董（右）少腹作痛，经事不行，脉形不爽，面部丹赤成片，不时发露。营气不宣。宜为宣通。", "8061": "二诊经停少腹作痛。营气滞而不宣。当通和奇脉。", "8062": "王（右）木旺脾虚，肝木克土，土不运旋，以致腹笥板硬，时为痛泄，月事不来，胸次痞闷。脉象弦硬，气血郁滞。拟宣畅气血，必得月事通行，方为稳妥也。用严氏抑气散合逍遥法。", "8063": "沈（右）阴虚气弱，脾不运旋，封藏不固。每至冬令，辄易感风，大便或结或溏，经事愆期，不时带下。脉濡细，苔薄白。拟气阴并调。", "8064": "二诊脾虚则大便或结或溏，肾虚则封藏不固。收藏之令，辄易感冒咳嗽，经不应期，时为带下，脉象濡细。气阴并调，从前法扩充。", "8065": "三诊脾虚则不运，肾虚则不藏，脾不运则大便时溏，肾不藏则封固不密。每至冬令，易召外感，而为喘咳，经事遂不应期，带脉从而不固。宜从脾肾并调。", "8066": "胡（右）十二经之血，注于冲脉，从冲脉而下者，谓之月经。冲为肝之隶脉，情怀抑郁，木土失和，中脘作痛。冲脉之气，因而阻滞，经事数月方行，面色浮黄。唇白舌淡无华，脉象细涩。气血皆滞，当为宣通。", "8067": "二诊宣通营滞，脉细稍起，经事未来，脘腹作痛。久病营血必滞。仍为宣通。", "8068": "某（右）经来淋沥，少腹作痛，腿股牵引不舒。冲瘀未清，则冲脉转难固摄，恐壅极而致崩败。", "8069": "朱（右）经来淋沥，少腹作痛。脉弦尺涩。冲气不调，则冲脉不固矣。", "8070": "某（右）经停十五月之久，而起居如常，脉缓苔薄白，此名为歇，不治自愈，但须徐以待之耳。", "8071": "林（右）诸经之血会于冲脉，从冲脉而下者，谓之月经。冲气不调，经来血聚，冲气不通，所以胀势每甚。仿金匮温经法。", "8072": "钱（右）经事愆期，腹痛脐下滞坠，按之尤痛。冲脉气滞。姑为宣通。", "8073": "朱（右）经前腹胀，带下腰酸，悸眩少寐，心中作痛。气滞血少，血不养肝，奇经之脉，隶于肝木，木旺则阳气升浮于上，带脉不固于下。拟补血之不足，疏气之有余。", "8074": "右经事先期，寒凛火升，嗳噫眩晕。苔黄，脉弦尺涩。此肝阴不足，胆胃之气少降。拟通降阳，明参泄肝木。", "8075": "丁（右）经事愆期，虚寒为多。然虚则肢体必形软弱，或微微身热。寒则腹中痛，脉必沉细。今经来日迟，诸如平人，惟四肢作酸。脉象濡滑。此痰湿占于血海，营卫之气不得宣通。宜理气化痰驱湿，不治血而治其所以病血者。", "8076": "朱（右）经来淋沥不止，少腹酸痛，偏右痞块攻筑，血色紫殷。冲脉气滞。宜调冲任而宣气滞。", "8077": "二诊淋沥仍然不止，中脘痞闷，少腹酸坠。冲气不和，冲脉不固。拟和营平木。", "8078": "江（右）曾经血崩，营血亏损，不能养肝，肝木克土。不时便泄，脐下气聚不舒，四肢节骱痰核结聚，咽中如阻，心悸带下。脉虚弦，舌心光剥。水亏木旺，土弱肝强。养血柔肝，为治本之道。", "8079": "粱（右）带下腰酸，小便不禁，心悸火升。带脉不固，肝肾空虚，阳气上逆也。", "8080": "二诊带下大减小便亦能约束，心悸火升。的是阳升而奇脉不固。效方进退。", "8081": "三诊带脉渐能约束，火升亦定，然寐醒舌干口燥。阴液耗损不复。前法参入甘凉。", "8082": "莫（右）从少腹作痛，以致带下腰痛。冲气不和，带脉因而不固矣。", "8083": "顾（右）赤带绵下，遍体作痛，小便烙热，甚则微痛，头空昏晕。脉象带数。肝火湿热沦陷于下，带脉从而不固矣。", "8084": "右久带不止，腰府酸楚。脉形滑大。此肝火湿热沦下。恐损而难复。", "8085": "汤（右）带下腰楚，中脘作痛。脉象濡软。八脉不固，湿热沦下也。", "8086": "右不时气喘，喘则欲厥。偏右头痛，带浊绵下。脉象弦滑。此饮阻肺下，痰水之气上则逆射于肺，下则沦陷于脾。用丹溪法。", "8087": "右半产之后，继以血崩，崩则八脉损伤，带脉不固，带下连绵，按月经来甚多，维护皆失其职，不能急切从事也。", "8088": "右肝经之脉环阴器。所见之象，形非枣核，似未可作阴茄论，仍是阴肿痛而已。按方书皆外治之法居多，至于内服之方，未必大备，今臆拟逍遥散法以舒木郁，略参宣畅气血之品。以备商榷。", "8089": "金（右）淋带漏下，少腹自觉冷气结聚，气分攻撑。此冲气不和，冲脉不固，为崩败之先声也。", "8090": "某（右）崩下之势，尚算和平，而呕吐恶心，滴水不能容纳。脉细弦，苔浊质腻。此由血去过多，木失涵养，致厥阳冲侮胃土，胃中之浊阻而不降。恐致痉厥。", "8091": "徐（右）崩带日久，脉形濡大。年近花甲，中气虚而不摄。恐难以草木奏功。", "8092": "严（右）久咳痰多气逆。脉象沉弦，苔白黏腻。此饮邪阻肺，而天癸当止反多。恐有崩坏之虞。", "8093": "某（右）崩淋不止，腰府作酸，其血即下。奇脉暗损。再参固摄。", "8094": "刘（右）经积九月而崩，崩后又停年余，腹满不和，脐下气坠，胸脘灼热。脉形沉滞。此血因气滞，冲脉阻闭。若壅极而决，必至复崩，不可不慎。", "8095": "范（右）崩漏数日不止，始则少腹作痛，今则痛止而觉作酸，间数日辄成块作片而下，头晕耳鸣，面色浮黄，饮食少思，中脘不舒。脉数濡软，舌苔浮白无华。此久崩之下，肝脾并亏，统藏失职。恐血复下而致晕厥。", "8096": "张（右）漏经不止，成块作片而下。迩则胸脘不舒，涎涌作恶，气撑腹满。脉细，关部弦劲。此由阴血失营，致厥气冲侮胃土。恐虚中生变不可不慎。", "8097": "又调气镇逆，而和肝胃之阴，作恶较定，复下血块，气撑胸满，由此而松。良以冲为血海，其脉从气街夹脐上行，而散于胸中，冲瘀既行，则胸中之气自展。特口中黏腻，津液悉成涎沫，不能下咽，频吐之余，喉舌转燥，舌边白糜星布，脉虚左大，右关无情。胃阴耗残之甚，恐虚火挟浊上蒸，而糜腐大布，所谓虚中生变者，即此而是。", "8098": "又昨进降胃之逆，和胃之阴，口腻恶心顿减。其为胃阴耗残，略见一斑。脉象较敛，舌糜已化。药既应手，宜再扩充。", "8099": "石（右）腹中胀满，𩠎杂欲呕。脉象弦滑。经停二月有余，恶阻而兼肝气不和之象也。", "8100": "陆（右）感风咳嗽。脉象弦滑而浮。怀孕在身，勿犯其下。", "8101": "某（右）经停三月，每月淋沥，色正赤且鲜，气攻漉漉。脉弦而滑。此气分不和，致血紊乱，胎漏之象也。", "8102": "盛（右）月前曾下黄水，胎元不能固摄，才有渗漏之事，适又劳动，胎系震损，今晨又复见红，腰酸腹满。脉缓急不调。急为安固，参以理气，盖安胎以理气为先也。", "8103": "穆（右）经停五月有余，不时漏下，饮食起居，悉如平人，脉缓微滑。胎漏见象。宜和阴泄热，参以调气。", "8104": "二诊漏下已止，脉缓微滑，起居如平人。良由血热不固，仍从胎漏主治。", "8105": "右肝气纵横，食入不舒者已经多月，至昨偶食瓜水，寒气不运，脘腹胀满异常，流行皆阻，水气更郁，致面色清淡，卫气阻窒，肌表凛凛恶寒。脉细沉弦，而呼吸仅得四至，舌色淡白。此气分寒滞，气机闭塞，正当心胆脉养之际，深恐损动胎元，致生意外之变。", "8106": "右向有痰饮，咳嗽痰多，习为常事。兹则怀孕七月，肺经养胎之际，咳嗽增盛，渐至遍体浮肿，气升不能著卧，转侧向左，气冲更甚，大便溏行，凛凛恶寒，头胀目昏。脉象沉弦，舌苔白腻。病从烦恼而来，肝气挟痰饮上逆，肺气不能下降，则脾土失其运旋，遂致水气泛溢于肌肤分肉之间，名曰子肿恐肿。甚生变。拟越婢汤发越脾土之湿邪，参以化痰降气。", "8107": "沈（右）妊娠素体阴亏，泄泻久延，脾阳损伤，而复汗多亡阳，肝肾之阴，愈加耗损。经崇山先生叠投温摄，泄泻顿止。然阴分既耗，何能遽复。遂致木失涵养，风阳大动，每至欲寐，辄梦魇纷纭，唇燥口噤，四肢牵强，不能举动，忽笑忽哭，所谓风善行而数变也。虚火风上浮，津液为之蒸炼，则凝滞为痰，痰阻肺胃之间，甲木更难下降，是直两木同升，所以吐出凝痰，则诸恙稍减。胎系于脾，而养胎者血也。今病久而致血虚风动，腰酸胎坠，亦所必至。脉象虚弦，舌绛无苔。若不期而产，虚之再虚，定有不堪之境。为今之计，惟有养阴以潜伏阳气，补气以固胎息，而以镇护化痰参之。能否应手，留候崇山先生商定。", "8108": "右产后数载，经事不行，然于当至之期，辄腰腹作痛，有欲行不行之势。此冲气不和，冲脉不利，理宜宣通营卫。兹以喉证之后，余毒未清，不得不为兼顾也。", "8109": "刘（右）产后两月，下痢不止，色黄而腻，身热脉濡。气湿不宣，恐成休息。", "8110": "右产后恶露未清，营气阻滞，营失流畅，气聚成形，腹中痛胀，寒热往来。脉数而弦恐从实变虚，而至难复。", "8111": "马（右）新产之后，气逆如喘，痰多白腻，不能著卧。心悸汗出，耳鸣头晕，悉与气逆之轻重而为出入。夫产后发喘，历代名贤咸以为阴虚虚火克金，肺气欲绝，最为危险之候。救援之法，则有生脉。阅前方按法施治，应验不验。详询起居，知胎前与初产之时，曾以湿巾揩身，窍毫疏泄，百脉弛张之际，其水寒之气，袭于外则应于内，内经谓形寒饮冷则伤肺，以其两寒相感，中外皆伤，故气逆而上行，经文如此，与病大致相符。今诊六脉虚微，右寸关沉弦。半身以上疹㾦密布。外无感触，安得有此。云翁先生所见独精，药归平淡，转比生脉等方稍有起色。兹从其意，略再扩充，作背城之一。但病在危急，平反前方，济与不济，非所计也方草商之。", "8112": "王（右）产后旬日，外感风邪，头痛发热，得汗不解，两日来恶露涩少，少腹作痛，按之微硬，牵引腰尻，动辄作痛。脉数浮大，左部沉迟。风邪袭于外，气瘀阻于内，恐成时证。姑疏风而宣通营卫。", "8113": "王（右）怀孕七月，忽然头痛发痉，神昏不语名曰子痫。都缘胎热有余火风鸱，张胎受热迫，竟至胎坠。乃小产之后，恶露不行，神糊妄语。脉象弦紧。此由败血上冲，极为危险。拟方请商。", "8114": "周（右）产后恶露未行，气血凝滞，腹中有形作痛，临圊更甚。脉细关弦。气升汗出不止。此营滞阻气，气滞为液，液泄为汗。宜宣通和化，所谓通则不痛也。", "8115": "汗为血之液，夺血者无汗，此指脱血者言也。产后瘀露，乃有余之血，非脱血可比。初产百脉沸腾，阴虚阳亢，啜热汤饮而津津汗出者，此卫气流通，阳从汗泄，身体自觉舒和。金匮云亡阴血，虚阳气独盛，故当汗出，阴阳乃复，此之谓也。若绝无汗，则卫气闭塞，必将有发热之症矣。所以产妇宜微汗，而不宜无汗，宜有汗而不宜多汗。案中荣滞阻气数语，得古圣之粗髓而融化之，言言金玉，字字珠玑，直足与金匮相颉颃矣。（文涵志）", "8116": "三诊脉弦稍收，便稍转润，临圊作痛亦减。足见血燥气滞，府浊因而不泄。前法再参破浊。", "8117": "李（右）胎前感风，产后不彻，咳嗽三月有余，痰多口腻，凛寒内热，汗出不能左卧。脉象细数微滑。久咳损肺，阴阳之二气有偏，气即为火，液即为痰，证入损门，非才疏者所能言治也。", "8118": "朱（右）产后匝月，少腹坠痛，腿股腰尻作酸带下阵阵，向来并有结块同下，腹满不舒，胃钝少纳，脉象弦紧。此由旬日之间恶露停留，旋虽复至，而脉络已滞，遂令瘀浊化带。恐其崩败。", "8119": "郑（右）因痢而产，产后痢仍不止，腹痛里急后重，恶露不行，少腹按之硬痛，所下之色。夹杂瘀黑，杳不思纳，胸脘不舒。脉滞而硬。此暑湿热三气郁阻肠中，瘀露不行，府气更加郁结。胎前下痢，产后不止之条，古人言之郑重，非虚语也。勉拟通化一法，以希天佑。", "8120": "二诊投剂之后，屡下紫黑瘀块，少腹亦舒，圊数顿减其半。然临圊犹然后重，气坠不爽，全不思纳，胸中似乎有物哽塞，由此而饮食更觉妨碍。脉虚无力，苔白少华。恶露既通，府中之阻滞稍宣，而中阳结痹。虽得转机，尚不足恃也。", "8121": "三诊头面遍身发出赤㾦，口渴较前稍定。暑热之气，藉得外越。无如少腹结块虽消，而按之尚觉作痛，下痢虽大减疏，然昼夜犹然在二十次左右。少腹之痛松，则胸中之痛甚，上下互相联络。良以冲瘀未清，则冲气逆上，盖冲脉起于气街，而布散于胸中，所以此响而彼应也。鼓棹迎风，茫茫涯岸。再为宣瘀，以冀冲脉得通，胸中得旷，若能安谷则昌。", "8122": "某（右）产后旬余，偏左头痛，恶露通行，频有带下。脉形弦细。此血虚生风，而阳气上升。姑养血熄肝。", "8123": "某（右）新产九朝，甫产之后，血从上冒，幸半时之久，即得安定。而肝阳由此上逆，冲胃则为呕吐，乘脾则为泄泻，扰神则为不寐。今胃逆之极，甚而作呃。脉左倍于右，按之鼓指。深恐阳升太过，而致发厥。急为镇逆，参以宁神。", "8124": "储（右）产后恶露淋沥，偏右肢体络隧不舒。人身左半主血，右半主气。右半不舒，似属气病，殊不知左半虽血为主，非气以统之则不流，右半虽气为主，非血以丽之前，易散。今脉象坚细，重取带弦，系陈者不除，新者不布之象。拟和营调气，俟淋沥止后再商。", "8125": "黄（右）向有肝阳，营阴虚亏，而以多食桂圆，辛甘温热，血热内迫，胎息不固，遂致四月而坠。胎下之前，与胎下之后，血来如涌，营血暴亏，风阳上逆，一时头晕耳鸣，神识昏乱，幸即平定。然神情倦怠，言语有时错乱，目从上窜，手足搐动，频渴引饮，二便皆热，阴户碎痛。脉象虚弦，舌苔浮糙。皆由血虚之极，不能荣养肝木，木燥生风，有厥脱之虞，不可泛视也。拟滋肾养肝。", "8126": "邵（右）腹满不舒，中脘痞胀，肝气郁于胃中也。乳尖属肝，乳房属胃，气滞胃络，乳中结核。气郁生火，内热连绵，咽中时痛，膝膑起块，无非气火之有余，或炎于上，或窜于络耳。脉弦而数，亦属木旺之征。病绪繁多，而图治必从要处著手，内经谓气有余，便是火，宜从肝胃两和，能使气机宣通，郁热自退三舍也。", "8127": "钱（右）脉证相安。两乳房结核，时作微胀，经迟涩少。此气郁而营分失和。再调气和营。", "8128": "李（左）脾虚则生湿，气弱则生痰。然中气空虚，何至胆阳上逆而为眩晕。脉滑，重取濡软。良以脾虚胃实，脾虚则液滞为痰，胃实则胆逆为晕。拟外台茯苓法出入。", "8129": "林（左）经云、卫气者，所以温分肉，充皮肤，肥腠理，司开合。足见阳气流行，断不容有所留阻。气虚生痰，痰湿内伏，流行被阻，卫气不能敷布。四肢每欠温和，神情难于振卓，而脉形沉弦带滑。有似阳衰，其实阳气不能从中用事耳。拟补气化痰，宣畅阳气。", "8130": "薛（左）脘胁肋攻撑，甚则作痛，脉象沉弦，为饮气内伏，曾用控逐之法，泻水甚多，然气分仍难舒展。夫中脘属胃，两胁属肝，胃喜通降，肝喜条达，脾胃失于健运，则胃中之水湿停留，中土气滞，木难疏泄，以致厥气郁滞，与土相仇，攻撑痛满之类纷至矣。从肝胃疏和。", "8131": "某尾闾为督脉所过之处，为二阴关键之区。淋浊止涩，湿热内留，遂致尾闾作酸，诸药罔效，日久不瘳，甚至投以参茸，犹未能却病。湿压气坠，少腹似胀似痛，湿胜而脾运不及，大便既溏，而且带泄。及至利气调中，苦温合化，如鼓应桴，诸恙若失。刻当初愈，似须补其真阴，调其督脉，殊不知补阴之药，性多呆滞，若漫行尝试，湿热复壅，所得不偿所失也。兹拟于调中利气，苦温合化之中，参以补而不滞之品。当否正之。", "8132": "江（右）肩背作痛，脊强腰折。夫腰为肾之府，背为阳明之府，腰背皆痛，而脉浮弦，良由肾本素亏，风与湿郁，遂致太阳之经气不行。宜于养营和络之中，参以胜湿而宣畅气分。", "8133": "沈云卿夫人脉象常数，左部带弦。绕耳前后，痰疬重叠，遇劳即发，发则似痛似胀，幸按之不坚，根脚尚带浮动。四肢不时灼热，心悸不宁，气分攻撑，头旋眩晕，腰酸带下。夫耳之前，后为少阳部分，肝主生发，若一遇怫郁，即不能遂其畅茂之性，气郁则生火，火郁则生痰，肝火挟痰上升，而胆经之气，偏主下降，欲升不能，欲降不得，于是横行漫溢，流入于少阳之经，凝而不散，所以垒垒然有形矣。木火既盛，则营阴被烁，以致阴分日见其亏，气分日见其旺，气撑肢热火升等象，皆出于此。阳气震撼，故心神怔悸，而眩晕头旋。木郁不调，脾清沦陷，津液随之渗泄，故带下连绵，液耗肾虚，腰府酸楚矣。拟泄木养营，和阴凝神，参以消散痰疬。当否即请云卿正之。", "8134": "李（左）平时咯吐灰黑稠痰，渐致吐血，叠投清养上中，以平浮热，复入辛温，而血得止。今诸臻平适，黑痰亦不多见。脉象沉细，右寸关滑大。确系湿痰内盛，水寒之气，迫热上行，损于肺胃之络，不然安有血症而可投辛温之理，且投辛温而可奏效之理。药既应手于前，法当遵循于后。", "8135": "窦（左）少阴之脉系舌本，循喉咙，喉有石鹅，不时身热。夫手少阴心，火也，足少阴肾，水也惟火旺斯水愈亏，惟水亏则火愈旺，两者相因也。童真未足，所见症象如前，其为阳有余阴不足何疑。补其不足，泻其有余，不易之定理也。", "8136": "陈（左）右脉微滑，左关脉独弦，弦为风木，偏亢之征。据述别无他恙，惟有时冒眩。夫阴虚木旺，木燥生风，亦令眩晕，若系阴虚，安得于眩晕之外，别无兼症。吾人脏阴而腑阳，脏升而腑降，体之阴者其用阳，是谓阴中有阳，体之阳者其用阴，是谓阳中有阴，故离虚其中，坎满其中也。肝为乙木，胆为甲木，肝为脏而胆为腑，一脏一腑，表里相应，与脾脏胃腑相附而升，相附而降，故肝合脾升，而心血以生，胆合胃降，而命火以长。今右脉微滑，胃有湿痰，而胃欠通降。胃降不及，则胆经之气，安能独向下行。于是肝脾之升也有余，而胆胃之降也不及，有余不及，即是偏胜之肇端，阳偏于升，而为眩为晕，亦固其宜。若壮水以涵养肝木，而潜其阳气，惟阴虚阳亢者，有阴以制阳之效。若胆胃少降者，得阴柔之品，则胃府愈窒，胆愈难降，斯肝愈上升。欲平其肝，当降其胆，欲降其胆，当降其胃，管窥之见，未识有当否。", "8137": "巫（左）陡然发厥，厥后不时𩠎杂，然得食又复痞满不舒，脉来弦。滑此由痰气内滞，甲木升浮，遂致一时之间阴阳闭塞，胃失通降之权，木邪从而摇撼。宜通补之中，参以化痰熄肝。", "8138": "孙（右）胃痛呕吐者久，叠从肝胃主治，旋止旋发，数年以来，未得大效。脉象沉弦。夫肝虽横暴。无刚锐无穷之理，胃虽被犯，无终始不和之理。盖由胃有痰滞隐伏，虽曾攻逐一鼓而下，其胶稠凝聚者，依然内踞。特猛剂断非久病所宜。拟以胃苓法，寓猛于宽，以觇其后。", "8139": "丁（右）经事愆期，虚寒为多。然虚则肢体必形软弱，或微微身热，寒则腹中痛，脉必沉细。今经来日迟，诸若平人，惟四肢作酸，脉象濡滑。此痰湿占于血海，营卫之气不克宣通。宜理气化痰祛湿，不治血而治其所以病血者。", "8140": "周（右）经、常也，不失其时，其来有信，故请之经。然必冲脉通流，心脾生化，源源相济，自无阻滞之虞。今月事每数月而来，临行并无痛胀涩少之类，惟于清晨阳旺之时，腹中微微而热。脉濡细，左关微弦。此营血不足，虽至一月，冲脉未满，所以迟迟其来。拟调气以生血。煎方恐不耐性，而浅尝辄止，用以丸药缓调，丸药尽再觇动静投药。", "8141": "宣（右）经事愆期，腹并不痛，惟来反过多。脉小软左涩，良以气血不足，营卫流行迟钝，八脉拥护无权拟补气益血，参以升清。", "8142": "裘（右）头痛起于新产。前人于头痛，都以眉骨之痛否，辨外感之有无今额作辛胀，而眉骨却不作痛，且脉见细软，其为血虚风壅阳络，略见一斑。仿竹林子玉露散法。", "8143": "程（左）目糊不明，并不红赤肿胀。历投药饵，凡属阴滞之剂，即觉欠适，余则如化湿祛风豁痰之品，尚属和平。脉象沉细而糊。经云、五脏六腑之精气，皆上注于目，而为之睛。又云、瞳子黑眼法于阴。故目疾由于阴精不足者多。然经文又云、阴阳合传而精明也。足见阴虚而阳火离散，与气滞湿郁而真火无光，皆足为障碍之缘起。拟药如左，备质专门名家。", "8144": "左膈消之症，叠投清金益阴，制伏君火，大势已退。而口渴终不能全愈，苔黄心糙。良以肺热来自少阴，而胃府浊痰，郁即生热，胃脉通心，故令君火日动不已，则必移肺。兹拟开展气化，弗令胃中有所蕴郁，即是不治热而治热之法也。", "8145": "王（左）失血往往盈盆而至，然屡经大吐，未几一切如常，若论阴亏，则火且由虚而起，何况血去之甚多乎。今诊右关脉滑大有力，两尺俱觉敛静。其血之上冲，由于胃之湿热蒸燔，迫而使涌，不言可喻。所以血去多而一切如常者，以阳明多气多血故也。刻下左胁时觉霍霍有声，盖胃热上蒸，则肺肝气逆。调理之策，惟宜清降胃土，而平肺肝，勿犯实实虚虚之戒。", "8146": "虞（左）曲直动摇，风之象也。因有是言，故世俗凡遇心中震荡之疾，莫不以为心血之亏，肝液之耗也。殊不知动摇虽系风象，而仲景痰饮门中，则曰心下悸者，为有水气，足见悸荡之疾，有虚有实，全在临症辨认之耳。脉象沉弦，面色晦黄，全无阳气有余之象。而每遇操劳，或暮夜临卧之时，心中辄悸，平素多湿之人，正与金匮水停为悸之条符合。用药不宜呆补，温理脾胃，即是补中寓泻，泻中寓补之法也。", "8147": "鲍（右）经云、阳气者所以温分肉，充皮肤肥腠理，司开合者也。病后而四肢常欠温和，似属病伤阳气，阳虚则分肉不温，所以肢为之厥。经又云、阳气者若天与日，失其所则折寿而不彰。足见阳气一失其所，尚如此之可畏，何况实系阳虚，而至于四肢厥逆哉。细察脉情，濡而带滞，谓为病后湿郁，阳气不能敷布于四末则可，谓为阳气式微，不能充达于四肢则不可。盖一由于阳气之衰竭，一由于阳气之不治，不可不辨也。若执阳气温分肉之例为言，则与失其所折寿不彰之条刺谬矣。以意会之，自有至理存乎其中。拟补气运湿，以宣其阳气运行之道路。", "8148": "尹（右）中脘不时作痛，月事不调，白带绵下，甚则头疼眩晕，遍身经脉抽掣，骨节作痛。肝为风木，必得真水涵濡木火，遂其生生之机，自不致有化火生风之弊。今带下频仍，脂液耗损，木失涵养，则厥气冲胃，胃脘作痛。抑则为气，升则为风，风主动摇，所以脉络抽掣，甚而作痛也。宜养血调气，兼益脾肾。至于孕育一层，苟得气血充和，自有造化天然之理。", "8149": "李（左）阴阳者，万物之纲纪，变化之父母，左右者，阴阳之道路也，阴阳相贯，如环无端，故太过者病，不及者病，经旨如此。忆自初诊之时，腿股厥而欠温，继则每有重著之处，辄觉脉络不舒。如谓腿股欠温，阳气必虚，虚则不能旁达，理亦近是。岂知阳气衰微，必肌肤淡白而少华色，一经温补，必精神焕发，百病蠲除。而见症如前，容光华泽。补阴而至于血肉之品，则龟甲为阴之极也，补阳而至于血肉之品，则鹿茸为阳之极也，乃服鹿茸在前，诸病杂出在后，脉象濡而带滑，因知阳气并无所损，而有似乎损者，阳气之有所不通也。补泻之关键，毫厘之千里，于此而分。所以并无补养之品，药辄应手，于以知阴阳相贯，则变化生生，自无太过不及之弊。今病象已得减轻，是善后之计，乃及今要务。夫阳气运行，本无所阻，所以阻者湿也。湿土之下，燥气乘之，所以湿郁之甚，而风即暗生，脉络不和，诸象皆由此致。及今之计，惟有运化浊痰，分消湿热。然分化太过，未免戕伐，因以补气之药参之，务期阴阳相生，道路交通，太过不及，各得其平，即是颐养天和之道。爰拟补气培脾养肝，以作调摄之资。而上则宣肺，中则和胃，下则分利膀胱，三焦流畅，湿痰自无容足之地，譬如一室氤氲，洞开前后，顷刻干洁。拙见所及，质之高明者，以为如何。", "8150": "某脉右关独大，饮食起居如平人，而面色无华，口有秽气，时觉口渴。夫口臭者，胃热也，口秽且渴，胃热明矣。经云、心者生之本，神之变也，其华在面。今面色无华，又似心经主病。良以心主血，营出中焦，今胃中常被热灼，胃液常不能自养，而欲求救于水，水谷之气，化血微少，血液不充，自不能上华，其面。治之之法，清胃热即所以裕其生血之源，非无理蛮补所能塞责者。", "8151": "某夙有哮喘，肺气不克下降，脾土不主运旋，始则生痰聚饮，继则气机凝滞，不能通泄，以致少腹疝瘕，脐下有形，小腹胀满，按之坚硬。少腹两旁属肝，居中为冲脉，经谓冲脉为病，男子内结七疝，女子带下瘕聚。良由冲气不调，则脉络皆阻，为积为聚，由是来矣。宜宣通脉络。勿谓冬季膏丸，须藉滋补以养生却病，邪之不去，正与何有。", "8152": "钱（左）卧则气逆，大便兼旬方解，四肢不时厥冷，甚则胸中热辣，似线上冲，得呕酸水则松，腿股筋掣，遗精频发。脉沉弦，苔白。此由痰饮内伏，上阻肺气则气逆，下困脾运则脾约，阳气之流行为之不宣。胃土失降，胆木漂拔，精关为之混淆。徒事呆补无益也。拟补气蠲饮，分化泄浊法。", "8153": "俞（左）疟后忽起遗泄，旋至多梦纷纭，体软力乏夫心实则梦可惊可忧，心虚则纷纭多梦。今脉象浮滑，且进分清之剂，遗泄转减。此盖由脾湿有余，扰动精关，心胆气浮，故有似心虚见象也。", "8154": "蒋（右）形体苍瘦，阴虚多火之质。春升之令，忽然发厥，当时神情迷愦，顷之乃醒。前诊脉弦微滑。良以相火风木司年，又当仲春升泄之时，阴虚之人，不耐升发，遂致肝脏之阳气，一时上冒，故卒然而厥也。调理之计，惟益其阴气，使之涵养肝木，参鳞介之属，以潜伏阳气。", "8155": "毕（右）咽中灼热者久，渐至头旋眩晕，甚则人事不省，片时乃复。脉细左弦。此由肝肾并亏，厥阳尽从上逆。宜育阴而熄肝镇肝。", "8156": "孙（右）久带不止，液耗阳升，头旋眩晕，肝肾空乏，足膝作酸。带脉者，如带之围绕，为一身之约束，带脉有损，则脾胃之湿，由此渗溢，脂液由此俱耗。宜补益中气，兼摄脾肾。", "8157": "徐（左）任行于前，督行于后，又督脉者所督护气血经络者也。龟背高凸，先天禀赋有亏。两膝膑时作酸痛，肝肾之空乏已甚。神疲力少，时或凛热，亦固其宜矣。治宜大益肝，肾并补八脉。", "8158": "张（右）高年气血两亏，营卫之气，不得宣通，遍身脉络抽掣，四肢不遂。腹为至阴，脏阴亏损，则脏络不和，运动之机，不能灵转，腹中常常拘急，下虚不摄，冲阳逆升，痰饮泛逆，气喘痰多，有时并发，营气不行，虚风自动。气可以补，血可以养，脉络可以宣，痰饮可以化，无如古稀之年，气血有亏无长，惟有循理按法，尽力之当尽而已。", "8159": "裴（右）产育频多，营血亏损，木失涵养，阳气升浮。夏月阳气泄越之时，往往头胀眩晕胸闷。若系痧胀，无动辄即发之理，其所以屡发者，亦由阳气之逆上也。兹又当产后，营气更亏，少肠之木火勃升，胸闷头晕汗出，手足烙热，咽痛音喑。盖少阴之脉，少阳之脉，皆循喉也。育阴以涵阳气，是一定不易之道。但泄少阳清气热之药。不能合入膏方，另以煎药参服为宜。", "8160": "刘（左）肺为华盖，位在上而其气主降，肾主封藏，位在下而其水宜升，所以升降相因，肺肾交通，而呼吸以匀也。胃为中枢，为十二经之长，主束筋骨，而利机关，脾弱湿困，胃为渊薮，中州湿盛，则肺降被阻，此稍一感触辄发咳嗽之微理也。胃湿蕴聚，则胃气不和，胃病则机关脉络不和，时为身痛。湿不自生，脾失运化而始生，脾不自运，气机鼓舞而始运，然则致病者湿也，生湿者脾也，脾之不运而生湿者气也。吴仪洛云、脾健运则湿自除。又云、气旺则痰行水消。洵哉斯言也。拟补气运湿为主。但调摄之方，自当顾及肝肾，择其不滞者投之，方为妥善。", "8161": "魏（右）经事无故，而不受孕，平日间亦无他恙，惟时为昏晕，或四肢烙热而酸楚，少腹时满。脉大有力。盖气郁则生热，热从内吸，则子宫枯燥，不能摄精，热盛则生风，风阳鼓旋，则头旋眩晕，脉络不和。养血益阴，固属要图，而泄热调气，尤为急务，非大剂补益便为良法也。", "8162": "梁（右）左脐旁瘕聚已久，发则攻筑，为痛为胀，偏右头疼，略一辛劳，辄绵绵带下。良以木郁不条达，厥阴之气滞积成形，下为瘕聚，上为乳疬。木旺而阳气上升，是为头痛。冲气不和，则奇脉不固，以致脂液渗泄。木郁宜舒，而肝为刚脏，其体宜柔，从养血之中，参疏肝调气法。", "8163": "盛（左）脉象濡滑，左尺少力，右尺沉细。壮盛之年，虽不至疾痛缠绵，而神情疲弱，时多迷睡。考伤寒六经，惟少阴篇有欲寐之文。良由命阳不振，阴浊弥漫，胸中阳气失旷。宜于调摄之中，仍寓扫荡阴霾之意，庶与少阴篇之章旨符合也。", "8164": "林（右）阴分久亏，木失涵养，肝强木燥，生火生风。阴血为热所迫，不能固藏，经水反多，甚至一月再至，营血由此更亏。阳气化风，上旋为头晕。撼扰神舍为心悸，为火升轰热，诸虚象杂陈。脉形弦细，左部涩弱，且有数意。阴弱阳强，急宜养血益阴，以配合阳气，庶不致因虚致损，因损不复耳。", "8165": "任（左）上则眼目昏花，下则阳道不通，有时火升面热，稠厚之痰，从喉中咯出。或谓真阳式微，阳道闭塞，则眼目昏花，火升面热，又系阴虚阳升明证，如以阳道不通与火升目花分为两途，则欲养其阴，必制阳光，欲助阳光，必消阴翳，未利于此，先弊于彼矣。或者阴阳并虚，水火皆乏。庸有是理。然果水火皆乏，安能形气皆，盛起居无恙乎。细察阳道不通，断非阳衰不振，实缘肾水不足，虚阳尽越于上，阳不下降，所以阳道不通，与阳气衰乏者，判如霄壤也。脉象弦大，尤为阳气有余之征。拟每晨进育阴以潜伏阳气，每晚进咸化痰热备方如下。", "8166": "蒋（右）心主灵明，胆主决断。灵明所至，虽虚幻之境，可以意构，惟有胆木决断乎其间，一举一动，方能合节。今诊脉象细弦，关部坚硬，人迎浮露，舌苔薄白。良以营分不足，木少滋濡，厥阳上升，甲木漂拔，失其决断之职，神情为之妄乱，目不交睫。刻下虽臻平定，而腹撑头晕，还是木旺见端。拟平肝宁神，交通水火。", "8167": "门人问曰、伤寒温病之异，近贤叶氏唱之，薜氏和之，可了然于心目矣。风温为温病之一，前人谓必身热咳嗽烦渴，则是风温无不烦，无不渴者，若劫液后变现之症，则神昏耳聋，鼻鼾发痉。然则未至神昏发痉，断无遽尔危亡之理。而今岁时气流行，秋分以后，咸病咳热，或渴或不渴，其变险也，必气喘痰鸣，痰厚而稠，多至盈碗，毙者甚多，论者皆目之为风温。夫风温之症，多起于冬季，今不在冬季，而发在秋分以后，其始也、无风温必有之见症，其毙也、又不在发痉神昏，而在痰鸣气喘，薛氏风温条例中，未见痰喘之例足以毙人之症。生窃有疑，敢以相质。曰、此燥症也。知其为燥症，而曰风温者，习俗也。当今之世，病者既属聋盲，医者亦类多粗鄙，风温之说，时有见闻，秋燥之症，转难入耳，谁登喻氏之堂、入喻氏之室者，必曰是燥症，非风温也耶。夫风为阳邪，盛则生火，火则生风，风火相煽，津液无不被劫，神明无不扰乱，故多眠鼻鼾，发痉神昏，是风温变险必有之症。惟今岁风木在泉，而秋令久燥，燥金克盛木，盛木生化，甚于寻常，故木生火而火气来复，其克金也，势若燎原，壮火食气，则肺之气伤，火烁阴津，则肺之阴伤，能不喘乎。火炼津液，而成胶腻，是以痰多稠黏。火激其痰而上升，故喉间霍霍有声，痰之声，即火之声也，火即无形之痰，痰即有形之火。曰、燥火为患，已知之矣。然所起之症，类吐黄痰，考黄痰为湿痰岂其既燥而复湿乎。曰、金病克木而木生火，火即燥之复气也。土为金母，湿即燥之化气也，故鞠通吴氏谓复气为火，化气为湿，复而且化，故痰兼湿黄，化少复多，故湿不能济其燥也。若风温则风火内旋，此则燥热伤肺，故彼之变险，则发痉神昏，此之变险则痰鸣气喘。治而愈者，类进甘寒清气，润燥清金，盖金受天气之燥而克盛木，复气伤肺，由内而起之枯燥，与清凉未寒，天气爽燥之燥，判若霄渊，有脉可凭，有舌可验，有象可征，临症推求，深有望于明敏者。", "8168": "或问曰，内经云、目受血而能视，掌受血而能握，指受血而能摄。又云、目者五脏六腑之精也。由此观之，人必精气内充，而后能神采流露。何子治若卿费都督之疾，而以风药主之，曾亦思夫风药皆燥哉。答曰、子但知夫归地杞菊之可以补水养血而明目乎。岂知都督身列戎行，风霜雨露之所感，浸淫其外，蓄伏其中，数年之前曾患鹤膝风症，鹤膝者、风寒湿之痹于膝者也，嗣虽目赤多泪羞明，发则眉骨作痛，谓之为水亏木旺，虚火肝阳上旋，固近似矣。不知人身一腑一脏，各相配合，脏阴腑阳阳升，阴降，所以阳本升而必使之降，不降则有散越之忧，阴本降而必使之升，不升则有沦陷之虑。故脾为阴土，其气上行，所以升其清，胃为阳土，其气下行，所以降其浊。故肝脏之气合脾脏之气上升，而心血以生，胆腑之气，合胃腑之气下降，而命火以化。都督每发目疾，辄脉细濡而模糊，舌厚腻而色白。合诸前番鹤膝等症，吾知其胃有湿寒，阳明不降，胆经之气，不能依附胃气下行，肝木犹然上升，胆木忽失下降。至但有肝升而无胆降，则肝之升也，不足以为化生心血之源，适足以成掀越鼓旋之害。目为肝窍，故欲愈其目，必熄其肝，欲熄其肝，必降其胆，欲降其胆，必降其胃。胃何以不降湿，阻之也，风药所以胜湿，而能疏其鼓旋掀越之势，所以经验屡屡也。又问曰、病发之时，全无痞满呕逆之类，何以为胃病，而了无所疑乎。曰、大便必阻。所谓九窍不和皆胃病也。况病至则苔腻而浊，病退则浊苔全化，此见之于外者，为可据也。阴虚者曾若是乎。又问曰、药既中病矣，何其频发而不获断绝其根蒂耶。曰、胃病传胆，胆病传肝，本非肝脏之自病，而其始发数次，医以凉药折之，滋药补之，致鼓旋掀越之邪，深匿于络，所以根蒂难除，一经外风而亦发者，即此意耳。又曰、曾闻风药不应，以柴胡愈之，何耶。曰、风药只能疏其掀越之势，不能泄热，迨鼓旋于上，郁而生热，柴胡散胆经之专药，既能散其郁勃之气，复能解其郁结之热，郁中有热，故风药不能治，而柴胡能治之也。又问曰、尝闻目疾之外，曾发胃痛，子以何法止之乎。曰、未之止也。初发时理其气不应，温通不应，因忆五饮中之悬饮能作痛，投以星半劫之，大便畅行，而其痛自止。此又胃病之一证矣。又问曰、曾闻胃痛之外，大发眩晕，岂能凡有疾苦，俱得谓之痰湿乎。曰、无痰不成眩，吾以导痰汤下白金丸，如鼓应桴，非痰湿而何。或曰、吾喻之矣。子以目疾之发，非为肝虚，实因胃有湿痰，阻其胆降，而肝升之太过也。胃痛者，胃为湿痰阻其气之通降也。眩晕者，即所谓胃痰聚而胆逆也。其病虽殊，而其源则一。吾喻之矣。", "8169": "或又曰、若卿都督之病，予略闻之矣。而其夫人就医远地，常从事于药饵，询其状则曰胸胁痛也，气升也，寒热也，精神疲备，气力衰微。丹溪云、上升之气，多从肝出。且两胁隶于肝，胆附于肝叶之中，而为开合之枢纽。吾意木郁则痛，亢极则气升，肝病胆亦病，枢纽不灵，开合失常，则为寒为热，此即俗所称之肝气是也。及至病退而精神气力衰微，元气已为病魔所伤。此时顾虑元气，窃恐气得补而愈滞，转触动其肝邪。疏泄肝邪。窃恐气以破而愈虚，更戕贼其根本。而子漫以橘半星枳杏郁藿朴投之，所效亦幸耳。答曰、子所言是也，而实非也。子所论者，木郁气滞也。余所诊者，饮蓄肺胃也。初诊之时，见其脉弦，亦以为木郁致之，而投药罔效。嗣察弦脉，沉候愈搏，因思沉弦为饮，则知此症实因饮阻肺胃之分，气不得通，故胸胁作痛。肺右旋而下降，饮阻其下降之令，故发为气升。饮阻则营卫循环失度，故为寒为热。精神气力衰微，由病而致，能却其病，则精神气力，不补而自复矣。所以导痰、温胆、四七、二陈、越曲、大和中饮、正气散等汤专主疏利痰气，痰气化而胸阳以通，故痛止。痰去则肺气得降，故喘宁。营卫无所窒碍，故寒热愈也。精力不补自复者，譬如人身负物，则手足沉重，一旦释其重负，岂不手足轻便，快然自如哉。所以昔常偃卧，而今俨如平人。虽经一月或数十日，必倦怠嗜卧，而肌肤凛凛然，似寒非寒，吾知其饮食又酿湿痰于内，脾阳受困，阳气不通，不能敷布，所以仍如前治，辄应手效验也。或又曰、然则通阳而独不投附桂，何也。曰、阳虚不布者，当用附桂人参之属以助其阳，此则阳气无损，不过为湿痰所遏，不能敷布，非真正阳虚之比，所以化其痰、和其中、理其气，阳气一通，便爽适矣。或曰、谚有云千方易得，一效难求。子治此疾，吾窃非之，而历数年来投药辄效者，究非无故也。医可忽乎哉。", "8170": "承示救时要略一书，久欲奉还，以便刊布。然有难焉者。方至刊布，人必深信，设有差池，则辗转贻误，必得于寒热两症，一见即可人人了然，然后可以活人而全生命。即如救时要略一书，其方法审症，悉遵王孟英霍乱论原文，删繁就简，并未窜改。霍乱论云、热症多，寒症少，若寒症不过十中之一二耳。孟英原有一定之据，如热症则于未病前数日，先有目中流火、肛门灼热等象预先知觉，则既病之后，更无论矣。然溯同治元二三四年间，修在常熟之梅里镇，后又迁于荡口镇，此处人烟幅集，四月至八九月，霍乱之症，沿门阖境，每日多则治二三十人，少则十数人，历见发作之时，一吐一泻，无不四肢厥冷，冷汗黏指，脉伏不起，大烦大渴，罗纹绉陷，甚则目陷失音。虽投白虎得生之热症，未必于未病之前，先显火象，既病后亦未必皆目中流火、肛门灼热也。投理中四逆得生之寒症，未必不烦不渴，神情未必安静，与热症亦相近似。盂英辨寒热二证，笔之于书，深觉其简明之极矣。然竟有村医见肢冷脉伏，不问其口渴如何，舌色如何，乱投四逆而霍乱向愈者。亦有肢冷脉伏，大烦大渴，渴而能饮，一派火热之状，投白虎及地浆而竟毙者。三十年亲经阅历，则知热痧于未病之前，先见有火象之说，殊难为信。惟一经芳开，热象发现，然后按热痧用药，此言最确。特热象未必门门见到，有数项即足为据耳。盖热症必有湿邪外遏，寒症本属阴寒闭塞阳气，如行军散、红灵丹、苏合丸、紫雪、玉枢丹等芳开之品，一遇病起即脉伏肢冷，或汗出淋淋，即急选用。虽有清开温开之异，设逢热症，投以苏合之温开，亦能见效。夫以温治热，固属抱薪救火，然能开发其抑遏，则火热可以透露，故以热治热，亦可回生。寒症而投以清开，则阴邪凝涩，便使开药不能应手，大能为祸也。大抵初起之时，不问寒热，概用芳开，芳开之后，随所见之象治之，是当生者能使起矣。施送药饵，似宜备以上所列温开之药，使火热之气，透于湿外，阴凝之气，宣畅运行。然后给以病情单一纸，单上开明服开药之后，若见书中所载诸热象，是为热痧，轻则以地浆水调六一散不时服，重则以理中白虎汤，或白虎汤，或竹叶石膏汤进之，方药即载于病情之后。若见书中所载诸寒象，则以理中汤，或附子理中汤、吴茱萸汤、四逆汤进之，方药亦载于病情之后。或即以病情单作包纸，与开药相附送人亦可。最可恶者，随便呼名，如绞肠痧烂喉痧吊脚痧瘪螺痧之类。霍乱之甚者，罗纹无有不瘪，经云、卫气者所以温分肉，充皮肤，肥腠理，司开合者也。既经霍乱，则卫气闭塞，自致分肉不温而肢冷，皮肤不充而罗纹瘪陷，开合失司而汗出淋淋，万病一律。譬如以手入水浸多时，湿气抑遏，则卫气闭阻，罗纹即瘪矣。而妄立瘪螺吊脚等名目，苟司命者识见不定，即为所惑。临症而无所折衷，以为一年有一年之时症殊不知霍乱二字，统概一切。凡医能究心于此辨认无差，自可十全为上。臆见如左，不揣愚昧，敬以缕陈。", "8171": "盖闻阳为阴逼，不走即飞，阴遇阳消，非枯即槁，是以阴不交阳，阳不交阴，上下几如两截，枢机失政，精岂能独居乎。然而阴不孤生，阳不独长，阳气闭密于外，则阴精完固于内，阳根于阴，阳欲脱而阴从下吸，阴根于阳，阴欲走而阳从上嘘，上下环抱，阴阳何自而脱。故精者神之本，气者神之用，形者神之宅。形之有生者，以其有神也，神之有托者，以其有气也。是以神太用则歇，精太摇则竭，气太劳则绝。比之于薪，薪尽则星火不传，方之于崖，崖溃则洪水不治，是即阴阳离决之比矣。然则阴阳离决之见证奈何。仲圣云、寸脉下不至关为阳绝，尺脉上不至关为阴绝。此阴阳离决之脉也。难经云、阴脱者目盲，阳脱者见鬼。此即阴阳离决之证也。内经又曰、精脱者耳聋，气脱者目不明。此精气两绝之明证也。扁鹊治虢太子尸厥之病，曰、上有绝阳之络，下有破阴之纽。此非常之变之起于仓猝者。善摄生者，胡可不审夫阴平阳秘之道欤。", "8172": "凡人之病，有同类相应者，有似是实非者。今举温病与湿温而言，温即热之渐，湿乃阴之类。由温化热，治之者自当以水制火。而湿生于脾，脾为阴土，温而夹湿，固明明湿而热，不若湿而寒者矣。然投以甘寒，甘即动湿。是必明乎温乃阳气发泄而成，一起即热，或表里有所缚，亦不过初起时凛凛微寒，一二日后便觉但热，表里一辙者是也。其烦也如天暑之极，而不可忍。其渴也，如天暑之极，饮凉辄尽。其神昏也，神乱语错，或至狂越。其溲也赤而短，其便也结而硬其溏也迫而泄，其舌也绛而刺，其燥也焦而裂，其舌黑也干而枯，其脉也洪而大。迥不若湿病于多日之后，依然凛寒湿之郁遏，里热而表不甚热。其烦也，闷甚而非热甚，热则伤津，亦必索饮，而中究多湿，每饮不过沾唇，湿性善凝，特喜热饮以开凝结。其神昏也梦寐迷沉，其溲也赤而浊，其便也泄而不注，其秘也结而不燥，间亦有燥者，脾湿不能鼓舞运旋。其舌绛也只在边尖，其燥也质多润，其枯黑也底质多有白苔。或无底苔，舌必淡萎，甚至干枯如镜。其脉也数而细，或滑而混。盖温病自有灼烁伤阴，燎原莫扑之见端。夹湿自有郁阻气机，弥漫熏蒸之的据。执此而分温病湿温之名目，随证立法，虽曰未中，亦不远矣。", "8173": "痉者，强直反张之象也。内经云、诸痉项强，皆属于湿，金匮曰、太阳病发热无汗，反恶寒者，曰刚痉太阳病发热汗出而不恶寒者，曰柔痉。此明言痉之初起，必由太阳而发。以太阳主一身之表，其脉起于目内眦，从头下后项，连风府，行身之背，并循督脉而行，故痉之见证，必有颈项强急，口噤背反，其所病之位，皆经脉所过之处。刚痉无汗，以表实也，柔痉有汗，以表虚也，表实者邪不能出，表虚者邪即能入，此得之于外而有余者也。又曰、太阳病发汗太多，因致痉。盖太阳为肾之外府，若太阳之邪，过于发汗，以致津液外脱，则少阴水亏，木少敷和，遂燥而生风，风生则伤筋，筋失血养，而亦成痉，此戕伐于内而不足者也。又曰、风病下之则痉。盖太阳之接壤，即是阳明，若太阳之邪，误于攻下，以致阴亡阳亢，则阳明土燥，土失培化而变热，热盛则灼筋而亦成痉，此又涸竭其内而不足者也。既言风寒在表之有余，复言汗下伤阴之不足，仲景于此，可谓反复推详，补泻之法，流露言外。然与内经皆属于湿之旨意似相悬异，何欤吾见夫湿伤寒水，而痉起于湿寒，湿郁生热，风淫火炽，而痉起于湿热，寒热悬异，而其湿则一，非所谓皆属者欤。夫至湿郁生热，火炽风淫，其脱液伤津，亦在所必至，则是内经不言燥而言湿，言湿而燥已囊括乎其中。若能推广其义，则是产后之去血过多，孤阳无依，大伤冲任督奇经之脉，以致反张强直，口噤拳挛，小儿之体禀纯阳，阴分未充，重感外邪，以成急慢惊风，噤口不语诸症，无不在范围之内矣。", "8174": "痢之见证不一，有但赤者，有但白者，有赤白兼见者，而不外乎腹痛后重。其受病之始，必由于寒，当夏日酷暑熏蒸，贪凉食冷，寒气入于肠胃，至秋阳气内入，与之相争，腹痛后重，气之病也。由气病而致血病，理之常也。寒则伤气，热则伤血，气血俱伤，寒热错杂，则赤白互下。此折衷之论，亦模棱之论也。河间专主湿热，丹溪以大小肠分主气血。然湿之与热，本是对举，未可言热而忘湿。且气壮而伤于天者，郁热居多，气弱而伤于人者，阴寒为甚。石顽张氏谓血色鲜紫者，信乎属热，若瘀晦稀淡，或如鱼脑，如紫草汁，或如玛瑙色者，为阳虚不能制阴。此外脉症之间，辨别多端未遑枚举。诚因当世多以痢属于热，峻用苦寒，故不惮反复详论也。继之曰，非温理其气，则血不清，理气如炉冶分金，最为捷法。明乎气为阳，血为阴，阳可以统阴，阴不可以兼阳，气可以统血，血不可以包气。故痢之始起，白多赤少，调气为主，误用血药，必致引邪入于血分。其后赤多白少者，虽宜活血养血，仍宜兼理其气，以和其血。此外噤口五色诸痢，及妇人妊娠下痢，皆当以调气之法，操纵而进退之。惟实系气壮而伤于天者，其热毒直入营分，肠胃如焚，喻氏有大黄黄连甘草法，苦寒直清其阴，不可再用芳香之品，以动其火也学者诚能于气血之孰轻孰重，寒热之为真为假，详晰而明辨之，不但可以治痢，其于诸病之治法，可一以贯之矣。", "8175": "或问白喉一书，养阴忌表，专以大剂甘凉镇润，然则治喉之法，果尽于此，而从前表散之方，皆可废弃乎。曰、治病之要，在乎辨症，辨症之道，求其精确。凡喉症之宜暂表者，必头疼板痛，鼻塞流涕，音声重浊，此为外寒包热，实喉症之轻浅者，辛凉散之即愈。近人以其辛散有效，于喉症之重者，亦必用之，用而不效，以为辛凉尚轻，继以辛温，口耳相传，并无他法。考之于古，无是理也。医书之中，伤寒金匮，最为近古，其论咽痛，独详于少阴之经，以少阴之脉，上循喉咙，为津液往还之道路也。首条症见胸满心烦，用猪肤白蜜，清润甘养之意，毕露于此。其但咽痛而无烦满者，少阴之热不盛，则甘草汤平调之。挟有外感不瘥者，加桔梗为桔梗汤。必不差而始加，其慎表之意若此也。其非少阴炽热，而由寒热杂沓为疮者，方书所谓乳蛾之类，苦酒汤主之。其寒犯肾中之痛，则又有半夏散及汤之方。后贤详其证状，谓猝然而起，不红不肿，但觉大痛异常，暴喑无音，脉多弦紧，或数疾无伦，此大寒犯肾也，用麻附细辛汤。然此症百不得一，姑备其法而已。惟是猪肤汤一方，实与白喉书中养阴清肺汤后先相望，诚以白喉一症，火热自内而发，燔灼于少阴经中，少阳之风，亦因之而动，火乘风势，风助火威，少阴天一之源，几乎有涸绝之势。求其属以济之，非壮水之主，不足以制阳光，养阴清肺者，求其属以济之也。是故其初起也，咽中干涩，咽物窒碍而痛，心中烦热，口鼻面上，皆觉烘热，绝无表寒之症象。然病犹在少阴本经，火未得风，势未炽也。至盛极而动少阳之风，则目眩昏花，胸胁不和。经络焦灼，或作掣引之状，而风与火相合而暴煽矣。煽及阳明，则蒸灼胃中之浊为腐，煽及肺金则熬炼阴中之液，尽化为痰。肺胃清旷之区，已成燎原之势。肺败而鼻塞音喑，喘逆痰升矣。胃败而衄流臭腐，神明糊乱矣。病至此，虽有智者，不能与谋。曰、不然。白喉之重者，其初起往往骨节疼痛，大寒大热，状类伤寒，苟不挟外感，何以若是。曰、白喉之外感者，感冬春温热之邪，郁伏少阴而成温毒，非风寒也。即病起之时，或触微邪，只足以鼓动少阳之风，少阳者，人身内生之风也，内风动而外风已不知何往，而少阴之火，乃因之愈炽矣。故伤寒之寒热，必先凄清怯冷，肢节疲倦，由寒而生热。白喉之寒热，必先肢肤焦燥，肢节烦疼，热极而生寒。曰、热极生寒，经训有之，然其理尚惝恍而无凭也。曰、阴阳之亢战，观于天地之风雷而知之矣。譬如盛夏之令，炎熇燔热，郁蒸不解，而后日月为之晦冥，万窍为之怒号，雷电为之大作。人身亦犹是也，阳亢之极，一线之阴气，欲承而不得承，乃作寒热交战之象。安得与伤寒之寒热相提并论乎。然则喉痹缠喉二症，果有异于此乎。曰、喉痹红肿为实火，厥阴之火也。缠喉肿闭为痰火，阳明之火也。白喉色带淡白，初起不甚肿痛为虚火，少阴之火也。本书中猛将之类，神仙活命汤方，即可治厥阴阳明之火。此外又有烂喉丹痧一症，其痧未透时，必须表散，本书除瘟化毒汤中有葛根薄荷，大可胜任。盖少阴伏邪，达于少阳，必须归于阳明，从肌肉而出，故伤寒论云，阳明者土也，万物所归。若与麻桂羌防等类，必至毒热四窜，奔腾莫制。况葛根薄荷辛凉甘润，与辛温燥烈之品，自有分别。伤寒论少阴篇中，先猪肤而次桔梗，此书首生地而殿葛根，三方鼎峙，直追南阳心法，未可仅以乩谶之语观之也。苟凡有医书，皆能如是之规绳划一，禁忌分明，庶几一病有一定之方，而无杂药妄投之虑矣。", "8176": "温邪身热热不扬一候矣脉数无力舌苔白不厚老年正虚乏力送邪外达急解之以防内走", "8177": "温邪挟湿胸闷脉数表热咳嗽邪恋肺胃也清解之", "8178": "湿温发热四日有汗不解脉濡舌不生苔邪深恋也", "8179": "湿温五日阳明表里兼阻三焦不通上下失贯陡致呃忒脉细且伏一候不得大汗虑其神昏变幻", "8180": "湿温解后复病灼热无汗头蒙膺闷表里两阻烦劳之体兼发劳倦病甫两日温邪挟滞周体作痛表热脉数解达之", "8181": "湿温化火内蒸两候余矣脉细弦数舌红苔剥渴饮初起似疟灼伤阴液连热不已阳明之邪多于少阳甘凉辛凉玎济之", "8182": "湿温病邪迫脏腑而致便泄表热仍蒸脉细数耎舌干苔黄询是湿热内蒸阳明表里俱病当从手足二经治之", "8183": "温邪退而复蒸蒸而复退胸膈稍舒脉数未和将在化火又恐复热常以清解", "8184": "湿热蒸于内暑气侵于外蒸灼三候有余舌绛无苔嗌干渴饮脉细弦数阳明热深且炽矣宜乎甘寒化解", "8185": "暴暑侵感身热往来脉数渴饮达之", "8186": "暑湿热混蒸发热呕恶舌垢便利脉濡数三焦不通先以解达兼和之", "8187": "病一候酷暑助邪郁蒸于阳明表不达汗脉细数不显舌红苔垢邪伏也非轻浅者", "8188": "病九日酷暑日逼更易化火舌绛液涸脉极数急清之", "8189": "暑伤气营舌绛脉数辛寒甘寒清解之", "8190": "暑暍薰蒸发热朝缓夕剧头蒙脉濡舌垢邪深恋伏一候解达为串", "8191": "病一候暑湿深伏阳明呕恶舌垢脉数不歇邪恋不解且与苦泄", "8192": "暑湿内蒸身热作咳舌垢脉数一候矣仍当解达", "8193": "伤暑发热旬日愈而复蒸神蒙脉数舌有苔渴症非浅者", "8194": "素有血症阴分内热近感暑热日午潮热脉细小数阴虚内热宜乎清化", "8195": "烦劳伤中藉感暑邪表发热频呃□手振脉数而虚气虚邪恋非轻浅者扶气达邪投之再处", "8196": "暑风闭腠发热头蒙胸闷呕恶脉濡数汗不遍身舌无苔邪深恋也解达之", "8197": "风热内蒸暑风外侵三候余而表热未解化火伤阴劫津脉极滑数深恋阳明势将走入阴经非轻浅清解达泄辛凉甘凉兼施之", "8198": "阳明热炽劫津生痰深恋肺胃咳不爽脉濡数与西昌法", "8199": "暑风发热袭于肺中咯吐腥痰脉极数舌绛干涸阳明热炽戕阴也滋清之", "8200": "现发疝气厥阴疾也又袭暑风音嘶发热舌白腻脉浮数阳明病也先去客邪而后治疝从阳明表分立方", "8201": "表热里泄脘闷腹痛脉弦数舌经苔黄暑湿兼滞病在少阳阳明之间宜乎表里两解", "8202": "暴暑薰蒸偶尔感受呕妨谷脘闷蒙脉濡且数三焦不宣先当清暑主用芳香", "8203": "始而作咳继而咽塞妨谷脘闷腹膨脉濡涩且便溏汇三焦不宣不贯吸受暑邪致此芳香宣达以通三焦", "8204": "失血之后阴虚内蒸又感暑邪发热二候脉细数宜乎从阴化邪", "8205": "伤暑旬日表里俱阻气逆呕吐脉濡数伏不慎起居病将增剧焉可就诊伤暑而又被暑侵也如之何则可", "8206": "昼暑夜凉感于阳明兼走少阳脉弦数舌黄苔垢妨谷粒阳明邪多于少阳清化之", "8207": "伏暑似疟挟湿内蒸表热甫退脉滑数舌红苔黄而垢腻邪未净也清化之", "8208": "秋暑蒸灼但热不寒有似瘅疟脉细数弦滑起于午蒸于晡剧于夜甫于一候仍应解达", "8209": "日哺不寒而热脉濡数滑舌红苔黄暑邪内伏欲化火辛凉清之", "8210": "伏暑发热退而复蒸舌红苔黄垢腻脉弦滑数秋令行□与西昌法", "8211": "伏暑挟湿内蒸似疟不准脉细弦数舌苔滑腻纳谷腹膨表热不振邪恋阳明老年气虚而不能振达也", "8212": "新凉束暑屡欲发热不定日期脉弦细舌灰苔干阴分渐虚暑湿犹恋当清少阳之热", "8213": "阳明伏暑经府交病表热里泄脉弦细数五日矣与柴葛解肌法", "8214": "伏暑两候邪火深炽劫夺阳明津液势将内陷生风形神色脉一派火象急投辛寒甘寒已嫌迟也", "8215": "伏暑甫热微蒸不寒而热脉细弦高年矣轻味清化之", "8216": "秋暑化燥燥邪入肺咽痛咳呛入夜微热舌红苔黄脉细数少阳之阳明兼症清达之", "8217": "凉风束暑暑热内蒸不达于表头痛脉弦膺闷□缠多日由阳明而走少阳仍应清化", "8218": "秋暑灼肺咳呛发热头痛脉细数衰年矣虑其不胜灼热内走之虞", "8219": "秋金燥邪灼肺咳呛晡热脉浮数舌红苔黄嗌干宜清之", "8220": "伏暑内热□缠两旬似疟不准退而复热热而复退舌白脉濡膺闷未经汗解邪犹深恋少阳阳明兼症辛凉甘凉相济而施一定之理也", "8221": "伏邪发热秋杪燥令尚甚热恋阳明化火内炽唇燥齿干脉数身热剧于夜分清达宜主辛凉", "8222": "伏暑至秋牛而发不寒而热热作于夜脉细弦舌苔腻口甜作渴妨饮阳明湿热暗助少阳之暑邪也本质之湿热浮于秋令之暑热", "8223": "伏邪发于初冬不达于外内蒸转剧发热咳嗽脉极数而细软□缠之邪未达而阴骤虚舌绛黄苔灰垢邪犹内燔正气不支邪正两脱不可不虑也", "8224": "感冒新寒营卫失和诸络酸楚脉濡涩细当归桂枝汤加味治之", "8225": "亲寒袭卫恶风发热头痛脉浮数解达之", "8226": "风伤卫头痛脉浮恶风翕翕发热太阳病也疏解之桂枝汤加减治之", "8227": "风伤卫恶寒恶风脉浮缓热芒于夜表邪犹在仍作太阳治之用桂枝汤加减", "8228": "冬温一候头蒙发热脉浮数舌红嗌干风化火也清泄之", "8229": "冬温发热咳嗽脉浮数清解之", "8230": "冬温六日邪恋肺胃入暮热之极呓语咳嗽气急舌红口渴脉未达者已化火也先从阳明解达得汗乃妥", "8231": "风温病阳明兼走少阳表热乍蒸乍退脉数咳嗽一候矣从少阳阳明清之", "8232": "冬湿一候化火内蒸表热不扬舌红苔黄脉浮数邪恋阳明犹蒙表分解达兼清以宣化气机之蒙遏也", "8233": "冬温化热阳明少阳兼症朝凉暮热脉弦数舌绛苔黄仍以清化", "8234": "暑风为疟化热蒸灼脉眩数嗌干渴饮阳明疟也和解兼清之", "8235": "寒轻热重脉数而眩舌苔不布胸脘瞀闷阳明邪多于少阳也仍与柴胡加括蒌汤", "8236": "暑风为疟疟日作作于夜脉弦而数寒热俱甚解达之", "8237": "暑湿为疟疟虽轻短余邪留恋脉濡极数居素中虚湿恋不清也和之乃稳", "8238": "暑风湿热溷蒸为疟疟作间日寒轻热重舌白苔黄脉弦数头痛胸闷暑湿深重也当与提达兼和之", "8239": "湿温化疟疟久伤阴脉细弦少阳阳明两不和谐也滋清化之", "8240": "三阴疟将及一载犹是蒸灼脉细数而弦独在少阳一经只宜和解", "8241": "疟作三阴经年矣虽能纳谷脉细犹弦三阳腑病而为三阴脏病宜其拖延岁月达邪宜顾阴宜益气气能生阴则不能伤气气充而疟可退也", "8242": "疟后脉和司消导失权营卫尚不和谐惟恐寒热复作", "8243": "疟复作犹间日脉犹弦当和解不宜补", "8244": "伏暑疟转为三阴疟寒颇重脉反强细邪深伏也截之尚早宜乎两调营卫", "8245": "茯邪郁蒸瘅热不寒日晡而作瘅疟也阳明邪兼少阳咳嗽脉浮且数宜从少阳阳明清之", "8246": "新寒引动伏邪疟发间日寒颇重而热轻短脉细小而迟卫气不与营和也", "8247": "胎疟本易反复因循失治邪恋募原三月矣元不能复营卫失调则阴阳不和纳少便溏脉微宜平中宫", "8248": "疟后余热未尽内蒸由秋未至春初不瘥黄昏犹是潮热脉细极数面目虚浮元气不振余邪未净也邪虽留恋不可从表只宜扶肋正元元气充复则余邪自退矣", "8249": "似疟非疟□缠二月余咳嗽形消色夺脉芤数会失血青年得此大非所宜怯之一途不免矣", "8250": "便泄腹痛脉濡妨谷脾胃失司且与清暑和脾", "8251": "暑湿夹滞混蒸发热热退便泄腹痛舌苔犹腻脉濡数三焦夫贯清之和之", "8252": "表邪里出化而为痢痢下后重脉细数暑湿夹滞也当升清导滞", "8253": "暑伤气湿阻气表热里泄脉微呃□高年中虚邪恋必当温阳达邪", "8254": "老年中虚湿热内阻阻闭三焦气机上呃下腹痛脉微便溲短通贯三焦必兼温阳逐邪", "8255": "始初霍乱而为痢痢下无度腹痛后重脉濡涩数邪滞深结中宫必当推荡使下", "8256": "暑邪夹滞混蒸为痢红滞居多后重脉濡阳明气隅先宜升清泄浊", "8257": "便泄三日当不后重脉濡数暑湿食滞留恋阳明急当升清降浊", "8258": "伏暑酿痢冬令而发由冬及春至夏半载余矣脉细数舌光红痢伤阴也拟仲圣法", "8259": "久痢半载余矣脉数舌光大伤真阴惟宜滋降", "8260": "痢延半载余成休息矣犹有下重脉细弦邪深药浅是以□缠李东垣清暑益气主之", "8261": "休息久痢脏真极虚脉细无力温摄脾肾先调奇经", "8262": "老年脾肾两虚下痢而腰痛脉微细必当温补脾肾庶可止之", "8263": "痢下红滞犹欲后重脉细极数初秋而起秋末未止气阴两亏湿滞留恋兴仲圣法", "8264": "青年血气初定而有道泄却无梦境脉细尺数坎离失交皆已之心猿意马也", "8265": "不得情志则有所思思则偏于心神为之失藏失守似痫非痫如呆而木脉促而乱大凡七情之感心肝脾不得其藏者而起也心藏神肝藏魂脾藏意一有不藏且不可况此全失其藏者乎填摄镇三者兼施医功草木调其偏胜然必自仗慧剑割断心猿意马之情庶可", "8266": "阴气过泄内热自生日晡潮热脉极细数虚火从此内煽有诺内形之外则生外疡至虚之处便是客邪海底穴痛而肿者少阴肾经之隙处也疡发于斯非所宜也总之不保下真而有斯疾必得自生慧剑割断情魔庶几守先夭以保后天不致相火胜于君火生化自有源流即可以保正命也勿以予言为迂腐", "8267": "男子十六天癸至至已三年血气生勃勃则安无欲念之动动则安无暗伤真阴体肢不健不任烦劳脉又细数而耎胃纳不旺面不华泽者为此故也急早毕姻所谓阴阳利万物生矣", "8268": "湿热内蒸蒸热发黄脉涩数老年气不胜湿湿恋于阳明平昔不嗜酒非酒湿也乃运谷迟呆水谷之湿所积当培中阳以化温热", "8269": "童子而伤水谷之湿湿热内淫面肿脉细数小溲不利此谓湿肿野人所谓河白病也修之即愈无妨", "8270": "居素便溏脾阳久虚乘虚木侮腹脘痛胀脉细虚弦土衰木旺也木得桂而枯", "8271": "始衰之年操劳太过易传中宫胃纳不旺常欲量眩脉细无力阴不内守阳亦衰也所以不制虚阳体丰者往往有之宜培二气", "8272": "胃主司纳脾主消导不纳不运脉数不鼓指脾胃枢机不利也先理中焦", "8273": "友升太过右降不及肝胃之气久已不和升太过者肝阳也扰心神而荣智慧降不及者胃气也得谷粒而常反胃脉迟细而馍糊神志清而失慧养肝和胃以助资生", "8274": "脾胃多虚右脉衰微左尺更耎中下两阳无以生土所以常自便泄兼夜数次必当温培中下之阳以实脾土", "8275": "脾阳久虚无以运湿阻遏消导气机以致中下两阳式微脘𪽪复𪽪两脉细涩几成中满温阳泄湿且与真武汤", "8276": "老年真水下亏小溲不清浊阴不化水也现在脉不鼓指断不可再泻膀胱膀胱贤之府也泻膀胱即泻肾也年巳七旬癸水久绝填之不暇安可泻乎虽有湿热肾气充足湿热自化矣", "8277": "咽痛百余日矣少阴之脉循喉咙挟舌本是少阴水亏不制处阳以钱仲阳补肺阿胶汤更添入咸苦", "8278": "交冬来天气温暖冬不藏阳人之阳气亦不潜伏逼近冬至阳生陡然咯血脉细弦数犹恐血溢末止滋阴降阳自然之理", "8279": "风入脑鼻垂腥涕稠厚成块脉数舌黄风化为火留恋肺胃鼻渊之机也", "8280": "肺胃热炽生痰作嗽嗽久伤阴阴虚阳亢咳少呛多脉细芤数痰见血点虚在少阴热恋阳明初起无非风温袭肺误闭其邪邪郁化火灼肺肺为娇柔柔藏不胜火灼致成劳嗽柔阴保金生水主用甘咸", "8281": "阳明失血脉细目晡肤热血去过多伤及真阴阴亏阳亢治法无非摄阴潜阳草木之功究竟式微自保下真尤为耍著", "8282": "胃中虚客气上逆而多噫暧纳谷运迟脉濡细数中气久虚真阴亦亏", "8283": "木火扰中纳谷辄吐脉细无力鬲症也衰年矣虽治调之", "8284": "烦劳伤中中阳失运纳谷不化中脘作痛两关脉软斯中鬲也且培之", "8285": "肝脾肾三阴素亏生化原流日薄纳谷颇少资生失侍从来血生于谷谷无生血阴亏可知脉极耎细数中心嘈杂抑且不寐女子十四天癸至逾此二七之年正是壮盛之时而有斯疾责在先天真阴不充非关后天而然也仲圣复脉汤县几近之", "8286": "脘胁作痛按摩则缓脉弦细是为肝著著者肝络之气著而不移宜投金匮旋覆花汤治之", "8287": "脊痛而骨突三足年矣痛引腰膂虚损症也病属奇经八脉之督带是以疾因种种不可枚举按妇科论二七天癸至五七天癸衰衰年损病难以复元补剂调理颐养天年以令正命", "8288": "血海空虚肝血乏贮每每天癸定期二三月之久脉细如丝面浮肢肿厥少真阴枯耗是以结缡五载从未孕育", "8289": "任脉为病带下瘕聚", "8290": "停经之脉细涩而不畅妊娠之脉滑搏而流利斯脉举之若无按之濡耎是血虚之脉也夫虚藏于肝出于冲脉冲为血海故女子先天寄于斯所以古人云女以血为本补血摄冲任一定之理也", "8291": "经阻三月脉数滑搏呕吐妨谷妊象也当安之", "8292": "经阻四月余脉虽小而滑数纳谷辄吐形色华泽微有寒热此非停经乃有恶阻之甚者也和之安之", "8293": "妊娠七月手太阴胎之际脉浮滑数胎元自在长养虽有汗不宽舒者火不胎静也无妨", "8294": "产后将及两月犹血不归经脉弦细显见不藏不统也与仲圣法", "8295": "心生血肝藏血脾统血血从气生气不生血则生内热心惕神疲脉微癸水愆期凉血一定之理", "8296": "吕东莱先生曰：不忧算之不多，而徒忧敌之难胜，天下之庸将也；不忧术之未精，而徒忧病之难治，天下之庸医也。医之道难言矣哉。夫医有医于未病，有医于将病，有医于已病，又或视有病若无病，见不病而实病，病之端多，即医之道大，医诚难言矣哉。得斯旨者，其谢映庐先生乎。先生少颖慧，嗜读书，士林每乐与之游。旋以境窘，弃举子业而就医，医于谢氏，固世精其业者也。先生既能自力其学，而又得先世心法之传，于是教人节饮食，慎寒暑，戒嗜欲，此则医人之病于未然。亢阳者抑之，纯阴者化之，阴阳驳杂者调之，此则医人之病于将然。辨症之表里虚实，审脉之浮沉迟数，且证以色之生旺休衰，而后拟方奏效，此则医人之病于已然。又或谵语颠狂，趋炎赴冷，人多仓皇失措，先生独声色不惊，应手而立愈。又神光外铄，坚匿膏肓，人每玩忽轻之，先生独深思竭虑，多方乃痊，此则医夫病如不病，不病而病之病。噫，先生之医，其良矣哉。若夫望五色，听五声，辨五行，度五候，因以定五气所由病，五病所由发，五邪所由乱，五劳所由伤，由是而调其五脏，顺其五气，固其五精，和其五味，此又先生数十年中精心苦志，济人之准绳也。夫至病必穷源，症必对方，以故疾无弗瘳，药无弗效，亦如兵家之战必克，攻必胜，此邑侯所以有妙手仁心之赠，而先生所以有得心应手之篇也。噫，先生之医，诚良矣哉。先生哲嗣杏园克承父志，医人亦多奇效，家学渊源，后先辉映，汇其先人手泽辑而成书，并附己所见效数十则于后，亦继志述事之意也。梓成而问序于余，余素不文，且不知医，以日与杏园游，谊不获辞，因即杏园平日所述先生之薪传独得者，撮其大要，而著之于篇。", "8297": "中风按中风症，诸书咸列首卷，盖风为百病之长。而中风原有真中、类中之分，经络、脏腑、气血之别，故治有浅深次第之殊，法有攻风、劫痰、润燥、理气之异。大抵见症，百无一同，治法因人而施。总之经络素虚，风乘虚入也。案中风邪在上，卒然牙关紧闭者，为中风本门。其偏头风痛，脑鸣肢痹，及肠风喑厥，血虚风袭，筋脉抽搐之治者，为虚风，与肝风为患者，附列本门。", "8298": "吐泻吐泻一症，责之脾胃，理固然也。治之不善，安危反掌。惟能窥其六淫之兼并，脏腑之寒热，则治之之法思过半矣。案中治吐泻胸胀，有从《内经》胃寒肠热之旨，则用连理汤及半夏泻心汤诸法。土虚木乘，面白飧泄，则仿古人培土必先制木之法。更有暴吐泄泻，厥逆无脉者，则从肾为胃关，用白通汤加猪胆汁，反佐通阳之法，较诸安脾理胃不大相悬殊乎。又治下痢，不以红白评寒热，而于营卫议虚实，以营主血，卫主气，红属血，白属气也。营卫不固者，先建立中气，脾胃虚寒者，理中焦之阳，俾脾胃有权，阳气乃运，庶气血各守其乡。其积热下痢，又有黄连解毒丸，六一散之治，附列本门。", "8299": "淋浊淋浊一症，方书诸罕确论。余于辛酉秋，避乱后，曾患是疾，茎中热痛，如刀刺剔，溲溺仍清，惟窍端时流白浊，淋沥不断，腿缝间有核作痛，或牵引睪丸，溺时艰涩不堪。推原其故，精溺本同门异路，原浊流管中，逗遛其间，溲溺直趋而下，故并道相迫而痛。观于溺出四射，足为明征。治之者，若专以利水之剂杂投不已，必至增剧，盖败精腐浊，因劳役而成者，十居六七，脾虚下陷，湿热下注者，十仅三四。主治不越升清、祛浊、清热、利湿诸法，所谓澄其源、流自清耳。今案中治败精阻窍者，则仿古人制虎杖汤意虎杖汤牛膝、麝香，用宜通窍隧、逐瘀祛腐之品。其热结肝经，阴器肿胀，溺则号痛不已者，必下血乃愈，直用龙胆泻肝之法。昔叶天士，论厥阴内患，少腹绕前阴如刺，小水涓沥难通，环阴之络脉皆痹，气化之机关将息，其症最急，曾引朱南阳法，用归、桂、金铃、小茴，通阳泄急，佐入韭白、鼠矢，循经入络，实发前人未发奥旨，足与是案互相发明，岂执用五苓、八正散者，可同日语哉。", "8300": "产后案中治妇人产后五更泄泻，崩漏不止，阴菌下坠，前后二阴诸疾，专以固奇经八脉为纲纪。或腹中胀痛，血寒凝位，交骨未缝，寒入阴中，厥阴中寒，呕吐胁痛，中虚血寒，夜热咳嗽，津液内涸，口渴自汗，潮热腹痛，口舌浮烂，妄见妄言，诸症悉分虚实寒热，酌治取效，缘皆起于产后，故概列入产后。", "8301": "痉痫案中分痉厥、痫厥二门，以大小男妇为区别。缘小儿体气孱弱，血脉未充，筋骨柔脆，易感六淫之邪，为患最速。以手足抽搐，角弓反张为痉，四肢逆冷为厥，太阳中风，亦可类推。若方脉男妇，有七情之郁结，六淫之兼并，血气之盛衰，由来之暴渐，与夫产后血虚，及厥阴肝邪为患，四肢僵痹，不省人事者，皆为痫厥。", "8302": "吴双龙乃室，得伤寒病，信巫不药，渐至潮热大作，胸前板结，谵语耳聋，数日未食，犹不服药，遂尔神识昏迷，眼翻牙紧。合室惊惶，延余治之。脉得细涩，十指微冷，面色黄白，问之不饮汤水，潮热时有时无，俨然虚极之象。细审此症，寒邪成热为阳，其返成阴候者，古人谓大实有羸状，即此类也。又河间云：郁热蓄盛，神昏厥逆，脉又滞涩，有微细欲绝之象，使投以温药，则不可救矣。盖其初原因伤寒失表，遂入于里，寒郁成热，热极变寒。理宜表里两解，治以柴胡、薄荷、菖蒲、大黄、枳实、甘草等味，急服两剂，连泄三次，潮热大作，口反大渴，知其里舒热出。三焦经络之热法当清之，以竹叶石膏汤四剂而安。", "8303": "危廷阶年二十，始病发热恶寒，进表散药二剂，汗已大出，热仍不解。更医又用柴葛解肌之法，反增气逆干呕，胸前板结。一医进大柴胡汤一剂，遂尔腹中雷鸣，利下不止。其父亦知医理，邀集同道相商，交口当进七味白术散，余独议曰：仲景云胸中实，下利不止者死。其父惶悚，诸医默然。余又曰：此真谓之死症耶？但症极险耳，俟吾以法治之，二剂可收神效。其父且惊且喜，及见疏方，乃生姜泻心汤，又疑芩连不服，余曰：此症吾揣摩有素，非一时之拟用也。服下果然呕热顿止，但渴泄未止，更与甘草泻心汤，呕利随止。归语门人，门人不解，因诲之曰：此症头绪错杂，无非汗下伤胃，胃中不和，客气上逆，伏饮抟结聚膈。夫胸前板结，即心中痞硬也。胃虚火盛，中焦鼓激，以致腹中雷鸣。盖火走空窍，是以上呕下泄也。生姜性温，善助胃阳，甘草味甘，最益胃阴。因仿长沙之诀，汗后胃虚，是阳气外伤，故用生姜之温以助阳；下后胃虚，是阴气内伤，故用甘草之甘以补阴。药仅更一味，意则有二，先后两剂，欲起一生于九死者，敢操无师之智哉？门人问曰：甘草补阴止利之义，先贤开导来学，但此症胸前板实，生姜散满，固其宜也，吾师复用甘草，独不虑其资满乎？答曰：甘草味甘补土，土健而满自除也。况施火性急迫，阴气不守之症耶！且甘草之功用甚长，惟仲景之圣，方知举用，试观发表药中，如桂枝、麻黄、大小青龙辈，必用甘草者，欲以载邪外达，不使陷入阴分也。若邪入里，必无复用甘草之理，如五苓、承气、陷胸、十枣诸方，俱不用也。至桃核、调胃两方，以其邪兼太阳，尚属用之。若阴血大伤，竟重用甘草以复脉。可见前贤用药，取舍自有法度，而后之叶天士，黄宫绣辈，每视甘草为畏物，致令良药见屈，固不识此取舍之妙，又不察资满泄满之意也。又问曰：土健而满自除，则凡满症，俱不必忌乎？曰：非也。阴气内盛之满，法所必忌；阴气下亡之满，法所必施。如发表药中之甘草，必不可少；攻利药中之甘草，有断不可用者。举一隅，不以三隅反，则不复也。", "8304": "何挺芳患伤寒病，服表散药而头痛，身痛，发热，恶寒诸症已除，可知表邪固解。惟大小便不利，咳唾多涎，医者不察，拘于伤寒法中有表邪既除、里邪可下之说，误与承气一服，遂至通腹反满，呕逆上气。前医再视，骇然辞去。余视口不渴，身不热，且脉来弦滑，知无热邪实结在里，不过痰饮阻滞肠胃，承气苦寒，徒损胃气，以致传化失常，湿邪不走，痰饮愈逆，故胃气愈乱，胀满愈增也。当取五苓散，重桂化气利湿，加入陈半，甘遂，和中逐饮，一剂二便俱通，病者立时精神爽利，未劳再剂而愈。盖气化湿走，又病机中，当以小便不通之为标急也。", "8305": "吴秀华，时值秋尽，头痛畏寒，略有潮热，食减便泄，来寓索方。予视面色晦黑，舌色干裂，因告之曰：内有湿热，外感风寒，当节口腹，免成疟痢，疏与小柴合平胃与服。病已霍然，殊伊归里，房室不谨，食物不节，疟症果起。其疟寒少热多，自汗口渴，不能自支，自服理中丸，次日疟发颇重，延医称为热症，与石膏知母之属，热势虽轻，却无退刻，乃热邪内陷，非热邪外解，果然里急后重，下痢红白相兼，烦渴谵语，其势转重。延予视时，人事昏惑，细按其脉，弦数劲指，重按有力，上则呕逆胸满，下则后重逼迫，中则腹痛拒按，且身虽发热，尚有头痛畏寒，此热邪内陷，气血怫郁，充斥三焦，故有谵语妄见，是表里内外交困，棘手重症矣。反复思议，非表里交攻之法，势所难挽，与仲景治伤寒发热，汗出不解，阳邪入里，热结在里，表邪未除，里邪又急之例相符，处以大柴胡汤，寒热红白顿除，谵语亦息，仍与前汤，除枳实再进而安，后与甘寒而健。噫，圣人之法，布在方策，倘能寻其端倪，而起一生于九死者，岂非仲景之徒哉。", "8306": "仁元，佣工也，躬耕田亩。年及半百，时值暑月，发热畏寒，未药已痊，渐次肢体怠惰，头腰重坠，通身带浮，面色黄，唇舌指爪皆白，二便如常。告于余，余曰：此乃太阳病，未经发表，邪陷肌肤之中，非湿热发黄之证也。次早诊脉，按得三部浮紧而数，时或喘咳，复告余曰：已服黄疸草药，头上如蒙，腰间愈重，四肢忽麻，胸前时紧。余曰：昨之所拟，更无疑矣。以仲景麻黄汤加厚朴，连服四剂，每剂令啜热稀粥以助药力，俱得微汗。头腰方轻，症稍减，然脉象仍如前，与五积散一料，药完而病愈矣。", "8307": "王富春，新婚匝月，得太阳伤寒病，头痛，发热，畏寒，误用补剂，邪无出路，遍身骨节疼痛，满头大汗热蒸，其面目如橘色之黄，其小便如栀子之汁，所服皆清补疏利，势愈迫切，诸医技穷，始延余诊。幸脉无阴象，腹无满结，胸无呕哕，谓曰：此症虽危，吾一剂立愈。其家且疑且信，服之果然，原仲景《伤寒论》中，有太阳病失汗，一身尽痛，头汗发热而黄者，有麻黄连翘赤小豆汤之例，盖发汗利水，令郁拂之邪，表里两解之意耳。", "8308": "高汉章，得风湿病，遍身骨节疼痛，手不可触，近之则痛甚，微汗自出，小水不利，时当初夏，自汉返舟求治，见其身面手足俱有微肿，且天气颇热，尚重裘不脱，脉象颇大，而气不相续。其戚友满座，问是何症，予曰：此风湿为病。渠曰：凡驱风利湿之药，服之多矣，不惟无益，而反增重。答曰：夫风本外邪，当从表治，但尊体表虚，何敢发汗？又湿本内邪，须从里治，而尊体里虚，岂敢利水乎？当遵仲景法，处甘草附子汤，一剂如神，服至三剂，诸款悉愈。可见古人之法用之得当，灵应若此，学者可不求诸古哉。", "8309": "张怀久乃郎，年方及冠，遍身忽发疮疹，形如麻粒，询诸疡科，内以凉血托里之剂，外以药汤沐浴，其疮尽伏，以致湿热内攻，恶寒发热，头痛身疼此表邪确据，延医又误为疟症，投以清脾饮服之此误认为半表半里，以致寒不成寒，热不成热，人事昏惑，绝粒不进。乃叩于余。脉颇浮数，问之不应，扪之身热，视之唇舌俱淡，此风热内蕴，抑遏于中，若不外达，势必内攻脏腑，机窍尽闭而毙，当与升阳之药，提出肌表。与升阳散火汤二剂，遍身发热，躁扰不安，其家惊惶，促余再视。其身虽热，而问之能答，则神识将清，且粥饮亦进，则胃气有权，余曰吉也。夫躁扰不安者，正邪气外达之征，明日毒气外出，则内可安，更与辛凉解表之法，以人参败毒散二剂，果然疮疹尽皆发出，形如绿豆粒，再与前法，疮皆灌脓结痂而安，仍与清散药而健。须知此症若不如此施治，脏腑能堪此毒乎？", "8310": "许庆承之子，及黄起生之弟，年俱二十，同患瘟疫，医进达原饮，大柴胡汤，潮热不熄，燥渴反加，因而下利谵语。许氏子，病经两旬，身体倦怠，两目赤涩，谵语声高，脉来数急，知其下多亡阴，所幸小水甚长，足征下源未绝，与犀角地黄汤，加蔗汁、梨汁、乌梅，甘酸救阴之法，频进而安。", "8311": "附：黄氏弟，悉同此证，但此病不过三日，即身重如山，躯骸疼痛，谵语重复，声微息短，脉来鼓指无力，此病虽未久，然表里有交困之象，阴阳有立绝之势，急进十全大补汤，重加附子二十剂始安。夫同一潮热燥渴，同一谵语下利，而用药角立，毫厘千里，岂易言哉！", "8312": "家万生廷诏之子，春杪远归，头痛寒热，默默欲睡。医者不知风温之症，当用清凉之法，误作伤寒之病，而以辛温之药，渐至神识昏迷，谵语不食，大便不通，小瘦或遗，与水则啜一口，与粥亦啜一口。延余两门人同治，汪生争用附子、干姜，陈生争用芒硝、大黄，两争莫决，急延余视，两生俱称脉象模糊，余诊亦然，及抉齿视，舌白干刺，唇虽干，而色稍淡。脉与症参，病邪不在脏腑，仅在三焦，因谓汪生曰：尔以为诸虚乘寒，有神虚谵语之例耶，但舌不应干刺。又谓陈生曰：尔以为三阳传经，有胃实谵语之条耶，然舌色不应尽白。究竟温脏攻腑，俱属偾事，盖此症，乃风温热邪蒙闭上焦气分，致令肺气痹极，古称郁冒者即此症也。但有入气入血之分，若入血分，则邪在膻中之内，此则仅入气分耳。夫肺主气，气阻血亦不行，故脉模糊，然亦重按触指。上焦不清，则胞中之络外蒙闭，故神昏谵语也。浮障之邪，惟与轻清味淡之药可得去也，汪生问小便自遗如何？答曰：曷不闻肺与膀胱司气化，热甚而阴挺失职乎？陈生又问大便不通如何？曰肺与大肠相表里，且天气不怖，地道亦阻之说。吾已讲明有素，何遽忘耶？两生愕然，促以疏方，佥用杏仁、杷叶、知母、通草、蒌皮、山栀皮、竺黄、灯草，药下安睡，大便果通。次早复视，能述病苦，再加琥珀镇心安神而安，仍以清肺药而健。越日两生叩曰：风温邪入气分之治，既闻命矣，但未知邪入血分，当以何法治之？答曰：若邪入血分，则入胞络之内，舌苔当必黑刺，而凉膈、导赤、黄连阿胶鸡子之属，养阴退阳之法，按症举用，以积热借以宣散，而心胸和畅，脉渐以生。又曰：风温初起，脉症如何，治当何法？曰：温症甚该，凡春温，温热，湿温，暑温，风温，以及温疫，大头瘟，皆不可汗。故书曰：温邪忌汗也。今仅举风温之症言之。发热头痛，状似伤寒，但自汗身重多眠。夫身重似伤寒，然寒应无汗，自汗似伤风，而风应身轻，此当辨也。且鼻息多鼾睡，语言多难出，脉象尺寸当俱浮，唇口齿舌当不润，无非风温酝酿之机，此当辨也。总由表邪蓄热，故曰风温治之之法，当与辛凉解表，如葛根、薄荷、防风、杏仁、连翘、通草、白薇、甘草之属，内清经络，外彻肌肤，清温而不阻风之出路，驱风而不助温之暴虐，庶内外之邪，表里两解，为清散法也。若犯香苏羌独葱姜陈半，是以温治温，故在禁耳。两生退而喜曰：既闻风温入气入血之治，又闻诸温忌汗之理，真所谓闻一得三。", "8313": "傅瑞廷，六月新婚后，触暑病热，头脑大痛，误用补剂，大热焦渴，医以瘟疫热症治之。凡清解疏利，升散养阴之药，治经数月，而病不瘳。节届大雪，始延余诊。视其形瘦面垢，身热谵语，自汗多渴，头痛有如刀劈，脉来长而不洪。是时医巫浩费，家计已索，病者因头痛难任，其叔孔翁曰：尚可治否？余曰：可治。戚友咸问病名，余语以暑邪之症，众诧为不然。问曰：何以知之？余曰：以气虚身热，谵语自汗，合于面之垢，脉之长而知之也。因请用药，余曰：甘寒解暑之剂，惟有天生白虎一方。旋重价觅至二枚，先将一枚破而与之。病者心躁口干，见辄鲸吞虎嗜，顿觉神清气爽。因再求瓜，家人止之，余更与之。食毕汗收渴止，头痛如失。但暑邪虽解，而阴气被阳热之伤尚未复也。夜仍微热，咽微干，睡不寐，仿仲景少阴病，咽干口燥不得卧之例，处黄连阿胶鸡子汤，三服而健。", "8314": "车觐廷妻，傅羽仪令爱也。初日，恶寒发热，次日大热不寒，饮水不辍，唇焦，红舌燥裂，大便闭，胸前板痛，烦躁莫当。余诊之，脉纯躁无静，刚劲冲指，谓曰：此乃温热病，非伤寒症也。若伤寒症，从皮毛而入，由传变渐入于胃，结成可下之症。至温热病，从口鼻而入，不由传变直入而附近于胃，结成大下之症。其来路异，其去路一也。然此症才二日，即一团邪热内结，如火燎原，其势已极，亦温热病之最速者，须防物极则反，或有痉厥之变，稍迟，有朽肠腐胃之事矣，是所谓急症急攻，无庸迂缓。疏方以凉膈散，大黄重用。药方煎时，掀衣发狂，怒目而视，牙关略紧，面红目赤，扬手掷足，乃邪火一概上冲，莫可止遏之势。忙进前药，灌至半，势稍平，剂终，人事略醒，自索前药，以其滓再煎服之，随取前方再进一剂，其病悉清。讵调摄不善，半月后，因口角盛怒，时见微热，初不以为意，倏于某日申酉刻，自觉难支，晬时声音悉闭，奄奄一息。问其苦否，但点额摇头，可见心地尚明，惟哑不能声耳。尤有奇者，腰以上发热去被，扬手摸胸，腰以下畏寒厚覆，两足僵直。医数辈，未敢下药，举家慌甚。羽兄即夜来请，余念知己之女，戴月而往，诊脉寸部浮数，尺中紧涩，似乎上下阻截，因其症从未经见，方非易拟，然目睹其状，心甚怜之，兼之房中稚子失乳，老姑抚孙相哭，吾大为踌躇，默以其症，证诸经旨，以冀一悟。其夫含泪问曰：前日重恙，幸叨再造，今复病此，先生亦蹙额无法耶？答曰：斯疾大奇大疑，泛泛一视，难明其理，吾正在谛审，且止啼哭，吾自当竭诚，以报知己。因环步思议，已而笑谓曰：此症虽奇，吾得之矣。窃思人身之气，全赖肺以运之。今上下不通，无非治节不行，失其常度，而为上热下寒之症。其上热下寒之由，盖前此温邪未得清解，今复加感冒，又值大怒，其气愈阻，愈阻愈结，其气遂横于胸。其热邪因气不流行，仍亲乎上，热多动，必扰其血，故见上热去被之症。其寒邪新感，亦因气不流行，仍亲乎下，寒多静，必滞其血，故见下寒僵硬之症。总因气结于胸，不能周流，以故旧热新寒，各随上下而相亲，热自热，寒自寒，俨然分疆界焉。曰：此先生大开生路之论，未知古圣亦有此论否？余曰：大哉问也，吾为子悉言之。尝读经曰：气并于阳，血并于阴，此上下相亲之义也。曰：其声哑如何？曰：夫声音发于肺，肺为娇脏，最易受伤。今气已结，更被热邪伤之，又被寒邪塞之，欲其出声，其可得乎？譬之钟磬，内以物塞之，外虽重敲，冀其响不可得。是其病之所受，全在于肺，法宜先开肺气而祛寒，使气宣通，热得下流，而胸结可散；后泻其蕴热，则肺可清，而壅塞自除。时际鸡鸣，疏方先以乌药顺气散一剂，以开肺气而祛寒。比晓遍体微汗，下身发热减盖，脚可屈伸，胸前亦宽。惟声音虽出，犹不清，时仍哑，日出进泻白散，合白虎加桂枝汤，此方足以泻热而清肺。一剂潮热悉退，声音清亮，前后两剂，病如冰释。后以保肺生津之药调理而健，观者钦服。", "8315": "李赓扬先生，苦诵读，馆僧寺，冬月衣被单薄，就炉向火，而严寒外束，虚热内蕴，渐致咳嗽吐血，医者见其神形不足，谬称痨损，日与养阴之药，遂至胸紧减食，卧床不起。余诊其脉，六部俱紧，重按无力，略有弦意，并无数大之象。密室中，揭帐诊脉，犹云恶风，被缛垫盖，尚背心寒凛。按脉据症，明是风寒两伤营卫之病，若不疏泄腠理，则肺气愈郁，邪无出路，法当夺其汗，则血可止。经曰：夺血者无汗，夺汗者无血。奈体质孱弱，加以劳心过度，不敢峻行麻黄，然肺气久闭，营分之邪，非麻黄何以驱逐？考古治虚人外感法，莫出东垣围范。因思麻黄人参芍药汤，原治虚人吐血，内蕴虚热，外感寒邪之方，按方与服，一剂微汗血止，再剂神爽思食，改进异功合生脉调理而安。亦仿古治血症，以胃药收功之意也。然余窃为偶中，厥后曾经数人，恶寒脉紧咳嗽痰血者，悉遵此法，皆获全效。可见古人制方之妙，医者平时不可不详考也。", "8316": "生脉散", "8317": "徐晓窗，年逾五十，形伟体强，忽患潮热咳血，楚南诸医，咸称血因火动，叠进寒凉，渐至胸紧头疼，不能自支。于是检囊归家，坐以待毙。延医数手，无非养阴清火。迨至饮食愈减，咳红日促，予按脉象，紧数之至，且病经数月，而形神未衰，声音犹重，肌肤虽热，而厚衣不除。久病面色苍黑，额痛时如锥刺。内外谛审，并无内伤确据，一派外感明征。伏思表邪入阴，扰乱营血，必当提出阳分，庶几营内可安，乃以参苏饮除半夏，加入止嗽散与服二剂，助以热粥，始得微汗，似觉头疼稍减，潮热颇息。以后加减出入不越二方，或增金钗麦冬，或参泻白散，调理一月，药仅十服，沉疴竟起。未尝稍费思索也。", "8318": "附：后李维翰先生，畏寒发热，脉紧无汗，咳嗽失红之症，医治弗效，慕名虔请。及余疏方，畏而不服，细为讲论，疑团稍释。奈前医纷纷，既不识表邪入阴之症，又不解夺汗无血之义，中坚阻之，而余独吹无和，以致热肠不投。越月见讣音悬市，自恨遇而不遇，抚躬一叹而已。", "8319": "黄成斋学博，外艰解组后，忧思百倍，今春面色如赭，坐谈口秽，神情张皇，若有所失，盖显孤阳不生之机。予见而骇之曰：足下神形面色，阳气独治，无阴以守，然尚不倦，得毋出于强勉乎？渠曰不然。又曰：人身负阴抱阳，阴阳交恋不露，所以生生不息。今神形相失，急当潜心静养，庶几亢阳自返，所谓静则阴生也。渠曰唯唯。厥后闻伊不但应酬不节，抑且多方会计。延至秋深，忽潮热不退，自拟因食物未节，屡进消导发散，因而汗出呕逆，乃邀余治。余固早知其病必重也，视之汗大如雨，身热烙手，舌苔满黄，口秽难闻，抑且绝粒不进，彻宵不寐，热微则神识稍清，热甚则神乱妄言，及诊其脉，洪大躁疾非常。余以谊关世好，而又金丹莫觅，直以病在不治之例辞之。盖《内经·素问》篇云：有病温者，汗出辄复热，而脉躁疾，不为汗衰，狂言不能食，病名阴阳交，交者死也。人所以汗出者，皆生于谷，谷生精气，今邪气交争于骨肉而得汗者，是邪却而精胜也。精胜则当能食，而不复热。复热者，邪气也。汗者，精气也。今汗出而辄复热者，是邪气胜也。不能食者，精无俾也。病而留者，其寿可立而倾也。此《素问》之言，已属吻合矣。又《灵枢》篇云，热病已得汗，而脉尚躁盛者死。今脉不与汗相应，此不胜其病也。狂言者，是失志，失志者死。今见三死，不见一生，虽愈必死也。况叔和云：汗后脉静，身凉则安，汗后脉躁，热盛必难。余以揣摩有素，莫敢援手，盖攻邪保精，两难立法耳。闻余告辞后，旋延二医，商从表里两解，未逾日，气高不返而逝。惜哉，设当日春升相见之时，肯听予言，急捣养阴镇阳之药，转刚为柔，归于中和，加以潜心静养，虽有此番病累，决无汗后洪大躁疾之脉矣。笔此以为养生者鉴，并为业医者鉴也。", "8320": "车启南之子，年方二十，发热头痛，服表散药，汗出淋漓，而热反炽，更狂言乱语，口渴粥饮不进。其戚友知医者多，特邀余诊之。脉洪大急疾异常，尺肤烁指，余知此症，为阴阳交矣，坚辞不治。门人在旁，嘱其不可用药。余出复延二医相商，与竹叶石膏汤，众皆谓可，未晚果卒。次早门人问曰：昨车姓之病，愚辈视之颇轻，而先生直云不治者，何也？答曰：此症《内经》明有开示一款云：有病温者，汗出辄复热，而脉尚躁疾，不为汗衰，狂言不能食，病名阴阳交。交者，死也。谓阴阳交尽也。凡治温症，若得战汗，理当脉静身凉，伤寒汗后亦然，今大汗既出，而热反炽，是汗为阴气之亡，而热为阳气之丧。夫汗为阴液，阴气既出，而孤阳独亢，因显躁疾之脉，已属不治，再加狂言乱语，是心肾阴精绝于内，神明越于外，合于脉之躁疾，其何以施救援乎？若能饮食入胃，游溢精气，或使精生于谷，尚可幸图于万一。今口虽渴，而粥饮不入，合于脉之躁疾，全失和缓之象，又无胃气矣。所谓今见三死，不见一生，虽愈必死也。吾侪身肩是任，可不见及此乎？门人促余笔之，以为后学之训。", "8321": "予临斯症时，病已四五日矣。某月十一日，睹神呆色垢，烦冤莫耐，潮热微而恶寒，脉小数促，舌赤唇燥，溺短而艰，是暑温之邪，深陷于营，势非易治。姑与淡渗轻清之药，而溺愈不通，脉现涩小，因思温邪固不可缓图，而淋秘尤当急治。且数脉转涩，下元阴必不充，仿滋阴化气之法，下午随疏滋肾丸作汤亟进，溺始得长。次日便泄溺短，更用五苓散加知母、木瓜，而二便无恙。十三日复诊，其寒热烦冤之状仍若，脉仍小数促，盖温邪虽陷于营，其去路已非从下，必当提出于表，方为合法，遂给兰草分消饮连服，而恶寒发热之恙稍减其半。十五日复诊，脉舒不促，但数小不长，谅非滋阴清热之法不可。连日服之，而寒热更减二三，神始清，耳始聪，惟烦冤之状，尚未能解。十八日，脉转迟数，舌清唇红，但指尖时微冷，天庭倏潮热而不自觉，盖温邪虽从表达，然脉象迟为阳虚，数断阴亢，是身中素虚之阴阳，尤当亟调。夫养正邪自除，理所有也。因订附桂八味连服二日，而脉皆平，诸病稍退，自云嗳气犹带地黄之味，意拟丹泽之寒乎？故改附桂理阴煎，脉来数多迟少，固知剂中过助其阳，念日更用柔阴扶阳之药，一服而寐已安。是日再视，二便寤寐如常，是暑温之邪已解。但脉来右犹带迟，左犹带数，口甘唇红，当从中治。似此阴阳两虚之体，寒热错杂余邪，最宜斟酌，非刚不足以涤秽，非柔何以济其刚？孔氏曰：宽以济猛，猛以济宽，政是以和，不佞谨以治国之法，而通于治病可乎？其药味必嘉言所谓能变胃而不受胃变者宜之，故疏连理汤与服，连进二日，所喜药与病机相投，但未知鄙见有悖而理否。至善后之治，犹未敢臆揣，缘一病变态不常，四方水土有异，谨陈颠未，附质慧眼采鉴。而善后之法，是有望于高明焉。后闻病者至家，仍以理中加枸杞服，旬余而安。", "8322": "熊清平，乃郎将冠，得温热病，自以感冒法治之。已不中病，延医更谓阴虚，投以六味地黄汤，益不中病。迁延旬日，胸腹饱胀，稍按甚痛，潮热渐退，四肢冰冷，手足爪甲皆黑，舌苔干燥，口不知渴，与之以水则咽，大便五日未通，小便赤涩而少，咽喉肿塞，日不能言，耳聋不知所问，六脉举按皆无。医者不审热深厥深之旨，郁热蓄盛，脉反滞涩之变；热甚神昏，口不知渴之情；复不将望闻问切，四字较勘，仅守发厥脉伏之假象，冒为真据；且将胸腹饱胀，为阴寒上逆，而可按拒按，置之不辨；咽喉肿塞，妄为虚阳上浮，而色之赤白，口气温冷，又置之不辨；又以大便燥结，谬为阴凝不化，而痞满实坚全具，又置之不察；直将一切内热明证，概为假热，竟用四逆汤，附子用到一两。清夫妇疑而未进，就正于余。内外一探，知为温热重病，阳邪亢热已极，反兼寒化，如酷暑雨雹之象，势亦在危。而细勘详询，明是在表失表，在里失里，酿成极重热症。再诊其脉，举按虽无，而沉候至骨，劲指甚坚，根蒂未绝，喜其可治。因谓曰：此大热症也。遂疏黄连解毒汤合普济消毒饮，重加大黄，嘱其日夜两剂，务俾大便通则火不伏，而厥可回，脉可出。清因二医一用附子、干姜，一用黄连、大黄，冰炭莫辨，无所适从。然其妇急欲将余方购药，而清究不能决，更延一医，匆匆一视，又谓为阴毒。其妇曰：生死有数，若服谢先生药，死亦无恨。清因妻意甚坚，勉为煎就，意仍狐疑，其妇强为徐灌。约二时之久，一剂已终，小水甚长，即索水饮，清见人事略醒，复煎一剂，是夜连得大利，果厥回脉出。次早复视，更以凉膈散，重服清胃药而健。后置酒于家道谢，清因述曰：众医谓为阴寒，独先生断为阳热，小儿几希之命，固蒙再造，但承赐妙方，若非内子坚意，几乎误矣。余惊疑之，嫂何以独信予也？适其妇出房道谢，其妇曰：先生初视之时，面有忧色，是忧其难治也；及诊毕而踌躇深思，是思其可治也；至再诊而面忽有喜色，是喜其得法也。且审症而战战兢兢，疏方乃洋洋溢溢，是直无所疑也。先生慎重若斯，无疑若斯，予复何疑？余闻言深为叹服。夫医家望闻问切，而望居其首，业医者往往忽之，今熊妇竟能望医之神色而知医，吾辈昧昧不且有愧于妇人乎！", "8323": "尝读医门八法云：伤风自汗，用桂枝汤，伤暑自汗，则不可用。又曰：人知发汗退热之法，而不知敛汗退热之法。敛也者，非五味、酸枣之类，是谓致病有因，出汗有由，治得其法，汗自敛耳。如傅金生一症，时当暑月，天气亢燥，饮水过多，得胸痛病，大汗呕吐不止，视之口不渴，脉不躁，投以温胃之剂，胸痛遂愈，而呕吐未除，自汗头眩加甚。其父来寓更方，余以昨剂颇效，原方加黄耆与服，服后亦不见躁，惟汗出抹拭不逮，稍动则眩晕难支，心下悸动。举家咸以为脱，吾许以一剂立愈，以半夏五钱，茯苓三钱，生姜一片，令即煎服，少顷汗收呕止，头眩心悸顿除。盖缘饮水过多，水停心下，火位不安，故惕惕悸动。本仅当心下作痞，兹以阳气素虚，更重为心下作痛，所以前投温胃之剂，助阳消寒，其痛自除，但水饮犹未下耳。水气上逆，则呕吐不止，水气上干，则汗眩难支。举以大半夏汤，行水散逆，使水下行，则呕悸汗眩俱止，所谓治得其法，汗自敛耳。由此益悟认症宜真，而辨症宜细也。试观瘀血症，亦头汗出，然必小便不利，而目珠先黄。又邪在少阳，亦头汗出，虽有呕吐目眩，胸满之兼症，然必有寒热往来之本症。至于伤暑自汗，郁热陷里自汗，阳明熯热自汗，三阳合病自汗，更有中寒冷汗，表虚自汗，阳脱自汗，汗多亡阳，与夫惊恐房劳，风湿漏风，产蓐津脱，以及盗汗诸症。凡阴虚阳胜，阳虚阴乘，种种汗出不一，各有兼症不同。且头与身皆汗，又与独见头汗迥异，乌可概指为虚脱耶？此余趋庭传受心法，今并志之。", "8324": "丁麒寿，时当暑月，腹痛泄泻，自汗神疲，叠进温补，遂至二便窘急，日益危笃。适一邻医，年六十余，谓病经数日，汗出不知几斛，兼之四肢逆冷，法在不治。且补剂服至附子、鹿茸，仍无寸效，今脉绝，无可为也。其家固贫，医药已难继矣，又听邻医之言，遂无复再生之想。奈病人呻吟在床，不忍坐视，遥闻先君善治危症，托人求诊，适应酬未暇，命余前视。诊得脉虚，重按若无，审得额汗溺短，气虚烦渴，背微恶寒，四肢逆冷。余笑曰：此伤暑也，安得以阳虚目之？经云：气虚身寒，得之伤寒，气虚身热，得之伤暑。今症见烦渴溺短，气促脉虚，伤暑奚疑？议进清暑益气，合桂枝汤一剂，嘱其即服可效。前医执余方私语病家曰：年少之医，孟浪殊甚，临危之症，犹谓伤暑。今汗出淋漓，收敛尚恐不及，反用升柴桂枝以发汗，非速其毙耶？其家虽疑，缘病由奔走日中而起，信余不谬，即进一剂，病势减半，继进二剂，兼吞消暑丸一两，腹中呱呱有声，二便一时通利，汗收渴止，烦退而安。复将原方除桂枝，二剂全愈。越三日来寓酬谢，始述前医之非，予不禁为之一快。夫暑属阳邪，心属离火，故伤暑必先入心，心主血脉，故脉虚大，不足重按。意在邻医，不知浮中沉三取之法，且暑脉多芤，状如葱管，浮沉二候易见，中取正在空处，故断为脉绝。余用参耆归木，合生脉散，养心而裕脉，固土以保金。其暑热伤津，故口渴溺短，饮水过多，停聚中脘，误进温补收敛之药，故二便不利，水气上涌，宜其头汗如雨。余二剂中，兼吞消暑丸，虽曰消暑，亦仿小半夏加茯苓汤，治水气头汗之意也。方中升柴葛泽，升清降浊，譬之云行雨施，然后沟渎自通，注之不盈，而额汗自收矣。", "8325": "傅妇，叶孕四月，恶寒体木，咽肿牙紧，付外科医治，内服外敷，直至声音不出，汤水难入。危急之顷，商治于余，其意中仍泥为痈毒之病，其延余者，欲决生死，非求治也。诊得脉来浮滑，身中麻木畏寒，悉是风痰为病，盖风邪中上，故多有咽喉上痹之症。此与前案，治品翁内人，牙紧舌胀相符，余令将外敷之药洗去，先与稀涎散，调水灌之，涎出口开。更有奇者，视其舌下另生一齿，观者数十人，咸称从未见闻，其齿大如枣核，摸之棱指，按之似痛。遂以白矾肉桂末，点于舌下齿旁，立时取落，敲之即碎，外黄内白，遂乃开声。疏以驱风消痰之方，二剂而痊，胎亦无恙。然意谓向治品兄内人舌下之虾眼固奇，今治惠先兄室人舌下之鬼齿，则又更奇矣。究皆风涎所生，可见风无定体，其为病之变态，人难测识，类多如此。", "8326": "汪亮辉，年逾五十，患偏头风症，自汗不止，脑中觉有冷涕一阵，自鼻而出，医人不识，与苍耳散，盖错认鼻渊症也。汗愈大，涕愈冷，痛愈甚，又与真武汤，盖误作阳虚头痛也，渐至火升便艰。更医又与茶调散，满头筋胀，二便阻滞，盖不识虚实内外之风故也。考虚风内动之症，仲景以后，罕识其旨，惟近代天士叶氏，养肝熄风，颇得其法。今此症脉左浮大，风居空窍，扰乱不息，头汗不止，是为内风虚风可知矣。夫风气通于肝，必养肝之中，佐驱风之品，然头脑空窍，隧隙颇多，最难尽逐，必兼佐以堵塞之义，则空窍之风，无隙可乘。乃仿《金匮》侯氏黑散，内取桂枝、龙骨、牡蛎、菊花，驱风填窍，更取叶氏养肝熄风之法，如首乌、黑芝麻、金钗、钩藤、桑叶、荷叶之属，不数剂，诸病如失。此症余经验颇多，向未发明，学者鉴此，当知治法矣。", "8327": "赵近仁，年将五十，须鬓已苍，左䚡自肩臑肘胛，麻木不舒，脑中鸣响。医者见其满面油光，饮食如常，辄称其气血之华，谁识真阳外露，肝风内鼓？所服之药，不出独活寄生汤之法，欲为驱风，适以招风，乃由平时不讲内外之风故耳。即有进以八珍之属，冀其血行风灭，无如杯水车薪，不济所事。且值冬初，寒风凛冽，木叶尽脱之际，渐显头眩耳鸣肢堕等症。余诊脉象缓大，知水不濡木，肝风始张，肾气将腾，卒倒痱中之日来矣。授以河间地黄饮子，加鹿茸，大剂煎服，欲其火归水中，水能生木，兼制扶桑丸，用以流利关节，祛湿润燥。服至腊月，肢体劲强，神彩内蓄，自觉神魂返宅，适因岁暮，停药未进，故头眩虽息，而脑鸣未止，应知髓海难充，亦功亏一篑之过耳。", "8328": "王惠阶，年壮形伟，大便下血，医治半载，以平素嗜酒，无不利湿清热以止血，如地榆、柏叶、姜、连之类，服之不应。厥后补中、胃风，四神之属，投亦罔效。求治于余，诊脉小弦，大便或溏或泄，不及至圊，每多自遗，其血清淡，间有鲜色，更有奇者，腹中无痛，但觉愊愊有声鼓动，因悟此必虚风内扰，以风属无形有声，与经旨久风成飧泄吻合。且脉弦者，肝象也，肝风内动，血不能藏故耳。因与玉屏风，重防风，加白术，乃扶土制木之意。更加葛根，辛甘属阳，鼓舞胃气，荷叶仰盂象震，挺达肝风，叠投多剂，其症一日或减，越日复增，轻重无常。予思虚风内动，按症投剂，疾不能瘳者，何故？潜思累夕，不得其解。忽记经有虚风邪害空窍之语，盖我居肠间，尽是空窍之地，非补填窍隧，旧风虽出，新风复入，无所底止，故暂退而复进。乃从《金匮》侯氏黑散，驱风堵截之义，悟出治法，填塞空窍，将原方加入龙骨、石脂，兼吞景岳玉关丸。不数日，果获全瘳。", "8329": "俞昌大，初病恶寒发热，继则热而不寒，喜睡羞明，二便略通。医以为外感，进败毒散，症变热炽谵语，又以为瘟疫，投达原饮，症变神识昏迷，更医断为虚脱，与理中汤，舌苔干黑，肢体若僵，绝食不进。家人治棺待毙，姑延一诊，以决卒期。诊得左脉沉缓，有脉数急，面黑目赤，昏昏嘿嘿，耳聋不知所问，上部扪之觉热，下部扪之觉冷，统计之，有似水衰火炎之象。细视左肢微肿，扪之觉有痛色，于是知为风邪所中，误治而至此也。法参喑厥风痱之例，以地黄饮子，服至二日方醒，七日全愈。", "8330": "何允中，年二十，两腿疮毒，脓水淋漓，医治半载，内服外敷，愈加浮烂。一日忽微热，身体抽掣，两目上瞪，喉中痰响，全似小儿惊风之形。请余视之，方诊脉，其老妪捧药一碗，辛散异常，诊毕，问所捧何药，系大秦艽汤也。余掷之于地，遂疏理阴煎，加黄耆、附子大剂与之。连服两剂，而眼已不戴，身已不强，随服十全大补汤数十剂，疮毒全愈。然此症实有天幸，倘不遇余，大秦艽汤已投之矣。盖医者，只知风邪为害，不知风从何来。彼其阴血先已失守，津液枯涸，筋脉不荣，阳气不藏，是为阴阳两竭之候，此际收摄已晚，尚堪辛散耶？况古云：治风先治血，血行风自灭。不但疮家，凡误汗，失血，泄泻，痘疹，以及产后老弱小儿诸人，此症最多，皆当审察。", "8331": "吴承先令爱，体素孱弱，勤于针凿，忽浑身战栗，牙关紧急，舌可略露，口不能言，时露抽搐角弓之状，寒热悉无，小水仍利，疏风解表之药不效，病经两日，其势渐危。诸医见大便未通，欲行攻下未决，余至，众皆推治。诊之脉来缓大，方思议间，手足抽搐，角弓反张，牙关紧急，两目翻视，诸医告退。窃此症其来甚暴，应知暴病非阳，且无寒热，决非三阳实邪。若果外邪固闭，其人早已昏迷不醒，安得清明若是？此必血虚风中，筋脉瘛疭无疑。与大剂十全大补汤，重肉桂，加附子急进，抉齿灌入，俾得略睡，其势稍止。昼夜一周，进药三剂，乃得口开能言，然犹微搐，共进十余剂始安。", "8332": "附：厥后郭永明，老年独子，稚龄体弱，深夜看戏回家，立时即病，悉同此症，明是血虚风中。余与前药，畏不敢进，竞争疏风化痰，兼进法司符水，分明可生之症，竟至不起，诚可惜也。须知阳邪之发，其来必渐，阴邪之发，其来必骤。人鬼关头，先具成见，况闭症多握拳，脱症多撒手。又凡中症，有中腑，中脏，中血脉，中经络之殊，有真中，类中之别，若不平时领会，岂不害人于冥冥中耶？", "8333": "傅海翁之媳，于归匝月，时值暮春，忽然仆地，眼翻口噤，两手握固，半晌方醒，已而复发。他医认为痰火闭窍，进大黄、槟榔、菖蒲、桃仁之属，治经半月不痊，众皆束手，延余诊治。见其唇红面赤，脉沉实而滑，问得饮食间，微若有呕，因称贺，海翁惊问，余曰：令媳之症乃胎痫，怀孕使然。因其体素有火，即误服破泻之药，而体坚病实亦无大碍，不治并亦无妨，但得药早愈，免合室惊惶耳。因以四物，加枯芩、半夏与之。仍然发闭，病者瞑目，口中呓语曰：我要银子还，不然，我要索尔命。众议此必邪祟所侵，又见其两手撮空，循衣摸床，皆曰：昨谢某在此，妄言胎痫，今已将危，何不延他一视？慌忙来寓，急延余往。余曰：早言胎痫小恙，何必如此大惊！此女肝家枯燥，此刻胎中正肝经主事，肝藏魂，血燥神魂不安，所以目中见鬼，口中乱语。又肝属木，木喜摇，所以手循摸耳。今吾以收魂药招之镇之，的可痊愈。疏方与服，数日未发，然不可停药，停药数日，往往复发如前，竟服至足月方已。后获弄璋，肥大之甚，母子均安，众称良治。", "8334": "大凡中风，中痰，气厥，血厥，病虽起于仓卒，决无屡发不愈。兼之妇科患此，即不论脉与症，亦当拟度其胎。况有脉可凭，有症可据，有因可问，是以预许为胎痫之疾。今方中具有收魂，养神，镇惊，消痰，补虚，润燥，种种妙用，全无方书所用胎药，一概出乎心裁。男澍谨识", "8335": "姜吉甫翁令正，据述今春分娩，得子甚小，患胎风症，不育。今秋燥气异常，患咳者比比，及大雪，正值肾阴当权，得咳嗽气促畏寒之恙，每临夜，两颧赤如火烙。认为寒邪外束，与以疏散之药，数日未效，然亦不介意。偶于五鼓时，忽然眩晕，四肢如麻，倏时冰冷，人事默默，胸紧气促，喉内痰鸣，逾时方醒，醒而复发。医者认为虚寒痰厥，进附杞陈半之剂未中。余见其形体清瘦，脉来弦数劲指，问知数日不寐，寐则口中乱语，且睡中每多惊怖，如坠于地，唇舌二便如常。因谓曰：尊阃之体，肝火太旺，以致血燥，无以荫胞，所以胎小而多风。即今之病，亦属肝风之症。夫人之一身，心高肾下，水火固不相射，然须相济。经曰：君火之下，阴精乘之。今元阴浇薄，何供所乘？所以火愈炎，木愈燥，风愈张，风火相煽，心主撩乱，而人事眩晕矣。治法发散攻下温补诸方，皆不相宜，发散而火愈升，攻下而阴愈亡，温补而阳愈亢，即补水之剂，亦后来调养之法，施于此际，殊属迂远。大约木喜调达，风宜静镇，火宜滋润，遂其生发之性，不令抑郁枯槁，使守其常而不变。吉翁闻余议，颇不以为非，促令疏方，连进数剂而愈。", "8336": "越旬日，人事清健，诸病顿除，更委善后之法。余诊毕论云：尊阃玉体清瘦，脉来尺涩关弦。夫涩者，血虚也。弦者，肝燥也。至于形质，在五行之中，禀木火而生者，其为人也性急，主正直，主多惊，主多怒，主善忧，主善敏，种种不一。大抵木有凋谢之日，又有生发之期，火有遏止之时，又有炎威之候，而火生乎木，木又畏火，前此之眩冒，肝风张也。吾不用驱风之药，但取养肝润燥之品，既已呈效，今嘱善后，所云补水之剂，可参用矣。诚能怡情善养，药饵平调，滋润苞根，不使枯槁作燃，即保无虞。管见酌方，后如叶梦，即当赐音召诊。", "8337": "杨桂生，初起呕吐，继而呵欠甚长，腹中绞痛，难以名状，身摇心振，十指紧撮，自谓爪掏肉痛，头汗气蒸如雨，发经片时，已而复发。日延数医，用尽驱风化痰之药而无效验，咸谓方书罕见，决无治法。余诊其脉，沉伏中忽显弦数，弦数中忽然沉伏。诊毕，一医旁问曰：先生，此何病也？余曰：木强土弱，肝风病耳。试观疟之初发，始必呵欠，今呕吐呵欠腹痛，显系土衰木往乘之，所以胃中不能容谷，肝阴被火所劫，是以筋急而牵引撮紧。但肝为刚脏，一切逐风辛散之药，反能助火劫阴，岂非愈加其病！况风热虽一，而木属有二，若病在少阳甲木之风热，固当仿小柴胡之制，今病在厥阴乙木之风热，又当变通小柴胡之制，仿喻嘉言先生，所谓丹田有热，胸中有寒之例治之，二剂而愈。", "8338": "周秋帆茂才内人，怀孕数月，一日周身痛痹，四肢拘挛，肌肤及手指掌皮，数变如蛇蜕之形，惊痛交并，恐成废疾。余诊脉得浮大，按浮为风，大为虚，此营卫不固，血虚风袭之候也。原中风，有中腑，中脏，中经络血脉之分，故见症各著其形。今起居如故，饮食如常，外无六经之形症，内无便溺之阻格，惟苦肢节间病，风中血脉奚疑！处以当归四逆汤，当归重用，佐以一派祛风之味，连进四剂而愈。", "8339": "黄锦盛，头左大痛，医以为偏头风，凡疏风清火之药，服之其疼愈甚。观其脉盛筋强，纵欲必多，以致水因下竭，而火愈上炽，宜养肝以熄风，滋阴以潜阳。仿仲景济阴复脉之例，参入嘉言畜鱼置介之法，与何首乌、阿胶、胡麻、麦冬、白芍、菊花、桑叶、牡蛎、龟板，药下其痛立止。惟其房劳不节，加以服药不坚，宜其愈而复发也。凡阴虚头痛之症，法当准此。", "8340": "曾魁星，六月由家赴湾，舟中被风寒所客，恶寒头痛，连进发表，头痛愈甚，又与归附芎芷之属，头愈不耐，呻吟床褥。同事中，见表之加重，补又加重，且有呻吟不已之状，莫敢措手。余诊之，脉来浮缓，二便胸腹如常，问其所苦，仅云头痛，问其畏寒，亦惟点额，又问饮食若何，则曰腹中难过，得食稍可，又不能多食，所以呻吟也。余曰：此中气大虚，清阳不升，浊阴不降，以致头疼不息，过辛过温，非中虚所宜，本宜补中益气，则清阳可升，浊阴自降，而头患自除，中虚自实。但因前药辛温过亢，肾水被劫，故舌苔满黄，小水短赤，故用益气聪明汤，果一剂而愈。可见医贵精思，不可拘泥也。", "8341": "头风一症，古无确论。原风虽属阳邪，实有内外之分，浅深之别，病多委曲，治少精详，且更混列于头痛门，悖谬不可胜纪。惟近代叶氏、黄氏，始有头风失明之说，仆鉴头风害目之流弊，颇得其旨，知眼科内外诸障，即方脉科之内外头风也。日者仁兄语以头风之病，欲为急治，且谓多因饮食失宜，烦劳过度，以致内风为患，足下虽未习医，不啻深于医理者。及今诊脉，益信不诬。盖头痛一症，或风，或火，或寒，或痰，而脉遂成或浮，或数，或紧，或滑之形。今脉来主绪清晰，丝毫不紊，且来去应指纯静，在叔和，则谓六阴永寿之征，在《太素》，则称脉清品贵之验。正岐伯所言，众脉不见，众凶弗闻。然脉既无病，则内无实据之风火寒痰可知。而其所以头痛者，诚以萦思过度，加以夜坐气升，扰动肝阳，化风内起。夫肝为刚脏，体阴而用阳，又经言肝为将军之官，谋虑出焉，内因之病，当从此脏悟之。夫肝喜疏泄，故常有梦遗精泄之症。又上盛而下必虚，故见有足寒筋惕之症。且肝阳既已化风内动，必乘阳明而走空窍，故兼有牙龈牵痛之症。窃拟头形象天，为清虚之界，惟风得以居之。夫肝阳伏则风熄而镇静，肝阳升则风旋而鼓舞，足下之头痛时止时发者，关乎肝阳升伏之故也。《内经》以目为肝窍，内风日旋，肝阴日耗，神水消烁，清窍遂蒙，阳亢阴涸，其明渐丧。然则头风害目之弊，亟宜除之。仆尝揆人身一小天地，天地不外阴阳以为运用，人身不外水火以为健行，审症当求虚实，治法必从标本。足下水非不足，火非有余，只因肝阳上行逆僭，不肯下伏潜藏。至于用药大旨，不过和肝熄风、育阴潜阳已耳。然犹有权宜者，务在识机观变，巧施手眼。风若鼓时，乃标重于本，则兼治标以固本，凡轻清甘缓抑扬之味，不得不为酌投；风若静时，乃本重于标，则当固本以除标，凡介类沉潜柔濡之品，不得不为亟进。审度于可否之间，权衡于化裁之内，必使肾阴上注，肝阳下降，庶几清空之窍，永保光明之旧矣。辱承下问，敢抒蠡测，惟仁兄鉴之。", "8342": "夫病有未经临治之症，亦必有未经用过之方，果症奇耶，抑方奇耶？总之内外之因，变幻不一，未经临治之症，汗吐下消和温清补八法，凡未经主用者，皆当触类旁通，分经别络为之主用其间，而收捷效者，乃曰善。王子冬，临治林用礼，心腹气痛，牵引头巅，绵绵半载，犹可治事，偶因用椒炒鸡，两块下咽，头痛如破，神昏气喘，不敢稍动。诊得脉如平人，不疾不徐，惟眉棱骨内痛如刀刺，天明痛发，至午如刺，至夜如失。余临症十余载，未尝一遇，即平日所读书中，亦不见载，惭愧实甚。勉从厥阳上冒，鸡性助肝之旨，且痛甚于左眉骨，用熄风和阳，两剂不效，更进清肝凉血之剂，亦如故。窃思痛发天明，正肝木旺于寅卯，显属肝火为患，治之不中肯綮，其理安在？复将三阳头痛疆界辨别，计眉棱骨，属阳明，阳明者，胃府也。经曰：葛根阳明药，柴胡少阳药，于太阳有何涉乎？此三阳之药，治三阳之病，稍逊毫厘，尚无干涉。今眉棱骨痛，果阳明胃火，而主治厥阴，宜乎罔效。乃疏以石膏、石斛、生地、丹皮之属，佐以葛根为使，服之果获全愈。余甚愕然，怪其速愈也。一日检阅诸书，适见《张氏医通》，于头痛门中，集有眉棱骨痛一条，分虚实两途，并用选奇汤，虚加归芍，实加葛膏。又曰：虚而痛者，天明时发，实而痛者，昼静夜剧。此虽与余治验痛发天明属热稍异，足征先贤纂述，用心颇苦。想张氏当日集头痛诸症，特拈出眉棱骨痛一条，多属阳明风热之语，以一时之心裁，启后人之端绪者多也。若曰分门别汇之症，先贤皆经临治，溯百岁之师，未尝尽遇也。所谓审机之士，不拘于文，通变之才，自符千古，亦视乎人之心思耳。", "8343": "汤胜参傍山而居，其地甚小，以农为业，时值暑月，其家腹痛呕吐，老幼相似，已亡数口，病之传染，沿门合境，而邻族中死者病者，更复不少。其戚友以为天灾流行，不相探问，近地诸医，咸远迹不至。及胜参自病，医巫交错，身已将危，始托友求治于余。至其村，满目凄凉，览其病，舌红口渴，目泛神昏。因问初起若何？其家哭云：起先腹痛呕吐，身热肢厥。余曰：此阴毒也，服何药而至此？乃将前医之方递出，悉柴胡、香茹、芩连之属。余曰：是矣。不待诊脉，先取药至，疏以附子理中汤，随进附子理中丸。于是汤丸互进，昼夜不辍，次早复视，其浊阴驳劣之逆，赖以潜消。但微阳复返之象，尚属游移，遍身小泡攒发，肤腠溱溱自汗，濈濈发热，脉来浮大，舌赤无津，转方以八味地黄汤，加黄耆五味，大剂缓进。昼夜再周，方得起坐思食，肤泡渐退，遍身复发小硬疖，肤无空隙，乃阴浊之毒，内伏而外出也，仍与八味小剂频服。于是合村颠连之家，悉求治于余。初起者，多腹痛，呕恶，发热恶寒之候，给以藿香正气散，加附桂温中而通阳；有阴寒极甚，而格药不入者，与之白通汤，加猪胆汁，引导而通阳；有阴寒入于血脉，厥逆无汗者，投以当归四逆汤，加附子、吴萸，温经而通阳。种种治法，随症而施。匝月以来，虽皆安好，然愈而复发，病风尚炽，细揣必有其故。因忆临治以来，各家之茶，皆混浊不清，初意以为不洁，久而疑之，因令取冷水一碗，视之其色混浊，尝之其气冷劣，而味苦硬，因叹曰：此地毒也，岂天灾乎！即问水从何出，众曰：屋后山下有土井一孔，历有年矣。亲往视之，满井混浊，余曰：毒也。试问时值六月，本当清泉澄映，况一向酷暑未雨，若非地毒，此水安得混耶？众皆醒悟，咸谓从无混水，今若此，或者山上旧冬所葬新冢之碍乎？嗟嗟，乡愚，昔清今浊，显然不识，其斯地之数乎？盖六月天时，阴气在下，人身阴气在内，再逢山脉之变，阴毒侵脏，酿成种种寒症。急令他处掘地取水，并制管仲、甘草、雄黄、黄土，各用斤许，煎汤一斛，与之皆啜。更经半月，病风遂息。由此观之，凡为医者，水土不可不辨。其乡人议建祠立位以报，因捐资维艰，有志未逮焉。", "8344": "记读《景岳全书》，有刮痧新按云：向予荆人，年及四句，于八月终，初寒之时，偶因暴而后，中阴寒沙毒之气，忽于二鼓时，上为呕恶，下为胸腹搅痛，势不可当。时值暮夜，药饵不及，因以盐汤探吐之，痛不为减，遂连吐数次，其气愈升，其痛愈剧，因而上塞咽喉，甚至声不能出，水药毫不可入，危在顷刻间矣。余忽忆幼时，曾得秘传刮痧法，乃择一光滑细磁碗，别用热汤一盅，入香油一二匙，却将碗口蘸油汤内，令其暖而且滑，乃两手覆执其碗，于病者背心，轻轻向下刮之，以渐加重。碗干而寒，则再浸再刮。良久，觉胸中胀滞渐有下行之意，稍见宽舒，始能出声。顷之，腹中大响，遂大泻如倾，其痛遂减，幸而得活。泻后得睡一饭顷，复通身瘙痒之极，随发出疙瘩风饼如钱大者不计其数，至四鼓而退。愈后，细穷其义，盖以五脏之系，咸附于背，故向下刮之，则邪气亦随而降。凡毒气上行则逆，下行则顺，改逆为顺，所以得愈。虽近有两臂刮痧之法，亦能治痛，然毒深病急者，非治背不可也。至若风饼疙瘩之由，正以寒毒之气充塞表里，经脏俱闭，故致危剧。令其脏毒既解，然后经气得行，而表里俱散也。可见寒邪外感之毒，凡脏气未调，则表亦不解，表邪未散，则脏必不和，此其表里相关，义自如此。故治分缓急，权衡在人矣。愚窃思寒毒中脏，脏为里，所以里气不达，外受之邪，表亦不散，非温经通脉，鲜克有济，足与是案互相发明，故特录出以公诸世。（男澍谨识）", "8345": "胡生考成，夜半潮热，头脑晕痛，脉来浮数，舌心带燥，似表有热邪。然其平时面色失华，声音不扬，知为中虚之体，不敢清散，姑以六君去术加金钗与之。是夜潮热愈炽，口出谵语，次早再诊，脉仍浮数，目赤舌刺，汗出透衣，开目谵语，昏不知人，小水赤色，大便不通，种种见症，颇似实热。但潮热虽重，尚可覆被，舌虽干刺，不喜冷水，与粥一杯，便如虎嗜，再啜发呕。参诸平时声色，而又发自半夜，知其表虽热，而里实寒，若果阳明实热，见此症候，便扬手掷足，安得覆被昏睡耶？又安得渴不消水，啜粥辄呕耶？昔喻嘉言，有谓热邪既盛，真阳复虚，此是真阳既虚，而热邪复盛耳。授以益元汤，原方中姜、附、参、草、艾叶、葱白，回阳补虚，合乎甘温能除大热之旨。浮火之泛，有黄连折之；阴气下竭，有知母滋之。且二味苦寒，更借以制姜附之猛烈，庶于口干舌刺之症，服之坦然无碍。若夫大汗伤津，有麦冬、五味，生精敛液，仍以姜枣和谐营卫，更入童便冷服者，犹恐格阳之症，拒药不入，合乎热因寒用。其始则同，其终则异。统而言之，究归清补之药耳。一剂诸疑悉减，再剂热退身凉。但愈后难健，调理之药，大剂养荣汤，叠服数十剂，始获如原，盖由少年禀赋不足故耳。", "8346": "陈怡太年老体弱，辛苦劳力之人，得伤风小病，头身作痛，发热畏寒。医者不以劳力伤风之例施治，乃以败毒散二服，遂变大汗如雨，舌干如刺，满面赤色，神志昏惑。问其小便不利，大解不通，俨似极热之症，余固知为误治所致。老年阴气既衰，误汗愈涸，故舌刺口渴，而泉源既竭，二便必变，诊脉洪大，按之寂然，虽无急疾之象，然恐误表戴阳于面，元气随汗立散。意欲行真武坐镇之法，但津液内竭，难受辛温之亢味；将欲与生脉救阴之意，而甘酸之药，其何以回垂绝之元阳？继思独阳不生，盖阳无阴，则孤阳失所，而飞越戴出矣。必得扶阳之药，而兼济阴可也，处古益元汤，回阳生阴。药一下咽，果获熟睡，舌刺少减。再剂，热退身凉，汗收食进，与理阴煎，数服而康。", "8347": "许晴霁室人，患伤风咳嗽，诸医投以疏风清肺之药，渐至潮热口渴，尚不知误，更以柴葛、知母、花粉之属进之，遂变面红目赤，舌刺无津，渴汗齐来，谵语无次。余临其帷，视之骇布，固知其阳已戴于上也，而前医本所素信，忽忽复至，惘惘一视，尚谓传经热症，急取雪水服之。盖仅知其上热，而不知其下寒也；知其脉洪，而不知其大空也。因令煎龙眼汤斤许，遂疏八味丸合生脉散，是晚进药不辍，次早复视，俾无根飞越孤阳，才得退藏于穴，复追进附桂理阴煎，数十剂全愈。", "8348": "生脉散", "8349": "陈南圃先生，由京归里，舟泊许湾，忽觉浑身麻痹，自服灵宝如意丸，得稍安。日西，浑身大热，谵语无伦，昏夜邀视，见其面色如妆朱红，热势沸腾，脉虽鼓指，重按全无，上身躁扰，下半僵冷，知为肾气素虚，真阳浮越肌表。恐其战汗不止，藩篱洞开，势必飞越而亡，宜用表里先后救援之法，因处大剂真武汤与之，坐镇北方，以安肾气。饮毕，复预煎黄耆二两，附子二两，五味、龙骨、牡蛎各五钱，沉香、肉桂各一钱，此畜鱼置介之法，以救既散之阳。后药方煎，人事已清，亥刻果然浑身战栗，魄汗不止，叉手冒心。即将预煎之药，亟为啜尽，俾得战止汗收。盖未绝之阳，先已安堵，而既散之阳，复以驷追，千金之身，救援有数，诚非偶然，重服养荣汤而健。", "8350": "陈甫三内人，洒淅恶寒，倏忽潮热，时值夏初，疫症流行。余诊其脉，缓大而空，舌白苔滑。又询其素有肠风便血，经不及期，且外虽肥盛，内实不足。察脉审症，知中气大虚，病从饮食劳倦中来，乃外耗于卫，内夺于营之症。与东垣益气汤，托里散邪之法，畏不敢服。更医谓是疫邪初起，当服达原饮，服后大热谵语，又见大便不通，更与大柴胡汤，连进二剂，症变热炽躁扰，张目不眠，谵语发狂，且甚有力。医见其表里皆热，更疏白虎合承气一方。甫三素与余契，药虽煎成，疑未敢服，就正于余。余视其目红面赤，乱言无伦，及诊脉，下指洪大，按指索然，此五脏空虚，血气离守之验。是日午刻以人参养荣汤，武火急煎，药才下咽，时忽咬齿，两手撮空。余甚怵惕，盖昆仑飞焰，挽救弗及，旁怨莫解，但审症既真，自当极力处治。时方申刻，又将原方四倍，加入附子二两，入釜急煎，逾时服毕，谵语未息，而发狂少止，似寐非寐。与粥一杯，大呕稠痰，其色青碧，是又不得不先救胃阳。戌刻复煎附桂理中一剂，药未下咽，寒战咬牙，肉𥆧筋惕，此假热一去，真寒便生之应也。只恐油汗一出，脉阳立越，幸药已备，亟与进服。亥刻果汗厥齐来，又与理中一剂，遂得安眠，片刻汗收肢温，复与粥饮不呕，差喜阴阳两交，胃气稍苏，余亦安睡。次早视之，阳已不戴，脉亦有根。然昏迷困惫，犹言见鬼，目尚赤，口尚干，此阴火未熄，虚阳未返，津液未生，神魂未敛，以归脾汤吞八味丸，数日喜获生全。但口苦少寐，与归脾汤，加山栀、丹皮，大便已闭十五日，至此始得一通。盖胃气素虚，仓廪空乏，经血不荣之故，更与十全大补汤，服半月方健。愈后，窃自笑昔吴又可先生治温疫热邪内盛，一日三变，急症急攻之条，数日之法，一日行之。余今治虚寒真阳外越，一日三变，有急症急补之验，亦数日之法，一日行之。症治不同，用意则一，学者当于读书之余，亟将阴阳真假之辨，逆从反正之法，殚力追寻，极穷其奥。日常闭目凝神，讨求至理，有如悬镜当空，妖魔悉显，庶几胸有定见，不为假症所惑，于以扶危拯溺，救世之慈航也。", "8351": "陈祥光，老年劳力感寒，医者不究其内伤色脉，拘定潮热咳嗽，日与外感之药，极力疏散，乃至气急神昏，烦冤莫耐。与之以水，可饮一杯，与之以食，仅尝一口，问其头痛，则云头痛，问其胸紧，便云胸紧，此气脱神昏，与热盛神昏者迥然不同。余察其形羸色晦，黏涎满口，二便如常，按脉冲指，忽散如汤沸腾，知为虚阳上攻脱绝之候。急与大剂附桂理阴煎，吞黑锡丸数钱，得安卧，重服前药而健。", "8352": "附：后其乃媳小产后，感冒寒热咳嗽，余视其面白唇燥，脉来虚大，其热忽有忽无，此产后血虚感寒，与补中益气加熟地、姜炭。其家咸议恐补住寒邪瘀血，更医进发表一剂，即变气促大汗。复延余治，更见其面红目赤，耳聋谵语，脉来如汤沸腾，此阴虚阳越，势在险笃。疏与八味地黄，重附子加五味，嘱其急服，尚可挽回。岂知复疑不决，且嫌言过激烈，旋延一医相商，妄称热入血室，竞用四物柴胡一剂，大汗发痉而逝，岂非下井压石者耶？呜呼，病家固不识病，又不识医，医者产后药禁不明，兼症不考，两者俱昧，每致伤生，悲哉！", "8353": "陈希正学博，素禀阳虚，时届秋令，偶伤于风，寒热间作，脉来浮缓，议用桂枝汤，重加附子。将疏方，寒战鼓栗，热汗骤至，进药少安，越日咳嗽，知汗后腠理空疏，复召外邪，遂将原方去白芍，加荆防。服下汗倍于前，而寒热咳嗽悉除。后因口干鼻热，类于火气上炎，自认秋燥焚金，未审汗后津伤，辛散耗阳之理，误进甘寒一剂。熟睡良久，越时口渴，火愈上炎，又误进参叶汤一碗，继进稀粥二碗，遂至胸腹饱胀，汗出如雨。复请予视，满面红赤，脉来冲指，内外一探，阴气弥漫，知为参叶稀粥阴壅之气，无由转输，上冲心肺，从皮肤而作汗也。因悟搏激过颡，逆行在山之理，取五苓散，加姜附以进，俾得膀胱气化，小便长行，汗止胀消而安。未越日，体间又津津自汗，于是汤扑兼施，按治不辍，面红虽息，汗仍不止。经云：阳气者，若天与日，失其所则折寿而不彰，故天运常以日光明，是故阳因而上冲外者也。今汗止复出，非由腠理空疏，阳不卫外之咎欤？遂用真武，重加附子，少佐收摄之味，服下汗虽渐止，而四肢渐厥，口渴喜饮，频引热汤自救。其间有议伏疟未分者，有议口渴服燥药太过者，纷纷聚讼，惟余独唱无和，坚执扶阳之法。复以附子四两，人参一两，浓煎汤服。服未终剂，汗收渴止厥回，诸症悉安，无何。越日汗渴厥逆交至，是为去而复返，必有所因。经云：欲伏其所主，必先其所因，可使气和，可使必已。兹者叠投汤剂，悉皆刚燥，于阳不违，于阴有乖，宜其退而复返也。乃进四逆汤，加童便，未甚效，继进白通加猪胆汁汤，吞黑锡丸数钱。药方下咽，忽然战栗，四肢渐温，阳气得所，顷刻间，诸症如失，所谓药不瞑眩，厥疾弗瘳是也。善后之法，一月未弃姜附，并须按日两剂。迨至卧不受被，有时手梗略冷，或掌心作热，是皆阴阳和而不合之势，乃将归脾、养心、十全大补，进退酌用，兼吞八味地黄丸。又遵阴平阳秘，精神乃治之旨，调理而后全要。", "8354": "周祥彩，肌体肥盛，惯服斑龙丸。客秋在汉，连餐炙爆，复患伤风感冒，微觉咳嗽气急，自进橘附汤，得小愈。但苦头眩难支，惟坐睡片刻少可，深以暴脱为虑。医者又以内伤为词，参耆日用，病势日增，渐至五心潮热，肌肉消瘦。一日眩晕时，忽饮龙眼汤一碗，觉少可，以后每发，悉皆倚之。病已逾年，医药日费，客囊殆尽，带棺买舟归里，坐以待毙。其戚友知余循理治病，请诊而求治焉。见其面额黧黑，形似烟熏，唇口齿舌，干燥异常，时欲得食，食已即便，所泄完谷不化。脉虽细涩，然寸关劲指甚锐，余以千虑一得之悟，直许可治，疏方与之。时门人在旁，问曰：周兄之病，势已趋危，吾师许其可治，必有奥旨，可得闻乎？曰：此症始因饮食之火内焚，后加风寒外束，是内热而复外寒也。夫病之在身，始先居肺，肺为华盖，耸然居上。经曰：形寒寒饮则伤肺。注云：形寒伤外，饮寒伤内。今热伤于内，寒伤于外，故病咳嗽气急，此际但取辛凉解表之剂，岂不金彻水清耶？奈何自服橘附之药，以致热邪愈固，肺失清肃，无从输泄。由是身中之气，有升无降，所谓气有余便是火。其头眩难支者，气升火亦升也。医者不揣病因大旨，端守眩晕为虚，日进参耆龙眼，愈加锢闭，无一外隙可通。火既无出，只得奔走空窍。夫大肠者，肺之合也。下利奔迫，辛庚移热可知。时欲得食，消中之累又萌。至于完谷而下，固属火性急速，不及变化，正嘉言所谓其土已为火焚之焦土，而非膏沐之沃土，安可望其生化耶？经云：暴病非阳，久病非阴。今病经年余，洞泄半载，其为阳火甚明。其火属阳，其阴必伤，急救其阴，夫复何疑？岂可再用参耆，复蹈前辙乎！且吾之许以可治者有二：两目尚明，瞳神光亮，上焦之阴未绝，一也；下利虽急，小水犹长，下焦之阴亦未绝，二也。况下利奔迫，胸中不实，身体和温，即五心潮热，尚未至于大热躁扰，可见所禀阴气丰厚，即肠胃空洞奔迫，而粥饮饭食，尚能继进不辍，吾乘此一线生机，仿壮水镇阳之法，使无上僭下竭之虞，效泻南补北之意，而无金热土伤之虑。爰引一派甘寒润濡之味，清肺泻火，救阴抑阳，如仲景立黄芩汤，治协热下利，虽清火迥殊，而存阴则一也。彼因胆火肆虐，移热于脾，故用苦甘之剂，直清胆火而存阴；此因肺火肆虐，奔迫大肠，故取甘寒之味，端清肺火而存阴。取用萎蕤为君，端清肺热，乃水出高源，象乎天也；地黄为臣，壮水保金，乃子母相生，象乎地也；佐以梨汁、蔗浆、蜂蜜、竹沥，除肠胃激烈之燥，济经络津液之枯，象乎人也。无论其邪火，正火，君火，相火，阴火，阳火，得此甘霖霡霖，如饥人求食，到口便消，吾故直许其可治也。下咽未久，便觉神魂返宅，安睡一晚，继进二剂，不饥不泄矣。至善后之法，仍从肺胃立方，即养百日，沉疴顿起。", "8355": "吴俊明，年二十，咳嗽多痰，微有寒热，缠绵数月，形体日羸，举动气促，似疟非疟，似损非损，温凉补散杂投，渐至潮热，时忽畏寒，嗽痰食少，卧难熟睡。医者病家，咸言痨瘵已成，委为不治。闻余精究脉理，姑就一诊，以决死期。因见形神衰夺，知为内损。脉得缓中一止，直以结代之脉而取法焉。此阳衰阴凝之象，营卫虚弱之征，卫阳虚则发热，营阴凝则畏寒。盖肺卫心营之机阻滞，气血不得周流，故见为结代时止之脉。谛思结代之脉，仲景原有复脉汤法，方中地黄、阿胶、麦冬，正滋肾之阴以保金，乃热之犹可也；人参、桂枝、枣仁、生姜、清酒，正益心之阳以复脉，乃寒亦通行也。用以治之，数月沉疴，一月而愈。按结代之脉，须知必缓中一止，方为可治；若急中一止，便为参五不调；乍疏乍数，安可治乎？故古人有譬之徐行而怠，偶羁一步之语，旨哉斯言，堪为结代之脉传神矣。世人惟知仲景为治伤寒之祖，抑知更为治虚劳之祖乎？", "8356": "傅妪，年逾七旬，素属阴亏，今春初起微寒微热，余以二陈加麦冬与之，一剂颇安。次日耳中忽流血水，耳傍筋痛，余曰：耳门属肾，老年下元先衰，非湿热停耳之症，乃肾气上奔之象。易曰：龙战于野，其血元黄。议早与《金匮》肾气汤，晚进当归、枸杞、萸肉、牡蛎、菊花、熟地，各二剂，筋痛血水齐愈。比晚寒去热来，是为阴阳不和，致令偏寒偏热，非疟症也。法当人参养荣汤，为阴阳两补之剂，嘱之曰：药固大剂，必多服乃可。岂知只投两剂，症未增减，更医误服升柴陈半之属，是夜大寒大热大汗，陡然人事昏沉，几欲脱矣。再延余诊，脉来鼓指，洪大无伦，声微息促，气高上迫，危在顷刻。细思此寒此热，固宜调阴阳，而值此气脱，又当收阳为主。以大剂六味回阳散，加耆术龙眼鹿茸，连进二剂，徐徐与服，次日人事清爽，寒热亦除而健。", "8357": "彭绍英年十八，向有咳嗽，曾经失血，客腊婚毕，新正病疟。延医数手，疟未减，而神大衰，咳嗽仍作，夜不得寝，每巳午时，寒去热来，寒少热多，热止无汗，间日一发。迨至人事昏困，肌肤削极，饮食减少，始就余诊。脉得浮大而空，两关甚急，余知其失血也。视其舌干发槁，面色枯焦，更知其阴虚也。因谓曰：此冬不藏精，肾水愈涸，至春地气上升，肝木发荣，全赖肾水灌其苞根，则枝叶畅茂。今水泉将竭，何供所乘？以致木郁不舒，发为寒热，渐至枯槁，岂细故哉！奈何医者，以柴芩斧斤之药，愈伐其生。见其人事昏困，凉散不效，更投补中益气，耆术助火，其阴愈烁。今议端以滋阴为主，又忌滞濡，而胃愈戕，清营为佐，更忌苦寒，而阳愈损。经曰：损其肝者缓其中，损其肾者益其精。缓肝益精四字尽之矣，随症处方，因人而施，以一派生津甘缓之药频服而健。", "8358": "陈东正，辛苦劳力之人，年近五十，一向时寒时热，咳嗽气急，而苏子、桑皮、枳桔之药，恣投屡矣。迨至两足浮肿，气急上冲，胶痰满口，卧不著席，医者见其小水涓沥，不知其肾阳不化之故，尤泥其大肠壅滞；未识其肺气不输之因，复误进滚痰丸。气愈急，痰愈鸣，及延余视，肩耸目直，脉辟辟然如弹石，势难逆挽。余悯其贫，求生无法，辞去不忍，姑疏肾气汤，以附子为君，互进黑锡丸五钱。私与其戚徐刘二友及乃郎曰：病本不治，只因尊翁垂危之际，尚有必求余剂死无憾之语，吾益不忍坐视其困。细按仅得一线生机，以小便不长，大解滞涩，盖上欲脱，而下未遽脱也。所订汤丸，竟乃郎复与前医相商，其医曰：前后俱秘，岂有可投补药之理！复给丸药一包，约重两许，嘱其急服。乃郎方进药时，适徐刘二友见而掷之，怒曰：竞闻谢氏生平谨慎，特因病势已极，故不肯担此重任。然视病反复，论症精详，足征持重有识。遂将余订汤丸亟进，次早复视，症未增减，脉亦如故，病之安危，犹未敢许。复将肾气汤加五味大剂以进，每剂吞黑锡丸五钱，令其昼夜三剂。是晚虽未能安枕，然辗转反侧，尚可著席，知其气已返矣。越日复诊，指下辟辟弹石之脉，方得柔软于冲和。再进三日，二便如常，卧可安枕。其后或投真武汤，或进景岳右归丸，亟培土金水三脏之本，经月之久，方得散步于外。而起一生于九死者，皆徐刘二友之功也，乃归功于余，因为记之。", "8359": "傅孔翁，于忧怒后，旬日鼻塞声重，咳嗽多痰。来寓索方，余知其元阳素亏，拟是肺胃虚寒，因与真水六君子煎一剂。咳嗽更盛，卧不安枕，气喘痰鸣，端人请诊。余思日间所服之药，其不疑陈皮之散，必议熟地之滞。再诊之，脉得尺部浮大而空，气促面赤，喉中痰响，元海无根，真阳上脱，急与黑锡丸。服后气略平，痰亦少止，随进大补元煎，加桂附一方。众曰：熟地滞痰，万不可用，余曰：下部之痰，非此不可。令服之，遂安卧，气亦归源。犹然鼻塞咳嗽，以原方加骨脂而痊。", "8360": "杨明质，三载劳损，咳嗽多痰，大便常滞，呼吸急促，卧不著席，买舟访治于余。诊得右脉数急，左脉迟软，系阴液虚也。仿古救阴液，须投复脉，因与炙甘草汤，令服百剂。逾年来寓谢曰：贱躯微命，自分必死，幸叨再造，感德不朽矣。", "8361": "炙甘草汤（一名复脉汤）方见前本门寒热如疟。", "8362": "胡晓鹤孝廉尊堂，素体虚弱，频年咳嗽，众称老痨不治。今春咳嗽大作，时发潮热，泄泻不食，诸医进参术之剂，则潮热愈增，用地黄、鹿胶之药，而泄泻胸紧尤甚。延医数手，无非脾肾两补，迨至弗效，便引劳损咳泻不治辞之。时值六月，始邀予诊，欲卜逝期，非求治也。诊之脉俱迟软，时多歇止，如徐行而怠，偶羁一步之象，知为结代之脉。独左关肝部弦大不歇，有土败木贼之势。因思诸虚不足者，当补之以味，又劳者温之，损者益之。但补脾肾之法，前辙可鉴，然舍补一著，又无他法可施。因悟各脏俱虚之脉，独肝脏自盛，忽记洁古云：假令五脏胜，则各刑己胜，法当补其不胜而泻其胜，重实其不胜，微泻其胜。此病肝木自盛，脾土不胜，法当补土制肝，直取黄耆建中汤与之。盖方中桂芍，微泻肝木之胜，甘糖味厚，重实脾土之不胜。久病营卫行涩，正宜姜枣通调，而姜以制木，枣能扶土也。用黄耆补肺者，盖恐脾胃一虚，肺气先绝。连进数剂，果获起死回生。但掌心微热不除，且口苦不寐，咳泻虽止，肝木犹强，原方加入丹皮重泻肝木之胜，再进而安。", "8363": "钱赞府，客秋患脱症，下元属虚，叠进耆术地归桂附颇效。而左胁气煽，夜难成睡，至今未除，服尽归脾养心之剂不应。面色㿠白，舌尖深红，肢体怠倦，脉来虚软，此乃心脾肝肾俱病。前服归脾养心之剂，未能疗及肝肾，而不寐由于气扇，气扇由于阳明脉络空虚，肝风得以内鼓，是填纳封固之法，万不可少。今议端以甘温填纳封固之品，服至十剂，饮食倍常，夜寐得安，乃二十剂，左胁之气亦不鼓矣。可见医者得心应手之妙，务在分清病源而已。", "8364": "尝观万物生成之道，惟阴与阳而已。盖非阳无以生，非阴何以成？有阴阳，即为血气。阳主气，故气全则神旺，阴主血，故血盛则形强，人生所赖，惟斯而已。尊阃玉体违和，前承不鄙，冒雨赴召，脉证相参，由来者渐，先天禀赋，已为薄弱之体，客腊分娩，调理不无失宜。心旌摇摇，内烁真阴，阴血既伤，则阳气偏盛，而变为火矣，是谓虚火劳瘵之萌也。前经治数手，不过见症投剂，未探真情。见其潮热，概行清火，目睹形羸，即为补血。孰知阴精日报，食饮无味，转劳转虚，转虚转劳，脉从内变，色不外华。而鼻血辄溢，食少力稀，正大易所谓龙战于野，其血元黄，乃亢龙有悔之象，非一二法所能疗。仆虽不敏，既叨不鄙，用敢直陈颠末，稍能深信，何辞病势之重，药进数剂，当有应验之功。足下勿以愚一管之见，视为泛常，幸甚。", "8365": "胡石泉先生，见余治周祥彩之病，心窃敬重，无病索诊，得两尺蹇滞，如刀刮竹之状，挺挺而现于指，似艰嗣之脉，知为气血衰残之候。因诘之曰：足下欲求房中之治乎？石翁曰：然。余曰：夫五脏之色，有诸内必形诸外，占其表，以知其里。今观先生明堂眼下，青色发露于外，且满面黧色，独天庭火光炎炎，是为阴阳亢战之象。夫肾属水，水涸则面黧，又水涸则火必亢，火亢则离宫自燃，君相争权，房中举而不耐，临战即泄可知，实阳强不能藏密之故耳。且肾司精血之脏，君本形盛之躯，宜见两尺泥滑，今乃滞涩异常，势如刮竹勒指，枯槁已极，所以关睢虽咏，而麟趾难赓，以精枯血少也。石翁怫然曰：吾闻丈夫以阳强为美，信如君言，则阳不宜强乎？余曰：阳以亢悍为畏，以潜藏为贵，值此衰残之候，当以寡欲为最。夫寡欲之善，一举两备。一则寡欲保身，一则寡欲多男。《内经》明言阴阳之道，阳密乃固，谓阳气秘密，而阴气自固也。若阳强不密，阴气乃绝，正阳根于阴，无阴则孤阳不生矣。至用药之法，必遵阴平阳秘，精神乃治之旨，合阴阳而两和之，而后雨泽降也。言时适一贵戚至，石翁借口辞曰：先生言皆金石，今有俗冗，愿俟异日。余甚惜其不纳也。徘徊其间，索笔记案，以冀其悟，其婢辈私指背笑者有之，岂知余爱友之苦衷哉！后石翁卒惑于方士之伪，力求房中术，方士日进之药，假名固本养元膏，又谓久战不泄丸，更炫名扶阳不老丹，种种妖诞，实堪发指。究竟内有硫黄、鸦片、麝香、蟾酥毒烈药物，用之提拔阳气，以供一时之药，数月不辍，渐至彻夜不寐，两肩高耸，玉茎不痿，交接出血，此乃矫阳独升，真阴欲尽之候。医者尚不知急行壮水镇阳之法，以少折其炎赫之威，乃日用人参、麦冬，徒竭重资，旷日缓治，颠沛半载，真至大肉尽削，肌肤甲错，皮焦筋屈，百苦交煎。又以芩连知柏，苦寒杂投，以致胃气日戕。后复求诊于余，余因未病先鉴，坚辞不往。越旬日，而先生讣至矣。", "8366": "陈鸿儒，年二十，时值春月，满面青白，步履不前，咳嗽多痰，声短语促，知其内伤甚重。余念世谊，谓乃尊曰：郎君青年，当此春生，反见尪羸之象，大有可虑。乃尊唯唯。匝月其病益剧，不能出户，始邀余治。诊得脉来弦数，时忽一止，自云别无所苦，只是少腹之气不上则已，上则心中战栗，周身寒冷，片刻内外皆热，冲至咽喉，必咳嗽不安。数月以来，请医专治，服疏表药，则汗多热重；服补脾药，则胸紧咳促；服滋阴药，则食少多痰；服降气药，则气愈升逼。余知其误，恐鄙见难以取信，因索纸书云：谨按脉来弦数停止，诀称乍疏乍数，三五不调谓之死脉，但数而不急，此处尚可转旋。据云：气上寒热咳嗽等证，乃厥阴伤寒病也。缘阴精素弱，肾气衰微，不能领邪外达，仅依脏气推迁。《灵枢经》云：厥阴之脉，自少腹上贯膈，循喉咙，病则气上冲心，惟其冲触不已，故心主不安其位，见为悸动。夫心主血脉，因营卫不调，遂悖乱失常，寒热顿起，且脉来结代矣。若逆冲咽喉，乃肺肾脉络之所，肝气乘水侮金，故为咳嗽多痰，实肝威猖獗，心主失权之象也。《内经》又谓主明则下安，主不明则十二官危，可不畏哉？今欲治此，必滋肾之阴以补金，益心之阳以复脉，非刚不足以去暴，非柔何以制刚？能识此意，方可言治。拟以炙甘草汤，滋阴和阳，养肝益心，庶肝火息而不升，则心主安而血脉复其常矣。其寒热咳嗽，不治而治也。方中地黄、阿胶、麦冬、麻仁，一派柔药，济肝之刚，乃乙癸同乡，热之犹可之义也。人参、桂枝、生姜、清酒，一派刚药，去肝之暴，乃木火相生，寒亦通行之义也。谨将病机传变，并用药大旨，一一陈之，愿高明垂鉴焉。乃尊世全，见余议论精详，亟将药进。甫投三剂，诸苦减半，寒热悉瘥，药已显有明效矣。讵知前医适至，大訾其药，阅余案，反议迂儒之言，何足为信？又议痨症尚不能识，岂有厥阴伤寒之书？旦议桂枝姜枣之药，大非痨症所宜，于是停药数日，寒热复起，诸苦复增。值余归里，复延他医，俱议桂枝姜酒，痨症最忌，每日令服人乳数瓯。其家戚友，咸称稳当，按日不辍，岂知人乳滑肠腻膈，卒至食少便溏，尚不知悟，犹以养阴清肺之药，卧床滑泄，竟致不起。嗟嗟，投珠按剑，诧为不祥，道穷于遇，可慨也已。王玉溪先生，莅任之初，适报海寇滋扰，缉究为艰，复值饥馑凶岁，亟筹赈救，数载以来，辛苦百倍。突增太翁之变，惊忧备集，因而成病。语言慌惚，步履欹斜，颇似颠狂。春杪至家，其病益甚，走书托治于余。因见人事瞀乱，两目左右顾盼，有时发怒乱走胡言，然禁之即止，是不明中尚有明机也。且时以手按摩心胸，可知膻中之地，必有郁结怔忡之苦。诊脉浮大而软，夫浮软为虚，大则病进，仆合脉审症，知先生病从七情忧劳中来也。订归脾汤，加龙齿、五味。其戚友知医者多，悉皆诧异，且谓此颠狂之病，城中诸医，悉称痰火闭窍，已服竹沥铁落，火且不衰，若投人参耆术，则不可救。予复详为辨曰：狂之为病，阳郁太过，挟胆胃两阳之火上炎，故越人称为重阳。发之甚，则水火不避，笑骂声强，登高逾墙，迅速非常。其脉来或弦劲有力，或鼓激冲指，故有唇焦齿燥，胃实不便诸症，是以有铁落石膏之治，乃制胆清胃，重而抑之使下也。此则不然，其有时发狂，不过有狂之意，中无所恃，故禁之则止。若谓痰火闭窍，则窍便塞矣，岂能禁之即止乎？又果重阳之病，岂无鼓指之阳脉乎？盖先生之累，始于忧思不遂，抑郁不舒，渐至心精日耗，神明丧失矣。君主之宫自燃，谋虑之舍乃枯，如木将朽，何堪斧斤？《内经》有言：尝贵后贱，虽不中邪，病从内生，名曰脱营；尝富后贫，名曰失精。曰失曰脱，收摄之法，其可缓乎？坐谈一午，众皆唯唯，孰意执迷不返，余药未投。厥后或服当归龙荟丸，或进礞石滚痰丸，其病日笃，大便溏泄。至六月，醴香少君，抵家省视，复邀余诊。脉来如火发燃，残阳尽逼指下，乃知心精已夺，告以事不可为。因问逝日，余以霜降为断，至期果卒。", "8367": "答门人问死期脉解", "8368": "门人问曰：王溪先生精营脱失之病，吾师朗若明镜，某等业已解悟矣。至死期之验，犹有未明，请更示之。答曰：《素问》篇云：脉至如火薪然，是心精之予夺也。草干而死。又曰：君火之下，阴气承之。今脉来如火薪然，然者，燃也，是洪大已极之脉也。久病见此，乃真脏之脉尽发于外，岂非心精已夺乎！夫心为阳，夏令赤帝司权，天时之阳犹在，是内绝而外未遽绝，非死期也。草干之时，秋令金气已深，阳气已消，万类咸萎，残阳之脉已极，极则必尽，再合天时之阳气并消，安得生乎？门人曰：唯唯，然某等尚有一疑请并示之。经又谓：脉至如弦缕，是胞精之不足也。病善言，下霜而死，不言可治。夫既言胞精不足，又安能善言？既能善言，又安得主死耶？又不言，为机关已阻，不曰主死，而曰可治者，何也？答曰：读《内经》之法，当字字推想。且上古文字古奥，尤宜贯通，庶得其真。弦缕之脉，其体虽细，最当玩其弦字。缕者，乃丝缕之谓，如弦缕，便伏有绞紧急疾下坠之象，此心阳已有亢熯之机，故言胞精不足也。胞精不足，残阳有丧亡之渐，神明失守之征，夫言自心发，其言必妄，善字当作妄字解，故云病善言。下霜之时，乃冬令水帝司权，正水来克火之候，残阳岂不消灭乎？故云下霜而死。若不妄言，则虽见胞精不足，却无神明丧失之症，城廓虽病，而君主尚安，亟以养营补心之类，尚可频施救援之法，故云不言可治也。某等跃然领悟，余因喜其明而复语之曰：前条盖言予夺，故必无可生之望，后条但言不足，故或有可治之症。此千古奥义，为尔辈笔之，以志一堂授受之心法云。", "8369": "黄守基，年二十岁，客汉阳，当秋寒热咳嗽，足跗浮肿。延疡科医治，误用敷药，足大指溃烂沥沥，又误用燥血药，煎熬津液，勉强收功。渐至足不能移，肌肤益削，已成瘫痪，历医不瘳，皆以不痛为不治。次年六月，买舟归里，求治于余。两人抬出诊视，余视其形羸发脱，脉象细数，腿股大肉已尽，脚垂纵缓废弛。因思经云：大筋软短，小筋弛长为痿。又曰：阳明虚则宗筋失润，不能束骨而利机关，法当端取阳明。且起自秋间，寒热咳嗽，肺失清肃，误进燥药，津液枯焦，此燥气焚金，当以肺热叶焦则生痿躄论治。盖痿者枯萎之象，非滋血液，何以得生？惟胃为生血之源，又为金之母，故曰治痿独取阳明也。况寒暑交迁，又值燥金用事，宜清金润燥，佐以甘淡益胃之药。于是以二地、二冬、石斛、薏苡、梨汁、蔗汁之属，日进大剂，按治十日，饮食稍加，改进虎潜丸，加黄耆，白术、薏苡、桑枝、茅根，补助阳明。自秋至腊，按日不歇，仅得肌肉稍充，筋骨稍束，尚未能开步，次年继进前药百日，至夏乃愈，计治一载，始获全功。", "8370": "傅妪四肢疼痛，不能运动，医进驱风燥湿、清火补血之剂，烦热大作，汗出淋漓，耳聋口燥，胸紧气促，四体不知痛痒。前医仍认为筋骨之病，投附子、草乌、秦艽、独活、牛膝、木瓜等药，愈治愈笃。延予商治，乃翁问曰：服药两月，愈见沉重，果是何症？余曰：此症原由形体肥盛，素多痰火，痰火盛于内，而召风以入，风入空窍，痰火随之，共入经络，初犹不觉，迨至机关不利，而痰火与风，聚结一家矣。书曰：肺主周身之气，虽痰火风杂并为病，无不关乎肺脏，正《内经》所谓肺热叶焦，则生痿躄是也。夫风药多燥，岂非助热而加其痿躄乎？《内经》云：风淫于内，治以甘寒。夫甘寒清火，人所共知，而熄风谁能深信？不知风走空窍，原由火召，非甘寒厚味，监督其间，不能填塞其隙。开方服二剂，潮热减半，汗止，大便艰，却无痞满，尚属枯焦，未敢议下。更方又服二剂，潮热蠲除，人事始清，但时言痛楚，非病进也，盖经脉流通之佳兆耳。复立第三方，服至五剂，手足运动，再服五剂，形骸如常。人皆渭奇，实非奇也。后七月余访友至高姓，治一妇，悉同此症，但初起多服耆术龙眼等药，筋加短缩，与以前第三方，每剂加倍，半月而愈。可知医贵洞悉病情，运巧思以制方，毋按图以索骥，斯得之耳。", "8371": "江妪下元素虚，今秋四肢十指肿痛，手足不能运动，有时右边肿甚，即右边痛加，似恶寒，或微热，舌苔灰白，二便略通，面色枯黑，口不作渴。有以血虚为治者，有以风湿为治者，有以痰饮为治者，竟无一效。卧床贴席，转侧维艰。其兄光裕，来寓请诊，脉得弦紧而数，时劲于指，认定为表里风热之症。踌躇良久，乃得其方。病者蹙额问曰：贱躯可活否？曰：三日之内即安。与防风通圣散，每日连进二剂，一剂而大便通，肿消肢软，二剂连泄黑粪两次，遍体得汗，痛止身轻。次早下榻向家人云：昨服药后，懵懂一日，至晚汗出始清，今晨周身轻快，但许久未经盥面。方取水间，乍闻余至，即出房诊脉。惟步履尚艰，犹须扶持，舌苔变黄，颇思饮茶。仍令原方再进一剂，复泄二次，下午速求止泄之药，余于原方中除硝黄，加葛根，服之泄止渴住，安睡进食，其病如失。病者急求补养之药，令买白皮梨，每日啜四五枚，十日外，更取熟早米煮稀粥，调养两旬，诸症悉痊。后其兄光裕来寓问曰：舍妹之病，几致废弛，先生一视，预限三日成功，果符所言，必有奥秘，可得闻乎？余曰：令妹之症，必先有饮食之热，后受外入之风，因其体虚不先伤卫，所以不病身热拘急，而直入于营，发为筋挛肿痛，与身中向有之热凝聚经络。夫风无定所，走注疼痛，或左或右，流注关节，风入既久，郁而成热，未经解散，久之必入于胃。夫阳明胃者，主束骨而利机关，阳明既病，机关不利，手足岂能运动？恶寒发热者，表邪之征也。舌苔灰白者，伏热之验也。合推此症，是上中下三焦表里俱实，有非轻剂所能疗者。又风邪散漫，非仅苦寒可以直劫。兼之下元素虚，即用重剂，又恐其放逸，更当以固护驾驭其间。由是观之，发表攻里之外，尤当寓一补字于中。然余自幼从不肯用错杂之方，追思古人表里门中成方，而得防风通圣散，此盖刘氏河间所制，虽非为此症而设，然与用旨默合，是以借之取效。方中麻黄荆防等药，能逐在表之风热，从皮毛而出；石膏硝黄等药，能驱在里之风热，从二便而出；风热深入于营，有归芎引表之药而入于营；风热淫聚于中，有术芍引里之药而入于中；而芎归术芍，又赖以扶持正气，使上中下表里之邪，悉从上中下表里而出。虽经络空隙之所，尽皆驱逐，何致久羁迁延！兼之汗不伤表，下不伤里，非比世俗补泻杂投之治，余是以知效，可计日而获耳。至病人药后而大便得通者，人皆知其攻里之验。其自云：药后懵懂一日，汗后始清者，人尚不得其解。夫懵懂者，冒闷之谓，乃身中作汗使然。譬之天欲雨，必地气蒸上为云，云升于天，雨施于地，而天地清矣。所以冒闷发汗者，发表之验也。至泄多而方仍不变，全不虑其虚者，此时补剂难投，只于原方除硝黄，以防身中在表之气，因咸寒而坠下，而加葛根升提，使身中清气上升，自然泄止渴住矣。以后不再制方者，以病虽至重，而表里未伤，只身中风热既久，津液必然受灼，故但以梨汁粥饮灌溉之，饮食消息之。此余自始至终，毫不紊乱如此。夫秘理深奥，化裁生心，本难言喻，今因吾兄愿闻奥秘一言，特一一剖之。光裕曰：医理真玄，治法果奥，请为立案。因详记之。后双某之子，亦患是疾，未费深思，按法而愈。此与前治傅妪一案大同，但病变稍异，故治法略殊，学者当合观之。", "8372": "吴新祺冲年困于酒色，阳道强而不痿，股胫痿而不坚，呻吟床褥，百治不效。籍居崇邑，就治于余。余谓此症，始则阳胜阴伤，金被火炼，今则矫阳独升，真阴欲尽。所进苦寒固谬，而温补尤非所宜。记古降心火益肾水法，惟三才封髓丹，于此最合，按方大剂令服。喜胃气尚强，每日纳药二碗，服至六十剂，两症始痊。因忆向治龚生，初起便血，渐至两足痿弱，不能稍移，服归耆参术，其血愈下，其足愈软，买舟由抚来湾，就治于余。两脉细劲，面黑耳聋，余曰：肝血大伤，肾水浆竭也。然从来补阴之药，难期速效，疏与虎潜作汤，令服百剂，许以病根可拔。殊伊服至五十剂，脚可趋步，便血已除，吝费停药。逾年肠红复来，乃将前方再服，稍愈又停，以致便血不息，竟至不起。惜哉，世之剖腹藏珠者，可以为鉴。", "8373": "陈鸣皋，体丰多劳，喜食辛酸爽口之物，医者不知味过于酸，肝气以津，脾气乃绝，以致形肉消夺，辄用参术培土，不思土不能生，徒壅肝热，故复阳痿不起。颠沛三载，百治不效。盖未悉《内经》有筋膜干则筋急而挛，发为筋痿之例。余诊脉，左数右涩，知为肝气太过，脾阴不及，直以加味逍遥散，令服百剂，阳事顿起。更制六味地黄丸十余斤，居然形体复旧。此种治妙，惟智者可悟，《内经》一书，岂寻常思议所可到哉。", "8374": "陈春初，乃郎将婚，服补养丸剂半月，反致两足无力，阳痿不举。医谓当用大补，加附子、鹿茸，服之无算，渐至两足难移，玉茎尽缩。诊得肾脉独大，右尺尤甚，与滋肾丸一斤，服至一半，阳事已举，药毕，步履如旧，此孤阳不生之义也。", "8375": "黄钦三，病发时，浑身洒淅麻痹，腹痛，囊胀，茎缩。一时灯火姜附乱投，得少安，其后屡发，更医数手，无非前法。盖医者总以阴症为治，而病者刻以缩阳为虑，紧持玉茎，诚恐缩完。诊得弦紧异常，目红唇燥，余知其误，以宽言慰之，令急服左金丸，合温胆汤，数剂顿安。后以一派养血济阴、镇心潜阳之药，调理而健。同道不解其故，余曰：吾人身中，惟色胆最大。肾家之强，均由胆家之旺，请鉴诸好色之流，有逾垣乘隙、高深不畏之胆，夤夜私奔、神鬼无惧之胆，而后能遂其欲。是凡潜踪入房，其胆家之火必先燃，而肾家之火乃盛。当其欲火初起，但制之以恐惧，其阳必顷刻而痿，岂非肾强由胆旺之验乎？故肝为阴脏，缘胆藏于中，相火内寄，其体虽柔，其用实刚。其性也，主动主升，其气也，彻上彻下，脏腑表里，为寒为热，身中内外，或现或隐，高自顶巅，深至血海，变幻莫测，病害最多。至其脉络阴器，尤喜疏泄。兹诊钦兄脉盛筋强，目红唇燥，乃肝胆俱旺，血燥不荣，且常有遗泄一病，明明肝火激动精关，诸医不察其遗泄之故，只想汇聚涩精补阳之药，岂非炽火涸血之弊乎？夫火愈炽，血必愈涸，血愈涸，火必愈炽，由是筋脉失滋，遂成结束，乃筋疝之象，非真缩也。加以惊恐，不缩亦缩矣。吾以宽言慰之，释其惊恐之缩，继以苦药清之。解其筋脉之结。补之以气，补肝即是补胆，养之以润，养肾便可养肝。吾临斯症，实非偶然，法参乙癸同乡之义。推观好色之原，丝毫不爽，所以获效。较诸阴症缩阳面青脉静，肢冷息微者，不大相径庭乎？", "8376": "汪宝泉，时届长夏，夜卧当风，值梦遗后，得风痹病，始苦左足肿痛，难以移立。即邀予视，亟祈补剂，诊之，脉大舌黄，身有微热，虽初起，其势已重，颇类脚气病，但无恶寒，发热，胸满，呕吐之症，且脉大舌黄，必是风痹。因告之曰：此风湿内蕴，久而化热，萃于经脉之中。法当轻扬辛凉之药，宣通经隧，兼以甘寒味淡之属，息风渗湿。但湿凝为肿，风胜为痛，而风为阳，阳主动，势必流走经隧，恐身中四肢关节处，难免流注之苦。以风性游移，非比寒湿之邪，仅著一处，留而不散，是以《内经》有周痹行痹之称，即此症也。必邪去然后正安，不可谓因遗精而病，辄与温补助邪。疏与杏仁、桂枝、防己、防风、蚕砂、羚角、桑叶、通草之属。日夜连进二剂，左足稍愈，身热已除，果然右脚肿痛，更加薏苡、萆薢以利湿。按服三日，两足肿痛虽轻，忽又肘腕掌节肩髃各处，逐日游移，肿痛不堪，又以前方参加石斛、黄柏、天冬、玄参、茅根、桑枝、梨汁、竹沥，便闭稍加明粉。盖遵《内经》风淫于内，治以甘寒。热淫于内，治以咸寒，半月之久，按日两剂，其功始半，续进地黄丸一斤，乃奏全绩。原自古风痹痿厥之症，治不得法，常多殒命，治或稍差，亦成痼疾。总由不知风痹痿厥该何证，寒热虚实从何据，捡方试病，误人良多。夫四末之疾，必识动而劲者为风，不仁或痛者为痹，软弱不举者为痿，逆而寒热者为厥。况风者必多风热相兼，痹者必风寒湿相合，痿者必火乘金，厥者或寒或热，皆从下起而逆上也。然又病机变化，寒热虚实，皆从人之脏腑转移。表寒里寒，表热里寒，阴虚阳虚，自有分别。或曰：风淫四末之症，案中分析甚明，但所言寒热虚实，皆从人之脏腑转移者何？答曰：凡邪之所凑，必乘人身之隙而入，内外相召也。如其人身中素有蕴热，外风一袭，则风为热风；若其人身中素有虚寒，外风一袭，则风为寒风。古之三化汤、防风通圣散，皆为治实火之风而设；八珍十全、地黄饮子之类，皆为治虚火之风而设。经曰：风者善行而数变。正为变虚变实，必从人之脏腑虚实转变也。其间祛邪养正，必察其脏气之偏胜，究其邪气之深浅，庶几了然在望，投剂无差耳。", "8377": "吴元东之妇，形瘦多火，患风热病，头疼身痛，发热畏寒。医者不知风为阳邪，寒为阴邪，误用辛温发散，汗出昏厥，不醒人事。迫切求治，视之面红脉大，知为火气焚灼，以血液衰弱之体，又值汗出过多之变，决非清降可投。盖人身阴阳相抱，乃能动静有常，今阳失阴守，是以阳气独上而不下，而为厥逆之症。又与亡阳之症有别，法当生阴以维阳。古有此例，处用白薇汤，以白薇达冲任而利阴，参归生血液而固气，合甘草以缓火势。许其必效，药下果然。", "8378": "傅孚远女孙，形体清瘦，前夏月，遍身发出红块，大小不一。医以丹证治之，用草药搽敷而愈。至秋初，忽然仆地，神昏不醒，喉内痰鸣，片刻复清，一日数发。请医数手，通用化痰顺气等剂，毫无寸效，日夜数十剂。举家慌乱，急请余诊。脉得寸口洪大，两尺弦紧，自云腹中如焚，欲饮冷水，言未毕，卒然昏倒，口开手撒，身凉默默，面白唇红，任捏不知，头仰垂下。因思此症杂出，拟是肾阴枯槁，水火相错，发为痱中。陡进地黄饮子，服之未效。推原其故，中寒条中，决无此例，夏月君火专权之令，发出遍身红块，未经清解，误用草药搽敷，逼毒入内，留于心胞。况且素禀木火之质，肾水不足可知。心火过亢，肝木有余，木盛生风，风火相煽，两淫于中。先哲有云：心火内蕴，膻中如焚，凉膈清心，功见一斑。又《内经》有云：风淫于内，治以甘寒。理宜先进清心散，后服二丹丸，庶为合法。于是疏方，连翘、薄荷，清上焦之热，大黄、芒硝，救北方之水，芩连、竹叶，清心肺而治风，甘草、山栀，通三焦而泻火，调以蜂蜜，合为一剂。服之安睡一顿，醒起更衣，其病如失，仍令二丹丸，调理而健。", "8379": "王作仪先生之内人，形长肌瘦，平时喜进温补，时值暮春，乳房胁肋，渐次作胀。初尚不以为意，一日忽牙关紧闭，不知人事，手撒遗溺，张目精摇。诸医咸称手撒脾绝，遗溺肾绝，叠进补剂，欲图固脱，淹治旬日，渐至筋敛抽掣，始延余诊。各部应指急数有力，唇齿干燥，大便不通，乃知虽属烦中，实为肝火厥逆之候也。若果脱结之症，五脏凶例全见，当顷刻告变，安得尚延旬日？且六脉俱有力耶，缘紊禀木形，兼挟内火，且令当木旺，肝气燥急，故乳胁作胀。夫肝主筋，筋脉不萦，故四体不用。木火生风，故目精动摇。筋脉不和，颊车不开，故牙关紧闭。肝威沸腾，津液妄泄，故汗大如雨。肝邪热炽，阴挺失职，故小溲自遗。津液被劫，故筋敛抽掣。统计之，悉皆肝火为患，处龙胆泻肝汤，合当归龙荟丸。连进二剂，病势大减，后进犀角地黄汤，兼龙荟丸，进食能言，随用八珍汤，除川芎，重加白芍、丹皮，调理而健。", "8380": "李妇，胸腹大痛，忽然昏倒，手足逆冷，口不能言，两手握固，两尺脉细。先一医，断其脉绝必死，已煎就附子理中之药，希图援救。适闻余至请视，诊得两尺果无，而症与脉反，若果真脱，岂有不面青大汗之理？书云：上部有脉，下部无脉，其人当吐不吐者死。似此必伤食所致，以故胸中痞塞，阴阳不通，上下阻绝。理宜先开上窗，俾其中舒，因问曾伤食否？伊姑应曰：曾到戚家贺寿，油腻肉面，颇为大啖。因放胆用法，而不用药，令炒食盐一两，热水灌服，兼用通关散吹鼻，大嚏大吐，顷刻而醒，吐出完肉数块，面蛋带痰数碗，其病如失。", "8381": "陈茂初，年壮体强，早膳后忽然胸膈大痛，叫喊数声，卧地不省人事，四肢逆冷，身体仍温。余诊尺脉虽无，而寸关甚坚，且面色未变，喉无痰声。如此卒暴之恙，决非中风、中寒、中气之症。意揣食前无恙，食后即胸膈作痛，盖胸中阳位，食物犹在贲门，阻遏阳气，不得下行，合乎尺脉不至，古人原有食厥之条，当作中食之症。至于治法，有上部有脉，下部无脉，其人当吐之训，于是烧盐一两，煎水一碗灌之，涌出痰食二升而愈。", "8382": "记昔先君授澍曰：病欲十全，入门只先求无过，肱当三折，斯时莫道学有功。临症无论大小缓急，总当于望闻问切四字加意，不中不远。旨哉言乎，何敢一日忘诸！昨视徐妇中气一症，素无他病，顷刻仆倒，目闭口噤，手撒脚僵。其夫曰：早吃胡椒汤一碗，身战作寒，午吃龙眼汤一碗，嗳气不舒，因而仆倒。余忽忽一视，以为龙眼壅滞，用神香散调灌，不效。诊脉上浮下伏，与经言上部有脉，下部无脉，其人当吐之例相符，又以盐汤引之不吐。再掐太冲穴，身略动，自以两手扪胸，知心地尚明，无非会厌机枢不利，转瞬依然，四肢僵冷，细聆呼吸，状如死人。再诊脉伏，乃静念曰：面色青白，必挟肝邪为患，脉来紧伏，可是经络皆痹？今日不过服汤两碗，仓廪之官，久已运化而下，故引之无吐，想非风，非痰，非食，非火，其闭不通者气而已矣。再问素性好怒否，家人曰：多气多怒，曾因丧子，悒郁至今。夫郁气素横于胸，加以椒性助肝，龙眼壅气，肝愈横，郁愈结，膻中之气无由转输，安得不猝然仆倒！然则斯症虽危，自有斡旋之法，用乌附散（香附、乌药），沸汤调灌。方下咽，喉间汩汩有声，即呕稀涎一口而苏。惟苦胸闷不舒，噫嗳自揉，继进越鞠丸一两，气畅郁舒，安睡复旧。越半月，胸紧头昏，复倒无知，目瞪口张，势似已危，脉象又伏，知非死候。余与伊夫常聚首，因谓曰：前番目闭口噤脉伏，今脉同症异，当从原意变通。言未已，开声知人，并云头晕目眩，重如石坠，面如火燎，转盼间，狂言见鬼，歌笑呻哭。众皆诧异。窃思中气之后，因思复结，仆倒无知，固其宜也。然面赤神昏，妄见妄言，必因郁久化火，挟肝邪为患，应用清肝泻火之剂。又胸紧气急，头重如坠，必缘郁气固结，经道久闭，故脉沉伏。与《内经》血并于上，气并于下，心烦惋善怒之旨合符。遂疏方以逍遥散，加丹参、牛膝、玄胡、降香，兼进当归龙荟丸。服下未久，神识顿清，诸症渐减，按方再服，诸症悉除。越日复诊，脉转沉数，沉无固结之患，数有流动之机矣。再询经期，果闭四月有余。本拟速行决津之法，但昨议已效，仍仿原意再投。后更方未费思索，直以解结通经而愈。", "8383": "游长万，连值房劳，忽患小腹胀痛，喜以手按，二便阻滞，腰膝酸楚，屈而不伸，食饮难入，食即吐出，却无烦热，唇舌如常。医者认为阴症腹痛，进参术附桂之剂，病仍如故，亦不见燥，但腹中愈满。更医见二便不通，又以实热作痛，大进硝黄枳朴车前滑石之属，愈增胀满，腹中窒塞。更服巴霜丸，欲求一利，竟不可得，日吐涎水如青菜汁者数升，众皆骇然。竟至粒米不入，二便不通者五日，小腹极痛，胀闭难忍，百方不效，愈治愈危，诸医束手，坐以待毙，求治于余。余思人非金石，岂有竭尽攻剂，竟不能通者？今上不得入，下不得出，内关外格之证悉具，本当死在旦夕，何五日尚未死耶？仲景云：小便不利，腹胀喘急者死。今幸未喘急，所以尚可生也。脉得肝部独强而横，初甚踌躇，久之脉症相参，始悟与妇人热入血室一症，其义相同。夫妇人先因外感传经热邪，经水适来，热邪既可乘虚而入血室，此亦必先因内伤饮食湿热，积聚于中，适值房劳，精道陡虚，所有积聚湿热，亦可乘虚而入精道。其内外所伤虽解，其乘虚而入一也。惟其阻塞经隧，胀闭二阴，故前后二便皆阻。夫少腹者肝经所属，阴器者肝脉所络，今湿热乘虚阻塞，如横一闩于中，湿热之气愈阻，肝木之气愈横，所以胀痛难忍。下既不通，无由疏泄，拂逆充溢，势必上冲，直侮所克，上乘于胃，土受木克，而为呕吐。观其吐出如青菜汁者，显然肝威之现形矣。此症若不循经引治，何以解肝之结，搜湿热之陷，通其经络，而消其阻塞乎？法用牵牛达肾道，走精隧，搜热逐湿为君，以吴萸、小茴、川楝、橘核、桃仁解肝散结为佐，加以苦酒之酸以入肝，明粉之咸以入肾，二味化水拌炒诸药，引之以入肝肾，引上加引，使之直达。初剂小水长，仅得数屁，腹中气响，而痛大减，二剂前后悉通，诸苦如失。可见凡病必当曲尽其情，悉心审度，自有一定之理，既得其理，自可应手取效。若但见病治病，不为推求，而谓知医，可乎？原此症从前未经阐发，医者端守下法，屡攻不通，愕愕惊奇，殊堪浩叹。余临斯症，从伤寒门中妇人经水适来，热入血室，悟出男子适值房劳，湿热入精道，补前人之缺陷，广后学之见闻，详述受病之由，并纪制方之妙，俾后之患斯疾者，得开一生路也。", "8384": "吴继文有腹痛病，时呕吐苦水，汤水难入，二便阻塞，而虽屡发得安，不过腹中宿积，由呕稍尽，究竟绸缪融结之情，并未去也。今春宿痰举发，倍盛于前，四肢厥逆，呕吐口渴，小水涓沥不通，大肠壅塞不行。延绵旬日，遍尝诸药，未能下咽，绝粒不进。脉尚弦数冲指，攒腹攻痛，每痛极时，索饮烧酒盏许，似若稍可。吴问曰：阴症乎？余曰：非也。若是阴症当早已入阴矣。又问曰：热症乎？余曰：非也。若是热症，岂有汤水不入，而反可咽饮烧酒乎？吴不悦曰：无病乎？余曰：兄之病，乃兄自招，良由舍命嗜酒，将息失宜，以致酒毒内结，已成酒癖。治疗之法，未易言也。亟宜从此痛戒，庶几希之命，得延岁月。言未毕痛复作，呕复升，急急促令疏方，数剂诸苦如失，但善后之法，犹未尽也。越日寓中诸生偶问吴之病，经先生手到病除，难明其妙。而酒癖之义，尤所不识，请受教焉。答曰：癖义颇微，难以言象，当喻而达之。酒关甚巨，夭枉死亡，吾不知其几许人矣。吾侪其操司命之权，各有尊生之任，可不亟讲乎？夫酒虽谷造，原藉曲水两性，湿热二气酿成，少饮未必无益，过饮暗中损命，多饮则乱血，恣饮则注肝。且酒后食必少，中必虚，饮入于胃，中虚未能施化，其浊质虽输注于小肠，而烈性必聚蓄乎肝经。故善饮者，面常青，于此可验。盖酒性助肝，肝性横逆，克于脾则腹痛，乘于胃则啘呕，横于血则肢痹，逆于气则便塞，是肝邪为患，此又历历可征也。又善饮之人，其有终于痿厥偏枯之疾者，禀阳藏而伤于热烈之曲性故也；有终于肿胀膈噎之疾者，禀阴藏而伤于寒冷之水性故也。吴之病，其始必因过量，肝胃受伤，气血多乱，由是乱气乱血，随酒性而溢于络。其气血酒性，交互凝结，势难分解，傍依肝胃之膜，藏于隐微之中，结成囊癖，如燕之巢，如蜂之窠。其积垒，非一日也。继是所饮淫质，随饮随渗，由胃肝而入囊癖，久之囊癖充塞，满则必溢，势必仰冲肝胃，犯肝而为痛厥，犯胃而为呕吐。向者病发呕吐，数日得以安者，不过囊癖之蓄积，由呕暂空，得以暂息。其后仍饮仍聚，癖势日增，关隘渐塞，故所呕渐艰，未易出也。他日此癖，为蛊为胀，滋蔓难图者，在所难辞。然则今日之治，尤当亟讲矣。大抵酒客忌甘，酸味助肝，最难相适。斯义惟喻嘉言透此一关，必取其气味俱雄之药，所谓能变胃而不受胃变者。今师其意而扩用之，有如寇匪蟠据，侵漫已极，使非有斩关夺门之将，其何以突围而劫寨乎？方中附子、吴萸、肉桂、草蔻之辛热者，用之以通经入络，散痞消症。然讨寇之兵，性情暴烈，每多峻厉，恐其放肆潜佚，不得不以法度制之，故以黄柏、桃仁、明粉苦寒咸下者，以制其猛烈，且借以泄热佐之也。但膈膜隐僻之区，道路常多曲折，非所易入，恐难决胜，故复使丑牛、草乌、牙皂，气味俱雄者，有锋锐巧捷之能，且有逐水搜湿之功，饮之下咽，犹号令一举，各皆走而不守，直达癖所，赞襄成事，取功易易。然征伐之地，难免受伤，隐曲之处，尚未尽扫，故锐兵利导之举，可暂而不可常，则善后清净之法，尤不可无。", "8385": "胡懋光，四肢逆冷，面色青白，吞酸呕吐，食不得入，六脉沉伏，大便不通，小水短赤。细察诸症，皆由阳气不舒，理宜先将下部疏通，庶几清气上升，浊气下降。因与大承气汤，叠进三剂，毫不为动，脉症如故，举家惊怖，余亦骇之，谓岂有大黄芒硝重剂，竟不能通者？继知其人嗜酒，每患足疾，今足未病，湿热未曾下注，致停中焦，将成关格之象。视舌滑润，非燥症也，中焦必有停积冷痰，以致闭结胶黏，正所谓阳微阴浊僭倨，非仅承气咸寒可能开者。法当通阳泄浊，开结驱阴。于是以姜附通阳以驱阴，硝黄开结以泄浊，加草乌、皂角，名为霹雳通关之将，以直劫其巢。方成药煎，即忙与服，未及片时，下秽污数斗，小便清长，四肢温暖，食粥二碗，不用再剂，诸症悉痊。此可为冷积绳墨，因详记之。", "8386": "邓学文初起小水短赤，继则腹胀便秘，已服硝黄寒下之药，腹愈窒塞，更进车前渗利之药，尿愈涓沥，胀闭欲死。危迫之际，延余往治，至时呃逆呕吐，汤水难入，审知素多酒色，湿热壅于膀胱，冷积聚于胃腑，故前阻小便，后塞大肠，气无下降之权，只有升逼之势。细察人迎气口两脉紧急可骇，症属关格已极，势在难挽。举家苦劝求治，勉为推寻。因思胃腑冷积，当宗热以攻之，辛以通之，膀胱湿势，宜遵寒以清之，温以化之。于是攻与赤金豆，化与滋肾丸，连进未呕，昼夜三服，俾浊污升逼之气，方得下降于沟渎。不再剂，诸症悉痊。", "8387": "胡生新科，胸腹胀痛，大解不通，已服枳桔香朴之属，毫无一效。又与滚痰丸，仍然闭塞。饮食虽甘，而食不作胀，每日探吐痰水数口，似觉稍宽，有粪结于肛门，努挣不下，挖之略出。延余视时，大便未通者，已十日矣。然脉来浮缓迟弱，身无寒热，口不作渴，舌无苔积，知为阴结之类，非阳结可比。此必胃气虚弱，津液不布，大肠传送之令不行，而胃中所蓄水谷，结而为胀。虽探吐稍宽，究竟津液愈涸，传送愈艰，与理中汤、加半夏、厚朴、枳实。才一疏方，众皆不悦，盖病家与病者，急欲求通大便，满想大黄巴霜之药，余独吹无和，只得详为辨曰：行医治大便不通，仅用大黄巴霜之药，奚难之有？但攻法颇多，古人有通气之法，有逐血之法，有疏风润燥之法，有流行肺气之法。气虚多汗，则有补中益气之法，阴气凝结，则有开冰解冻之法。且有导法熨法，无往而非通也，岂仅大黄巴霜已哉！今病原胃气空虚，津液不足，即按症投剂，亦必三五日始通，决非一二剂可效，盖胃气虚而运行迟也。但依吾见，力可承任。胡生闻言姑信不疑，每日二剂，腹中毫不为动，殊料服至五日，药已十剂，仍然如故，急欲更医，余恐前功尽堕，又苦劝之。因思蓄饮不行，加入半硫丸四钱，仍与前药吞服，再加婉言，把持二日，共计十七日之便，仅得半升溏粪而已。自此饮食起居，未费调理而健。然病家与戚友俱议曰：行医仅通大便，如此为难，何贵于明耶？嗟嗟，医固难知，医则愈难也。", "8388": "都昌舟子，大小便秘，腰屈不伸，少腹胀痛，倩人扶持来寓求救，狼狈之状，势甚可骇。细视之，面色正赤，鼻准微黄，额汗如珠，舌苔中黄。诘之曰：小便秘乎？其倩人曰：二日一夜，并无半沥，大便亦闭。余知鼻黄者，多患淋秘，淋秘鼻黄者，势必危。仲景云：无尿额汗者死。因谓之曰：事急矣，恐难治也。病者闻言大哭，余为之恻然，姑为诊之。尺寸沉小，幸劲指有力，复慰之曰：此症虽危，吾可以法求之。意仿无阴则阳不化之旨，欲举东垣滋肾之法。病者忽云：服车前草及六一散大黄药一剂，愈加胀痛难忍。此又凉寒不服，意者，冷结关元乎？然脉象症候，固非无阳，且似有火，乃寒之而反重者何耶？因思《内经》有云：诸寒之而热者取之阴，所谓求其属也。遂订六味地黄合滋肾作汤，大剂以进，滋阴以化气，外用捣葱合盐炒热，布包熨脐，通中以软坚。自午至戌，内外按法不辍，俾得关通，二便顿解。此症生死反掌，读仲景书者方知。", "8389": "王辅粥，初起腹鼓脚浮，小水短少，大便甚艰，气逆上冲，医用五苓八正诸方，愈加腹鼓，小水涓沥不通，按脉洪大，神彩尚存，足征禀赋甚厚，方可耐此重症。诊毕谓曰：此乃湿热内蓄，恐成单胀，膀胱气壅不行，以致小水悉闭。今欲治此，须通小水为急，但通小水，非气化不出。因问欲汤水否，曰：极不口渴。乃知确由下焦湿热所致，与李东垣先生治王善夫一案大同，遂以黄柏、知母之苦寒以泻内蓄湿热，肉桂之辛热以化膀胱之气。才下咽，腹中甚痛，小水遂行，胀满亦消，后以八味地黄丸，数服而痊。", "8390": "黄万顺，善饮，素嗜炙食，每患淋秘，医投以五苓八正散，辄小效，渐至溺必艰涩，少腹觉满，时平时笃，已半载矣。一日房劳，前症倍盛，仍进五苓八正之属，服之溺愈不通，涓沥难出，腹胀腰屈，不可俯仰，匍匐就诊。脉得两尺坚搏，知为素蕴湿热聚于下焦，膀胱之气不化，仿东垣法，以知母三钱，黄柏三钱，肉桂一钱，服之半晌，安睡一顷，诸症如失。厥后一月数发，或一年数发，悉以此方必效。惟其酒色不节，调理不善，宜乎病源不清，湿热日聚，肾阳日耗，他日腹鼓喘急之患，殆所不免矣。越岁，果患是疾而死。", "8391": "小水不通，《内经》称为淋秘癃闭，最当详审。夫小水之源出于肺，故经曰水出高源也。其道由于三焦，故经曰：三焦者，决渎之官，水道出焉。其藏在于膀胱，膀胱者，州都之官，津液藏焉，气化乃出。可见小便之通与不通，全在气之化与不化，然而气化二字难言之矣。有因湿热郁闭而气不化者，用五苓、八正、禹功、舟车之剂，清热导湿而化之。有因上窍吸而下窍之气不化者，用搐鼻法、探吐法，是求北风开南牖之义，通其上窍而化之。有有阴无阳而阴不生者，用八味丸、肾气汤，引入肾命，熏蒸而化之。有因无阴而阳无以化者，用六味丸、滋肾丸，壮水制阳光而化之。有因中气下陷而气虚不化，补中益气，升举而化之。有因冷结关元而气凝不化，真武汤、苓姜术桂之类，开冰解冻，通阳泄浊而化之。有因脾虚而九窍不和者，理中汤、七味白术散之类，挟土制水而化之。古法森立，难以枚举，总之治病必求其本。奈何近时业医者日益众，而古法日益荒，每遇小水闭塞之症，不究其本，执用车前、木通、苓泽，沉寒淡渗之药，以为知医，幸遇湿热聚蓄内结，侥幸得功，以为能事。倘遭一切阳虚之症，而用淡渗沉寒之药，其阳愈虚而阴愈盛，阴愈盛而便愈不利，势必腹胀。仍执槟榔牵牛之药，而阳愈损，其气愈乱，转输无由，势必上奔，而为喘急无救矣。仲景云：小水不利，腹胀喘急者死，正因阳亡气散故也。吾先君深知此理，曾有治詹姓冷结关元一案，足为承先启后之资。今秋尽冬初时，有字春和者，体肥面白，一日二更时，忽然腹痛，敲门邀视，余念邻谊披衣而往，见其腰屈不伸，自以两手抚按，小腹膨胀，腹中甚痛，面唇俱白，十指稍冷，小水紧迫欲解不出，脉来沉迟。内外一探，阳气大虚，因问曰：日间曾服物否？应曰：清晨无病，上午小便时，身中忽然战栗，尚有一半未能解出，以后微觉小腹带坠，服六一散一文，愈觉腹胀，腹中大痛。余曰：起先小便时寒战，足见身之阳虚，再进滑石沉寒之物，凝而不化，是犹雪上加霜，自然关元冷结。时值二鼓，正阴气充盛之时，阳愈不耐，故病见剧，法宜助阳开结，暖其水而冰自解，冰解而水自流，水流而壅塞自开，塞开而胀痛自消矣。疏方以附子为君，姜桂为臣，茯苓、甘草为佐，沉香为使。意用姜附桂以消阴也，茯草以泄满也，沉香以鼓升下焦氤氲之气也。药味精专，丝毫不杂，因病势已极，重剂与之。恐其阴盛亡阳，彼疑药之燥，分之重，竟不敢服，再四叮咛，勉强服之。余回寓，药下未半刻，彼见病虽未加，而痛尚未减，即更他医，至则大罪吾药，幸彼亦仅用猪苓、泽泻、车前、茯苓、陈皮、桔梗之轻剂，药一下咽，小水长行，立时而痛胀俱失，岂知余剂为之向导哉！次日医者病者皆曰：昨非后剂，几被姜桂闭死矣。嗟乎！彼居无功之功，我得无罪之罪，安得同道高明之士，为我一正之。", "8392": "记读先祖著《医卜同源论》，末附治验，有詹姓癃闭一案云：病自腹痛，连日服药未愈，一日偶用车前草煎服，须臾痛转加甚，小水紧迫，膨胀不出。延余诊时，痛闷于床，呼吸将危，四肢厥冷，脉得寸部浮弦时止，尺部沉迟而疾。潜思阳明实痛，热结膀胱，痛极必汗，今无汗，知非阳症也。又初无恶寒头痛，则于表里无涉，此必生冷伤脏，是为冷结关元，阳气不化。经曰：膀胱者，州都之官，津液藏焉，气化则能出矣。重用附桂，加苓草，佐以枳实，合为逐冷化气。一剂后，人事稍苏，小便紧急十余行，仅得半盏，再剂后，安睡一顷，下榻小水长行，痛止而安。此症因案中引而未发，故特表而出之。男澍谨识", "8393": "黄平福，形瘦面白，时当暑热，得呕吐泄泻之病，医见口渴溺赤，与石膏竹叶汤，而呕泄未止，反加心胸胀满，神气昏冒，躁扰不安，势甚危急。诊之脉来浮数，肌热灼指，舌边红刺，满舌白苔，中心黄黑。伊父绍邦，年老独子，求治甚切，因慰之曰：俟吾以二法治之，毋庸惧也。先与连理汤，继进半夏泻心汤，果得呕泄顿止，热退纳食而安。门人问曰：吾师治病，每预定安危，令人莫测。此症先定二法，服下丝毫不爽，其理安在？答曰：业医必揣摩有素，方有把握。《内经》有云：肠中热，胃中寒。胃中热，肠中寒，肠中热则出黄如糜，胃中热则消谷善饥，胃中寒则腹胀，肠中寒则肠鸣飧泄。胃中寒，肠中热，则胀而且泄；胃中热，肠中寒，则疾饥，小腹痛胀。斯人斯症，合乎胃中寒，肠中热，故胀而且泻也。然胃中之寒，始先原是盛暑逼于外，阴冷伏其中，而医又以大寒之药清胃，则胃愈寒矣。故虽寒热错杂，不得不先与连理，调其胃气，分其阴阳也。然阳邪内陷，已成痞结，非苦以泻之，辛以通之，其何以解寒热错杂之邪耶？世医治病，但守寒以热治，热以寒治，倘遇寒热错杂之邪，不知《内经》胃热肠寒，胃寒肠热之旨，及仲景诸泻心，嘉言进退黄连汤法者，其何以肩斯任也？", "8394": "傅德生，善饮，衣食弗给，时值暑月，吐泻交作，大汗如洗，口渴饮水，四肢厥冷，尚能匍匐来寓求治。余见而骇之，忙与附桂理中丸一两，更与附桂理中汤一剂，俱呕不纳。又托人求诊，见其吐泻汗厥恶症未减，余益骇之。尤可畏者，六脉全无，四肢冰冷，扪之寒彻指骨，顷刻间，肌肉大夺，指掌尤甚。急以回阳火焠之，诸逆幸挽，始获斟酌处方，以大剂附子理中汤加益志，又呕而不纳。因思胃者，肾之关也，寒邪直入，舍此大热之药，将安求乎？复悟肾胃之关，一脏一腑，寒邪斩关直入，与少阴肾寒之气，滔天莫制，大热之药，势必拒格。夫理中者，理太阴也，与少阴各别。原仲景治少阴病，下利厥逆无脉之症，格药不入者，有反佐通阳之法，用白通加人尿猪胆汁汤，按法煎进，下咽乃受。渐喜脉微续出，阴浊潜消，阳光复辟，九死一生之症，赖以生全。", "8395": "按：回阳火，不惟能回阳于无何有之乡，凡一切暴中阴寒、阳缩、痰厥、气闭等证，用之得当，无不立效。惟脐下平平三焦（中焦宜稍偏），病人长则下焦宜疏，病人短则下焦宜密，诊脉之理，下指亦然。", "8396": "周孔昌体肥而弱，忽然腹痛，泄泻，十指稍冷，脉甚微，因与理中汤。服后泄未止，而厥逆愈进，腹痛愈甚，再诊无脉，知阴寒入肾。盖理中者，仅理中焦，与下焦迥别，改进白通汤，一服而安。", "8397": "附：次日其堂兄，腹痛缠绵，渐至厥逆，二便阻闭，胀闷之极，已进攻下，而痛愈重，促余诊治。六脉俱无，且面青唇白，知为寒邪入肾，亦与白通汤，溺长便利而安。", "8398": "门人不解，疑而问曰：一泄泻不止，一二便阻闭，何以俱用白通汤而愈？答曰：少阴肾者，胃之关也。前阴利水，后阴利谷，其输泄有常度者，原赖肾脏司开阖之权耳。若肾受寒侵，则开阖失职，胃气告止，故厥逆无脉也。今两症虽异，而受病则同，一者有开无阖，故下利不止，一者有阖无开，故二便皆闭。均以白通汤，复阳散寒，温暖肾气，使肾气得权，复其开阖之旧，则开者有合，合者有开矣。噫！此《金匮》奥义，仲景隐而未发者，子辈既从吾游，读书必期悟境，悟能通神，洵非虚语。乃知圣人之法，变化无穷也。", "8399": "熊锦松潮热泄泻，呕吐蛔虫，咳逆牵引，左胁疼痛，历服清散温补之药，愈治愈危。迨至夜半，气逆神昏，面红目赤，汗大如雨，俨然虚脱之象。但从来热泄之症，最虑阴液消亡，断无戴阳之理。诊两寸弦数，知其脏体属阳，察脉审症，推肝火冲逆，犯土侮金，是以呕泄咳疼，诸苦并增，加以温补误投，以致热盛神昏也。与温胆汤，加石斛五钱，桑叶，白附，数剂果安。", "8400": "门人问曰：传孔英之子，夜半腹痛，自服曲蘖砂糖，次日上则呕吐而虫出，下则泄泻而血出，医者以桂枝、白芍、黄芩、木香之药，连下痰血数升，四肢厥逆，辗转躁扰极危，索饭一碗，食毕频笑频哭而逝，此曷故也？答曰：大凡治病，必先察其外感内伤，为吾侪临症之权衡，次究其在营，在卫，为人身气血之分别。然人有两死而无两生，故曰脱血者无汗，脱汗者无血。盖汗即血，血即汗。孔翁乃郎，吾早见其语声低陷，神彩外扬，声陷而气必弱，神扬而内必空，固知其非永寿人也。今腹痛自半夜，其阳虚阴盛可见，奈何误为食积腹痛，而用曲蘖砂糖，极力消导，大戕其脾胃生气耶。盖曲蘖能化米为酒，而砂糖破血尤速。尝于吾乡幼科并方脉诸士，及处家者皆切戒之，乃世俗通弊。无论寒热虚实，一见小儿腹痛，即以曲蘖服之，产后腹痛，即以砂糖服之，盖只知其利之小，而不知其害之大也。幸遇体坚病实者服之，虽得取快之一时，每多暗损于后日。至若病虚体弱之人，害可胜言哉？且今人之禀气虚弱者多，虚弱之体，脾胃既伤，安得不上呕吐，胃虚虫无所养而上出，下泄泻，脾虚血无所统而下脱乎？当是时中气大困，安之固之，犹恐不及，奈何医者，尚认为外感实火之证，投以发散清上，致令阴阳表里俱伤，是其外感内伤之辨不明矣。夫其临危索饭者，仓廪空求救填也。大凡虚病将危，食饮倍常，俗云装路食者，此也。至此已为除中不治之证，除中者，言中气已除尽也。躁扰不安者，虚阳外绝，中气内断，厥逆脾绝，频笑心绝，频哭肝绝。盖心主血，肝脏血，脾统血，以三脏俱绝而殒，岂非寒中决裂之验耶？何孔翁及世俗尚不知曲糖医药之误，乃归咎于方隅鬼祟，不亦异哉？故医者能于望闻问切之间，先清其内伤外感之由则几矣。子辈后遇此症，必当以扶土救阳为先，盖万物以土为根，以阳为生，无土不立，无阳不长，此其大要也。门人又问曰：此证今先生道破，固知其为内伤矣。但分明下血，即为血虚，似宜救阴补血，乃言扶土救阳，其理安在？曰：吾早已言之，夫汗即血，血即汗，有形之血不能速生，无形之气，所当急固。况中虚之病，何堪辛散苦寒戕劫之剂？当知治此症，与仲景治误汗亡阳救逆之法无少异。且中土一脏，尤为人身吃紧关头，试以五行言之。土能生金，不待言矣，设使木无土，何以载其根，遂其生？水无土，何以御其边底，折其江淮河汉之流？又火能生土，而实火生于土，设使火无土，固无从始其赫曦之化，又何以蓄其升明伏明之胜复乎？盖上非火不坚，非木不疏，非金不泄，是以一岁之中，春夏秋冬，木火金水，各旺七十二日，土寓四季之末，每旺十八日，大哉地道，土膏一动，百草蕃茂，土气一收，万物归藏。究而言之，万物归于土，万物生于土也。推而广之，水火相克，水火又同穴，设使水中无火，则神机寂灭矣，火中无水，则万物枯焦矣。其实水包火外，火胎水腹，故《仙经》曰：龙从火里出，虎向水中生。又《道经》云：两肾一般无二样，中间一点是阳精。学者必须从此推求，自然心地顿开，所谓知其要者，一言而终，不知其要者，流散无穷。读书若但随文解义，何能精义入神？今因子辈不知人身以土为重之要，故并及之。", "8401": "聂安生，腹痛下痢，红多白少，诸医以腹痛为积，又以红多为热，屡进消导不应，更与芩连归芍，服之潮热时起，下坠难支，欲进巴霜丸，疑而未决。余为诊视，左关弦大之至，唇舌虽红，然不喜茶水。脉症相参，知为劳伤中气，以致营卫不调。盖营虚则血不藏，卫虚则气不固，而为下痢红白也。加之苦寒迭进，致使阳虚外扰而潮热，中气内伤而下坠，意拟理中焦之阳，使气血各守其乡。但脉无沉细，且有弦大，又兼腹痛，据症按脉，斯制木、补土、提气三法，在所必须，与黄耆建中加姜炭，四剂始安，后与附桂理中加固脂、鹿茸，十剂而健，孰谓下利脓血定为热耶？", "8402": "邹锦元之妻，小腹绞痛，里急泄泻，每欲小便，腹筋牵引阴中。诸医见泄止泄，投尽理脾涩剂，月余不瘳，势甚危笃，继复呕吐，汤水不入，胸以上发热，腹以下畏寒。余诊之曰：若果内寒外热，安得月余痛泄之病，尚有弦数之脉？此必木邪乘土，下寒上热，当推关格之例治之。仿进退黄连汤，加吴萸、木瓜、川楝、蜀椒、乌梅，月余重病，不过三服而安。盖仿先君治熊锦松，泄泻吐蛔，潮热咳逆一症，推肝火冲逆，犯土侮金，用温胆之法，扩而充之也。", "8403": "傅毓尚长子，潮热畏寒，医以羌防柴葛之属，热愈甚，大汗淋漓，四肢怠惰，食已即饥，医者犹谓能食为美，见其潮热不退，更认为疟疾，复用柴胡、槟榔之属，其热如故。问其大便甚难，又加大黄、枳壳，便仍未通，乃至牙关紧闭，口中流涎，面唇俱白，大汗嗜卧，腹中欲食，口不能入，前医束手而去，始延余诊。问其初有潮热畏寒，继则大汗易饥便坚，四体倦怠，后乃牙紧床肿涎流，诊得诸脉弦小，惟两关洪大之至。细察此症，虽属三阳经病，但与太阳少阳全无相涉，悉是阳明胃病。盖胃中伏火，为中消候也，以泻黄散，加七厘、升麻、大黄与之。方中最妙，防风、升麻有升阳泻木之用，所以能启发胃中伏火，不致清阳邪火，两遏其中，使之尽行舒畅。又有七厘诱之，石膏凉之，大黄泄之，栀子引之，甘草调之，蜂蜜润之。井井有法，诚为胃中伏热之妙剂也。下咽后，熟睡一顷，牙关即开，流涎亦止，潮热亦退，更以搜风润肠之药，频服而健。", "8404": "熊妇，年十七岁，起日畏寒发热，次早大热不寒，不知人事，牙关紧闭，面唇俱赤，胶痰满口，遍身痿软，状若无骨，六脉急数，二便阻滞。医者见其身软，咸称不治，不知寒则筋急，热则筋弛，此真风火之症，古称类中之属也。询知食炒豆子过多，盖身中素积内火，加以外入之热，继受外入之风，风乘火势，火借风威，所以卒倒无知。理宜两彻内外之邪，使表里清而神识朗，先以稀涎散吐之，随进疏风清热、通关化痰之药而痊，后以生津之药而健。", "8405": "王毅垣先生，平日操劳劳倦思虑俱伤脾气，素有痰饮，稍饮食未节，或风寒偶感，必气喘痰鸣。十余年来，临病投药，无非括痰降气之品。迄来年益就衰，病亦渐进，值今秋尽，天气暴寒，饮邪大发，喘息不休，日进陈半香砂之属，渐至气往上奔，咽中窒塞，喉如曳锯。密室中，重裘拥炉，尚觉凛凛，痰如浮沫，二便艰涩。余见其面赤，足胫冷（阳被阴逼外出），两人靠起扶坐，气逼咽嗌，不能发声，脉得左手沉涩，右手缓大，因思喘急沉涩，已属败症，且四肢虽未厥逆，而足胫已冷，实未易治；继思胸中乃太空阳位，今被饮邪阴类僭踞，阴乘于阳，有地气加天之象。急以仲景苓姜术桂汤加附子一两，连进二剂，病全不减。再诊左涩之脉已转滑象，而右大之形，仍然如昨，乃知中土大虚，不能制水，饮即水也。嘉言喻氏曰：地气蒸土为湿，然后上升为云。若中州土燥而不湿，地气于中隔绝矣，天气不常清乎。遂将原方重加白术，减附子，大剂再进，而阴浊始消，胸次稍展，溺长口渴。毅翁恐药过燥，余曰：非也。此症仲景所谓短气有微饮者，当从小便去之。况渴者，饮邪去也，何惧其燥耶？仍将前药叠进，乃得阳光复照，阴浊下行。其善后之计，仍仿嘉言崇土填臼之法，缘饮水窃踞，必有科囊故耳。", "8406": "附：后治周成翁，恶寒胃痛，医与疏渗药，胃痛偶减，忽加左胁疼痛，时发眩晕，欲补未决，延余诊之。脉来濡滑，因推胃中痰饮，流注肝络，故有风旋痰眩之象，与二陈，加芥子、瓜蒌、枳实而痊。", "8407": "杨有成先生，患疟两月，历试诸药弗效。其疟独热无寒，间日一发，口不渴，身无汗，自觉热从骨髓发透肌表，四肢如焚，扪之烙手，视舌润，脉又沉迟。窃思果属瘅疟，安得脉不弦数，口不作渴，且神采面色，不为病衰耶？此必过食生冷，抑遏阳气于脾土之中。阳既被郁，郁极不通，而脾主信，故至期发热如疟也。治之之法，必使清阳出上窍，浊阴归下窍，则中焦之抑遏可解。与升阳散火汤，果汗出便利而安。", "8408": "附：陈友生病疟，脉象形色悉同，惟独寒无热，医治三月不痊，察其溺短无汗，知为外寒内热，伏火畏寒之症。盖火郁土中，而脾土主信，故至期如疟，惟有发之一法，亦与升阳散火汤而愈。", "8409": "陈奇生室人，妊身九月，得疟病，久治弗痊。其疟寒少热多，汗大口渴，迨至坐卧不安，势难支持，腹中胎气乱动，诸医以安胎攻病，无从措手。余诊其脉，略有躁乱，再视其舌，已显镜光，面白唇红，青筋满露（此木邪侮土），乃津液大伤，胃火掀腾。虽年少体强，然汗后脉躁，最犯禁例。盖恐明日疟至，而正虚邪盛，治不得法，则母子难保矣。因思胃火掀腾，而久疟食减，芩连决不能进；津液大伤，而土败木贼，归术又难酌投。拟补虚清热之药，惟有纯甘可采，因举黄耆五钱，石斛五钱，人参五钱，桂枝八分，乌梅一个，煎汤已成，另捣梨汁一杯，姜汁少许冲服，嘱其即服一剂，至夜备煎一剂，明早将曙再进。病者两服药后，俱云好药，以味甘可口，与胃相适也。是日疟竟不至，再与甘温调理而健。但此症脉来躁疾，面白唇红，青筋满露，若用柴芍伐肝，必毙。", "8410": "周秋帆先生，秋间患疟，每日午发，寒热稍平，退时有汗，头疼或又不疼，口渴或又不渴，二便无恙，夜寐亦安。此客邪尚浅，然治经二旬，凡发表清里、和解补中诸法，投之渐剧。况体气素虚，而烦惋莫耐，叠投补剂，而胸膈加痞。余诊其脉，亦皆和平，舌苔黄滑，审症察脉，似当温补，然又补之不投，岂敢再陷前辙乎！谛思良久，不得其情，惟于审症中察其略有嗳气，或时以手摸胸，知饮食伤胃，食滞未消，方书称为食疟者也。法当消补，兼行疏通脾胃，庶几中无阻滞，营卫自通，俾枢机流利，其疟不治而治。方以生白术为君，佐以陈半草果藿朴苓泽之属，一剂疟轻，二剂果愈。足见医家治病，如老吏审案，倘正案难凭，当以旁情参之，庶不为假证所惑也。", "8411": "许静常之女，于归后患疟数月，自秋徂冬，百治不效，转居母家，就治于余。视其面黄肌瘦，唇淡口和，本属虚象，阅前医成方，悉多峻补，无一可投。询其病，间日一发，或二日一发，甚或一日一发，总无定期。此当著眼，须知脾主信，今无信，病不在脾胃也。又询发时，或早或晏，亦无定候。尤属无信。且发时寒则身冷如冰，热则身热如烙，有阴阳分离之象，口渴饮水，面赤如朱。有虚阳外浮之据。及诊其脉，颇觉弦大当推水不生木，因谓此症全非疟疾，乃阴阳不协，致亢龙有悔，故为似疟非疟耳。处以八味丸全服四剂，其疟不治果愈，蒙称神治，安知循古而非新裁也。", "8412": "傅妪，于疟疾流行之年，秋将尽，忽然浑身战栗，瞬息大热烦躁，热去寒复生，寒止热复至，先寒后热，心烦意躁，脉来洪大无伦，两尺上涌抵指，唇红面赤，喜饮热汤，舌上白苔布满，时吐稠痰甚多，正《内经》所谓阳维为病，病苦寒热，发为劳疟。证虽疟名，方非疟治，急宜引阳回宅，整顿纲维，大固中州，阴阳调和，寒热自止。以六味回阳饮为主，加暖中摄下之药。是晚连进三剂，寒热顿止，次早精神爽利，仍服三剂，间日微寒微热复至，再服原剂而痊。", "8413": "诊脉控弦，明者亦惊，", "8414": "王云周之子，秋间患疟，其疟二日一发，以其邪气内藏于风府，其道远，其气深故也。然病经两月，而神不衰，惟发时心中寒，寒久热甚，多惊，一日偶触外风，以致寒不成寒，热不成热，四肢僵硬，医者不知内风召外风之理，犹以归附燥血，羌防升气，乃至气急上冲，两人挟坐，不能著枕。危急之顷，始延余治。诊得便秘脉浮，许以一剂可愈，遂疏桂枝、桔梗、蒌皮、苏子、杏仁、紫菀、把叶之药，果得便通气平，诸症皆安。五弟启明，未识此中妙义，问曰：此症之最急处，似在气逆上冲。但气逆便阻，惟有虚实两途，一则收摄温通，一则破气攻利，今不治气而气得平，不攻便而便得通，且药味平淡，而取效甚捷，何也？答曰：此病见症虽多，无非全在于肺。察其疟时，心中寒，多惊，尝考《内经》论病，惟疟最详。有云肺疟者，令人心寒。注云：肺为心盖也。又云：热间善惊。注云：肝主惊，有金克木之象也。夫内风召外风，最易成痹，然外风既入，内风必乱，故寒不成寒，热不成热。夫肺主皮毛。经云：皮痹不已，复感外邪，内舍于肺，因而营卫行涩，故四肢僵硬也。至于气逆上冲，能坐不能卧者，正《内经》淫气喘息，痹聚在肺也。盖人身之气，全赖肺以运之，今肺气痹矣，机关必窒，是以肢僵，便秘气逆，诸症丛集。方中惟桂枝、桔梗二味，领风邪外出，余皆轻清疏降之药。且桔梗能通天气于地道，观其有升无降，但得天气下降，而地道自通也，肺气通调，而百体自舒也。至于取效甚捷之义，原《内经》所谓风气胜者。寻其治病易已也。五弟退而专功《内经》。", "8415": "徐锦窗先生，年逾六旬，患时行疟症，尚未分清，医以柴葛大黄之药治之，寒愈入里，反至纯热无寒，口渴饮水，小水全无，时欲登桶，溺不得出。诸医日投四苓芩连之属，迨至神识昏迷，舌白干刺，奄奄一息，无从措手，始延余治。余曰：此症之最急处，全在小水不通。夫溺闭虽属下病，然有上取之法，东垣有云：渴而小便不利者，热因上焦气分，故脉之浮数，舌之白刺，口之渴饮，神之昏迷，非热邪蒙闭上焦气分乎？盖上焦肺部，主周身之气，司治节之权，今肺热痹，清窍已窒，浊窍自阻，非与轻清之药，其何以解上焦窒塞之邪？上焦不布，降令弗行，其何以望其输泻乎？疏以萎蕤、石斛、知母、通草、桂枝、杏仁、紫菀、杷叶，一派轻清之药，果臻奇验。", "8416": "陈景阶内人，初冬忽然遍身浮肿，小溲不利，医以利水消导之药，胀满日甚，气急不能著枕。视其形色苍赤，脉象浮大，独肺部沉数，舌苔灰黄，以苏叶、杏仁、防风、姜皮四味，连进二剂，气急消减，再与人参败毒散加入生黄耆与服，小水通，肿胀遂消。缘此症时当秋尽，肺气消索，天气暴寒，衣被单薄，风邪内入，腠理闭遏，营卫不通，肺气愈塞，致失清肃之令，又无转输之权，水邪泛溢，充斥三焦，故启其皮毛，疏其肺窍，合《内经》开鬼门之法。盖腠理疏通，天气下降，而水气自行也。", "8417": "龚甥可象，时值秋尽，偶患咳嗽气急，微有寒热，已服参苏败毒之类如故，改与泻白散一剂，小水短涩，渐次遍身肿满，略与导湿利水之药，更加腹胀气促。窃思治病不过表里虚实，然散之表不除，清之里反逆，固非尽属实邪，又脉来弦数鼓指，唇皱红，舌灰白，此岂尽属于虚，其中错杂有非一途可尽。然既见寒热，咳嗽，气急，尿短，腹胀，无不关乎肺脏。肺气受病，既不服散，更不容清，其挟虚也审矣。况时值秋尽，燥金之气已虚，天令下降已极，人身莫不应之。今肺气已虚，便衰其护卫，失其治节。护卫衰，风寒得以外郁，治节失，湿热借以内停。由是闭而不行，而肺家通调下输之道，其权已废，邪气正气清浊相混，一概窒塞于中，无由输泄，只得散越皮肤。再加泻肺利药，以致阳愈下陷，阴愈上冲，故见腹胀气急。诊其脉来数急者，乃阴火上冲之明征矣，法当疏其肺，益其气，举其阳，降其阴，为法中之法。设使疏肺而不益气，则肺气重虚矣，益气而不疏肺，则抑郁不开矣；举阳而不降阴，则阴火不服矣，降阴而不举阳，则阳愈下陷矣。是必法兼四备，无一可缺。初欲仿补中益气方，加入知柏之属，虽有举阳降阴益气之能，却少疏肺开郁之力；后悟李东垣先生原有升阳益胃一法，直取其方，加入黄柏一味，服之小水倍常，乃降阴洁净府之验，连服十剂，诸症悉痊。愈后遍身发疮痍，可见里蕴之热，久被表寒外束，乃至内外交郁成毒，缘得开鬼门之药，逼其外出，不致内陷之明征也。方中参术耆草，益气升阳也。柴陈羌独、防风，升阳疏肺也。芩泻连柏，降阴导湿也。白芍敛阴和血，散中有收，姜枣调和营卫，补中有散，一举而诸法兼备，可谓先得我心矣。夫人知利药可去湿，而不知风以胜湿：人知破气以消肿，而不知益气以收肿；又知发表以散邪，而不知升阳亦散邪也。外此以及通因通用，塞因塞用，寒因热用，热因寒用，上病下取，下病上取，阴病取阳，阳病取阴，医家诸法最当素谙。学者于此一案，倘能类推其余，则于诸症，皆可得法外之法矣。", "8418": "吴乐伦，时当盛暑，陆路归里，中途发疟，其疟每日夜发，寒少热多，汗出口渴，小水短赤，面目浮黄，舌苔堆积如粉，大腹阴囊及腿胫一带，悉皆浮肿。又发旧痔，每日零星去血，约在升余，凡凉血消肿治疟之方，俱历尝不效。按脉属虚，而症似湿热，窃疟肿便血三症，皆虚中挟热，正合《内经》气虚身热，得之伤暑之旨。盖病者原因途中暑热，渴而啜瓜，湿热蕴蓄于胃，三焦不化，四海闭塞，以致营卫失常，而成斯疾。必须先洁净府，以少杀其暑热之炽，顺趋水道，令膀胱气化先行，然后再提阳陷于阴之疟邪，从鬼门而出，则腠理自和。俾卫分有气化之机，营中无扰乱之苦，而便血不治可自止矣。于是以轻清微寒之味，解暑渗湿之品，方用西瓜、滑石、石韦、丹皮、通草。服至二剂，小便甚长，身肿消退，随以清暑益气汤除苍术，连服旬日，果然三症顿愈。所谓病变虽多，法归于一之验也。", "8419": "傅孔怡，病缠服药，十有余载，初起，腹痛时胀，得食身重，时愈时发，渐次而甚。旧冬足跗有浮气，至春通身浮肿，腹皮胀满，腹中鸣响，上气喘急，胸前塞紧，食饮不运，左肾睪丸吊痛，遍身之病，自难名状。三楚名剂，历尝不瘳，买舟归里待毙而已。邀余告曰：今请先生为我决一逝期耳。余曰：此为单腹胀证，古贤皆曰难治，病源本深，但今诊其脉，尤有和缓之意，可知胃气以及真阳尚有微存，是为先天禀赋之厚，急进大药，尚属可治。经曰：阳气者，若天与日，失其所则折寿而不彰。今阳气所存无几，全是一团阴气混扰其中，所以腹中鸣响，哇哇之声，皆阴气漫弥也。阴气盛，则中州无光土，被浸润泥滑矣，所以饮食不运，胸紧腹鼓者，皆土病也。至于吊疝跗肿，乃命门火衰之征，而上气喘急，由乎肾阳为阴所迫，无根之气，端往上奔。为症如此，安之固之，尚且不暇，何医者见病治病，不明塞因塞用之法，希图目前之快，任行攻伐，使非先天禀赋之厚，真阳早已扑灭矣。吾今许以可治者，以崇土为先，而土赖火生，又当以治火为急，火旺则土自坚，土坚而万物生矣，火旺则阴自消，阴消而阳自长矣。方既立，何孔翁疑药之重，畏术之补。余曰：前被劫药之误，岂可犹陷前辙？今仅留残喘，岂能迁延时刻？比之黄河坝倒，岂担石培土所能竖立？而用燥药者，譬之贼兵鼓众，虽选强与敌，使非铳炮为之前，焉能直突营围？因亲验其药，面视其服，而犹药轻病重，三服始验。告余曰：服白术之拦阻，胸前反宽，腹中之气，竟走肛门而出。余曰：此正云开雾散，日将出也。以后服五十剂毫不改味，而腹胀足肿始消，七十剂遂奏全效。可见阳气存留，得于先天禀赋之厚者，终克有济也。", "8420": "余毓贤，堪舆为业，冒暑登山，因而疟痢交发。医者不究其劳，惟责其暑，凡胃苓香薷芩连之药，数手雷同，乃致疟痢未已，而气急肿胀日增。延余治时，败症百出，忙以补中益气、《金匮》肾气，日夜交斟，按治三日，疟邪不至，痢转滑泄，似乎大有起色。然细揣尚有三不治焉，盖水肿症脉宜洪大，今见沉细一也，且囊与茎俱肿二也，又滑泄而肿不消三也。以此告辞，求治不已，勉力处治。潜思火土伤败，非大剂破格，何能逆挽？用六味回阳饮，加白术、骨脂、肉蔻，兼进硫黄丸，日进三剂。按法不歇，五日之久，病全不减，扶至十日，附术各进两斤，硫黄丸已下九两，始觉气急略平，便转溏粪。再经旬日，进药不辍，方可著枕，便坚溺长，脉稍有力，皮肤始露绉纹，旋以归脾汤，吞八味丸，再经月余，始克起死而回生也。", "8421": "汪廷选秋间患疟，发表后叠进附桂理中汤，已获小安，惟疟邪未曾全止，急求止截。余晓以养正邪自除之义，竟私取截疟膏药贴背，疟邪虽止，渐加浮肿腹胀，玉茎肿亮，状似鱼泡，咳嗽气促，呻吟不已。视形容面色舌苔脉象，俱属大虚，拟以火土伤败，与术附姜桂。按服数日，色脉如原，茎肿尤甚，改进五皮饮，重加苡仁、桑皮与服，俾得溺倍于常，茎肿乃消。此症原是脾肺两脏，气化不行，水壅经络，泛溢皮肤，徒然益火燠土，与皮肤无涉，故诸症自若，而茎囊原为聚水之地，故肿尤甚，水溢皮肤，以皮行皮之义，故肿乃消。可见医贵圆通，不可执一也。", "8422": "陈敬斋先生，年逾八十，身体坚强，声音洪亮，耄年尚御女不辍。旧冬曾举一子，其先天禀赋之厚可知，迩值春升，面足带浮，语言不利，惟眠食犹安。诸郎君，各延一医调治，咸称脾肾之虚，理中肾气诸方，叠投益甚，渐加气促不能著枕，遂谓高年重症，无药可治。停药数日而病益进，托友转请于余。余至扶诊，脉颇浮大，遍身肿，而面部尤甚，语言壅塞，涎唾自流。予想从来肿症，未闻有言謇流涎之例，言謇流涎，惟中风有之。奈何肿症亦有之乎？默思《内经》病机篇云：有病肾风者，面跗庞然，壅害于言，缘邪之所凑，其气必虚。大凡水病多有由于肾虚者，况高年禀赋虽厚，而下元已衰，或加房劳惊恐，俱伤肾气。值此春升，风木司令，下虚不纳，肾液奔腾升越于表，适逢风袭中于廉泉（舌根下两旁穴），故面跗庞然，而兼壅害于言也。处以归杞、附桂、白芍，抑风而制肾水，微加辛防、独活，用之流利经络，稍开鬼门以逐邪。一剂下咽，竟获熟睡，小水倍常；再剂肿消，语言清爽，流涎亦止。可见圣人之法，不可不熟而深求也。", "8423": "杨志荣躬勤力作，感冒风寒，变成疟疾，自取截方服之，果愈。越三日，胸腹饱闷，时现寒热，更医数手，崇事消导，延至胸高气急，胀痛交迫，手不可触，卧不安枕，始请余诊。视其色，如饥，闻其声，先重后轻，问其苦，晚间尤甚，切其脉，浮大无力，知为苦寒攻伐伤中。谓曰：尔必先服槟榔、枳壳，其时痛尚可忍，后服大黄、枳实，胀不可当。荣曰：先生何以知之？余曰：合症与脉而知之也。近世见病治病，不用破气攻下者鲜矣。疏以治中汤而重其剂，服下半日，胀痛未减，亦不觉增，然肠胃间已渐渐稍舒。继进二剂，即可安睡，二便通快如常。越日复视，惟四肢无力，胸喜推摩，更方以附子理中汤数剂全愈，又以附子理中丸数两而健，此正嘉言先生，所谓健脾中阳气第一义也。", "8424": "吴发明，得噎食病，咽喉阻塞，胸膈窄紧，每饭必呕痰水，带食而出，呕尽方安，遍尝诸药，竟无一效，粒米未入者月余。审其形气色脉，知为痰火素盛，加以七情郁结，扰动五志之阳，纠合而成斯疾。疏与四七汤，合四磨饮而安。盖察其形瘦性躁，色赤脉滑，且舌旁虽红，而白苔涎沫，如粉堆积其中也。次年复发，自以前方再服不应，余以四七汤除半夏，加石斛、桑叶、丹皮、蒌皮，数剂复安。盖察其脉虽滑而带数，且唇燥舌赤，故取轻清之味，以散上焦火郁也。越年又发，又将旧方服之，病益加甚，余于五磨饮中，用槟榔、乌药，加白芍，七气汤中，用厚朴、苏梗，加入旋覆花、郁金、橘红、淡豉、山栀治之，二剂而安。盖察其脉来浮滑，加以嘈杂胸痞，知其胃之上脘，必有陈腐之气与火交结也。后因七情不戒，饮食不节，药饵不当，调理不善，逾年仍发，自与知医者相商，谓余之治，无非此意，遂将连年诸方加减凑合，服之愈服愈殆，余又用苏子、芥子、莱菔子、巨胜子、火麻仁，擂浆取汁，合四磨饮，服之顿安。盖察其脉转涩，而舌心燥粉堆积，加以气壅便秘也。吴问曰：世云古方难以治今病，谓今病必须今方，今以今方今病，且本症本人，而取效不再者，其故何哉？余曰：本症虽同，兼症则异，此正谓景因时变，情随物迁耳。夫药犹兵也，方犹阵也，务在识机观变，因地制宜，相时取用，乘势而举，方乃有功。若不识地势，不知时宜，敢任战伐之权哉？吴恍然曰：若是，真所谓胶柱不可鼓瑟，按图不可索骥矣。因请立案，以为检方治病之鉴。", "8425": "吴敬伦先生，年近六旬，得噎食病，每食胃中病呕，痰饮上泛，欲吐甚艰，呕尽稍适，久投香砂六君丁蔻理中等药，毫无一效，计病已五阅月矣，诸医辞治。肌肤削极，自分必毙，其嗣君姑延一诊，欲决逝期。诊得脉无紧涩，且喜浮滑，大肠不结，所解亦顺，但苦吞吐维艰，咽喉如有物阻，胸膈似觉不开，因谓之曰：此症十分可治。古云：上病过中，下病过中，皆难治，今君之病，原属于上，数月以来，病犹在上，故可治耳。以四七汤合四磨饮，一服而胸膈觉开，再服而咽嗌稍利，始以米汤，继以稀粥，渐以浓粥，进十余剂，始得纳谷如常，随以逍遥散，间服六君子汤，调理两月，形容精彩，视素日而益加焉。门人疑而问曰：自古风劳蛊膈，四大重症，法所不治，而吴翁噎病，先生一视，极言可治，用药不奇，而取效甚捷，何也？答曰：昔先君尝诲余曰：人身有七门，唇曰飞门，齿曰户门，喉间会厌曰吸门，胃之上口曰贲门，胃之下口曰幽门，大小肠之下口曰阑门，肛肠之下曰魄门。凡人纳谷自飞门而入，必由魄门而出，原噎食一症，始则喉间阻塞，继则胸膈不舒，涎食涌吐而出，推其原，多由七情气结，或酒色阴伤，或寒热拒隔，或蛔虫贯咽，或凝痰死血，或过饮热酒，虽所因不一，而见症则同，以贲门上至飞门俱病矣。由是津液日涸，肠胃无资，幽阑渐窄，粪结弹丸者，势所必至。脉或弦数劲指，甚则紧涩坚搏，无非阴枯而阳结也。至此不究所因，而不治则一，以贲门下至魄门俱病矣。故善治者，必先乘其机，察其因，而调其上，务期速愈为工，倘贲门一废，虽有灵芝，亦难续命，而况庶草乎？此千古未发之旨，独先君悟彻病情，不以五脏六腑定安危，而以七门决生死，更分可治不可治之例，其亦神矣。今吴翁之病，喉间若塞，胸膈若闭，而脉来浮滑，大便甚快，是病尚在贲门之界，故许其可治。余乘机投以辛温流利，舒气降逆，则阴阳自为升降，七门运用如常，亦先君乘机速治遗意也。至吞之不入，吐之不出，此七情气结，方书所称梅核症耳。张鸡峰先生云：噎症乃神思间病，惟内观善养者可治。", "8426": "傅光廷令堂，年逾七旬，时微发热，躁扰呻吟，大扇扇之，或可稍安，口渴饮汤，辄呕稠痰。医以发汗药治之，遂时热时汗，饮食药物，入口即吐，大便阻格。又以攻下药治之，仅得一解，仍然秘塞，面浮腹胀，胸紧气促，心烦口苦，日夜不寐，身软难支。有议下者，有议补者，其家惶惑无主，求正于余。诊其脉，流利平和，余曰：用补者，因其年老，已经汗下也。用攻者，因其腹胀便秘也。究属见病治病，不察其因，不辨其症。其因者，内因、外因、不内外因是也。其症者，六淫七情之属是也。夫其初起之际，时微发热，已非外感热甚可知；身可受扇，其骨蒸内热，又可预拟；兼之先病呕吐，后加汗下之劫剂，宜乎困倦神昏，口淡无味；而心烦口苦，日夜不寐者，知其肝胆相火上升也；又病缠日久，表里俱伤，脉宜细数短涩，今流利平和，其先天之厚可知。由是推之，其所以脉流利者，痰也。心烦口苦者，火也。胸紧呕吐者，痰也。腹胀便闭者，气也。发热受扇者，内热也。口渴饮汤者，痰逢冷则愈凝，遇汤则暂开也。合观诸证，显系内因七情之病，必因素有思虑郁结之情。盖思虑则火起于内，郁结则痰聚于中，而五志厥阴之火，早已与痰饮结为一家。夫火动则阳亢，痰聚则阴涸，乃病势所自然。今阳气结于上，所以呕吐不食，阴液衰于下，所以腹胀便秘。若误补则阳愈亢，误攻则阴愈涸，此定理也。然则治之当何如？余思病，既由于七情郁结，痰火内生，下秘上吐，九窍已属不和。经曰：九窍不和，都属胃病，但胃属阳土，较治阴土不同。盖太阴脾土，喜刚喜燥，阳明胃土，宜柔宜和，故阳明无壅补之条，太阴有忌下之禁，此阴土阳土，最紧疆界，世医不察者多。斯疾阴枯阳结，呕吐便秘，发热不寐，凡此皆阳明不和之本症，法当清胃和中，但久病阳气亦惫，是清胃又忌苦寒滞腻，老年阴精已竭，故和中尤非香散可施。惟有温胆汤可用，内加乌梅一味，取其和阴敛痰。一剂呕吐略止，稍能纳粥，大便亦通，腹胀顿减，再剂食己渐进，夜寐亦安，后以生津济阴药，洋参、麦冬、石斛、萎蕤之属，频进而痊。", "8427": "傅定远，得痰膈病，发时呃逆连声，咽喉如物阻塞，欲吞之而气梗不下，欲吐之而气横不出，摩揉抚按，烦惋之极。医治两月，温胃如丁蔻姜桂，清胃如芩连硝黄，绝无寸效。延余诊，视其气逆上而呃声甚厉，咽中闭塞，两肩高耸，目瞪口张，俨然脱绝之象，势甚可骇。然脉来寸口洪滑，上下目胞红突。辨色聆音，察脉审症，知为痰火上攻肺胃。其痰也火也，非气逆不能升也。遂处四磨汤，加海石、山栀、芥子、瓜蒌、竹沥、姜汁，连投数剂，俾得气顺火降痰消，再以知柏地黄汤，加沉香，以导其火而安。", "8428": "梅生荩臣，得冲气病，医人不识，自分必死，每发气上冲，咽喉窒塞，一身振战不已，耸肩目突，不能出声。家人意拟为脱，一日数发，延医丛集，亦称气脱，日进理中、黑锡，缠绵数月，竟服黑锡丸斤许，其病愈进，诸医辞治。予诊其脉，右尺数盛，人迎亦大，因思《内经》有诸逆冲上，皆属于火之例，遂制滋肾丸，煎《金匮》肾气麦门冬汤吞服，旬日始见微功，一月乃奏全效，未尝更变药味也。", "8429": "周维友，高年体盛，素多酒湿，时值严寒，饮食未节，湿邪不走，始则胸紧咳嗽，医以陈半枳桔消导之剂，继则气急痰鸣，更医又谓年老肾气不纳，而姜附沉术二香之类叠进，病渐日笃。延余视时，气急上冲，痰响窒塞，阻隘喉间，日夜不能贴席。尤可畏者，满头大汗如雨，气蒸如雾，时当大雪之际，不能著帽。问其二便，大解数日未通，小水涓沥难出，满舌痰沫，引之不透。及诊其脉，沉而劲指，知为阴浊上攻，雷电飞腾之兆，正《内经》所谓阳气者，若天与日，失其所则折寿而不彰。法当通阳泄浊，连进半硫丸，俾得冷开冻解，二便稍利，阳光复辟，阴浊下行，胸膈始舒，而痰壅头汗气蒸诸急，不觉如失。亦阳气得所，则寿考彰明之验也。后与冷香饮，数服而安。", "8430": "余启初，捕鱼为业，患呃逆病，医以丁香柿蒂汤，叠服如故，复就原医诊曰：丁香柿蒂汤为止呃神方，连服数剂，毫不见效，且脉已离根，病在难治，因而辞去，始请余诊。诊得脉来迟细，重按乃得，满面浮气，状如通草糊成，呃声甚长，似空器中出。谓曰：此症之可望生者，正得脉之迟细耳。且细玩有神，毋容惧也。遂用代赭旋覆汤与服。药方下咽，呃声即止，继进二剂，呃声复起。越日又诊，脉症如前，呃则抬肩，声类牛吼，溯仲景设代赭旋覆汤，原为重以镇怯立意，今声如牛吼，中虚可知。故一服呃止者，乃得重镇之力，再服又呃者，足征中州之虚，而仓廪空乏，尤恍然悟矣。因详诘之，启曰：始因感冒风寒，来求先生数次未遇，向药铺问服一剂，寒已除清，后因胸前不舒，得食身重，复问一剂，不识何药，只见有花色如槟榔者，服下未久，五脏翻裂，有如刀割肠断之苦。始知以往之误，于是以理中加赭石、当归，镇中安脏，日进两剂，呃渐休，脉渐充，按方再服，诸症皆平，惟面部尚浮，以脾虚失统治之而安。按此症，因胸不舒，得食身重，理当健运脾阳，或辛温助胃，亦可奏效。夫呃逆，一总名也，有因寒，因热，因虚，因实者，治以清火、温寒、降气、理虚之法，种种不同，敢曰柿蒂一方，遂足以毕斯症之能事乎？", "8431": "汪纶诏，患左肩胛疼痛，自肩入腋至胁，觉有一筋牵引作痛，昼夜叫喊无少休息，凡攻风逐痰，历尝不应。延余视时，病已极，然虽痛闷，口不能言，脉尚不停，且弦大洪数之至，明明肝火为病。曾记丹溪云：胛为小肠经也。胸胁，胆经也。此必思虑伤心，心脏尚未即病，而腑先病，故痛起自肩胛，是小肠经已先病也。及至虑不能决，又归之于胆，故牵引胸胁作痛，是胆经又病也。乃小肠火乘胆木，子来乘母，谓之实邪，与以人参木通煎汤吞当归龙荟丸，应手而愈。", "8432": "王国翁，少年嗜酒过度，致经隧凝痰，近来嗔怒频生，木火炽盛。今春肝阳暴升，肘膝痛楚重坠，寐难成睡，面白而光，舌黄而裂，鼻煤，眼泪，腹痛，便秘，旧痔复作，恶寒鼓栗，玉茎痿缩，脉得关弦尺数，洪而有力，固非阳绝，亦非阴虚。细按诸症丛杂，由乎肝阳拂逆，木盛生火生风，《内经》病形篇曰：诸禁鼓栗，皆属于火。于是以左金丸为君，加入山栀、苍术、白芍、瓜蒌，连进十剂，接服搜风顺气丸而愈。", "8433": "黄绍发腰屈不伸，右睪丸牵引肿痛，服补血行气之剂，病益日进。余诊脉象，弦涩带沉，询其二便，小便长利，不及临桶，大便则数日未通，知为蓄血无疑。处桃仁承气汤，加附子、肉桂、当归、山甲、川楝，下黑粪而愈。", "8434": "刘氏妇，青年寡居多郁，素有肝气不调之患，今秋将半，大便下坠，欲解不出。医用疏导之药，并进大黄丸，重闭愈增（气虚可验），两胁满痛（非补中可投），诊脉浮大而缓（是风邪确据），饮食不进，四肢微热（中虚可知），小水甚利，月经不行（又是蓄血之症）。据此谛审，不得其法，细思独阴无阳之妇，值此天令下降之时，而患下坠之症，脉来浮大且缓，系中气久伤，继受风邪入脏无疑。两胁满痛，肝气郁而不舒，惟有升阳一著，四肢独热，亦风淫末疾之义。月经不行，乃风居血海之故。执此阳气下陷，用三奇散，加升麻以提阳气，复入当归少佐桃仁以润阴血，果然应手而痊。", "8435": "万海生，腹胁胀痛，或呕或利，而胀痛仍若，医者不察，误与消食行滞之剂，遂腹胁起块有形，攻触作痛，痛缓则泯然无迹。自冬迄春，食减肌削，骨立如柴，唇红溺赤，时寒时热，诊脉两手弦数，似属木邪侮土之证，究归阴阳错杂之邪，正《内经》所谓胃中寒，肠中热，故胀而且泻。处仲景黄连汤加金铃、吴萸、白术、川椒，数剂而安，随进连理汤乃健。", "8436": "汪慎余，由苏州归，时当酷暑，舟中梦遗，旋因食瓜，继以膏粱，致患小溲淋痛（此湿热乘虚入于精道之据）。途次延医，投利湿清火之药，淋痛虽减，又加少腹胀急，舟至许湾，左睪丸偏坠，胯胁牵痛，而少腹之胀日益甚，小水清利，大便不通，连延数医，俱以五苓散合疝气方，更增车前、木通，颠连两日，少腹胀不可当，左肾肿大如碗，烦躁闷乱，坐卧不安，急切邀治。脉得沉弦，遂处桃仁承气汤，重用肉桂，加当归，一服大便下瘀黑二升而愈。夫邪结膀胱、少腹胀急之症，原有便溺蓄血之分、在气在血之辨，盖溺涩症，小便不利，大便如常，蓄血症，小便自利，大便黑色，此气血之辨。古训昭然。今者少腹胀急，小便自利，则非溺涩气秘，显然明矣。独怪市医既不究邪之在气在血，且已知小便自利，反以利水耗气之药，其何以操司命之权耶？", "8437": "江发祥，得痃癖病，少腹作痛，左胁肋下有筋一条，高突痛楚，上贯胃脘，下连睪丸，痛甚欲死，或呕或利，稍缓若无，呕利则痛苦迫切，连宵累日，绝粒不进，或得腹中气转，稍觉宽舒。医人不识，辄以治疝常法，苦辛之味，杂投不已。有以肾气不藏者，或以冲任不固者，而金匮肾气、青囊班龙，叠投益甚，误治两载，疾已濒危。视其形瘦骨立，腹胁贴背，知为误药减食所致。按脉滑沉，且觉有力，审病经两载，形虽瘦而神不衰，拟是肝胃二经痼冷沉寒，积凝胶聚，绸缪纠结，而为痃癖之症。盖痃者，玄妙莫测之谓，癖者，隐辟难知之称。察脉审症，非大剂温通，何以驱阴逐冷？于是以附术、姜桂、骨脂、葫巴、丁蔻大剂，稍加枳实、金铃以为向导，兼进硫黄丸火精将军之品，用以破邪归正，逐滞还清，冀其消阴回阳生魂化魄之力，日夜交斟。按治半月，病全不减，再坚持旬日，势虽稍缓，然亦有时复增，且沉滑著指之脉，仍然不动。因谓之曰：病虽减而积未除，尚非愈也，此症颇顽，姑忍以待之。所喜者，倾心信治，余益踌躇，因思冷积不解，欲与景岳赤金豆攻之，然恐久病体衰，断难胜任其药，只得坚守前法。再进旬日，忽然大便大通，所出尽如鱼脑，其痛如失，姑减硫黄丸，仍与前药，稍加黄柏，每日出鱼脑半瓯，再经半月，前药不辍，鱼脑方尽，冷积始消，前此腹肋高突之形，泯然无迹。厥后露出皱纹一条，如蛇蜕之状，乃知先贤人身气血痰水之积，均有澼巢科臼之说，为有征矣。", "8438": "吴妪，初起心腹间微痛，越二日，痛苦异常，汗大如雨，水米不入，口不作渴，小水清利，神昏懒言，坐难片刻，俨然虚极之象。自云素属中寒，难以凉剂。诊得六脉时伏，内外一探，虚实难决。因思痛症脉多停指，况阳明痛极必汗，若三阴之痛，必面青背曲，何得汗大如雨？势必内有积热，所以饮食加痛；病方入里，所以口不作渴；痛难支持，所以神昏懒言。乍观虽惑，细究无疑。于是君以芩连、白芍平肝清火，臣以槟榔、厚朴下气宽中，佐以油归润肠，使以泽泻下行，三剂通利而全愈。盖此症极多，治不一法，倘大便旬日未解，及壮实之体，宜承气汤攻之，正所谓痛随利减，通则不痛之意也。", "8439": "傅妇，素属阴亏，常宜班龙丸。无病求诊，冀余写补剂，余曰：脉来弦紧而沉，有凝滞之状，腹中必有宿食，秋深恐成痢疾，目今调治，昔药非宜。况邪气久居肠胃，其脏气之虚实可知。但伏邪未溃，岂可暴攻，譬之贼兵方聚，未张其势，我等只宜先固城郭，以示其威，令其自散可耳。以四君子汤加枳壳。一剂服下，腹中略响，正邪气缓散之征，讵妇女辈，闻余言有滞积，竟私煎服浓姜茶二汤一碗。下咽之后，腹中绞痛难堪，下利数十行，头身大热，十指微冷，时值傍晚，急延余视。初不知其服姜茶汤也，谓曰：四君逐邪，果有如此之暴耶？因述所误，盖微积久伏，肠胃素薄可知，得此姜茶刮决之物，岂不大张其势？然至圊虽勤，所下甚少，余邪尚存未尽，而既已误治，惹动其，无如乘其元气未败，再与疏通，尽驱其邪。更以小剂行气之品一剂泻下，腹痛略减，但潮热指冷不除，次早复诊，问所下何物，视之，一团白沫，隐然秋深肠癖之征，此时人事困顿，脉仍弦紧，是知当理阳气，投建中汤，以大建中建立中气，弗投理中，以复削其阳气，与《金匮》小建中汤一剂，其症悉痊。愈后，余不禁自笑，盖初因未病，余为寻病治之；中因自误，余即以误治之法治之；末因脾阳衰弱，余全不以补药补之。见亦奇矣，而非见之奇，实见之先耳。", "8440": "吴鼎三，形禀木火之质，膏粱厚味，素亦不节，患胁痛冲脘之病，绵缠两载，痛时由左直上撞心，烦惋莫耐，痛久必呕稀涎数口，方渐安适。始则一日一发，继则一日数发，遂至神疲气怯，焦躁嘈杂，难以名状。医者不从正旁搜求，用控涎导痰诸方，治之毫不中窍，延磨岁月。迨至春升，一日痛呕倍甚，吐血两碗（红白相间，结成颗粒，是阳明离位之血留久而为瘀者，所当审辨也），神昏气涌，目瞪如毙，即进人参、当归二味，渐渐苏回。嗣后神容顿萎，杜门静坐，不乐对客交谈，而气上撞心，胸胀脘闷诸症，仍是一日一发，守不服药，以攻补两难，惟日进参汤而已。值余道经其门，邀人诊视，细询其由，始知原委。问曰：伤症乎？余曰：非也。曰：痨症乎？曰：非也。曰：非伤非痨，请先生明示何症。余曰：肝气病也。诊得脉来弦大（弦为肝强大，则病进），记读《灵枢》经脉篇云：足厥阴所生病者，胸满，呕逆。又仲景云：厥阴之为病，消渴，气上撞心，心中疼热，饥不欲食，故见嘈杂焦躁等症（窃意焦躁嘈杂即古人所谓烦宽懊𢙐之状）。知肝气横逆，郁火内燔，仿仲景治胸中懊𢙐例，用栀子淡豆豉汤，以泄郁火，参入叶天士宣络降气之法，以制肝逆，酌投数剂，诸症渐愈。", "8441": "傅瑞廷之女，年十龄，时值六月，发热口渴，小便淋秘，溺则号痛不已。延医以利水之药，渴热不减，而阴户肿胀，又以三黄散、马齿苋敷之，遂至溃烂不堪，臭秽之极。更延疡医，概以解毒之药，因而益剧，腿胯结核，稍欲解溺，则号痛日甚，畏解不解，而少腹胀满难当，内服外敷，百治不效。危急之间，请决死生，以余非外科也。余视斯症，内外脉色，悉皆火象，独唇舌不燥，尚有可疑。因思阴器属肝，此必湿热下陷，聚于肝经血分，故唇舌不显燥象，若湿热在于气分，则唇舌必燥也；故清利无效。但十龄稚女，冲任未通，亦无热入血室之症。因询食桃子颇多，盖未熟之桃，最能助肝燥血，热结肝经故耳。处龙胆泻肝汤，兼龙荟丸，大便下血一瓯，小便乃利，阴溃自愈。", "8442": "许静堂内人，年近六十，素多劳虑，患口疮唇裂，顶生痱疹，久服祛风清火药，渐至两颊满颐浮烂淋滴，愈治愈剧。时值寇氛，静堂商楚被劫，家计萧条，疡医亦束手辞之，始延余诊，决一逝期，非求治也。余视所患处悉白色，水液流注，并无秽脓，自口颊延及胸项，亦无漫肿，且喜脉象不大，肉食不呕，身亦凉，便亦利，因谓此症七恶不见，五善备陈，十分可治，但取效甚迟耳。其家甚喜，及见疏方，用薛氏加味归脾法，戚友皆蹙眉，诸郎君亦咸缄口，察其必不能用。姑与在庠季子论曰：尊堂颊项浮烂，孰不谓之毒火？夫火犹贼也，贼至则驱之固也。然有邪盛正虚之时，不但贼不受驱，且驱之而正反伤，此安民攻寇之法，即医家攻补兼行之法。况养正之法，可转为驱贼之方，当今之世，乘正之虚，寇盗蜂起，孰知乱世之寇匪，即治世之良民？古之良帅，奉行坚壁清野之法，以养正安民为怀，首逆潜消，而胁从归顺。通之于医，正所谓养正则邪自除，未有伐正而能保身者也。况《内经》原有少火壮火之分，后贤更详有形无形之辨，乌可混施而不讲乎？尊堂禀赋虚弱，素多劳虑，离宫自燃，心火外炎，此本身之元气外越，收之养之不暇，尚可视为毒火而清之驱之乎？考古明贤之论，谓无形之火，生生息息，窈窈冥冥，为先天之化，为后天之神，为死生之母，为玄牝之门，又岂于形迹所能摹拟者哉！夫形迹不能摹拟，则虽外显火象，不可断为真热，概行攻伐。然亦非谓无实火也，惟在察其真假耳，故曰有形之火不可纵，无形之火不可残。若能知火之邪正，而握其盈虚伸缩之权者，则神可全而病可却，是生道在我矣。试观疡科痈疽溃后，气血已耗，每以补药收功，如八珍、十全、养荣、归脾之法，历历不爽，此岂余之创见乎？季子长揖钦服，其昆季与戚友谓曰：此老用药似非，而所谈却是。命煎药当余面进，服后果安。余归时，嘱临夜再进一剂，旬日中，竟服二十剂，其烂始敛，服至五十剂其功始半，但苦流注不干，促余外药。疡科余素不娴，敷贴之方未备，姑与古矿灰敷之。转进十全、保元，间服而痊。季子感余再造，蒙赠诗联，余亦领笑曰：此秀才人情也。因忆向年朱叔岳母太夫人孀居有年，焦劳忧郁，虚火外炎，患口舌糜烂，日进清凉，虚火愈炽，复延外科包治，愈增糜烂，延及唇外。适余归里招视，其色甚白，脉息亦微，余谓并非外症，实皆心脾郁结，虚火烁金。夫心主血脉，脾主肌肉，肺主皮毛，故皆受累，急当调养气血，则虚火自藏，疏与归脾汤，兼进天王补心丹，嘱其多服。讵意只服数剂，余转浒湾，而前医复至，总认热毒攻注，谤余为火上添油，岳家无所依治，疡医日进丸药，外用膏丹，乃至牙宣颊裂，爪脱发落而逝。因思疡医之药，必是丹铅之毒，方有如此之酷，深堪悼惋。若知乱世之寇匪，即治世之良民，通于壮火食气，气食少火，壮火散气，少火生气之理，何至生灵荼毒，玉石俱焚耶？此余耿耿于衷，深为感悼，因并志之。", "8443": "记读《张氏医通》石顽曰：尝读《内经》，有脱营失精之病，方书罕言，近惟陈毓仁痈疽图形，仅见失营之名，究无方论主治，故粗工遇此，靡不妄言作名，为害不浅。夫脱营者，营气内夺，五志之火煎迫为患，所以动辄烦冤喘促，五火交煽于内，经久始发于外，发则坚硬如石。毓仁所谓初如痰核，久则渐大如石，破后无脓，惟流血水，乃百死一生之证，是以不立方论，良有以也。其形著也，或发膺乳腋胁，或发肘腕胫膝，各随阴阳偏阻，而瘕聚其处，久而不已。五气留连，病有所并，则上下连属如流注，然不可泥于毓仁之耳前后及颈间，方目之为失营也。以始发之时，不赤不痛，见证甚微，是以病者略不介意，逮至肿大硬痛，蟠根错节已极，岂待破后无脓方为百死一生之证哉？原夫脱营之病，靡不本之于郁，若郁于脏腑，则为噎膈等症，此不在脏腑，病从内生，与流注结核乳宕，同源异派。推其主治，在始萌可救之际，一以和营开结为务，而开结全赖胃气有权，方能运行药力。如益气养荣之制，专心久服，庶可望其向安；设以攻坚解毒清火消痰为事，必至肿破流水，津复外渗，至此日进参耆，徒资淋沥。其破败之状如榴子之裂于皮外，莲实之嵌于房中，与翻花疮形像无异，非若流注结核之溃后，尚可图治，亦不似失精之筋脉痿躄也。详脱营失精，经虽并举，而死生轻重悬殊。脱营由于尝贵后贱，虽不中邪，精华日脱，营既内亡，瘕复外聚，攻补皆为扼腕，良工无以易其情志也；失精由于先富后贫，虽不伤邪，身体日瘦，内虽气结，外无瘕聚，投剂略无妨碍，医师得以施其令泽也。然二者之病，总关情志，每每交加，而有同舟敌国，两难分解之势，故毓仁以失营二字括之。惜乎但启其端，而肯綮示人之术，则隐而不发，何怪粗工谬言为道，妄用砭石，宁免五过四失之咎欤！愚窃思石顽之论，足与是案互相发明，故并录之。男澍谨识。", "8444": "金绍裘内人，患两目红赤，畏日羞明，左眼尤甚。延目科医治，日进清火散寒，目愈难开，饮食日减，形体日瘦，始延余治。余于目科素所未娴，谛思经旨有云：五脏精华，皆上注于目，禀气于脾。合于色脉，当推中气久虚，五脏失禀，精不注目，虚火上炎。此内因之疾，既非发散可解，更非沉寒可清，当从甘温泻火之法，授以归脾汤，加柴胡、丹皮，十余剂，目赤渐退，光明如旧，且从此气充血盛，已怀孕矣。", "8445": "喻廷锦，能食而疲，时饥嘈杂，小便赤涩，胸膈间微若有痛。诸医咸谓消中，误认为火，连服生地、麦冬、芩连、知柏，数月不辍，遂至时欲得食，旋食旋饥，面黄形瘦，小水愈赤，有进竹叶石膏汤者，疑而未服。余诊得脉息属虚，曰：君几误死。能食而疲，此乃脾弱胃强，法当扶脾抑胃，奈何认为实火耶？其昆季咸知医理，群起而问曰：小便赤涩，岂非火乎？余曰：曷不闻经云：中气大虚，溲便为之变耶？且从来大小二便，岂定为虚实之确据耶？今诸君以便赤即认是火，则天下皆医矣。遂疏六君子吞左金丸，数日稍愈，后除左金，独用六君子汤，百余剂而安。", "8446": "聂义远之妻，病始畏寒发热，两足僵硬，微肿疼痛，步立不能，医者不知为脚气之病，误与发表，渐至气急上冲，腨皮红赤，热痛难耐。又疑为毒气所致，遂付疡科医治，而气冲热痛，愈觉不支。急迫之间，求治于余，诊得右脉洪而无力，左脉伏而不见，形羸唇白，声微舌润。询其体格，又属素虚，理直调补气血，但气冲，便秘，足腨红肿热痛之极，此属气实明征。且脚气古称壅疾，是又不可遽补，从此酌量先后缓急诸法，当先治其标，而后其本也。缘按症以气血虽虚，而经络必滞，宜先与疏通经络，而后调补气血，方为合法。于是将古方鸡鸣散除苏叶，恐再散也，加生耆，以固表也，入桑皮，以下气也，减桔梗，恐载浊也。面嘱只服一剂，次日当视症定方，服后大便亦通，肿痛少除，气冲大减，寒热悉瘥。其家见药已效，更进一剂，亦觉相安。越日疡医适至，意在侥图诈取，谬谓毒气未化，当用敷药，更仿余方加防己、苍术，内服外敷。是夜寒热顿起，汗出衣发俱湿，神魂飘荡，气上冲心。余复视时，张口瞑目，危险至极，急进十全大补汤，二剂始得稍安，又数十剂方全安。原此症《内经》所言因于气为肿，四维相代，阳气乃坏。只因气冲便秘，订一剂之方者，势不得已也。乃病家轻命图便，违嘱投药，而疡医复贪功射利，罔识忌讳。嗟嗟！此当世通弊，独聂氏哉？", "8447": "文定辉，病苦少腹胀满，肛门重坠，欲解不解，时下脓血，诸医咸称休息痢，百治不愈，淹缠半载，延余施治。视其神色不衰，少腹按之愈痛，所下或尽是白脓，然亦有时污血，诊脉举按皆滑，沉候略带微数。疏方与黄耆、防风、银花、山甲、丹皮、瓜蒌、连翘、白芷、甘草，一剂下白脓带黑污而出腥秽不堪者一勺，少腹始舒，后重乃除。再剂除瓜篓，加薏苡而痊。此肠痈之症，因用排脓之药也。", "8448": "孙康泰内人，产后一日，畏寒发热，恶露不下，满腹作胀，手不可按，二便俱闭，胸紧气迫。危急邀视，知为产后受寒所致，盖血得寒则凝泣而不行，非温不通，先与失笑散二钱，次进黑神散，重用姜桂，加漆渣、山楂，急煎与服。顷刻小水先利，污水随下，腹始稍宽，气始稍平。是晚再进一剂，大便甚通。次日泄泻不止，腹痛口渴，当斯时也，于泄宜补，于痛宜通，是通补两难立法。询知临产，食鸡汤过多，缘腹中所蓄瘀血，今得温通，腹中宣畅，恶露已从前阴而下，食滞又从后阴而出，津液暴失，宜乎口渴，然喜脉无洪大，神不昏迷，许以无忧。但身中之津液下泄，精气不腾之症，当从釜底暖蒸，庶几氤氲彻顶，疏与苓桂、骨脂、姜炭、木瓜、甘草，投之渴泻腹痛俱止。", "8449": "周秋帆茂才之内人，产后恶露甚少，腹大如箕，自言作胀，小水甚长，大便不通，俨似蓄血之症。但口虽渴，喜饮热渴，两尺脉亦软濡，可知血寒凝滞。投以黑神散不应，更医用大黄、红花、枳壳之药，腹胀愈甚，腹坚如石，再求余治，知为寒邪凝结，必当温通，连进附桂、干姜、归芍，似胀稍宽。叠投二日，已经四剂，而恶露不下，窃思舍此温通之法，决无破血可进，然非血行，胀何由消？考古治虚损吐血逐瘀之法，有花乳石散之例，能化瘀血为水，不动脏腑，可引以为用。遂煎米饮调服二钱，少顷腹中气响，前阴出秽水甚多，大便亦通，叠进前药，胀消一半。惟腹右稍坚，十指挛急，足亦时僵，此气血虚寒，今始大露，改进理阴煎，重加附子，诸症悉瘥，后进养荣汤数十剂，调理全安。", "8450": "周吉人先生内人，冬月产后，少腹绞痛，诸医称为儿枕之患，去瘀之药，屡投愈重，乃至手不可触，痛甚则呕，二便紧急，欲解不畅，且更牵引腰胁俱痛，势颇迫切。急延二医相商，咸议当用峻攻，庶几通则不痛。余曰：形羸气馁，何胜攻击？乃临产胎下，寒入阴中，攻触作痛，故亦拒按，与中寒腹痛无异。然表里俱虚，脉象浮大，法当托里散邪。但气短不续，表药既不可用，而腹痛拒按，补剂亦难遽投。仿仲景寒疝例，与当归生姜羊肉汤，因兼呕吐，略加陈皮、葱白，一服微汗而愈，得心应手之妙，不知其然而然者有矣。", "8451": "吴显余内人，小产后腹痛，夜热，咳嗽，医者作瘀血治之，遂尔腰屈不伸，痰多食减。又以理中、四物之属投之，致今夜热大作，少腹极痛，脉来迟紧带弦，因谓之曰：此中虚而血寒也。四物泥腻，非痰多食减者所宜，理中壅燥，岂夜热咳嗽者能任？遂疏黄耆建中汤，叠进而安。", "8452": "陈飞云学博之女，产后两月，忽然战栗，左胁微痛，胸中窒塞，屡进表散之剂，寒栗愈盛，呕吐清水。时值天气炎热，诸医莫辨虚实，招予视之。诊其面色，红中带青，脉象甚微，久按觉弦，细揣知为久寒在血。其左胁微痛，是肝气郁而不伸；肝挟相火，是以面色青红；木邪侮土，是以胸中窒塞，呕吐清水。因思厥阴中寒，相火内寄，非发表温经，病必不解。但发表宜兼养血，温经最忌助阳，宗仲景治厥阴久寒之例，与当归四逆加吴萸、生姜，药下立安。", "8453": "萧洪元室人，产后偶然寒热如疟，医以外感投五积散不效，洪元自知医理，又与黑神散不应。更医以为血虚，进八珍汤，是夜潮热烦躁，次早口干舌裂。又用归芍芩连，服后火势愈腾，唇口愈燥，咽喉窒痛，胸腹胀迫，燥渴异常，脉来洪数，按之亦皆鼓指，内外一占，严然大热之象。但临产艰难，神气固丧，且血下甚涌，阴营亦伤。思人身阴阳相抱，始得资生，今阴精内竭，孤阳外扰，若非滋液敛神之法，势必阴亡阳灭而已。因处大剂理阴煎，加附子、五味，另用龙眼二斤，熬汤搀服。服后寒战，重复不减，唇舌俱淡，乃阳微之状已彰，但明知产后血枯阴涸，且脉形未敛，尚不敢偏行辛温，确守前意，滋液敛神甘温到底而安。", "8454": "周捧书乃室，小产后数日恶露如崩，胸紧腹胀，气迫窒塞，怒目而视，人事大困，自言见鬼于前。余临其帷，犹用法师敕符喷水，燃火叫喊，余见之大为惊骇，盖知其心阳将脱也。急以耆术、鹿茸、姜炭、枣仁、五味、龙齿，约重斤余。捧兄以产后瘀血，且因天令亢热，疑不敢用，因面令煎服。进药时，神气愤乱，目已半合，身已将僵，余为惊怖，盖恐其药之不及也。亟为灌完，随合复煎一剂更服，毫不为动，于是又煎一剂，服之而神少醒，自云：身非己有，渺茫不知所从。盖神魂尚未归宅之验耳，更加五味一倍，又服一剂，是晚神魂略安，犹然时惊时惕，时恐时昏，不敢开目。次早脉犹未敛，按之豁大如空，下血痰少，仍与前方连进一剂，始敢开目，饮食大进，忽然肠中作痛，下血水，腥臭不堪，意者果有瘀乎！于是原方加泽兰、益母、生蒲黄、肉桂一剂，下出朽腐白肉一团。众妇不知何物，余曰：此双胎也。妇视之果然。痛始除，胀始消，随以归脾汤加鹿茸、姜炭、肉桂，连进十剂而健初视时，舌白胀满塞口，外以蒲黄、干姜末搽舌，遂缩如原。", "8455": "黄杏帘先生之媳，体气孱弱，素禀肝火，且针黹书画，日夕劳神，今秋产后，即下榻如常。因目中觉燥，自取旧方药只熟地、白芍二味，立时恶露顿止，目瞪反张，逾时方醒，醒而复发。昏夜邀视，合室惊惶，坐视片刻，连发二次，醒时忽言见鬼，一身战栗。余诊两脉，幸无洪大，知为神魂不藏。隔壁喊叫，闻之则发，探病客至，见之亦发，立时怒目上视，十指紧撮，牙关随闭，面若涂朱，汗出如雨。片时之久，稍呕微涎，人事复清，余坐二时之久，已发三次。家人咸称邪祟，又议恶露上攻，余曰：闻声则惊，见生人则惕，显属正气大伤，因生惧怯。且恶露虽止，腹无著痛，实因芍地酸寒凝滞之故，惟有收敛温通一法，尚何恶露可破，邪祟可驱哉？重用参归、姜桂、龙齿、五味、茯神、钩藤、龙眼，叠进不辍，其势渐缓，恶露随下而痊。或问曰：病因血止而变，今用补血而反通者何耶？答曰：《素问》病机篇云：血气者，喜温而恶寒，寒则凝而不流，温则消而去之耳。", "8456": "吴应新内人，产后寒热腹痛，诸医以芎归加入行瘀之药，两投愈痛，人事困顿。余以血虚腹痛，当温养血液，疏以理阴煎，畏而弗服。明是血虚发热，气虚生寒之症，误以时行疟症之治，以致大汗如洗，衣被皆透。举室慌乱，复延余至。原知产后津脱之症，未敢轻许可治，所喜脉无躁扰，神明未乱，亟以大剂人参养荣汤，叠进三剂，外以五倍末，津调敷脐，其汗稍收，而寒热乃除。惟腹痛既非瘀血，必是内寒无疑，但血去液伤，辛温难进，爰拟交骨未缝，寒入阴中，仿仲景产后腹中㽲痛属寒疝之例，与当归生姜羊肉汤，服下腹痛果除。后数日，又因换衣触寒，寒热复起，舌心灰黑，与理阴煎加附子一剂，寒热虽熄，而大汗仍来，重进养荣汤，三剂不应，外以荞麦粉扑之，汗亦不止。余甚踌躇，其家以为尸汗，咸称不治，余曰：药虽未效，症尚未变，且脉亦甚微，亦属吉象。仍将原订养荣汤，用五味子八钱，外以龙骨牡蛎粉扑之，其汗稍息。复将原方昼夜三剂，其汗始收，舌黑始退。自云：心多惊怖，犹是血去液伤。重进归脾养心，数十剂始健。", "8457": "吴鹤皋乃室，是临川陈祥光之女，产后两旬，忽然汗出二日，医治数日，身热烦扰，口干发渴。祥光因鉴媳妇之误命也，请诊而任其治焉。视其舌光如镜，边刺红燥，身热烙指，汗出黏手，口虽渴而热渴不畏，脉虽洪而重按无力，可知汗血同源，内液枯涸之故，非收神敛液，势必神丧而亡。急用黄耆、桑叶、麦冬、五味，四味同煎，不杂他味者，盖仿血生于气，水生于金之意也。直进十余剂而康。祥媳误案附虚寒门误表气脱。", "8458": "吴乐伦乃室，年近四旬，素患小产，每大便必在五更，服尽归脾、四神、理中之药，屡孕屡堕。今春复孕，大便仍在五更，诸医连进四神丸，不仅解未能移，并且沉困更甚。商治于余，诊毕，乐兄问曰：拙荆虚不受补，将如之何？余曰：此乃八脉失调，尾闾不禁，病在奇经，诸医丛事脏腑肠胃，药与病全无相涉。尝读《内经》骨空论曰：督脉者，起于少腹以下骨中央，女子入系庭孔。又曰：其脉循阴器，合纂间，绕纂后，别绕臀。由是观之，督脉原司前后二阴，尊阃督脉失权，不司约束，故前堕胎而后晨泻也。又冲为血海，任主胞治，治之之法，惟有班龙顶上珠，能补玉堂关下穴。但久病肠滑，恐难以尽其神化，当兼遵下焦有病人难会，须用余粮赤石脂。如斯处治，丝毫无爽，五更之泄，今已移矣，十月之胎，今已保矣。《内经》一书，可不读乎？", "8459": "按：四神丸原为五更火衰泄泻而设，今施于下虚关滑，宜乎不中肯綮。矧五更为诸阳之会，八脉之聚，非专固奇经，乌乎有济？而余粮、石脂二物，人皆泥为重坠伤胎，今反不然者，《内经》所谓有故无殒，亦无殒也。男澍谨识。", "8460": "桂煜堂内人，因取乳服药，患阴菌下坠，足腹肿满。又误治半载，忽变口噤舌缩。诸医无从措手，延余诊脉，六部按之全无，似属不治，盖心主血脉，舌为心苗，有内外交绝之象。然呼吸调匀，神明未乱，面无杂色，均非死候。因原其始而求其理，妇人两乳，乃冲任所关，故乳汁与月水相应，误投下乳之药，冲任大伤，以致子宫脱出。又因误治，肾气散越而为肿满。按少阴肾脏，位虽居下，然其脉常萦舌本，今气已坠散，脉道不能上朝，故脉不至而舌本不能萦也。此际收摄之法，有断然必用者矣，遂处大剂养荣人参汤，重加鹿茸、艾叶，频进旬日，新旧诸恙，统获痊安。噫！医可不求其理哉。", "8461": "丁桂兰内人，年近五十，得崩漏之病，始则白带淫溢，继则经行不止，甚则红白黄黑各色注下，绵绵不绝。迁延五载，肌肤干瘦，面浮跗肿，胸胁作胀，谷食难进，所下已有腥秽，自分必死，所喜脉无弦大，可进补剂。然阅前方十全、归脾之药，毫无一效，窃思妇人久崩，调补气血不应，必是冲脉损伤。考《内经》逆顺篇，以冲称血海。又为五脏六腑之海，又云：冲脉起于胞中，而胞中原属命门。因推人身自头至足，腹前背后，无不禀承于命门，以海为百脉之宗，经络发源之地。然非独血海为然也，即气海、髓海、水谷之海，亦皆禀承于命门，与人身气血之盛衰，大有关系。再考《内经》于胸胁支满，妨于食，时时前后血，必因少时有所大脱血，或醉入房，气竭肝伤，此症虽非醉犯房劳，必当年产后胞户未扃，房室不慎，损伤冲脉可知。夫冲既不蓄，则诸脉皆废不用，有职无权，由是任脉不为之承任，带脉不为之带束，督脉不为之统督，阴阳跷维不为之拥护，故身中之精华，散漫无统，无所禀承，不及变化，所以诸般颜色之物，注于冲路而下，譬之漏卮不竭不已也。所服参耆归术，计非不善，但甘温守补，岂能趋入奇经？仿《内经》血枯血脱方法，特制乌鲗丸，义取咸味就下，通以济涩，更以秽浊气味为之引导，参入填下之品，立成一方，似于奇经八脉，毫无遗义。且令其买闽产墨鱼，间日煮服，亦是同气相求之意。如此调理两月，按日不辍，五载痼疾，一方告痊。后黄鼎翁之内悉同此症，但多有少腹下坠，未劳思索，迳取前方加黄耆而痊。", "8462": "丸以雀卵，大如小豆，以五丸为饭后饮以鲍鱼汁，利肠中及伤肝也。窃忆《内经》之方不多见，除此方外，惟有治心腹满，旦食则不能暮食，名曰鼓胀之鸡矢醴。一剂知，二剂已，其方用羯鸡矢干者八合，炒香，以无灰酒三碗煎至一合，滤汁，五更热饮则腹鸣，辰巳时行黑水二三次，次日觉足面渐有皱纹，又饮一次，渐皱至膝上则愈，及阳气盛，阳跷之脉不得入于阴，阴虚故目不瞑之半夏汤。以千里长流水扬万遍，取五升，半夏五合，煮为升半，饮一小杯稍益以知为度，复杯则卧，汗出则已而已一剂知，谓药病相知，犹言药与病合，二剂已，谓病已除也。男澍谨识。", "8463": "傅补轩内人，产后匝月，忽患四肢僵痹，呼号鬼神，众惊以为邪祟，祷之不灵，召余往诊。脉得右大左伏，面青唇白，舌苔边白中黑，兼之久未更衣，小便短少。按：此症舌心滞黑，便闭溺短，当推实热例治。然无口渴痞满之患，舌黑而滑，四肢僵冷，当推虚寒例治。而脉候又非微细迟弱，复于色窍细审，面青目瞪，似属肝邪为患居多。且左脉隐伏，应有绸缪郁结之情，原肝为刚脏，体阴而用阳，魂被火迫外游，故探病客来，未至先知（虚症亦有，肝不藏魂，能知宅外之事，而妇人产后血虚，尤多此证，宜养荣汤之类者。）况肝主筋，热盛筋急，故目瞪上视，四肢僵痹也。又肝主疏泄，脏病联腑，故便闭不通也。此则肝气愤郁，足为明征。补轩与余素契，执前医方来阅，皆参甘归杞守补之味，大概泥于左脉不见，惑于丹溪产后当补气血一语，似于凭症审视之道尚未尽善。补轩信余甚笃，并述右乳肿痛，已经数日。原乳房属阳明，乳旁属厥阴，经曰：营气不从，逆于肉里，乃生痈肿，故见症于阳明厥阴之部分。又肝之为病，足为明验。直疏以逍遥散合龙荟丸，进退酌用。是夜连进二剂，谵语肢痹俱止，惟于天晓时前症欲萌，旋尔又止，是得前方叠进之力。设认症不确，小剂暂试，势必病重药轻，前症复萌，定归咎于药之不当，又作更方之想，则失之远矣。其前症欲萌于天明时者，乃肝木旺于寅卯故也。后又将原方加疏肝导气一剂，诸症潜消，视其乳房，果红肿迸迫，欲作脓溃之势，继将原方加公英、香附、白芷，托里排脓，果得出脓一碗，肿痛悉瘥。只经数日，尚未更衣，渠母促用通剂，余以下不嫌迟，遵王道之治立方，用五仁以代通幽，连进数日，大便渐通，未症亦渐以除，未费调补而安。此虽余临症审治之不差，实补轩信余之不差也。倘补轩任前医参甘稳当之方，势必肝气愈结，四肢渐变厥逆，指甲皆青，神识愈见昏愦，舌卷乳缩有之。而参附姜桂，又安能禁之不用？值此错乱纷更，则余亦无所适从矣。", "8464": "郭大兴之子，因食桃李甚多，腹痛口渴，四肢厥冷，泄泻半日，饮水即吐，以后大便不通，人事虽困。然吐声甚洪，痛声甚厉，舌虽不燥，而唇极焦。一医不明先泄后闭之义，更不细审内伏之情，且不知沉涩之脉，妄谓无脉，迫以附子理中急投，余见而止之，与左金合四逆散，加元明粉五钱，下秽物甚多而痊。盖桃李生硬难化之物，最能助肝犯土，阻格中焦，以致胃气抑遏，故腹痛而厥，乃阳不能舒布之象。起先腹痛下利，不过热结旁流之泄，究竟燥结未下，故虽利而痛不减，后因水入即吐，肠中槁而无下利矣。古云：食不得入，是有火也。且因吐泻甚频，舌虽不燥，而唇已焦，势虽笃而声甚厉，种种明证，如宝炬当空，幽怪悉显，奈何其医匆匆不察，遂有毫厘千里之差。古谓医者意也，如操舟之工，如对敌之将，其可不尽心乎？", "8465": "吴启明之子，甫及周岁，发热呕吐，泄泻迸迫，烦躁不能少睡，大渴饮水不休，医者误为脾胃不足之呕，虚阳发外之热，津液下陷之渴，与七味白术散。一服，遂至两目上吊，角弓反张，肢体痉强，牙紧气促，唇口齿舌干燥而不可解。余知此症，乃疫邪传胃，未经清解，以致协热下利，直以葛根黄芩黄连汤，一服病气大退，再以小柴胡汤去半夏，加花粉，二剂而安。盖哑科之病，人皆详其外而略其内，所以头疼身痛，胸中膨满，小腹涩痛，大便热泄，人所不知，而医者又不详为谛审，徒执白术散为渴泻圣药一语，致令疫邪愈炽，熇热偏强。小儿筋骨柔脆，极为难耐，欲其不筋脉牵引变为痉症，其可得乎？余因解肌清热，将表里两症，外内合邪，一同并解。记此一案，不仅协热下利之绳墨，尤为幼科疫疾之鼓钟矣此症著眼处全在泄泻迸迫，唇口齿舌干燥而不可解上谛审。", "8466": "王志耕乃郎半岁，夜半腹痛，啼哭不已，以热手重按其腹，似觉哭声稍可，久以仍否。延诸幼科，无非行气消食，误治两日，目珠上瞪，四肢微搐。余视其面色赤中带青，目中白珠颇蓝，手足指尖略厥，小水直无，指纹透甲。危急之顷，静神默悟，详推此症，原是寒邪入里，与方脉寒症无异，意拟姜桂通阳。然细察面色唇舌二便，又非无阳可比，倘辛热误用，而稚阳之质势必血燥津涸，愈增筋掣瘛疭。因思肝藏血，寒伤营，非养血通脉，寒可由解，痛何以除？先以灯火焠腹，疏通凝寒，以仲景厥阴篇当归四逆汤，一剂霍然。", "8467": "杨协胜之女，寒热咳嗽，腹痛泄泻，医者未知痛一阵泻一阵属火之例，木强反克之理，妄用消耗之剂，渐至面浮气促，食减羸瘦。又误用耆术之药，潮热愈重，痛泄愈多，延绵两月，众谓童痨难治，乞余诊之。先与戊己丸作汤，二剂痛泄顿止，继以泻白散合生脉汤，二剂潮嗽皆安。", "8468": "生脉散方见卷二虚寒门误表戴阳。", "8469": "附脾胃困惫久隆见余治效之速，始投余治，抱出一视，大为惊骇，面现五色，惟目中神彩尚存，生机只在于此。谓曰：此症全因克伐，过伤脾胃，中土困惫。其唇红口圈青黑者，即脾胃败也。鼻准黄而两颧独白者，肺气败也。败症丛生，本属不治，幸得五色之中，尚有润泽，真脏尚未枯槁，兼之目中精光了然，虽有呕吐，犹时可纳粥，即有泄泻，尚未至于鸡口牛后，通盘揆之，犹在方败未绝之界，所以许为可治。但非参术叠进，固不能起。久隆问曰：昨舍侄之病，苦干烦渴吐泻，小水不通，而先生乃用栀子、黄连凉之。今小儿之症，历历皆然，而先生乃称重用参术者，何相反若是？曰：令侄之病，全因胃中伏火，势如燔燎，焰扰诸经，为之挥霍撩乱，故用苦寒之药，直清其肠胃之火，使由小便而出，而诸经自安，是以烦渴吐泻立止。今令郎之症，相隔天渊，先天之体质不足，后天之脾胃更虚，乃因饥饱乳食致伤，复因药饵攻伐，是虚上加虚矣。脾胃一虚，便失其传运之职，关门失禁，所入水谷，迸走肛门而出，遂使津液下陷，不能上升，所以口干烦渴。脾失传运，肺亦言伤，失其治节下输之道，而小水无矣。此与虚阳发外之症，同类并称。值此之际，亟宜大固中州，兼以保肺生津，庶中土安而诸经健运有常，此必然之理也。倘误认为火，妄用苦寒，定然神机寂灭，成慢脾厥逆不治之症。渠竟不信，遂曰：姑看晚间何如，明早再请先生可也。余曰：医有好生之心，吾不忍其觳觫，疏与四君子加附子，合生脉散一方，并嘱勿复疑迟。及余回寓，旋延二医，或曰寒，或曰火，商进一派辛散寒凉之药，至以参术为不可服，同声而和之。迨鸡鸣阴阳交界之时果变厥逆，至黎明木旺之时，中土告尽木克土也，忽变角弓反张而殒。姑笔之，以为择医者戒。", "8470": "王启元之子，夏月烦渴吐泻，唇红舌赤，尿短烦躁。启元自知医理，疏就香薷、扁豆、车前、滑石、黄连一方，未服，商治于余。视其面白神慢，气急多痰，脉息微细，显系脾虚，非暑热之燥。谓曰：分利止泄，解暑除烦，固医门之法则也，然必因人而授，因证而施。今苗窍脉色，脾胃大虚，与此法全不相涉。斯疾唇红舌赤者，津液由吐而上亏也。尿短烦渴者，津液由泄而下亏也。与七味白术散二剂，烦渴略，减再进六神散加枸杞，十余剂而安。凡泄泻脾阴亏者，当仿此，若脾阳亏者，六神加干姜，为至稳之法，用者详之。", "8471": "聂秀章之子，三岁尚不能行，皆由体禀素弱。时值长夏，患烦渴吐泻之症，医者不究其脾胃之虚，执用外感之治，误投知连陈半之属，延经十日，愈治愈危，商请于余。冒暑视之，神已大败，呼吸将绝，视其眼生翳膜，肌肤削极，吐泻交作脾胃败也，小水赤涩泄多亡阴也，口中时渴津液亏也，声微息促气不相接也，昏睡露睛脾败不能合也，四肢厥逆阳气竭绝也，手足微搐，喉内痰鸣枯延无统也，脑后腹上发热虚阳外越也，通计诸状，皆由脾肾两败，真脾慢风症。然喜尚能饮乳不辍，但不能久乳因其虚而乏力之故，众曰此症患者皆死，何治之有？余亦蹙额踌躇，然慢惊之证，固由脾肾之虚，至古人所制金石脑射之方，后贤已辟其谬，今极重之症，非取后贤所选理中、六君之药，大剂急投，鲜克有济。遂将古方十全、理中、六君、胃关之意，加入驱风之品，酌为一方，每剂十两之重，每日夜令进三剂，缓缓与服，如灌溉之法，欲其周身空虚之地，无处不到。每药嘱其戚人聂方兄督进，毋令稍减。如此三日，败症稍回，神已渐醒。四日内，白珠赤脉贯眼，口舌糜烂，白垢满布，状似积粉，如月内小儿鹅口之形，众嗟热药之误，急欲更医，聂方兄委曲周旋，邀余再视。众持改用凉药之见，余曰：服补剂而眼红口烂，不但世俗谓之燥，即医者亦多谓之燥矣。殊不知虚火上冲，阳气将回，游移不定，扰攘于外，尚未归宅，斯正岐伯先师所称阴病见阳者生，正属可喜。此时若改用凉药，势此前功悉废。遂将开水拭去口中白垢，仍令原方加熟地三钱，以和其阴，再进，日夜三剂。次早视之，口中润滑，眼内俱清，遂减一剂，每日令服二剂，逐日渐愈。不一月，前后共计药三十斤，肌肉充盛，遂能趋步行走，众始钦服。然余尝叹小儿之死于慢惊者，多由于此，即如此证，设认定其虚，或知其用药而不能以重剂多剂救之，是为病重药轻，延绵复死。即进此方后，多有阳回而现阳证者，咸疑为热，稍无定见，每多意乱心迷，乃至大变其法，改用凉剂，无不立毙。余每于斯证临治之时，苦心体察，深恨世医所治小儿吐泻之证，无分寒热虚实，端守辛散清凉之药，实者侥幸得功，虚者脾肾两败，露睛厥逆，吐舌抽搐，遂曰惊风。复不分急慢虚实等情，更以凉散香疏汤药丸散灯火杂投，以致二便不禁，四肢冰冷，五脏竭绝而死。至死不明其故，良可悲也。近时人体禀气浇薄，夏月极多此症，堪为痛心。是以愈加精研，博览古训，参以拙见，似有寸长，久欲与同道勘破，恐管窥之见，有不尽然，近年阅历稍深，凡治慢惊悉用此法，屡验不爽，敢望同志之士，共明夏月伏阴在内之理，当先顾脾胃为主，后察其六淫兼证，战战兢兢，毋伤其正，庶几得焉。因名其方曰大回生汤。", "8472": "傅锦翁乃孙，端阳后，时忽吐乳，未曾介意，二十日外，其吐愈多，一幼科用藿香正气散一剂，开肠洞泄，大热发渴。延余视之，面色浮白，两目无神，虽吐次多，而无秽气，泄泻频而澄彻清冷，唇虽燥而无绉纹，热虽重而指尖冷，口虽干而热汤不畏，诊得脉息沉微，最防慢脾，遂疏理中附子丁香一方。服后诸症渐减，但有微渴微烦未除，更用七味白术散一方，嘱进数剂，勿图速效，俟其清阳升而渴可止，脾阳健而热自除。适余他往，只服二剂，更医大罪吾药，用柴胡、知母、乌梅、花粉、藿香，半夏之属，连服数剂，人事默默，干呕身冷，医者病家，咸以安静为功。偶于途间遇余述及，余曰：尔以默默为快耶？岂不闻人事不醒，神识昏迷为重乎！尔以呕吐无物为快耶？岂不闻呕吐有物为轻，哕无胃气为重乎！尔以身冷无热为快耶？岂不闻身温为和，肢冷厥逆为重乎！此虚风内养，脾慢之证已显危候。言未毕，其家端人来报云：此儿手足牵动，睡则露睛，喉中痰鸣。复延余视之，昏迷不醒，掏之不哭，睡不交睫，翳膜遮睛，二便长流，四肢厥冷，时忽抽搐，喉如曳锯，内外一探，阳气竭绝。因其无阳，药可偏恃，但救危须在顷刻，药饵一时难回，令研胡椒五钱，津唾调敷于脐，立时身动，似觉微烦，口中闻有椒气，哭声渐出。随调扶阳丹一两，徐徐灌下，大呕一声，胶痰旋出，随吐随灌，随灌随吐，约吐胶痰半碗，其色青碧，系由无阳，津液冷凝所致。随进大回生汤一剂，计十两之重，每日夜三剂，连服二三日，败证皆回。尤有奇者，不过一周之儿，服乳后自能以手探吐，余甚讶之。但胃中全赖乳食充养，因束缚其手，仍以回生汤加赭石，以安其胃。前后共服回生汤五十剂，厥病方瘳。愈后专理脾阳，两旬而健。", "8473": "附：陈蕃宗之子，烦渴吐泻，医治两日，延余诊治，视其眼沉囟陷，面色青黄，唇深红如艳朱，舌深红而干刺，脉得急数无伦，睡时烦扰，此胃败津伤，五脏精华尽发于外，中无所蓄，乃阴阳两竭之候，诚为死证。救阴碍阳，救阳碍阴，两不能受，直辞无治，随延别医，是夜果卒。然此症倘遇相信之士，竭力挽救以尽人工，当用理中、附子、猪胆汁，从阳引阴，从阴引阳，及胃关、理阴二煎，阴阳两救之法，或可回生于万一也。", "8474": "林寿之子三岁，脾胃素亏，今夏发热口渴，医者不知其脾虚发热，误用外感之药，其热愈盛，其渴愈加，小便甚多，大便甚艰。更医又不究其津液前阴已泄，致后阴津枯便艰之理，误投破气润肠之药，陡泄数次，肌肉消瘦，面唇俱白，舌光如镜，饮水无度，小便不禁，饮一溲二，喜食酸咸之物。亟求余视，谓曰：此消渴之候，遍身肌肉血脉津液，皆从二便消泄而上愈渴，若不治其消，何以止其渴？且败证种种，阴阳两损，前贤已无治法，愚何敢任？所喜两目精彩尚存，声音犹响，生机或在于此。但未审能舍此三分之命，服吾十分之药否？曰：无不信从。遂酌裁一方，阴阳两补之意，加以涩精秘气之药，连服三十剂而愈。以后连遇数症，消渴泄泻，诸医执用滋火之方，一经余治，悉用此法，加减出入，皆获全愈。以龙眼莲子汤代茶。", "8475": "陈庶凡之子，素禀木火阴亏体质，及周时当季夏，每多夜啼，渐至口糜舌烂，唇红齿燥，面白颊赤，小便赤短，时忽惊叫，微有搐掣，用尽石膏竹叶芩连木通之药，苦寒叠进，其火愈盛。前医束手辞去，庶凡来寓请救。余视之，果属火症，并无他岐，前医之药，种种皆是。然凉之不效，乃太仆所谓大热而甚，寒之不寒，是无水也，当滋其肾。况此儿阴亏之质，纯阳之姿，内火发外之症，岂六淫外入之疾者比。以六味地黄汤，生脉散，数服而安。", "8476": "门人问曰：昨视一小儿起自烦渴吐泻，他医误认为火，妄用芩连栀子之药，已服两剂，其泄稍止。更加厥逆昏睡，脉得沉涩，面唇俱白，明是无火之症。投附桂理中，下咽反大泻如倾不止即毙。岂苗窍脉息，不足以为据耶？答曰：连服寒药，其泄既减，若果热症，自当人事清爽，安得厥逆昏睡耶？明是阳气竭绝。由此可明寒药太过，窒塞中焦，所进寒药，未能转输，如天寒地冻，水不流行。今骤进热药，阳气通行，如开冰解冻，决江疏河，促之而下。奈气已先亏，不能上吸，宁不随泻而下脱乎？此寒则凝，热则流，乃医门之要义也。", "8477": "映庐夫子，珩姨表叔父也。珩兄弟九，衍行二，先父特钟爱。知夫子精医理，俾珩受业门下。其时夫子季弟启明者，与珩同笔砚，读《灵枢经》，夜辄数十行，夫子亦深夜督课，不间寒暑。珩羡启叔之敏而感夫子之勤，益奋力于经旨，恒偕启叔挑灯彻晓，夫子为之叹甚。亡何，启叔体弱肝强，因劳致疾，遂以不起。夫子大恸曰：是天丧予也。自是珩独侍门下，阅三十余载。有延珩治病者，夫子示曰：病欲十全，入门只先求无过，肱当三折，斯时莫道学有功。呜呼，斯语也，岂独珩当永志哉！间尝观夫子临症，始或蹙额，继乃舒颜，其慎重为何如也。迨道光辛卯，始有《得心集》之著，每一临症，必书之册，置诸箧中，不下盈千累万。咸丰丁巳，惨遭兵燹，夫子悲愤弃世，集亦散佚过半。大嗣君时若专举子业，惟三嗣君杏园，侍学有年，克承先业，惧夫子著述湮没，爰与珩及同门绍基汇集抄出，取其已效于世堪为准绳者，编成六卷，并附杏园《一得集》数十余案于后。我夫子失之弟而得之子，天何尝丧夫子哉！珩既沐夫子训迪深恩，又忝襄校之末，敢附数语以志渊源一脉耳。", "8478": "阅病源诊脉，是肝肾精血暗亏，由至阴伤及阳明之脉，身半以上，渐致拘束，此非外来客邪也。", "8479": "劳伤肝肾，奇脉不用，遇烦必腰痛背垂，虽有失血，未可沉阴滋降，以柔剂温通补下，以充奇脉。", "8480": "接案中年，夏秋失血再发，劳烦内伤，背痛腰板，肝肾下亏，跷维奇脉，不主用事，子后汗出，阴阳发泄。是包举温养勿迟，苟不安逸，药必无功。", "8481": "早食颇安，晚食不化，脉左弱细，右尺中虚动。是脾肾两虚，自阴伤及阳，以阴药中佐以温煦，以坎水中真阳内崇也。", "8482": "初春脉动而不鼓，亦收藏之司浅矣。当壮年未育，晨吐咸痰，皆水亏火炎，精气不充之象，胃旺能纳谷，当专理下焦，不必以痰为虑。", "8483": "少年奔走劳动，动则阳升，阳气不主内守，咳非外感，岂必肺伤，必情志未坚，龙相内灼，冲阳上举致咳。知见咳治肺，非辛解，即寒凉，治不中病，徒耗胃口，食减，其病日凶。病人自述，自腰以下，筋脉不束，竟夜不寐，晨必咳呕。中下损极，显然明白。", "8484": "中年脉细便燥，五液不充，即是阴亏，长夏失血，交秋再发，食减什三，为下损及胃，劳怯难愈之症。用药不宜偏寒偏热，但主养精血有情，勿损胃口者。", "8485": "脉小数，是精血内损成劳，阴虚生内热，久而不复，阳气不伤，夜不成寐，以包固大气。", "8486": "形瘦脉虚，左部空大，嗽病三年，行走气喘，据述从脐下气冲，必咳甚而呕。经言久咳不已，则三焦受之。乃他处累及，非治肺矣。思下之任脉失任，冲阳由胃及上，犯肺致咳，须固下摄纳滋养，肾病在下，必先形容憔悴者此也。", "8487": "脉细小，色白食少，不易运，形容入夏更瘦，不独精血不充，气弱易泄，不耐烦劳。此脏阴腑阳交损，补三阴为是。", "8488": "病是老劳，不肯充复，入夏时令热燥，气泄形肉日瘦，行动气喘，纳食日少，平昔喜用冷食，只宜用生脉四君子。", "8489": "面色青黄，脉垂入尺，吸气短促如喘，身热尤甚。此皆精血下夺，气不归元，肝肾损极不复。虽填精充髓，病深未必能效。", "8490": "脉下垂右大，深春失血，入秋半不复，饮食仍纳，无以充长精神。由精血久损，肝肾不纳，行动则喘，语言气怯，著枕冲气上逆，咳呛。皆损及八脉，不易治之症。", "8491": "脉数虚右大，入夏咳嗽失血，遂饮食顿减。此属劳伤内因，以养胃阴甘药，乃土旺金生之义。", "8492": "自正月间吐血，至今形瘦气短，身动尤甚，饮食仍用，大便溏，著枕卧息不安，欲得坐起。此下焦冲脉之气冲上，遂令喘咳不已，痰系脂液所化，吐咯永不清爽，下损劳怯症，最不易治。", "8493": "壮年脉形数垂入尺，痰多曾嗽血，冬底盗汗。显然真阴不旺，精血雄充，若不加保养，久延成怯。", "8494": "少壮脉小数，垂尺及泽穴，男子精血不肯充旺，情萌内震，阴火即动。此失血咳嗽，外寒内热，非外来客病，自能保养，不致成怯。用药不过治偏，无关于生长身中之精气。", "8495": "复脉汤去参桂姜加入北沙参甘蔗浆病乃阴伤，已及阳分，形羸背寒，河车丸包举填精，究属浊阴之药，必兼建立中阳，以崇生气。若医咳治血滋阴，必然败坏决裂。", "8496": "血后咳嗽食减，子后汗泄，虚损虽自下起，验诸色脉，扶中更要理嗽，清凉愈治愈凶。", "8497": "诊左脉浮弦，右大而缓，视面色痿黄，肤乏淖泽。据述泻血已二十年，频用清凉止血，血仍不止，食减神困，改进参术甘温有效。此乃救前药之谬，未明病机所由来。夫积劳者令阳伤，金匮云：脉大为劳，虚极者亦为劳。圣人明示大而劳者，宜理阳虚，而劳之必宜理阴。自血去太过，自述大腿跳跃，按之不息。肾液肝血，无以养骨营筋，内风翔动，致奇脉跷维，全不司其约束。腑阳脏阴，奇脉交损，中年以后，最难充复，日就衰惫宜矣。论久病内伤，必究寝食，今食少艰运，寐少寤多，莫言治病，当固护二气之衰，再参天运地气之胜复，斯身中阴阳消长，必有合也。", "8498": "附方北沙参固本加阿胶，又加芡实、山药、茯神、莲肉生脉合六味去丹泽加女贞、芡实都气汤加青铅固本加茯神、芡实、阿胶、五味、莲肉、龟版、人参须八珍汤料为末加河车胶和丸", "8499": "形瘦脉细色夺，下焦气冲心，痛咳甚。此肝肾精血内亏，冲脉之气逆上所致。此治肺清润无益，乃内损之症，最不易治。", "8500": "诊脉左部弦大，若有锋锐，右脉如数，按之虚濡。述上秋失血，夏季再发，交秋咳嗽甚，必食谷哕呕而出。凡人身左升主肝，右升主肺，左升太过，必右降不及，木反刑金，气不肃化而咳，咳甚而呕。况冲年阴火易动，龙相交炽，胃少宁静。越人有下损及胃之文，此皆内动精气之恙。苟非屏绝欲念怒劳，徒以药饵为治，草木无情之物，不能充精益髓耳。", "8501": "脉右弦大数，左小数，据述操持过烦，遂咳嗽失血，血止半年不复，肌瘦色夺，身动喘促，鼻息有音，咽喉乍痛乍缓，显然精血枯痿，下焦元海，乏收摄之权，阴不上承，但有冲脉浮阳升举，有升无降，无秋收冬藏之应乎天地。故清凉润肺，无济乎喘咳诸症，皆由根本下怯，子令母虚。此谓内损，草木藉其偏胜攻邪，精血有情，药味未能充长。故吃药无功，惟潜心屏俗，静处山林，寒暑一更，凝然不动，间有病痊者。", "8502": "色㿠白，脉小不食不饥，便溏不爽，久坐脊骨痛软，行动如喘。此精气内夺，失血内损未复，更加时疟再伤，涎沫涌吐，五液所化，非阴腻之药所宜用。", "8503": "夏至阴气不生，乃损不能复矣。今当大热，气泄愈甚，百脉诸气皆空，脂液尽耗，难更苏。为寒为热，无非阴阳互乘。阳由阴上越，则头巅痛，风木之火入中，则呕逆咳呛。总之液涸神竭，进两仪琼玉，扶至稍凉，再为酌量。", "8504": "脉左数甚，夏季嗽血，入冬声嘶喉痛，阴损成劳，药不易治。", "8505": "脉细促数，是肾精肝血内耗，咳嗽必呕吐清涎浊沫。此冲脉逆气，自下泛上，气不收纳，喘而汗出，根本先拨，药难奏功。医执见血为热，见嗽治肺，是速其凶矣。", "8506": "向有失血阴虚，春夏又病时气，秋咳呛，舌根白胎，形质软弱。以热伤津液，治用复脉法。", "8507": "劳损夜热咳甚，皆阳亏无以摄伏阳气，冲脉皆冲上扰为嗽。若以清肺治嗽，嗽必不愈，必致胃伤废食矣。", "8508": "脉数形瘦，久嗽不止。", "8509": "色苍脉数，嗽已半年，纳食不多，姑以甘凉润剂，不得犯胃。", "8510": "失血后咳呛不已，行走气喘，心热脉细数促。此下焦肝肾精血伤损，阳浮上炽为咳，故清肺寒凉则谬。", "8511": "复脉汤中去人参。", "8512": "脉左数，咳必下气上冲，此为阴亏，乃怯症之根萌也。", "8513": "复脉去参姜桂。", "8514": "右脉虚大，色夺形瘦，肌燥疮痍，咳嗽经年，曾经失血，是津亏气馁，由精劳内损，但理胃阴，不必治咳。", "8515": "脉数虚右大，久嗽咽喉痛，足冷，是虚阳气浮越，引导不应，曾服八味丸。", "8516": "诊脉左部平和，右关弦大带滑，此失血并非虚损，问胸脘不爽，是阳明胃气不和，气逆则扰动血络。只宜暂戒酒肉辛辣，胃和即愈，不须介怀。", "8517": "脉细呛血，病从下焦，气冲根怯，宜戒酒色，妥守百日可旺。", "8518": "脉小弦虚，久嗽，失血盈碗，血止仍然纳食，晨起顿嗽甚。此劳伤嗽血，宜养胃阴，治肺无用。", "8519": "脉左如刃锋，多呛，夜少熟寐，呛甚必血溢。此冲脉中阳升，乃下元精血不足。法当滋填实下元，若但寒凉清热，必致胃减，便难调治。", "8520": "脉左空右濡，右胁先痛，继以呛痰血块。此肝胃络伤，都因情怀不舒之郁，形瘦食减，甘缓主治。", "8521": "形瘦脉数，长夏见血，入秋发疟，皆阴分不足，不耐时候热蒸发泄。趁此胃口颇旺，只要静心保养百日，不及一年，可复。", "8522": "少年脉数形瘦，是先天遗热，真阴难旺，衄血上溢，阴亏无以制阳，疟热再伤其阴，血来更频，延及损怯。当以静药补阴，不必苦寒伤胃。", "8523": "形充脉小，痰嗽带血，此非阴虚火升，乃辛燥劫动胃络。只宜薄味清养胃阴，戒酒肉烦劳可安。", "8524": "脉左数大而坚，用力致伤，气升血上，静坐安养，百日可安，用养肝阴和胃阳方。", "8525": "诵读心烦，阳易动，阴不能守，血随气升，所喜胃旺，苟能安闲保养，经年不发。其脉络日固，药以壮水制火为主。", "8526": "劳力络动失血，脉大寸搏，能食咳呛，用甘药养肺胃之阴。", "8527": "脉数失血，不咳面槁，勿进阴药。", "8528": "嗜酒沉湎，胃虚络热，加以烦恼易怒，肝胆气火易炽，纳食味不甘美，脘闷常有嗳气，肝阳犯胃，血必带痰而出。从来酒客喜食爽口之物，不用滞腻甜食，脉大为阳气上逆，滋阴如地黄于肉，皆与体质不相投矣。", "8529": "久咳失血，食少便溏，脉来虚小。当以后天脾胃为要，清气滋水，为第二义也。", "8530": "失血后卧著呛甚欲坐，不饥勉强纳食，脉细促，两足皆冷。此元海气乏不纳，冲脉之气逆冲，虚怯门常有，最不易治。", "8531": "脉左细数，右关弦大，失血两三年，咳嗽不已，行动气塞，腰膝酸软，显然下焦不主收纳，是精血内损，胃纳颇安。议从填实下元，勿以治嗽肺药，所令妨胃，必戒怒勿劳，庶百日可望小效，经年坚固乃安。", "8532": "秋暑失血，初春再发，右脉大，颇能纳食。《金匮》云：男子脉大为劳，极虚亦为劳。要知脉大为劳，是烦劳伤气，极虚为劳，是情欲致损。欲驱病根，安静一年，可期其愈。", "8533": "脉细软涩，气冲失血，寐欲遗精，今纳谷不运，神思日倦，缘操作太过，上下失交。当先治中焦，心脾之营自旺，诸症可冀渐复。偏寒偏热，都主剥丧真元，宜禁。", "8534": "络脉空隙，气必游行作痛，最虑春末夏初，地中阳气上升，血从气溢，趁此绸缪，当填精益髓。盖阴虚咳嗽，是他脏累及于肺，若以清凉治肺，必然胃伤食减，立成虚损。蒙其害者累之。", "8535": "失血以来，气从少腹上冲，即咳逆坐起不得寐，乃肾虚不司摄纳，冲脉上升而然。夫冲脉即血海，男子藏精，女子系胎。今精气内空，血独升举，食入瘕泄，火土交惫。时师每以清凉治肺治咳，不过通套而已，非论病也。", "8536": "失血五年，今夏秋发作最重，脉左涩右弦，冲气逆则咳甚，天明汗泄，议用柔剂阳药以治下。病者四十三岁", "8537": "接案失血数发卧枕，气冲至喉，似乎痰阻，其实吐咯不出。此任脉不司担任，冲脉阳气直冲于上，纳食多嗳，下损及胃，秦越人尚称难治，便溏。凡填补下焦，必佐益胃，最忌清肺，寒润更伤中气。", "8538": "脉缓，寒失血，自述负重伤力，已是营卫两怯，当以甘剂益中，勿见血辄与滋凉。", "8539": "脉微而芤，失血之象也。膺胸隐而痛，肺胃之络也。", "8540": "盛体失血，作酸嗳逆，脉得左涩右弦。合引血干之条，曲直作酸之旨，责之厥阴中阳气上乘为治。", "8541": "脉左数搏大，因骤然跌仆，吐血仍然，安谷如常。此阳气暴升莫制，络血不得宁静而泛越夏三月至秋分，戒嗔怒情欲，莫令举发。", "8542": "脉缓大，吐血甚多，仍然安谷，此阳明胃络病也。戒奔走烦劳，方可冀其奏效。", "8543": "老年因秋燥咳嗽，食少胃弱，脉小数，当以清润甘药，不致伤胃。", "8544": "脉虚数，形寒，心中烦热，五更后气升咳呛，当秋分节燥金司令，大热发泄之余，皆能化燥。肺为娇脏，最处上焦，先受其冲，宜润燥以滋其化源。", "8545": "入秋一月，天令肃降，脉得左寸搏数，左关小弦而动，是心烦君相少宁，肝阳变化，内风陡升莫制，巅顶皆眩，脑后筋惕，何一非阳动所致。此皆阴弱不主配，非肝脏有余之比，法当益水滋木培母，另开养心脾之营，使上下不致庞杂，肝肾方以摄固。柔温宗聚精七宝法以治之。", "8546": "复脉去参姜桂", "8547": "右痪舌喑无声，脉小微涩，病起上年十二月，仍能纳食。此中于脾络，治以宣通灵窍。", "8548": "脉缓男子右瘫麻木，丹溪议从血虚有风，思起病值冰雪寒威，以舒筋汤。", "8549": "中年麻木筋胀，阳气已衰，内风自动，最怕痱中，脉微色痿，宜温补通阳。", "8550": "脉静，寝食便调，向有胃痛，饮暖烧酒相安。今年春季跌仆，右肢偏麻，语音不爽，是皆气伤痰阻，致内窍少灵也。", "8551": "接案目瞑戴阳，脉空大，肝风正甚易回也。", "8552": "右痪舌喑，足痱面赤戴阳，呵欠微呃，诊脉小濡而缓。此肾纳失司，肝风突震。但病起耳后暴肿，必兼湿热客气，清上轻扬，肿势颇减，七日以来，当阴阳经气一小周天，不必以时邪引病为惑。昔河间《宣明论》中，谓舌僵难言，其咎在乎舌下经脉不主流通，以肾脉萦及舌下耳，其主地黄饮，取意浊药轻投，机关渐灵，并无碍乎上气痰热。仿此为法。", "8553": "接案脉象左部稍振，水亏风动，左牙痛。盖风从内旋，乃阳之化气，只以春升少纳，下元不司收藏，虚症何疑。况因目恙，频用韭子烟薰，查本草辛辣升腾，助阳损真，人于遗浊用之，藉其升阳以涵阴，更无漏泄耳。今痱中八日，声音渐振者，乃精气略有宁静，里窍略有灵机，是顺境也。不明此理，仍用辛泄加人参，亦是清散上焦之药，但肝肾脏虚，在于至阴，若再投辛苦，以伤其阴，必致虚症蜂起，专望其向安。倘必以上有火热，古称实火宜清，虚火宜补，温养柔和，与温热刚燥迥异，幸勿疑讶。", "8554": "阳明脉衰，厥阴风动，头晕心悸，肉𥆧麻木，有风痱之累，少饮加谷易安。", "8555": "中年脉弦，右臂肢指麻痹。凡男右属气分，气弱阳不运行，则痰日生，乃水谷不主变化精凝，当以健中佐运为主。盖脾胃主四肢，滋阴血药多腻，为痰树帜矣。", "8556": "形神过劳，阳动不静，六脉皆弦大，彻夜无寐，以静摄心肝肾之阴。", "8557": "肾开窍于耳，胆脉远出耳后，经以肾藏液三合，胆藏汁三合，烦劳太过，液耗汁干，少阴少阳，枢机不利，遂有失聪之状，中年有此，液少风动使然。", "8558": "脉数耳鸣吐痰，天柱骨腰膝酸，两足冷。此阴亏阳升，当填补实下。", "8559": "勉强摇精，致阳缩囊纵，不但形弱伛偻，肛门脐窍，皆为收引，咽喉牵绊似垂，食物渐渐减少，由精血之伤有形，最难自复。少阴厥阴脉循喉咙，开窍于二阴，既遭损伤，其气不及充注于八脉，故症见拘束之状。上年进柔剂阳药，服后巅顶维脉皆胀，耳窍恋鸣。想脏阴宜静可藏，试以乘舆身布，必加跼促不安，宜乎升阳动药之不灵矣。夫少阴内藏，原有温蒸诸法，厥阴相火内寄，恶暖喜凉。仿丹溪法。", "8560": "脉数上盛下虚，当固其阴。", "8561": "脉濡食少，腹鸣烦倦无力，此属劳伤阳气，当与甘温补其营卫。", "8562": "诊脉弦涩之形已退，夏秋病邪已去，但食少神不爽健，欲大便，肛门下坠，是皆气不复为之。气陷不藏，都因忧思致伤，开怀怡悦可安，不独恃药饵。用升阳法。", "8563": "阳气素亏，背部怕寒，冬月嗽甚欲坐，入春纳谷䐜胀，脉左弱右弦。议湿中有热气蒸，肺气𪱥郁，口舌咽喉仍窒。", "8564": "夏秋气大发泄，身中之气久虚，无以主持，故见病治病无功，而安中纳下，每每获效，入秋进附子七味丸颇合。今秋分后天气渐升，地气收敛，缘久热伤气，虚体未能收肃，是以肢节时寒，巅顶欲冷。无非病久诸气交馁，斯外卫之阳少护，液髓暗枯，则血脉不营，而阴乏内守。凡此皆生气之浅薄也，急当温养益气，填补充形，助秋冬之收藏，豫为来春生发之用。《内经》有四季调神之训，今投药亦当如此旨。", "8565": "面黄肌瘦，脉数虚，形寒食少，乃劳倦致伤，不可为外感有余，议用", "8566": "脉涩缓无神，胁痛吐痰腥秽，渐至减食，短气寒热，肝病入胃显然，劳伤不复。", "8567": "色夺脉小，形寒久嗽，皆营卫二气久损，病属劳伤。《内经》云：劳者温之，损者益之。", "8568": "脉大缓而无力，色黄痿瘁，喜暖恶凉，心下痛连及胁肋。此劳倦内伤，久则延为脾厥。脾主营，以辛甘温养血络。", "8569": "咳喘频发，脉细畏寒，乃下不纳。", "8570": "脉沉迟，背寒色夺，久有劳倦，新年暴冷，再拟用", "8571": "春交旬日，形症小愈，但右脉仍弦，舌白味变酸甜。昔喻嘉言云：当以气雄刚药，能变胃不为胃变。", "8572": "鼻痒心辣闪烁，即大便下血，形瘦脉小数，已经数年。", "8573": "邪陷入里，疟变为痢，古称经脏两伤，方书都以先解外，后清里。拙见论病先究体质，今素有血症，且客游远临，从阴虚伏邪是用药须避温燥劫阴矣。鼻煤龈血，舌张干涸，阴液有欲尽之势，奈何，邪热内迫，有油干焰灭之危。医见病治病，不审肌如甲错，脉细尺不附骨，入夜烦躁不寐。议以护阴，急清阴中之邪热。", "8574": "下血后大便燥闭不爽，继而自利，白滑胶黏，日数行下不禁，年五旬，形衰脉沉。必因久伏水谷之湿，府病宜通，以温下法。", "8575": "脉弱形瘦，食不适，必泄泻。此阳气已伤未寒，下焦先冷，用", "8576": "脉微晨泄，初冬未及藏阳，以脾肾治，最是纳谷减少，当以中焦，兼理其下。", "8577": "平素阴亏，热注入里为利，粪结便出痛坠，诊脉左坚下垂，不以脾胃燥药。", "8578": "久痢久泻肛坠，频频不爽。此乃肾伤，脉来数小，医作脾胃病治，故不效。", "8579": "脉沉迟，下利血水，神呆不欲食，四肢冷，前已完谷，与温理其阳。", "8580": "脉两关弦虚，先血后粪，两月未已。当年原有病根，遇劳而发属虚，仿仲景黄土汤。", "8581": "脉弦无胃，面青呻吟，汗出目瞑，是为肝阳外泄，宜与肾同治。", "8582": "老年脉沉目黄，不饥不食，腹痛自利，后坠溺涩。此长夏湿邪，伤于太阴脾位，阳不运行，湿热凝注。法当温脾导湿，佐辛香以宣浊，补中益气，甘温升守壅气，宜乎䐜胀。议开太阳温太阴方。", "8583": "脉沉迟，食入腹胀便溏，平昔饮酒中伤，留湿阻气，小便不爽，用香砂平胃散。", "8584": "不饥少寐，二便不爽，经脉中牵掣。此非风寒从表，乃长夏水土之湿，与水谷之湿，互蒸气阻，三焦不通，中年两月不愈，恐延格胀之累。", "8585": "夏秋内伏暑湿，皆是阴邪，久疮渐致食入痞满，形寒脉小。当温中醒阳，莫以清凉治疮。", "8586": "脉沉，汤饮食物，呕吐吞酸，胸高腹胀，二便不爽，浊气上阻，柔温宣通。", "8587": "脉微小而迟，久食物不进，形色枯悴畏寒。此为无阳，延久成胀。", "8588": "左脉独弦，脐突筋青，肝胀显然，脾愈虚，肝愈实，又不合实脾治肝之法，先泄肝。", "8589": "腹右有形为聚，脉大，食入即胀，治在六腑。", "8590": "脉微迟，左胁宿痞，渐腹胀，便溺少。明系浊阴上攻，当与通阳。", "8591": "饮酒聚湿，湿生痰生热，维脉为湿热所阻，遂为痹痛，犹是浅近之恙，其在里久酿痰饮，深处络中，二年以来，阳气日衰，痰湿皆属阴浊，乘夜冲举，有妨卧寝。仲景论饮非一，总以外饮治脾，内饮治肾为要法。总之，脾阳鼓运水谷之气，何以化湿变痰，肾阳潜藏，斯水液无从上泛而为痰喘。试以过饮必泻甚，酒肉当禁忌矣。先议越婢法，宣上郁热，以通痰饮。", "8592": "脉沉背寒，咳嗽吐稀涎，夜不得卧，此为伏饮，遇冷即发。", "8593": "脉濡，中宫阳不主运，湿浊聚痰，不饥不渴不食。", "8594": "幼年哮喘，是寒暄失时，食味不调，致饮邪聚络，凡有内外感触，必喘逆气填胸臆，夜坐不得卧息，昼日稍可展舒，浊沫稀涎，必变浓痰，斯病势自缓，发于秋深冬月，盖饮为阴邪，乘天气下降，地中之阳未生，人身藏阳未旺，所伏饮邪，与外凉相召而窃发矣，然伏于络脉之中，任行发散，攻表涤痰，逐里温补，与邪无干，久药不效，谓此治法，宜夏月阴气在内时候，艾灸肺俞等穴，更安静护养百日，一交秋分，暖护背部，勿得懈弛，病发之时，暂用汤药，三四日即止，平昔食物，尤宜谨慎，再经寒暑陶溶，可冀宿患之安，发时背冷气寒，宜用开太阳逐饮。", "8595": "脉弦，脊骨中冷，深夜痰升欲坐，少阴寒饮上泛，议通太阳。", "8596": "诊脉左沉右弦虚，过劳阳伤，清气不主流行，温中丸不应，非有形之滞，以辛温微通其阳。", "8597": "长斋数年，脾胃日弱，食进脘中少运，小溲入暮渐多，色萎黄，脉弦虚，皆中气不足。", "8598": "脉左小涩右弦，六旬有六，阳微肢冷，脘痞不易运化，大便三四日一更衣，初结后溏。此太阴脾阳受困，当用温中醒阳。", "8599": "向系积劳伤阳，肝风内动，症如类中，专以温肾补脾，运痰熄风得效。丁巳春深，诊脉不附骨而洞泄，迄今形瘦未复，频年久泻。法宗泻久伤肾，以固摄下焦，定议六君子汤，仍宜暮服勿间，以胃气弱，阳微呕酸。", "8600": "脉左涩伏，右弦，呕吐脘痛，引及胁时，痛甚则四肢冷麻。是肝厥心痛，惊起怫郁致痛。", "8601": "接案脉伏者起，似宜病减，而痛胀脘痞，口涌涎沫，舌仍白，鼻窍煤，面欲赤头汗，显然肝厥犯胃，左升之气，逆乱攻络，胁胠乳穴皆胀，辛香开气不应，便秘溺少。用河间金铃子散，佐以润液，两通气血。", "8602": "脉沉小左弦，冲气至咽欲厥，下坠入前阴，溲溺不能，自利。此厥阴冲脉之病，当以秽药驱浊。", "8603": "用甘药呕缓，都因治嗽苦辛寒伤胃，冲脉亦阳明胃经管辖。此补胃以宁冲阳，实具至理。", "8604": "虚里穴为阳明胃，阳明气血皆多，络脉窒塞为痛，映及背部。脉络不和，必宣通望其痛息，彼萸地之凝，耆术之守，皆非络药。", "8605": "先有血淋，淋止胁痛，脉来左部坚搏，是少阳郁热乘络所致，忌食酒肉厚味。", "8606": "脉沉小，痛起胸脘，串及腰背，五年宿恙，寝食不改。此病在脉腠之间，痹阻不伤藏腑。议以流通周行气血，勿得峻剂。", "8607": "中年以后，阳气已微，午时嗳气，食纳上泛，皆胃弱气逆，视面明脉弦，必伏痰饮，仲景胃虚客气上逆例。", "8608": "脉症乃气结在上，津不运行，蒸变浊痰，由无形渐变有形。徐之才谓轻可去实，非胶固阴药所宜。", "8609": "脉小涩，面赤目黄，喉痛咽物不碍，溺后淋浊。此水谷之气，凝聚成湿郁，气不升降，三焦不利，当以清肃上焦主治。", "8610": "昔年强旺，夏秋热病顿减，精采不复，鼻窍不通，左胁有声，攻触痛呕，遇劳即发，必脉络中瘀留凝聚，顿然食减少饥，大络必聚血，病中衄血，已见一斑矣。", "8611": "此跌扑致经脉气血壅痹，胁背高凸，非汤药可效。", "8612": "脉虚浮，沉取直上下行，胃纳素减，病发从背彻心，先胀闷几日，气遂从下焦直冲至咽，手足厥逆发呃。细测病源，属胃虚，相火直冲清道而上也。夫冲脉并少阴之经，行乎幽门通谷，夹巨阙而上。故丹溪谓呃逆属于肝肾之虚者，其气必从脐下直冲，上出于口，断续作声。右肾为相火所寓，相火炎上，挟其冲气，乃能逆上为呃，主以大补阴丸，折火滋水，伏藏冲任。治虚呃用参术汤，崇土以制龙雷之火也。至东垣之论，又云胃为冲脉所逆，而反上行，其症气上冲咽不得息，名曰厥逆，宜调中益气汤加吴茱萸。观厥气多少而用之，且随四时寒热温凉而治。若夏月有此症为大热，宜加连蘖知母，直至下元，以泻冲脉之邪也。两条治法井井，高出千古。今拟大补阴丸早服，调中益气午服，恪守勿懈，自可除根，远胜后人庞杂之方矣。", "8613": "右脉如控弦。", "8614": "老人脉右弦左涩，因嗔怒，致呕吐䐜胀不纳物。此肝木犯胃，涌逆不已，必致浊阻上下不通，老年复虑关格。", "8615": "平昔嗜酒，肺胃积热，阴液下枯，阳津变痰，鼻塞多呛，减食无味，旬日更衣，粪如羊屎，老人关格，治之极难，况酒客不喜黏腻甘柔。形脉症象，不受温热，议以铁瓮申先生琼玉减蜜方法。", "8616": "六旬外阳气不旋反闭，上不纳食，下不更衣。此为关格，脉小结涩，伤于无形，最为难治。", "8617": "经云：食下不化，是无阳也。今早纳晚吐，仍然完谷，胃阳衰惫困穷，反胃涌吐，阳气结痹，浊阴壅遏，况少壮至中年，操持萦思，喜饮少谷，阳气积伤。虞天民有云：格拒反胃，必阴枯阳结。视面赤属饮，脉弦为痰，饮留气凝，焉得不痛，缓痛宜通，然非攻下荡涤之比。当从通阳镇逆为法，真寒辛酸，破泄真气，大伤胃阳，不可再服。仿仲景胃虚客气上逆例。", "8618": "酒热伤胃，谷食入脘即噎，涌出涎沫，阳明脉不用事，筋脉牵绊，与半夏泻心汤。", "8619": "右脉弦长而数，左脉带涩，阻在胃之上院，起自恚怒，不独伤肝，肺亦有之，何也？以其循胃上膈，是肺之所属，金不及木，得反侮之，聚则气凝痰阻，眼胞足以证之。拟泄金平木何如。", "8620": "食不得化，是无阳也。脉络映痛，辛香芳温可效，当用", "8621": "途次吸入寒气，伤及络脉，每胸痛饮热酒，宣通小愈。中年屡发，阳气受伤，必有瘀聚，漫延反胃噎膈。宜薄味节劳。", "8622": "噎膈为患，脉微而迟，乃胃之冲和之气，曲运神机所致也。今已颗粒不食，呃逆不止，仓禀顿惫之象。", "8623": "脉右弦面色赤亮，纳谷咽干脘阻碍不下。五十四岁清阳日薄，致转旋日钝，痰必阻气，结则脘窄不能宣通耳。大便仍利，但治脘膈之上。", "8624": "舌白不渴，脉沉腹满，不饥不食，二便不通。是暑湿发疟后中气不复，骤食大荤，亦气结成胀。", "8625": "脉左数搏，是先天真阴难充，则生内热，疟热再伤其阴，与滋养甘药填阴。", "8626": "疟止反复，必有所因，姑就色脉气怯神弱，因病致虚，夏秋宜调中益气。", "8627": "复脉去参姜桂", "8628": "寒自背起，热不烦渴，不饥不思食，指臂麻木，脉来小弱。近受温邪如疟，其实阳气久虚，当从本病调折。", "8629": "夏秋所伏暑湿，至霜降节乃发，是新邪引动宿邪。初病头痛汗出，寒热势猛，是新邪锋芒易解。继而势似差缓，疟来两日，越一日再发，半月竟成三疟，发于子午地支为太阴。盖邪气久伏，六淫客气，皆从火化。然中年形体丰伟，已见脉弱神倦，外似有余，里真不足。凡寒热之邪，必由四末渐攻中焦，病来心中热躁渴饮，胸闷不知饥知味，寒则肢背拘束，热甚心腹最剧，由邪聚为重，邪分稍缓。此为里中之表，病在络不能汗解下夺，惟辛香宣通，以氤氲氛瘴，原非质滞，阻清阳流行之隧，日加蒙痹，致正气日疲。故深秋入冬，伏邪在阴发疟，不与时疟和解清热同例。", "8630": "阴疟上部先寒，年十三未出。是营卫疏，客邪留著，色黄脉小。", "8631": "此厥阴疟症之最重者，烦躁吐蛔，脉弦数可征，拟苦辛酸法。", "8632": "诊脉缓软涩，胃脘不爽欲嗳，夜来腹胀，吐痰酸水，口鼻吸冷，损及中阳，暂用冷香饮子方，宜缓进参术。", "8633": "脉沉缓，目黄舌白，呕恶脘腹闷胀。此冷暖不和，水谷之气酿湿，太阴脾阳不运，周行气遂为阻。法当辛香温脾，宣气逐湿，用冷香饮子。", "8634": "舌白黄不饥，筋骨甚软，自暑湿内蒸，脾胃受伤，阳明胃脉不司分布流行，若不早治，必延疟痢。", "8635": "咳嗽二年，形瘦谷减，冬季喉垂渐痛，可见水亏。阳气不藏，春月气日甚，皆阴乏上承，阳结于上，为喉痹矣。近日寒热风温客气，脉小数为阴伤，忌用辛散。", "8636": "脉数右实左弦，服养阴药已得效，但未能愈耳。嘈杂恍惚，胸上动气，苦寒清热，用小柴胡汤治阳维之会。", "8637": "温邪感触，气从口鼻，直走膜原中道，不同伤寒阳症，邪自太阳次第传经。盖春温夏热，鼻受气则肺受病，口入之气，竟由脘中，致以手经见症，不似伤寒足六经病也。仲景论温不可发汗，汗则劫津伤阳，身必灼热，一逆尚引日，再逆促命期。又云：鼻息鼾，语言难，剧则惊痫瘛疭，无非重劫阴阳而然。今病发热，原不是太阳客邪见症，所投羌防，辛温表汗，此即为逆矣，上窍不纳，下窍不便，亦属常事，必以攻下希图泄热。殊不知强汗劫精而伤阳，妄下劫液而亡阴。顷诊脉两手如搐而战，舌干燥而无苔，嘴前干板目欲瞑，口欲开，周身斑纹隐跃，时有呃逆。因胃乏谷气而中空，肝阳冲突上冒肆虐耳。为今迫正，先用糜粥，使胃中得濡，厥阳不致上冒，而神昏之累可已。进药之理，甘温可以生津除热，即斑疹亦不必虑。观仲景论中，邪少虚多，阴液阳津并涸者，复脉汤主之。今仿此意。", "8638": "脉数，上出鱼际一寸，心中热，与背相控。", "8639": "脉数上出鱼际一寸，是谓溢脉，阴气不能上承于阳也。寒热汗出身半以上，是亦阳失阴守，非寿征也。议摄阴救阳。", "8640": "牙齿常紫，膝盖酸痛，上年秋季为甚，此湿邪阻于经络，阳明之气，不司束筋利机。议宣通脉络之壅，使气血和平。", "8641": "新沐头痛鼻塞，状似风温，次日寒战大热，胁肋痛不可转侧，自利稀水，乃湿聚于经脉，病在气分，热渴欲饮水。今目黄上视，手肢发痉，舌苔白齿板燥，胸中隐隐痛，皆邪深痉变凶。", "8642": "用木防己汤，痉厥已缓，经脉郁伏湿邪已解，胃汁大伤，痰嗽气闪，与甘药不伤胃气。", "8643": "今年天运寒水，地气湿土，春夏雨湿泛潮，郁勃秽浊之气，人在气交之中，口鼻触受，直走胃络募原，分布上下。如此症初病头胀，痞闷呕恶，必舌白，病全在气分，为里中之表，芳香逐秽，淡渗逐痰。此不为仅以陶氏全书方案竞进，彼寒分六经，热犯三焦，不同道也。且医药初用即泻，暑必挟湿也。消之不降，清之不应，此湿邪乃是无形，医治却是有形。今诊脉小涩，舌干口渴，不能汤饮，胸次软而涩，仍有呕逆之状，当温脾阳以运湿，仍佐辛香，可望其效。", "8644": "舌赤头痛，恶心脉大，温邪入募原也。", "8645": "脉右大，舌黄不渴，呕吐黏痰，神躁语言不清，身热不除。此劳倦内伤，更感温邪，须防变痉。", "8646": "舌干黄，经脉软弱，脘中不爽，热伤津液，阴不上承，清热不应，以甘寒生津。", "8647": "脉弱无力，心中洞，入夜神昏谵语，面目皆红，烦渴微饮。是劳倦内伤，频与苦辛消导滋阴，阳愈伤则浮越，有虚脱之虑。议用仲景救逆法。", "8648": "脉弦长，入尺而数，舌上沾苔，时或发热，大便或溏，显然素禀阴虚，复受暑湿。", "8649": "阴泄为遗，下焦诸脉既空，不主拘束，其阳浮上灼，自有首痰咳嗽。此治肺无益，必填实下元可愈。所虑少年精志未坚，失于保养，有劳屡内损。", "8650": "色夺脉虚，夏秋日加烦倦，此非客痛。据说左胁中动气，因遗精惊恐而得，乃下损精血。仿气因精而伤，当补精以化气。", "8651": "尿血即血淋，热遗小肠膀胱为多。今四肢不温，膝酸足软，天暖犹欲火烘，脉缓小弱。此系八脉不摄，以壮冲任督脉，佐以凉肝，乃复方之剂。", "8652": "体伟肌丰，脉得缓小，凡阳气发泄，行似有余，里实不足，水谷之气，不得畅遂，酿湿下注为浊。已经三四年，不效气坠，直升阳为法，非比少壮阴火自灼之病。", "8653": "诊脉右数，左小数入尺，淋浊不止，继患目疾，是精血暗损，肝肾之症。凡操持用心，五志之火自亢，是情志突起，非客气六淫之邪，并不许以辛散清火为治。", "8654": "脉左弱下虚入尺，有梦久遗，足软如痿，行动气促似喘。此督任交亏，冲阳升举，务以填塞精窍，不及傍治。", "8655": "饮食不司运纳，人皆知脾胃不和。但夏季之湿郁，必伤太阴脾，湿甚生热，热必窒于阳明胃脉。全以宣通气分，使气通湿走热清，四末微肿，黄未尽除，阳明之脉，尚少流利机关也，宜忌厚味腥浊可愈。", "8656": "久痢休息，脾胃皆弱，今夏湿胜，臂痛右痪，湿郁阻遏经脉流行之气，主以温脾辛香，为里中之表。治已得痛缓臂伸，当减姜黄蒺藜之走经络矣。", "8657": "脉缓软，四肢牵强，环跳髀尻牵引，壮年有此病，起四月中，乃时湿邪入于经络，为痿痹之症。", "8658": "脉小足冷，四肢发疹，骨骱肿痛，风湿已入经络成痹，形脉皆虚，护卫以攻邪。", "8659": "风寒久必入脉络，外卫阳失护，已现右肢麻木，虽鼻渊脑寒，不可发散。议和血脉，以逐留邪。", "8660": "脉形已小，痛移左右，由阳明虚，厥阴来侮，重按痛缓。", "8661": "脉沉迟，疝冲瘕聚，收引拘束痛甚。是阳微阴浊痹阻，议以刚药。", "8662": "脉沉伏，逆痛不止，厥阴挟冲气为患。", "8663": "色悴脉芤，下焦疝瘕，是冲任病，乃肝肾精血不足致损耳。", "8664": "脉微涩左弦，跗⿰⻊廉麻冷，走动无力，少腹微满，睪丸日肿。察神呆色衰，畏风怕寒，阳虚疝瘕，难愈之疾。", "8665": "经云：阳维为病苦寒热，阴维为病苦心痛。盖维脉乃一身之纲维，阳司外护，阴主内营。若家庭夫妇，管辖内外事宜也。缘二气日衰，营护不周。凡劳倦寒暄，皆乘其空隙为害，为寒为热，阴阳矛盾所致。是八脉奇经之病，温补不能入脉，不效亦无害。若以湿淫客气搜逐，其害大矣。", "8666": "带脉横围于腰，维脉挟内外踝而行，劳伤受寒，脉络欹斜，不司拥护，而为瘕疝，麻木不仁，非小病也。久而痿痹，废弃淹淹。", "8667": "产后十年，晨泄形寒汗出，是下元阴伤及阳，奇脉不固，遵古人用", "8668": "少腹微膨，经来后期多痛，秋冬膝跗冰冷，冲气致左胁攻触，脘中胀闷，痛不能食。此属气血郁痹，络脉不和，虽无性命之危，然恐有不得孕育之累矣。", "8669": "天癸当绝，今屡次崩漏，乃冲任脉衰，久漏成带，延绵之病，且固其下。", "8670": "胎前疟热伤阴，产后下焦之阴更损，冲任脉不下固，气冲咳逆呕，午后潮热，子后汗泄，皆阴虚损及阳位。夏令大热发泄，络空胁痛失血，虽颇纳谷，大便溏泄，蓐劳下损，渐干中上，故延绵不愈不疴，医药无效。", "8671": "少年怀妊恶阻，误药殒胎，十余年后不孕育，每经来周身经络暨痛，少腹瘕触寒热皆至，乃八脉交损。八脉之治，非转展不效。", "8672": "质偏于热，阴液易亏，女人肝为先天，月事虽准，而里少乏储蓄，无以交会冲脉，此从不孕育之因由也。凡生气阴血，皆根于阳，阳浮为热，阴弱不主恋阳，脊背常痛，当从督任二脉治。", "8673": "形冷惊伯，旬日经淋漏注，心怔悸若悬施，自七八年产后致病。夫肝主惊，肾主恐。产病先虚在下，奇经不为固束，急急温补固摄，仍佐通药，其力可到八脉。", "8674": "自产后五日，恶露渐少，遂卒然右胁下痛引少腹，手不可按，身体不能转侧。此乃卧著于右太早，致败血横行入络，痛甚神迷昏乱，皆瘀腐浊气，上冒胞络矣。此属产后重病，夫通则不痛，议宣通脉络之壅。", "8675": "蓄血有如狂喜忘症象，今络中瘀聚，还注于冲脉，所以右胠痛缓，而少腹痛胀，大便黏腻白滑，亦瘀浊之化，但必前通溺浊，不致凶危，即痃痞症瘕，犹可缓商调治矣。", "8676": "络通痛减，病已挽回，但少腹余氛，瘀留冲脉，不必以宿佝偻为重，只宜溺通瘀下，斯为得矣，用交加虎杖合方，加炒灵脂。", "8677": "胎前咳嗽，产后更加失血，脉来左数，咳甚呕吐，是下虚气逆，冲任内损。医屡投肺药，必致延为蓐劳，断乳调理为上。", "8678": "奇脉空虚，腹中瘕痛，温补佐以宣通，其力可以入八脉。", "8679": "三旬有崩漏形体日加充壮，此皆发泄，外盛内虚，如背部周身肌腠之中热烘，肢体皆为动摇，阴液内乏，阳气旋鼓。《病能篇》云：诸风掉眩，皆属肝木。风木不宁，阳明脉空，暴中暴厥，皆由此而起。", "8680": "此气血不和，脉络不通为胀，用大针砂丸胀减。其经水仍阻左胁，宿瘕久聚，此病根未去。", "8681": "腰胁刺痛，虚里尤甚，头晕跗肿，形寒临经诸病皆集。此病久八脉损伤，调经和养气血，不得见病治病。", "8682": "思虑忧愁谓之郁，气血暗伤，肌肉日瘦，不食不寐，心中时觉昏愦。是皆内因之症，酿痰为痫，枯槁成损，必得情怀开旷，斯郁结可开。目下用药，因夏秋失血以来，倏冷忽热，脘闷胸痛，自天柱挟脊至腰，酸软如折，不但营卫偏欹，八脉皆失其职司。先议宣畅脉络，勿以滋滞补涩。", "8683": "阳浮汗泄，如饥忽胀，眩晕麻痹，产前心痛，谓之子悬。病起于产后，由肝肾内虚，真气不自收纳，内风掀旋不已，病传阳明脉络，筋骨不司步履，乃沉锢之疾。", "8684": "连次小产，初伤冲任，久而督带跷维皆伤，八脉不匀约束，阴不下固，阳乃上浮。如经后期淋带晨泄，上热下冷浮肿，脊酸腰垂，耳鸣不寐等症，久损不复，必以从阴引阳，通固兼用。若非积累工夫，未得旦晚得效。", "8685": "热升冲咽，咳嗽不止，两足冷如冰而至骨，脉得细促，先天最弱，笄年不肯充长，倘经水忽闭，劳损难治。", "8686": "久病形神日消，脉象兼大，是谓脉无胃气矣。上年夏季，曾诊便泻腹痛食减，舒肝健脾疏补，春进安胃丸，总无效验，此生气不至。女子当天癸将通之年，经脉气机怫逆，久郁热聚，渐为枯涸之象，议用汪石山郁劳治法。", "8687": "蓐劳下损，不独病属八脉，则延及三焦，晨泄呕食，心热下冷吸短寒热。用药岂有止嗽清热之理，扶得胃气安谷，月事仍来，方得回春。", "8688": "经来甚少，脉左坚搏仍然，咳呛嗽涎沫，夜热汗出，肝血肉枯，已属劳损。宜进甘缓，以养肝胃，令其纳谷，庶可望愈。若见热投凉，希图治嗽，胃伤速惫矣。", "8689": "停经九月，少腹重坠而痛，及诊少阴脉涩小，并非妊象，且冲任虚馁，怕其暴崩。", "8690": "经先期三日，热多寒少，脉右弦大，血分偏热，治厥阴疟，邪窒在血。", "8691": "暴崩去血过多，络中空虚，浮阳挟内风，以心悸筋脉酸软，奇经病也。", "8692": "阴伤于下，热气上冒，脉左坚数，虑其失血，不可强迫通经。", "8693": "肝脾既不统藏，任带又疏约束。天癸妄行有块，腹痛作哕，谷食减少，脉象弦细而数。再延有崩漏之渐。", "8694": "（案1）湿温月余，弥漫三焦，身热不清，耳聋面瘦，结胸自利，脉息弦数。深虑正不敌邪，致生歧变，拟方以尽人力。", "8695": "（案2）湿温结胸自利，身热未清，脉象细濡，已五候有余。深虑正不敌邪，外生枝节，拟方获效乃吉。", "8696": "（案3）湿温延经月余，寒少热多，胸次不开，脉象滑数。深虑正不敌邪，致生枝节。拟方获效为顺。", "8697": "（案4）产后百脉空虚，湿温弥漫三焦，将近一月。右边发颐，向来肝郁不伸，湿痰内扰，所以谷食不进，脉象弦细而滑，深虑外脱之虞。", "8698": "（案5）湿温后肝木乘脾，水湿困中，脘腹膨胀而大，脉象弦涩。再延有胀满之虑。", "8699": "（案6）湿温五候有余，身热不清，白㾦现而未透，舌苔白滑，渴不多饮，甚则作呕咳，脉来濡数。虑其正不胜邪，致生歧变，拟方获效乃吉。", "8700": "（案9）先后天不足，湿温结胸，自利月余不解，加之湿痰入络，左腿痹痛，伸屈不利，脉息弦数。虑其正不胜邪，致生歧变。拟方获效乃吉。", "8701": "（案10）湿温九日，身热下利，白㾦现而未透，脉象细濡。深虑化热逆传。", "8702": "湿温郁而不伸，寒热多日不清，白㾦未透，脉息细濡，舌苔底白罩灰。乃水极似火证也，谨防昏陷。", "8703": "（案1）肝木乘脾，湿痰内困，遂令脘腹膨大，谷食减少，脉象弦细，面浮肢肿。再延防成胀满。温中化饮法。", "8704": "（案2）肝木乘脾，湿痰互结中宫，胸次结痞，肝阳上升，头目眩晕，脉象弦濡，拟方徐图之。天麻二陈加通络化饮之品。", "8705": "（案3）肝旺胆虚，湿痰入络，虚阳上升，于是心悸头眩耳鸣，懊𢙐难名，间有呛咳，惊悸麻痹，善怯多疑，脉息弦滑，右脉反关，左脉独见。拟方善图，方可渐入佳境。", "8706": "（案4）肝木侮土，湿痰困中，少腹膨胀而大，脉象沉弦。再延防成气臌。", "8707": "（案5）肝木乘脾，湿痰内伏，遂令脘腹两胁胀膨，已延三年之久，脉象沉弦。宜远烦戒怒为要。", "8708": "（案6）肝木乘脾，湿痰互结，致成痞块，任带不调，经频带下，内热熏灼，间或作哕，脉弦数。拟方缓图之。", "8709": "（案7）肝肾血水两亏，不能涵养筋脉，故令左肢不遂，脉沉小。加以水火不交，拟方善图之。", "8710": "（案8）肝木乘脾，湿痰内伏，虚阳上升，于是胸次不开，头目旋运，其则哕吐涎沫，食少神疲，脉沉弦而滑。拟方徐图之。", "8711": "（案10）素本体半气虚，多湿多痰，加以肝郁乘肺，膺胸痹闷久矣。数日前胃逆上升，气逆血流，动辄盈碗，脉息尚幸沉细，防涌脱。", "8712": "（案11）素本肝脾不和，湿痰入络，胸次嘈杂，心悸头眩，加之热蕴于曲肠，致成赤白滞下成片，腹痛，脉象虚滑。法当先治其标。", "8713": "（案12）气滞血瘀，湿痰互结，心腹瘕聚，已延二十五年，今夏因肝郁而作，疟痢叠见，腹中脘胁作痛，漉漉有声，谷食减少，脉象弦细而紧，痛甚防厥。", "8714": "（案1）向有悬饮，加以肝木侮土，脾胃交亏，命火不能上升，心悸懊𢙐，哕吐涎沫，脘左作痛。近来水饮不能下输膀胱，以致脘次膨胀而大，足跗亦肿，小水不利，食少神疲，脉象沉弦而滑。再延防成气臌，拟方力图之。", "8715": "（案2）饮邪入络，名曰悬饮。脘胁前后心痹痛，漉漉有声，时作时止，脉象沉弦而滑。拟方缓图之。", "8716": "（案1）肝木侮土，气滞寒凝，少腹作痛，痛甚哕吐，食入反出，大便秘塞，已作三次，脉象沉弦。拟方徐图之。", "8717": "（案1）肝阳化风，上腾清窍，饮邪入胃，脘次左右作痛，甚则哕吐，两肋有形，心悸头眩，肉𥆧筋惕，脉象弦滑。拟方缓图。", "8718": "（案2）肝阳化风，痰饮入络，扰乱上升，于是目眩头晕，哕吐并见。书云：无风不眩，无痰不晕，此之谓也。脉弦滑。拟方缓图之。", "8719": "（案3）肝阳化风，上腾清窍，于是头目眩晕，间或梦遗，脉象弦滑。拟方善图，方可渐入佳境。", "8720": "（案1）肝胆之热上移于脑，致在鼻瘜。右颧红肿，牙龈时而出脓，脉弦而数。拟方尽力图之。", "8721": "（案2）向有鼻瘜，兼之痰饮射肺，咳嗽气喘，声音不扬，脉弦滑。速当屏烦戒怒，庶可与药石兼功", "8722": "（案3）起于鼻渊，酿成损怯，脉弦数。拟方应手乃吉。", "8723": "（案2）湿热蕴于曲肠，致成肠癖，已延数载之久。七月间尤甚，居经四月，食少神疲，脉弦细。久延防怯。", "8724": "（案1）惊恐伤胆，郁痰内犯心胞，于是言语错乱，神识不清，脉沉弦而滑。似属癫症，治之不易。", "8725": "调治以来，肝胆渐和，郁痰渐化，心肾渐交，脉象就平。症势如此，已有转机，拟方仍期获效。", "8726": "（案3）数年前曾患癫症，调治就痊。近来复发，经三月余矣。仍属肝胆内蕴郁痰所致，脉沉弦而滑。拟方徐图之。", "8727": "（案1）血行横逆，经鼻而出，谓之鼻衄。已延半载有余，时发时止，加之胆热上移于脑，致成鼻渊，且生瘜肉。头目昏眩，嘈杂吐酸，胸胁胀痛，食入不运，脉象滑数。拟方徐图为宜。", "8728": "（案2）由鼻衄而成鼻瘜，血去过多，肝阳上升，脾土受侮，郁痰内扰，头额昏痛，胸次嘈杂，面浮肢肿，脉沉而数。再延防损。", "8729": "（案3）阳明胃热上升，致成鼻衄，虚阳上僭，头目不清，脉象弦滑。拟方徐图。", "8730": "（案1）相火有余，肾气不充，遗滑并形，加以肝热胃寒，哕吐酸水，阳络受伤，血吐成块，营卫交亏，寒热往来，脉象弦芤。仍防涌吐。", "8731": "（案2）阳络受伤，气逆血溢，动辄盈碗，交春发作。近又感受客邪增患，咳逆，脉细数。法当先治其标。", "8732": "（案1）向有疝气，膀胱之气不化，二便不通，已经两旬，脉弦涩。治之不易。", "8733": "（案2）七疝统属于肝，肝旺侮土，脾胃受伤，遂令脘肋胀大，面浮肢肿，谷食减少，脉沉弦而涩。再延防其土败。", "8734": "（案2）暑湿内蕴于曲肠，酿成肠癖，胸次喜温，遍身皆寒，皆阳虚之故，脉象沉细。治之不易，拟方力图之。", "8735": "（案3）暑湿内蕴曲肠，酿成赤白滞下，加以肝气犯胃，郁痰内伏，胸痞作哕，右肋时痛，谷食难运，脉弦而大。防成噤口，拟方获效乃吉。", "8736": "（案1）肝气不降，肺气不升，升降失常，气与痰搏，食入作阻，甚则哕吐饮食，脘腹时痛，脉象弦涩。再延防神思间病。", "8737": "（案2）肝厥犯胃，湿痰困中，脘痛哕吐，食入反出，脉象弦细而滑。拟方徐图。", "8738": "（案3）命火、脾阳不振，水饮伏胃，呕吐涎沫，甚则食入反出，脉象沉弦。拟方获效乃吉。", "8739": "（案4）火不生土，木来侮土，土不制水，水饮停中，于是哕吐并见，甚则食入反出，脉弦细而滑。症延三载，非徐图不可。", "8740": "（案5）肺气不升，肝气不降，气与痰搏，升而不降，道路妨碍，食入觉阻，动辄呕吐，脉象弦涩。关格之渐，拟方聊尽人力。", "8741": "（案6）肝气横逆，乘胃犯肺，脘中时痛，间作咳逆，营卫不和，为寒为热，声音不扬，向曾失血，脉弦细而数。延防成肺痿。", "8742": "（案5）客冬调治，诸恙渐解。奈根株未尽，近来复作，殆有甚焉，脉弦细无神。谨防肺胀，拟方以尽人力。", "8743": "（案6）肝木侮土，脘腹膨大，脉象弦涩，谨防单胀。", "8744": "（案7）素有痰饮咳喘肿胀，脉弦滑，谨防水溢高原成肺胀。", "8745": "（案8）居经五月，肝脾不和，水湿困中，肚腹膨胀而大，面肢肿，脉弦细而涩。拟方力图之。", "8746": "（案9）暑湿蕴于曲肠，酿成滞下，脘腹膨胀而大，谷食减少。脉象弦细。再延防成胀满。", "8747": "（案10）产后肝木乘脾，湿浊盘踞中宫，以致脘腹膨大，左胁作痛，谷食减少，不能安卧，脉象弦滑而涩。谨防水溢高原，酿成肺胀，拟方获效乃吉。", "8748": "（案11）天癸应至不至，肝木侮土，营卫交亏。少腹胀痛，或寒或热，食少神疲，脉象弦数。拟方徐图之。", "8749": "（案12）肝木乘脾，湿邪内困，脘腹膨胀，临经期尤甚，脉象弦细。根蒂已深，非徐图不克。", "8750": "（案14）肝气入络，脾土受侮，前后心时而串痛。刻下脘痛且胀，甚则作哕，脉象弦滑。气虚多汗，久延非宜，拟方获效为顺。", "8751": "（案15）肝郁乘胃，脘次及脘右胀痛，哕吐并见。病久入络，气血皆瘀。六年前阳络受伤，曾经失红。脉弦细而芤。病久根深，治之不易，拟方缓图之。", "8752": "（案16）木火凌金，咳嗽失红，加之肝胃不和，郁痰扰乱神明，营卫交亏，寒热互见，脉细滑而数。久延防损。", "8753": "（案1）肝脉布于胁肋，脾脉络于胸中，肝脾不和，水饮内蓄。于是脘胁胀痛，漉漉有声，天癸先期，脉象弦滑。若不善调，防其土败。", "8754": "（案2）本属水饮困脾射肺，肿胀气喘，加以肝火上冲，左目既损，右目陷塘，脉象弦细而滑。症势丛杂，拟方徐图。", "8755": "（案3）命火不足，水饮内蕴，脘腹胀痛，漉漉有声，脐旁有形，初发之时，上吐下利。脾胃交亏，脉象沉弦。根蒂已深，治之不易。", "8756": "（案4）命阳不足，脾肾交亏，水饮聚胃，遇寒则哕吐并作，有时冲脉之气上逆，精关不固，脉象沉细。拟方缓图之。", "8757": "（案5）肝木侮土，火不生土，水饮停中，脉象弦细。再延防成反胃。", "8758": "（案1）肝胆厥阳之气由肺系上升于喉，喉间不利，状如物阻，天癸应至不至，已延二载，脉象弦细。拟方徐图。", "8759": "（案2）肝胆厥阳之气上升，宿饮亦随之上逆。于是喉间不利，状如物阻，项外结核，音嗄喘咳，寒热往来，天癸逾期而少，脉象弦滑。再延防闭脱。", "8760": "（案4）肝胆厥阳之气上升，喉间不利，状如物阻，膺胸不开，间或哕吐，脉象弦沉。速当自开怀抱，庶可与药石兼功。", "8761": "（案5）肝胆厥阳之气上升，喉间不利，状如物阻，起于客冬，谷食懒进。脉象沉弦而滑。久延非宜。", "8762": "（案4）肺痈溃后，未能完口，脉象细数，声音不扬，再延防痿。", "8763": "（案1）肝脾不和，攻冲作痛，胸次结痞，脉象弦涩。痛甚防厥逆。", "8764": "（案2）肝木乘脾，腹如束带，肝气入于肺管，膺胸不开，谷食不运，胸次结痞，已延二载，脉象弦涩。治之极不易。", "8765": "（案3）三年前，产后病疟，疟久伤脾，胸次结痞，大便时溏，脉象弦细。拟方徐图之。", "8766": "（案4）产后肝脾受伤，寒湿内困，天癸逾期，少腹膨胀时大，胸次结痞，大便远血，每经期大便不实，脉弦细而涩。久延防土败。", "8767": "（案5）肝木乘脾，气与痰抟，以致三焦不通，胸次结痞，天癸先期而少，病情夹杂，脉弦细。拟方次第图之。", "8768": "（案6）肝木横逆，克脾犯胃，气与痰抟，胸次结痞，胀痛哕吐，昔瘦今肥，天癸渐少且而过期，脉软滑。已延数年之久，根蒂已深。治宜徐图。", "8769": "（案7）天癸先后不一，肝气横逆，克脾犯胃，胸次结痞胀痛，哕吐，脉弦滑。再延防成反胃。", "8770": "（案8）肝木横逆，脾胃交伤，少腹有块，胀痛作哕，根蒂有年，脉弦细，非徐图不可。", "8771": "（案9）肝木横逆，克脾犯胃，胸次痞塞，既胀且痛，哕吐涎沫，食入不运，形气消索，脉弦细。再延防入神思间病。", "8772": "（案1）睪丸下坠，气虚下陷，肝木不舒所致，脉象弦细，延二载。拟方徐图之。", "8773": "（案3）肝木乘脾，湿痰互结，脘腹胀痛，谷食减少，脾阳不振，大便不实，脉沉弦而芤。再延防土败。", "8774": "（案4）肝木横逆，克脾犯胃，脘肋胀痛，哕吐涎沫，已延十载之久，根蒂已深，脉沉弦。非徐图不克。", "8775": "（案5）命火不足，脾阳不振，水饮停中。自五年前产后起，见面色黄瘦，少腹膨胀，漉漉有声，肢肿且痛，天癸渐少，脉弦沉而滑。再延防土败。", "8776": "（案8）肝木乘脾，湿痰内扰，脘腹胀痛，按之有形，闻之有声，脉虚弦而滑。久延非宜。", "8777": "（案9）肝气横逆，肺胃交病，膺胸串痛，遍身酸痹，由客秋起见，脉沉细而数。拟方徐图之。", "8778": "（案1）木叩金鸣，络伤血溢，咳逆气喘，脉弦细而滑。拟方徐图。", "8779": "（案1）天癸六载不至，木叩金鸡，络伤血溢，脾阳不振，大便不实，脉象弦细。乃损之渐也。", "8780": "（案3）木火凌金，咳逆频仍，肝脾不和，胀痛并见，脉象细数。久防成损。", "8781": "（案4）肝脾不和，湿痰内伏，脘中胀痛，哕吐酸水，脉弦滑。拟方获效乃吉。", "8782": "（案5）木叩金鸣，络伤血溢，营卫交亏，寒热往来，脾阳不振，大便不实，脉象细数。损之渐也。", "8783": "（案7）久嗽金伤，饮邪射肺，营卫交亏，寒热往来，脾阳不振，大便不实，脉象弦细。拟方徐图。", "8784": "（案9）先后天不足，水不涵木，木叩金鸣，经伤血溢，脾阳不振，大便不实。阴分不足，内热频来，天癸愆期而少，脉弦而数，损情已萌。", "8785": "（案11）水弱肝虚，气逆血溢，已经二载有余，春时血来甚涌，咳逆频仍，脘中时而作痛，营卫交亏，寒热往来，天癸先期，谷食减少，脉弦细而数。乃损之渐。", "8786": "（案12）素本血不荣肝，肝气横逆，不特下侮脾胃，并上不畏金，头晕耳鸣，脘胁串痛。自客秋八月产后，发生气瘰，耳之前后皆有，两腿亦然，心悸不安，善怯多疑，近加呛咳多汗，肢体痛楚，寒热互见，脉弦滑数。症势多歧，再延防成疬劳。", "8787": "（案13）先后天不足，宿饮射肺，咳逆气喘，已延年久，营卫两虚，寒热互见，跗肿便溏，间有盗汗，脉弦细。延防土败。", "8788": "（案14）木叩金鸣，络伤血溢，气血交亏，往来寒热，肝脾不和，天癸先期不一，谷食减少，形容消索，脉象细数。种种皆损情之渐，拟方以尽人力。", "8789": "（案15）肝郁乘胃，脘胁胀痛，哕吐并作，痛久入络，气血皆瘀。六年前阳络受伤，曾经吐血，脉弦细而芤。病久根深，治之不易，拟方徐图之。", "8790": "（案16）木火凌金，咳逆失血，加之肝胃不和，痰热内扰神明，营卫交亏，寒热互见，脉弦滑而数。延防成损。", "8791": "（案17）阳络受伤，吐血盈碗，血后咳逆，愈而复作，已经两次，侧眠于右，尚未成怯，脉细数。拟方力图之。", "8792": "（案18）木火凌金，咳逆失红，阴分不足，内热频来，脾阳不振，大便不实，脉弦细而滑。病根已深，非徐图不可。", "8793": "（案19）先后天不足，木火凌金，咳逆频仍，阳络受伤，痰中带血，营卫交亏，寒热往来，天癸先期而少，脉象数。损情已萌，拟方尽力图之。", "8794": "（案20）劳伤咳逆，愈而复作，阳络受伤，曾经失红，脉细数。久延非宜。", "8795": "（案21）先后天不足，木叩金鸣，络伤血溢，营卫交亏，寒热往来，经前带下，食少神疲，脉象细数。损之渐也，拟方以尽人力。", "8796": "（案22）木叩金鸣，络伤血溢，阴分不足，内热频来，天癸不至两月有余，侧眠，食减，形气消索，脉象弦数。乃劳损根萌，拟方以尽人力。", "8797": "（案23）先后天不足，天癸愆期，木叩金鸣，络伤血溢，呛咳形瘦，侧眠于右，土受木侮，谷食减少，入食脘中胀痛，脉来细数。久延防怯，拟方速冀胃开，方有进步。", "8798": "（案24）先后天不足，肝木横逆，肺胃交伤，咳逆时作时止，间或作哕，营卫两亏，往来寒热，脉弦数。久延防损。", "8799": "（案25）先后天不足，脾肺交伤，面浮肢肿，少腹膨胀。阳络受伤，时形衄血，食少神疲，脉弦细。再延防损。", "8800": "（案26）肝胆厥阳之气上冲肺胃，于是喉间不利，状如物阻，咳逆作哕，痰中带血，寒热往来，天癸先期，脉弦数。再延防损。", "8801": "（案1）㾬疟后失调，致成疟母，肝肾交亏，间或遗泄，面色无华，少腹膨胀，得大便方解，脉弦细而涩。再延防成胀满。", "8802": "（案2）邪客太阴，致成疟疾，左胁下已有疟母，胸次痞塞，肝脾不和，症属显然，脉来弦滑。拟方先治中宫。", "8803": "（案3）疟久脾胃受伤，湿痰困中，遂令脘腹作痛，心悸面黄，哕吐酸水，脉象弦细。防成反胃。", "8804": "（案4）寒疟邪伏阴阳二维，三、四、七、八月但寒不热，已七载，今秋七月，外邪内侵，遂令寒热交作，甚则一日两次，得汗乃解，脉象弦涩。根蒂已深，非徐图不可。", "8805": "（案5）温邪化疟已经三月，脉象弦数。久延非宜。", "8806": "（案7）疟后失调，气血交亏，湿痰下注，故小溲带浊而痛，天癸数月不至，脉象弦数。拟方徐图之。", "8807": "（案1）积湿成痰，积痰成饮，痰饮射肺，咳逆气喘，脉象弦数。拟方徐图。", "8808": "（案2）积湿成痰，积痰成饮，痰饮射肺，咳逆气喘，脉象弦滑。拟方获效乃吉。", "8809": "（案3）痰饮射肺，咳逆气喘，阳络受伤，曾经失血，脾阳不振，大便不实。肺气久虚，声音不扬，刻下吸受外邪，肝气入络，寒热不清，膺胸串痛，脉虚细而数。当先治其标，节劳静养为要。", "8810": "（案4）痰饮二载，肺脾肾交亏，咳逆哕吐，动辄气短，脉象弦滑。拟方改重就轻可也。", "8811": "（案6）痰饮射肺困脾，咳逆气喘，面色萎黄，四肢痿躄，脉弦滑。拟方改重就轻。", "8812": "（案7）肺脾肾三经皆亏，加之肝旺胆虚，痰饮内扰，神明龙雷之火上升，症势多歧，脉弦细而滑。拟方力图之。", "8813": "（案9）痰饮咳喘，曾经失血，已延八载，脉细滑。拟方改重就轻。", "8814": "（案10）素本肝脾不和，现因宿饮上干，客邪外抟，咳逆频仍，身热不清，又经旬日，脉象弦数，虑其正不胜邪。", "8815": "（案11）痰饮射肺，咳逆气喘，脘腹膨胀，漉漉有声，脉滑。虽调治较轻，拟方仍望获效。", "8816": "（案12）肝木乘脾，饮邪入络，脘胁少腹窜痛，食少神疲，加之木火凌金，咳逆频仍，脉弦细而数。再延防损。", "8817": "（案13）肝胆不和，心肾不交，郁痰内扰神明，于是胸中懊𢙐，多食善饥，舌白苔黄。内热熏灼，心悸头眩，脉弦数而滑。渐近半载，再延防成痫症。", "8818": "（案14）抑郁日久，痰热聚于肝胆，甚则犯于心包，神思恍惚，语言错乱，舌白苔黄，脉弦数。再延防生痉厥。", "8819": "（案1）肝脾不和，任带交伤，湿热内蕴，于是天癸应竭不竭，反而妄行，带下不已，气味腥臭，少腹作痛，延经年余，脉弦而滑，再延防崩。", "8820": "（案2）肝胆不和，郁痰内扰，心悸头眩，小溲淋血，大便不实，天癸先期，时形带下，脉象弦数。拟方次第图之。", "8821": "（案2）肝脉络于阴器，七疝统属于肝，左有偏坠，加之脾虚湿热下注膀胱，小溲淋浊，肾气不充养，善怯多疑，拟方速图之。", "8822": "（案3）先后天不足，相火有余，精关不固，湿热下移膀胱，致成虚淋，脉象弦滑。拟方徐图之。", "8823": "（案5）先后天不足，湿痰困脾，加之相火有余，精关不固，两腿时而酸痛，脉象弦细。拟方获效乃吉。", "8824": "（案6）心肾不交，热伤阴络，小便带浊带血，脉象弦芤。延三月有余，再延防损。", "8825": "（案9）肾气不足，相火有余，于是遗滑并见，加之肝阳上升，阳明脉络不和，饮邪内扰，心悸头旋，脉象弦滑。拟方次第图之。", "8826": "（案1）因跌扑伤筋，四肢麻痹，时形腰痛，良由肝肾不足，瘀血入络所致，脉息细滑。能于节劳静养佐以药石，可免类中。", "8827": "（案2）努力伤于阴络，致成血淋，反复无常，脉象弦芤，治之不易。拟方徐徐图之。", "8828": "（案1）疮湿传里，脾肺交伤，咳喘肿胀，吸受外邪，寒热不清，脉象浮濡。谨防水溢高原，肺胀致变。", "8829": "（案3）伏邪夹湿，身热不清，已经旬余，脉滑数。拟方获效乃吉。", "8830": "（案4）时邪入于气分，以致神昏谵语，身热不清，脉沉弦而滑，深虑正不敌邪。", "8831": "（案5）肝肾不足，加以吸受外邪，身热不清，大便不实，腰痛不已，脉象滑数。拟方力图之。", "8832": "（案1）肝胃不和，胀痛作哕，大便秘涩，脱肛下血，脉象弦细，再延防土败。", "8833": "（案1）湿热下注大肠，致成外痔有年，气虚下陷，坠不可言，脉象细濡，拟方获效，方可渐入佳境。", "8834": "（案1）小产后正虚，气血凝滞，少腹结瘕，攻冲作痛，痛牵两腰，天癸两月不至，脉象弦滑，治之不易。", "8835": "（案3）产后四朝，因受外感，气血凝滞，少腹结瘕，腹中作痛，虚火灼金，间有咳逆，谷食少思，形气消索，脉细数，久延防劳。", "8836": "（案1）肝气入络，饮邪乘势而入，于是遍身串痛，不能起卧，步履维艰，已经一载，所幸胃纳如常，脉象弦滑。根蒂已深，非缓图不可。", "8837": "（案1）肝邪入肺，风池、风府痹痛，痛及肩臂，背俞皆所行经之地，间有咳逆，脉象沉弦，再延防其土败。", "8838": "（案1）急躁伤肺络，致成胸痹，脉象弦细，已经年余，拟方徐图之。", "8839": "（案1）风邪中经络则口眼歪斜，中血脉则半身不遂，脉弦滑，起于春正月，为期已久，非缓图不克。", "8840": "（案1）肝旺胆虚，心火上炎，遂令患目左目，血贯瞳人，瞳凹陷，外眦白翳，脉弦数，左部倍大。拟方候专科。", "8841": "（案1）肝木乘脾，水湿内困，脘腹膨大，谷食减少，脉象沉弦。再延防成胀满。", "8842": "肝木乘脾，水湿停中，少腹时痛，腹大如鼓，脉象沉细。拟方应手，方免胀满之虑。", "8843": "（案2）命火不足，脾阳不振，水湿停中，遂腹中胀痛。食入不运，形气消索，面色无华，脉弦细。再延防成胀满。", "8844": "（案1）惊恐伤胆，抑郁伤肝，思虑伤脾，郁痰内扰神明，于是神思恍惚，力倦神疲，脉象弦滑。速当自开怀抱，打破疑团，庶可与药饵兼功。", "8845": "纪古称湔浣肠胃漱涤脏腑割皮解肌抉脉结筋此炼精荡形之术超伦希世之神其法不可攻矣三代以降汤液初兴方论始备十剂以准规矩七方以明绳墨补泻因乎虚实寒热合乎时宜症有真假恁脉而施治治分从逆临症而审机变化生克若易道之无方虚实奇正如兵家之有纪故一症有一定之论一方有万变之能未可寒热两歧攻补互似也非审脉验症辨明定治何能干旋造化之意耶东坡云脉症难明古今所忠至虚有盛候大实有羸状疑似之间生死反掌佩服斯言战兢自惧犹恐遗训在耳贻羞地下乃奋然鼓志研求灵素考据百家受知当世十有余年虽无回生起死之功稍有吹枯振槁之用或舍症而取脉或舍脉而取症或对症以定方或因方以立论楮陈墨迹累案盈儿矣及门二三子请付剞劂用广闻见于是不揣愚鄙聊录一二自知雕虫小技不合大道然而他山之石可以攻玉狂夫之言圣人择也则此刻或有道之所取裁乎敢以就正", "8846": "申江邹邑侯子含仲夏患泻精神疲惫面目青黄因素不服药迁延季秋忽眩晕仆地四肢抽搦口斜唇动篇体冰冷面黑肚缩六脉全无署中幕宾通晓医理各言己见或曰诸风掉眩法宜平肝或曰诸寒收引理应发散议论纷纭不敢投剂延予决之曰脾为升阳之职胃为行气之府坤土旺则清阳四布干健乖则浊阴蔽塞此自然之埋也今泄泻既久冲和耗散所以脾元下脱胃气十浮阴阳阻绝而成天地之否故卒然仆倒所谓上空则溃也况肝脾二经为相胜上脏脾虚则木旺肝旺则风生故体冷面青歪斜搐搦相因而致也若误认风寒的候而用发表之方恐已往之阳追之不返矣宜急煎大剂参附庶为治本合署惊讶见予议论严确乃用人参一两熟附二钱生姜五片煎就灌下一二时手指稍温至夜牛而身暖神苏能进米饮后以理中补中调理而安", "8847": "嘉定孝廉陆佑公长子童年发热偏尝凉药热势更炽昼夜不减复认阳明热证投大剂白虎禁绝谷食致肌肉消瘦渐致危困迎予往治见面色枯而不泽脉现细数力断大虚之证速用甘温之药庶可挽回佑老骇日皆言外感寒热无闲内伤寒热不齐今发热昼夜不已而反言内虚者必有确见愿聆其详予曰阳虚昼剧阴虚夜剧此阴阳偏胜因有界限之分今脾胃并虚阴阳俱病元气衰残阴火攻冲独浮肌肤表虽身热如焚而寒必中伏况肌肉消铄脾元困惫也彻夜无卧胃气不和也面无色泽气血不荣也脉象无神天真衰弱也此皆不足之明验若禁川五味则胃气益孤专服寒凉则生气绝灭宜晨服补中益气汤加麦来冬五味以培资生之本暮服逍遥散以疏乙木之郁兼佐浓鲜之品苏胃养阴庶元神充而虚阳内敛也令先饮猪肺汤一碗当即安睡热即稍减遂相信用药服十剂而精神爽快调理经年服参数斤乃获全愈", "8848": "常镇道尊陈么久患下血甲辰春召予调治诊得六脉安静右尺重按稍虚此命门火衰不能生土土虚荣弱稍微下陷而成便血之候盖土为生化之母堤防下气者经曰营出中焦又曰气因于中小者脚胃也为生气生血之乡升清降浊之职故胃盛则循经之血洒陈于外脚强则守荣之血滋养于中皆赖少火生气耳若元阳既亏离虚无以生坤坎满无以养良使脾胃衰残而清阳不升转输失化而阴血不统宜乎精华之气不能上奉辛金反下渗庚大肠也当用甘温之剂培中宫之虚升阳之品提下陷之气庶生长令行而阴血归藏方以补中益气加阿胶醋炒荆芥数剂而安", "8849": "保定文选张鲁彦少年登第纵恣酒色患便血四年午晨各去一次诸药杂投剂多功少延予调治诊其脉象两手浮洪断为肾虚火动之候盖血乃精化精充而血始盛阴随阳动阳密而阴乃固房劳太过则真水亏而虚火独发元气不足则闭藏弛而阴不固也遂以熟地山萸山药石斛归身白芍秦艽阿胶等煎成调棉花子灰二钱空心温服数帖乃愈", "8850": "协镇王公生长蓟北腠理闭密癸卯秋谒提台粱公于茸城乘凉蚤归中途浓睡觉恶寒发热缘素无病患不谨调养过食腥荤日增喘促气息声粗不能安枕更汗出津津语言断落不能发声延予商治六脉洪滑右寸关尤汨汨动摇以脉合证知为痰火内郁风寒外束正欲出而邪遏之邪欲上而气逆之邪正相搏气凑于肺俾橐籥之司失其治节清肃之气变为扰动是以呼吸升降不得宣通气道奔迫发为肺鸣一切见证咸为风邪有余肺气壅塞之征若能散寒驱痰诸病自愈乃用三拗汤（三拗汤麻黄不去根节杏仁不去皮尖甘草生用按此方治感冒风寒咳嗽鼻塞麻黄留节发中有收杏仁留尖取其能发留皮取其能涩甘草生用补中有发故名三拗）加橘红半夏前胡一剂而吐痰喘缓二剂而胸爽卧安夫以王公之多欲误认丹田气短用温补之品则胶固肤腠客邪焉能宣越顽痰何以涣解故临症之时须贵乎谛审也", "8851": "相国文湛持在左春坊时患左足下有一线之火直冲会厌燔灼咽嗌必得抬肩数次火气稍退顷之复来或用补中益气加肉桂服之更甚求治于家君脉两尺虚耎知非实火奔迫乃虚炎泛上然虚症之中又有脾肾之分脾虚者气常下陷法当升举肾虚者气常上僭又当补敛今真阴衰耗孤阳无依须滋坎之阴以抑离之亢乃为正治方以熟地四钱丹皮山萸各二钱麦冬钱半五味三分黄柏七分牛膝一钱煎成加童便一杯服四帖而虚火乃退左足遂凉参戎王丽堂夫佞佛长斋性躁多怒腹胀累年历用汤丸全无奏效延予治时腹大脐突青筋环现两胁更甚喘满难卧此系怒气伤肝坤宫受制之证前医但知平肝之法未知补肝之用所以甲胆气衰冲和暗捐清阳不升浊气不降壅滞中州胀势更增殊不知肝木自甚则肝亦自伤不但中土虚衰已也法当调脾之中兼以疏肝之品使肝木调达则土自发育耳拟方用苍术白术各钱半白芍广皮香附茯苓各一钱肉桂木香生姜皮各五分服后顿觉腹向胀宽喘平卧安后加人参调理而今瘥", "8852": "休宁汪振先夫人受孕八月胎前劳瘵肉削肌瘦环口黧黑舌色红润饮食如常六脉滑利状若无病予曰九候虽调形肉已脱法在不治所赖者胎元活泼真阴未散线息孤阳依附丹田譬之枯杨生花根本已拨胎前尚有生机恐五十日后虽有神丹总难回挽盖分娩之时荣卫俱离百节开张况处久病之躯当此痛苦之境恐元神无依阴阳决绝仅陈躯壳而生气杳然岂能再延耶越二月果子存母殁", "8853": "居君显子舍青年患疬因睡中惊醒即口眼歪斜嚼舌流血四肢搐搦学家惊异邀医用治痰不效干予诊视因其抽掣不常难以候脉但望面色黄中现青搐搦之势左甚于右经日东方属青入通于肝其病为惊骇况乎久患瘰沥则肝胆之气尝讥于外而阴血不荣于内偶因梦中惊骇触动肝火火旺而风生风生而摇动此自然之理也且四肢为胃土之末口目乃胃脉所过木气摇土所以㖞斜瘛疭夫舌属心脾齿属阳明阳明气盛则口噤心脾气盛则舌挺一挺一噤故令嚼舌宜用平肝之品佐以驱风清火遂用二陈汤加山栀枳壳钩藤羌活防风一剂而诸苦若失", "8854": "江右李太宰讳日宣有如夫人自耳至胁忽结核成块偏延疡科均以瘦愈治之反增发热体瘦口燥唇干饮食少进迎家君往诊脉左关芤而无力此肝血枯竭不能荣养诸筋故筋脉挛缩有似瘰疬而实非也若以败毒清火消痰化坚之剂投之则胃气转伤变症百出矣当滋养肝血以濡润筋脉为要方用四物汤加丹皮玉竹秦艽麦冬等剂不数服而痊", "8855": "内卿令乔殿史次君自幼腹痛诸医作火治气治积治数年不愈后以理中建中相间而服亦不见效特延予治六脉微弦面色青黄予曰切脉望色咸属肝旺凌脾故用建中以建中焦之气俾脾胃治而肝木自和诚为合法宜多服为重于画或甚于夜或饥饿而发或饱逸而止治皆不同殿史曰方饮食下咽便作疼痛得大便后气觉稍快若过饥则痛交阴分则贴然予曰我得之矣向者所用小建中亦是治本之方但药酸寒甘饴发满所以无效贤郎尊恙缘过饥而食食必太饱致伤脾胃失运用之职故得肝旺凌脾之候所谓源同而流异者是也今以六君子汤加山查麦芽肋其建运之机令无壅滞之患则痛自愈也服二剂而痛果止所以医贵精详不可草草", "8856": "庠生范啸凡令正向患头眩症六脉浮滑服消痰顺气之药略无效验予曰无痰不眩此虽古语然痰之标在脾而其本属肾素问曰头痛巅疾下虚上实此之诮也夫肝为乙木之本肾为癸水之源肾阴不充肝火便发上动于巅而眩作也治法以扶脾为主脾安则木自和而肺金有养金为水母而子亦不虚何而瘥", "8857": "大场张公享内正年逾四句伤子悲悯崩涌如泉用四物胶艾或增棕榈棉灰毫不可遏医颇明义理论阳生阴长无阳则阴不能生用补中益气以调脾培本势虽稍缓然半载以来仍数日一崩大如拳块彻夜不卧胸膈胀满势甚危殆邀予诊视面色青黄唇爪失泽四肢麻木遍体酸疼六脉芤虚时或见涩此病久生郁大虚挟寒之象夫脾喜歌乐而恶忧思喜温燥而怨寒湿若投胶艾止涩之剂则隧道壅塞而郁结作矣若专用升柴提举之法则元气衰耗而生发无由也乃以归脾汤加益智炮姜大剂与服四帖而势缓便能夜寐胸膈顿宽饮食增进调理两月天癸始正记前后服人参十六觔贫者奈河", "8858": "檇李孝廉沈天生夫人血崩不止势如涌泉医谓血热则行血寒则止四物加芩柏等剂两昼夜不减延家君往治诊其脉息安静全无病象肌体清癯原非壮实知为脾胃气虚不能摄血苦寒杂进反以潜消阳气须用甘温之品以回生长之令乃以补中益气汤加阿胶炮姜大补脾元升举阳气二剂而崩止以后调理渐安", "8859": "河间司李朱思皇长公令方夫人坐孕七月胎睡异常喘急不能言并不能卧者月余举家徬徨投药甚乱一医用人参白术以实脾一医改用商陆葶苈以润肺相去天渊益增疑思邀予决言予曰此症似危脉幸洪滑产前可保无虑即应分娩之后颇费周旋耳舍前两治余不过一二剂便狨安枕矣座中讶出言之易各言辨驳予据理折之日胃为清阳之海肺为元气之龠故呼吸升于丹田清浊输化赖于中土若平素膏粱太过则中州积热况胎孕内结则相火有余至六七月以来肺胃用事胎渐成大故胎气愈逼而火愈旺凑逆于上喘呼不卧名曰子悬者是也兹用参术丫补则肺气壅塞若用葶苈苦寒则胃气孤危均致变症蜂起岂非实实虚虚之患乎疏方用苏梗枳壳腹皮各三钱茯苓陈皮半夏各钱半甘草五分生姜三片一帖便能言再剂则安卧合门信为神丹余曰无欢也胎前喘急药石易疗恐临盆在迩其喘复生虽灵丹在握不能为也须预备奇策调护真元不致临产涣散乃可万全不数日产一子甚觉强健越两日喘果复作惊呆无措进食亦减常时此胃土虚而不能生金之象以大剂参术苓草五味肉桂数剂乃安", "8860": "歙人方李生儒人向患左胁疼痛服行气逐血之剂反加呕逆甚至勺水难容脉左沉右洪明属怒动肝火来海脾阴过投峻药转伤胃气俾三阴失职仓廪无由而化五阳衰惫传道无由而行所以中脘不通食反上涌斯理之自然毋容议也方以异功散加白芷肉桂于土中泻水并禁与饮食用党参五钱陈仓米百余粒陈皮一钱生姜三钱加伏龙肝水三碗煎耗一半饥时略饮数口二三日后方进稀粥庶胃气和而食不自呕依法而行果获奇效", "8861": "柯霭宁患吐血后咳嗽连声气喘吐沫日哺潮热服四物知柏后兼服苏子贝母百部丹皮之属病势转剧乞予治之六脉芤耎两足浮数知为阴枯精竭而孤阳气浮俾肺金之气不能归纳丹田壮火之势得以游行清道所以娇脏受伤喘嗽乃发理应六味丸加五味沉香导火归源但脾气不实乃先以人参白术黄耆山萸山药各一钱五分石斛丹皮各一钱五味子念一粒肉桂五分服数十帖大便始实改用前方调养月余咳嗽亦瘥后三年前病复发信用苦寒遂至不起", "8862": "云间田二府封翁久泻肉脱少腹疼痛饮食下咽泊泊有声才入贲门而魄门已渗出矣或以汤药厚脾或以丸散实肠毫不见效几濒于危召予力救望其色印堂年寿夭而不泽切其脉气口六部细弱无神则知清阳不升原阴下陷非但转输失职将见闭藏倾败矣盖肾者胃之关也脾之母也后天之气土能制先天之气肾可生脾良由坤士是离火所生而良木又属坎水所生耳故饮食入胃如水谷在釜虽同脾土以腐熟亦必藉少火以生气犹上万物虽始于土皆从阳气而生长彼生生化化之气悉属于一点元阳所谓四大一身皆属金不知何物是阳精也惟命门火衰丹田气冷使脾脏不能运行精微肠胃不能传化水谷三焦无出纳之权五阳乏敷布之导升腾精华反趋下陷故曰泻久亡阴下多亡阳阴阳根本悉归骨中若徒知补脾而不能补肾是未明隔二之治也宜用辛热之品暖补下焦甘温之剂资培中上譬之炉中加火而丹易盛灯内添油而燃不息真有水中火发雪里花开之妙何虑寒谷之不回春耶遂用人参白术炮姜炙甘草熟附子煎成调赤石于末三钱与服渐觉平安十剂而痛止泄减面色润泽饮食增进不一月而全愈乃蒙赐顾缱绻竟日而去越明年春田公觐还父子重逢喜出望外不意过食瓜果前症复发竟难挽回卒于仲夏庚寅日可见木旺凌脾之验毫发不爽也", "8863": "庠生奚易思令正发热腹痛呕恶不食六脉沉郁面黑如薰用解郁调中之剂前症渐愈若感怒气应必复发半载以来形神憔悴小便涩痛小腹重坠延予治之予曰症瘕痞块多属中脘发则形象可求痃癖两症贴在脐旁发则攻冲而痛数症皆水道通利者也今小水涩滞少腹重坠必身皮甲错绕脐生疮此系下焦肝火久郁不舒已成小腹痈也非予专门应疡科调治庶可奏效延医治之果如予言越数日而痈溃脓色稠紫服托里养荣等剂月余而康", "8864": "除敬山伤寒郁热过经不解愈后食复谵语神昏剌高胎黑耳袭加愚六脉洪大此阳明胃热血化为斑之状乃燃灯照其胸腹果紫斑如绿豆大者期如列足但未全透于肌表宜清胃解毒使斑点透露则神清热减矣用竹叶石膏汤二剂壮热顿退斑势掀发但昏呆愈甚厉声呼之亦不醒觉将身掀动全无活意惟气尚未绝俱云死矣予复诊其脉两手皆在不过虚微耳盖此症始因胃热将腐先用寒凉以解其客邪今邪火虽退正气独孤故两目紧闭僵如死状急用补胃之剂以醒胃脘真阳生机自回也即以生脉散合四君子汤一剂至夜半而两目能视乃索米粥以后训理渐安", "8865": "燕京礼垣房之麟患伤寒五日病势困殆伊亲在太医院者七人莫能措手延家君治之脉人迎紧盛右关洪大神思若狂舌胎微黑此邪热拂郁神思昏愦而如狂亢阳煽炽火极似水而舌黑炎炎蕴隆将成燎原若非凉血火将焚矣视其胸腹果有红斑遂用化斑清火一服顿愈", "8866": "分镇符公祖恭人形体壮盛五旬手指麻木已历三载甲辰秋偶感恚怒忽失声仆地痰潮如锯眼合遣尿六脉洪大适予往茸城飞骑促归缘符公素谙医理自谓无救议用小续命汤俟予决之予日是方乃辛温重聚利于祛邪妨于养正其故有三盖北人气实南人气虚虽今古通论然北人居南日久服习水土卑禀更移唐腠亦疏故卑下之乡柔脆之气每乘虚来犯致阴阳颠倒荣卫解散而气虚卒中此南北之辨者一况中风要旨又在剖别闭脱夫闭者邪塞道路正气壅塞闭拒不通脱者邪胜五内心气飞越脱绝不续二证攸分相悬霄壤故小续命汤原为角弓反张牙关紧急闭证而设若用于眼合遗尿之脱证是既伤其阴复耗其阳此闭脱之辨者二又风为阳中阴气内应于肝肝为阴中阳脏外合于风恚怒太过大起肝胆内火外风猖狂扰乱必然挟势而乘脾土故痰涎汹涌责脾勿统摄肾不归经滋根固蒂尚恐不及若从事发散是为虚虚此真似之辨者三灵枢所谓虚邪偏客于身半其入者内居荣卫荣卫稍衰则正气去邪气独留发为偏枯端合此症当法河间东垣用药保全脾肾两脏庶可回春亦以六君子加黄者白艾桂枝钩藤竹沥姜汁服二剂恶症俱减脉亦收敛俣声哑如故此肾水衰心宙枯槁至更余后火气下行肾精上朝方能出音遂用地黄饮子服至十五剂大便始通坚黑如铁虽有声出状似燕语乃朝用补中益气汤加五味麦冬以培脾夕用地黄汤加肉苁蓉当归以滋肾调理百日语言加旧步履如初怛右手稍逊于前耳", "8867": "茂才虞葛来少年多欲醉饱无惮初患胁痛继而嘈杂渐成反胃医久无效邀家君往视见面色如土面上两颧稍带赤色六脉细数食饮即吐历览前方颇不相胶但四君理中频服不瘳知病不独在中州也信为无阴则吐耳况诸呕吐皆属于火而季胁又属肝肾之乡即以地黄汤加石斛沉香愈后一载秋前旧症复发适家君有携李之行于予诊治左关弦长知怒气伤肝故现独大之象用加味逍遥散而安又两月因劳忍肌恣酒感怒前症蜂起较前尤甚六脉虚耎胁痛胀闷卧则气塞欲绝此大虚而得盛候为脉证相反法在不治伊父强请立方仍用逍遥散更医用小建中汤二寸余剂胁胀稍宽痛则仍在咯血稠痰醒秽难近复干余治往者虚耎之脉变成蛛丝之细两眸露白气促声嘶脾元大坏肺气孤危此肺痿之恶候也时冬水将弱春木方强延于冬者得肾水之相助也记初十立春木气临官肺受其侮脾受其乘岂能再延耶果殁于初十之寅时", "8868": "素君素多劳动因乘暑远行遂胸臆不宽呃忒连发八日以来声彻邻里自汗津津语言断落汤药偏尝毫无效果举家惶恐特干余治现症虽脉尚有根况准头年寿温润不晦法令人中光泽不枯若论色脉生机犹存但徒藉汤丸恐泄越之阳不返潜伏之阴难消常先用艾火灸期门三壮并关元气海诸穴再煎大剂四君子汤加炮姜肉桂为佐丁香柿蒂篇使内外夹攻譬之釜底加薪刚蒸气上腾而中焦自暖四大皆春何虑阴翳之不散真阳之不复耶果一艾而呃止再进而全愈共骇为神奇云间司李王公伤风鼻塞周身刺痛欲用表剂邀余商治六脉浮虚予曰风为阳邪卫为阳气阳与阳合则伤表分病虽属标而治则求其本盖肺主皮毛司开阖充元气主清肃者也清阳不发腠理空疏外来风邪内舍肺分经曰邪之所凑其气必虚正谓此也法宜东垣先生补中益汤补中兼发乃谓至常王公曰可服一剂而诸病捐除", "8869": "徽商朱圣修内人呕逆吐食出多入少皆利痰白沫眩晕气急半月有余大肉尽消治者咸谓反胃谓吐沫脾败已无救矣于余调治手少阴脉动甚两尺滑利为结胎之兆而见恶阻之候非翻胃也用人参橘红白术半夏苏梗桔梗赤苓砂仁枇杷叶伏龙肝水煎服三剂而吐减数剂而全瘥后产一女", "8870": "龚姓妇产拍发痉口歪不语角弓反张时或梢愈顷之复作诸医皆用风治予曰肝为藏血之乡风水之司也肝气为风肝血为水流则风息而筋脉舒古人云治风先治血信有矣况产后气衰于表血衰于里气衰则腠理疏而外风易袭血耗则肝木枯而内风煽动故血不养筋则角弓反张风淫胃脉则唇口引动常用滋润之品内养肝血直补其虚少佐驱风之剂使同气相求得以易入用四物去芍药加羌活防风独活钩勾酒炒荆芥两剂而愈若用辛散则风能燥血辛走阳气适滋其困矣", "8871": "遂安令曹缘岩长君安初少年嗜欲真元素虚已亥秋丁内艰悲恸大过内火燔灼肾水干涸肌肉顿消咳咯脓血腥秽异常延予商治六脉洪大重按虚豁右寸独数此上盛下虚之候夫上盛者赫曦过极肺中之假阳旺也下虚者涸梳衰竭肾家真阴虚也阴虚则火独发坎宫津液上腾救母浸浸炽灼反成稠痰浊阴胶结于清虚之脏久而肺热叶焦腐化为痈若不求本而治则肾阴愈虚邪火更旺痈将溃也法当先清上焦痰火保定肺气以麦冬沙参紫菀贝母橘红茯苓甘草桔梗瓜蒌霜等五更时服复用六味汤加麦冬五味大剂临卧服以滋化源数帖而痰清嗽减一月而精充神复越三载因感于邪术广图婢妾以自娱前症复发卒至不救", "8872": "晋中商人高鸣轩年六旬外久历鞍马餐风冒雾六淫之邪袭其经络染成痿废已三年矣偏访名医咸以解表为治两足愈觉无力顽麻不仁辛丑夏初适过海邑告余服药累百不获少瘥自信此身永废矣予曰风寒湿气乘虚而入不思养正以补其本一误也屡解表而风邪已去犹然发散愈损真元二误也且气虚则麻血虚则本人有恒言是症必为中风先兆乃以神效黄耆汤加肉桂服之才四帖麻顿去便能却杖而行后以还少丹调理月余倍常矍铄德州都谏王介清丁内艰患左胁顽痹足腿麻木按摩片时少堪步履服清火消痰补气活血病势不减后服阕人凉邀家君诊视见伊肾肝脉虚断为肾虚不能生肝肝虚不能荣血水亏血耗经隧枯涩之症先以四物汤加秦艽石斛牛膝葳蕤不数剂而胁痹顿除后服肾气丸一杯永不复发", "8873": "秦商张玉环感寒咳嗽变成哮喘口张不闭语言不续呀呷有声外闻邻里投以二陈枳桔毫不见减延予救之诊六脉右手寸关俱见浮紧重取带滑断为新寒外束旧痰内搏闭结清道鼓动肺金当以三拗汤宣发外邪涌吐痰涎为要若畏首畏尾漫投肤浅之剂则风寒闭固顽痰何由解释况经曰辛甘发散为阳麻黄者辛甘之物也夏天地轻清之气轻可去实清可利肺肺道通而痰行痰气行而哮愈矣乃以前药服之果一剂而汗出津津一曰夜约吐痰斗许哮喘遂平越二年因不忌口复起前证而殁", "8874": "茸城朱公亮令媛血枯经闭已年余矣大肉去半饮食减少日哺寒热至夜半微汗而解予诊其脉两手细数证属难疗素问二阳之病发心脾有不得隐曲女子不月夫心统各经之血脾为诸阴之首二经乃子母之脏且气恒相通也病则二脏之气乘涩荣血无以资土故地道之不行由心脾之气不充也张洁古师弟首重内经一以训荣培土为主而薜新甫将逍遥归脾二方为用使气血旺而经自通若不培补其源反以消坚破硬苦寒伤胃通道癸水为捷径殊不知愈攻则虚而愈闭且生生之源从此剥削殆尽直至风消贲闭虽有神丹难为治矣不信予言专行通道竟至不起", "8875": "嘉定庠生沈来壅食后感寒头疼发热胸膈胀满医用表散消导虽胸次稍舒寒热愈剧反增神昏不寐已三传经矣一医因病久症虚议用温补一医颇明医理复尔消导议论多端过予决之六脉弦数不和与寒热往来大便溏而小便赤此少阳经症不可汗下与渗利转犯他经只宜和解其邪易散纵有食停俾邪气解而食自消此仲景先生之秘旨也竟以小柴胡汽去人参加丹皮炒山栀花粉冬一剂而神清气爽寒热亦定", "8876": "上洋王邑尊幕宾张姓盛暑发热至六七日昏沉不语面赤苔焦与水则咽大便不通身艰转侧医者束手投柬招治予诊毕谓王公曰病虽危候脉象和顺况身体软缓唇吻红润气息调匀俱为吉兆只因邪热传入手少阴经郁而不舒所以面赤昏呆口噤不语乃以导赤散加黄连麦冬佐犀角少许加灯心竹叶煎成用刷脚抉开口徐徐灌下片时觉面色稍退再剂而目开能视三剂而语言如旧后调理乃安", "8877": "李元吉妻半产后血崩如注头晕眼暗饮食少进面色青黄六脉虚大无力甚至昏量不苏一日数次延予治之予曰血脱益气阳生阴长灵枢之旨也况阳为阴之使阴为阳之守今久患崩中宜乎几微之时而欲绝奚能固其内守之阴所以经流不竭皆阳气不能卫外故也若从事养阴止涩是人已入井而又投之以石耳用补中益气汤加五味艾叶服之势不稍衰予思古语云大虚必挟寒再以人参一两熟附一钱煎成呷下乃熟睡片时醒来晕减神清后以养荣汤去肉桂加附子调理而安", "8878": "雷廉道潘畏庵乃郎自幼腹痛向以内伤调治时或见愈不能社根庚子春过龙华扫墓归由巨浦而前适风雨骤至银浪排山泊舟小港因而受饥忍寒痛遂大作邀予往治左手脉皆弦迟右寸关虚大无力盖此症因饮食过饱伤其中州嗣后食虽消而大阴分野犹然损伤故一有不调痛即随至况历有岁时中脘之阳不布畜积痰涎结成窠臼即内经云未传寒中之谓也若不用温补辛散之品其沉郁久凝之疾焉能转否为泰乎用异功散加桂枝半夏炮姜木香为粗末姜煎服痛即止后照前方加益智仁白芍神曲姜汤和丸后不复发大学士徐元扈夫人胃脘痛初以气治次以食治继以火治总不见效痛至昏□良久复苏延家君治之曰夫人尊恙非气非食亦非火也由劳碌太甚中气受伤脾阴弱而不化胃阳衰而不布阴阳并虚仓廪壅滞转输既弱隧道失运所以浊清相干气血相搏而作痛者若用消导则至高之气愈耗误投寒剂则胃脘之阳益伤为今之计非补不可虽云痛无补法此指邪气方锐者言也今病势虽甚而手按略止脉气虽大而重按稍松则脉症俱虚不补而何用六君子汤加香附砂仁一剂而眩定痛止", "8879": "疁城王五松子舍大肉削去虚气攻冲症情恍惚手足麻木不能自主夜寤不宁咸谓心脾之气涣散所以脉络胀张如不束之状所谓解㑊者也盖阳明为气血俱多之乡主束骨而利机关者也阳明戊土一虚必盗母气自养而心亦虚以灵枢云心怵惕思虑则伤神神伤则恐惧自失破㿉肉脱矣治宜补心脾之气以充元神之用可指日而奏功乃与归脾汤服数帖而始止", "8880": "燕山中丞刘汉儒泄泻数日医见肝脉弦急认为火热用苦寒平肝掇洞泄不已筋挛少气招家君往治日此因寒气入腹清阳不能上腾即素问清气在下则生飧泄之意也前医以肝脉局为火予以肝脉盛为寒盖寒束之脉每多见弦先哲明训班班可考何得以寒为热耶方以苍术白术各二钱羌活防风各一钱干葛炮姜各八分升麻柴胡各五分一剂而减", "8881": "上洋秦斋之劳欲过度每阴雨左足麻木有无可形容之苦历访名医非养血即补气时作时止终未奏效戊戌春病势大作足不转舒背心一片麻木不已延予治之左脉沉紧右脉沉涩此风湿寒三气杂至合而为痹其风气胜者为行痹寒气胜者为痛痹湿气胜者为著痹著痹者即麻木之谓也明系湿者邪内著痰气凝结郁而不畅发为著痹须宣发燥湿之剂加以报使之药直至足膝庶湿痰消而大气周流也方以黄耆苍术桂枝半夏羌活独活防已威灵仙数帖而痊若以斋之多劳多欲而日服参耆壅瘀隧道外邪为能发而病安能去乎", "8882": "海宁相国陈素庵病足肿痛用补血药则肿愈甚用补气药则痛益增延家君往治诊其脉耎而气滑属湿痰流注下焦为有余之症定非不足也若滋阴则壅沉滞阳气若补阳则胶固经络此病之所以增进也用陈皮茯苓半夏独活苍术厚朴桔梗灵仙两服痛减肿消故虚虚之祸世所共戒实实之殃人每蹈之若从执补养之法是未明标本缓急邪正虚实之机也乌足以与议道哉所以动人立法专主驱邪诫虑夫补实之祸以救未流时弊耳", "8883": "皖城玉山王学师子舍产后早服参耆致恶露不尽兼因过于恚怒变为臌胀菁筋环腹神阙穴出延予商治左手脉皆弦劲重按则涩右手洪滑此下焦积瘀怒气伤肝以致是症夫畜血之候小腹必硬而手按畏痛且水道清长脾虚之症大腹柔软而重按之不痛必水道涩滞以此辨之则属虚属实判然明矣王翁日是症为积瘀不行无疑矣前治皆模糊脉理洞投药石所以益增胀痛今聆详辨洞如观火请疏方为感遂用归梢赤芍香附青皮泽兰厚朴枳实肉桂元胡等加生姜间投花椒仁丸三服数日后胀痛悉愈张侍川脾泄经年汤药遍尝大肉尽削小便枯竭势已危殆余往诊之方脉弦细右脉虚微此系干阳不运坤阴无权所以脾伤而破㿉肉脱肺虚而气化失调俾浊阴不降内滞肠胃清阳不发下乘肾肝由是三阴受伤而成久泄之症况当四十年之升阳之气与浊阴之令自此相半今侍川已逾五旬不思举其下陷之阳反以渗利为用则失治本之旨矣且下久亡阴未有久泄而肾不虚者若单补其脾则力缓不能建功须得温暖下焦之品辅佐其脾间丹田火旺则脾土自温暖中州健运则冲和自布精微之气上奉干金下输膀胱分别清浊则二便自和可以指日收功矣方用人参白术黄耆炙草广皮木香升麻柴胡肉巢补骨脂数剂而小便亦实后以四神丸加煨木香调理乃安", "8884": "家君治江右太师傅继庵夫人久泄不已脉象迟微微为阳衰迟为阴胜此脾土虚而真阳衰也盖脾虚必补中而后土旺阳衰必温中然后寒释乃以四君子加姜桂服二剂而畏寒如故泄亦不减知非土中之阳不旺乃水中火不升也须助少火之气上蒸于脾方能障土之湿遂用人参三钱白术五钱肉桂一钱附于一钱数帖渐瘥从八味丸调理乃安春元唐次仲小腹脐傍刺痛连胁及胸坐卧不安余诊六脉弦滑重取则涩此食后感怒填寒太阴致肝气郁而不舒胸困作痛经日木郁达之解其郁而痛自止用二陈汤合平胃散加枳壳木香一服而愈秣陵罗明求奉藩摧饷适感风寒发热恶寒头疼而体痛至七日后变成温疟发时惊骇异常日哺见鬼如二岁童子大者数十缠绕腰间悚惧不堪至晚方散已五六发矣治者皆篇鬼疟议用截法然犹未决过余诊视六脉洪滑余曰此系痰涎内积非真邪祟外干也古语有云无痰不成疟又曰怪病多属痰盖痰乃液所化液乃肾所主必平日肾水素弱虚火独旺煎熬精液成痰攻冲经络而为疟之根本况腰原属肾其液化痰更无疑矣惟先服其痰俟痰去而疟鬼自除然后培补本原至为切当遂用小柴胡汤加茯苓枳壳槟榔临服调元明粉三钱顷刻便润下积痰甚快至明日而疟鬼俱绝", "8885": "句容孔太师随朝使者每至午余无端见鬼恐惧昏沉夜半发热黎明始苏诸医用安神养血之药继投导痰顺风之剂均无效验邀家君诊视两手脉现滑数此因沉湎于酒酒能生湿湿能助火火湿相合而成痰痰迷心窍则见鬼即以橘红贝母天花粉干菖蒲黄苓麦冬山栀竹茹苦丁茶二服而神清鬼没四剂而平复如初", "8886": "胡文宰子舍向患怯弱乙巳季夏方饮食后忽腹中绞痛自谓著暑调天水散一服不愈又疑停食进山查麦芽汤其痛更增发厥昏晕无有停歇中脘硬痛手不可近两眼露白舌缩谵语状若神灵延医调治或日大便实而用□朴或云积暑而用芩连诸药杂投病势益增当事者咸疑惧无措余独谓虚症力主大补之剂盖平昔脉弦洪兼数且右手更旺今也转数成迟左手更觉无本根此至虚有盛候恁脉合症之良法急煎理中汤加陈皮半夏与服庶胃气充肺元阳流动总有蓄积盘踞方隅定然向风自化果一剂而稍安数剂而全愈", "8887": "慈溪天生杨先生馆江湾镇时值盛暑壮热头痛神昏发斑狂乱不畏水火数人守望犹难禁止甚至舌黑刺高环口青暗气促眼红谵语直视迎余往治余见众人环绕蒸汗如雨病狂躁无有休息寻衣摸床正在危候强按诊脉幸尚未散急取筋头缠绵用新汲水抉开口凿去芒剌即以西瓜与之犹能下咽乃用大桶置凉水并洒湿中间空地设席于地扶忠者卧上再用青布丈许折作数层浸湿搭在心间便能云顿入清凉世界六字语虽模糊亦为吉兆遂用大剂白虎汤与服加黄芩山栀元参半日之间狂奔乱走目无交睫此药人口熟睡如泥乡人尽曰休矣余曰此胃和而睡著也不可惊觉自日中至半夜方苏其病遂愈", "8888": "吴明初平素体弱因年来忧郁忽然呕血自蚤至慕百余碗两目紧闭四肢畏寒冷汗如注汤药人口随即吐出举族惊狂迎余视之幸病虽为急脉尚未散喘促犹缓一线生机尚可挽回若以血药投治则不及矣盖初则血随气上今则气随血脱语云有形之血不能速生几微之气在所急固此阳生阴长之道寓诸灵素扶阳抑阴之权具于羲易诚以阳者生之本阴者死之基故充塞四大温润肌肉皆赖此阳气耳今脉气虚微天真衰败也汗雨不收卫气散失也四肢畏冷虚阳不能旁达也两目紧闭元神不能上注也药入即吐继之以血者乃呕伤胃脘守荣之血不藏也为再用汤药恐激动其吐宜设计以取之遂用人参一两内芨四钱均为细末米饮调丸如樱桃大含化自黄昏至一更约用一半汤饮方通血亦不吐至明日神思稍清脉气夫静似芤似革参互不调全无胃气尽属阴亡于中阳散于外之象乃速煎参附进之以追散失之元阳八日内记服人参二斤附子五枚而元气顿充脉始收敛至今强健倍常徜此时稍有疑虑从任浅剂焉能挽回其真气耶", "8889": "上海邑尊陈虞门慕宾吐血不已或用犀角地黄汤降火或以加味四物汤滋阴绝谷数日气喘随毙延家君诊治六脉虚弱精神怠倦明属思虑过度脾元亏损所以气衰则火旺火旺则血沸而上溢也血脱则气孤气孤则胃闭而绝谷也法当甘以脾脾温以启胃甘温相济脾胃调和庶元阳得以扶持气血有所生长耳遂用四物汤加米仁石斛麦冬五味广皮桔棚数剂而愈", "8890": "吴淞一女在闺时患左眼上胞内生疙瘩日渐长大下垂遮目红肿重坠痛楚异常端科者始以驱风治标继以养血治本迁延岁月未获稍减余诊其脉左关弦强搏指右关妈涩予曰目廓应肝内轮应脾肝脾二脏性喜疏利故忧思伤脾则气结而血瘀恚怒伤肝则气郁而热生由是火炎血沸上腾空窍目廓积闭火旺赤肿也治宜疏中宫之滞泻东方之实则郁开火降瘀化肿消耳用龙胆泻肝汤数帖疙瘩渐消复以六味丸料加龙胆草白蒺藜决明子牡蛎与滋阴之中兼以清火之品逾日而平复", "8891": "周文怕乡居课农偶发寒热解表一剂转觉神思恍惚日增倦怠目呆如愚语言错乱昼夜呻吟六脉微弱不堪重按余曰是症之因必有大惊损伤神气故现神鬼飞越之象盖神藏于心心主镇静魂藏于肝肝主惊骇故惊则气乱心失镇静之当神气孤浮邪入神明之窟由是魂无安宅飘荡于外若能安神益气固守飞扬之真自然魂随神摄可复清明之职丹书所谓神是性兮气是命神不外驰气自定者也遂服归脾汤数帖灵动如初自述病概缘溪头失足从高坠下遂觉神气越出精采不定作见游魂须眉状貌酷肖己身约长尺许或从空行走或相依同寝所谓魂离吾体断不诬矣自后稍有震怒惊呆复作屡用前方获效后迁于城道逢形人因而受惊至晚忽大呼杀入举家骇异议用前药值余适至复诊其脉弦强搏指较前大异此正虚祟乘之病非从前神脱魂离者比也治当清痰降火祟是不作若用参耆胶固邪气将成痼疾矣乃以温胆汤加苏子黄芩山栀瓜蒌服即熟睡醒来诸病如失但觉倦怠乃淡粥调养数日后仍服归脾汤而全愈则知鬼岂真鬼那", "8892": "蒌江金公采谋秋患痢昼夜百余次赤脓腥秽呕恶不食口渴发热向用滞下法竟难奏效忽冷汗不止四肢如冰气促神昏延余往治外证虽逆六脉尚存乃煎附子埋小汤服二剂四肢渐温自汗渐收又服数帖精神充旺痢下顿除若抱痢之赤白口渴身热再投凉药气将脱矣故曰泻虚补实神失其室此之谓也", "8893": "淮右章公克壬寅春客游海邑患温病发热邪气再传壮热神昏濈濈自汗眼红面赤口渴舌黑胸膈满闷势甚危殆医者泛用清热轻剂以冀幸免余曰春温之温邪伏藏于冬触发于春随天气化寒郁为热此时令之热也脉来洪大舌黑口干灼热汗流神思昏□此脉症之热也当速煎甘寒大剂清彻里邪庶不使胃热腐化若从任芩连诸药恐一杯之水难救车薪之火势必自焚矣立方用石膏五钱麦冬二钱知母花粉各一钱五分山栀一钱甘草五分加竹叶粳米灯心为引二剂而神爽热除", "8894": "大名司理陈玉山素患胸膈胀闷四肢顽麻六脉坚劲似芤类革咸属冲和虚损清阳散耗之症用六君子汤加益智肉桂以培脚并进金匮肾气丸一料已恶粒米不进者二十余日六脉顿退重接豁然予曰脉为神机神为气立全赖胃气充沛者也今脉息无神则知郁结伤脾脾病传胃俾磅礴浩大之气停留郁滞于中所以胃脘否满者脾主中州也右胁胀痛者坤出西南也况木虽条达依土为生土既硗薄木无生长此物理中之常耳故郁怒太过不但重损脾阴而肝亦自病所以不能藏血而血瘀血去而阴伤阴伤则阳无以自主将有飞越之虞也速宜培养元神不使涣散乃可万余遂用附子理中汤数帖食能惭进后用六君子汤兼八味丸而安", "8895": "文学包曰余因食蟹腹痛发则厥逆逾月不已延余商治述前服平胃二陈继服姜桂理中不但无效反增胀痛余曰痛非一端治亦各异感寒者绵绵无间因热者作止不当二者判若霄壤尊恙痛势有时脉带沉数其为火郁无疑虽因食蟹然寒久成热火郁于中热郁似寒厥冷于外此始末传变之道明训可考察何执泥虚寒漫投刚剂是以火济火求愈岂不难哉以四逆散加酒炒黄连一剂而愈", "8896": "又：辛凉解散后，大汗遍身，斑疹齐出，头痛畏风随之而愈。在表之邪，从表而出，表气和矣，未始不美。无如在里热邪，布于三焦，聚于阳明，正属不少，肌肤蒸热，舌苔于黄，胸前痞闷，便泄溺黄，脉形弦数，尚恐反复。", "8897": "牛（关上）病经六日，述已经大汗而身热不退，头痛节酸，舌苔尚白，口已干苦，痞闷按痛，耳聋溺赤，脉紧而数。此系温邪夹湿，招风以起，夹食难消，其势正在张皇，每多传变。慎之。", "8898": "又：进前剂，热退身凉，邪已解矣。然散而留者，舌上白苔，变作嫩黄之色，口鼻干燥，神倦妨食，溺黄脉数，清化为宜。", "8899": "又：达原之后，病从战汗而解，此方之灵，于郡中者鲜矣。然白㾦转黄，黄者里有伏邪未尽，所以脉静身凉，口干咽痛，容易发作，不能不虑。栝贝养营法主之。", "8900": "又：栝贝养营汤后，自云无病矣。然脉虽虚，口尚干燥，津液未润之候。养营一法，在所必需。", "8901": "又：病情如昨，舌上之白苔化作嫩黄，脉来不浮不沉而数，身热少汗，口仍干苦，烦热不寐。提化为主，如不战汗，必变端。", "8902": "又：（师转）已进解毒法，青紫之斑更多于昨，紫黑之血仍盛于今。身之热，口之臭，便之黑，种种见症，毫无向愈之期。温毒之伏于中者，正不知其多少，然元气旺者，未始不可徐图。而今脉息虽数，按之少神，深恐不克支持，猝然昏喘而败。", "8903": "又：（琢转）青紫之斑，布出更多，紫黑之血，尚涌于齿，口舌糜烂，口气秽臭。温毒之极重极多，不可言喻，大清大化，本非难事。无如脉之无神者，更见数促，神气更疲，面青唇淡，一派无阴则阳无以化之恶候。古云：青斑为胃烂，此等证是也。勉拟方。", "8904": "姚（常熟。）恶寒无汗，之下，身热不除，甫经三日，神气渐昏，不知人事，面垢遗尿，谵语时甚致肢动头摇，气急痰声，口干苔剥，脉弦滑数，左右无神。暑先入心，亦必伤气，都被冷风外遏，袭入手足厥阴，有进无退，骤变之形已露，奈何奈何！勉拟方以尽医力。", "8905": "又：头之摇、肢之动、言之乱、神之昏，患在手足厥阴者皆有和意；且面垢时笑，循衣摸床等象，亦能递减，似属佳兆。然十分病仅衰一二，而身有微热微汗，胸次不舒，得汤如噎，舌苔灰腻，口中干燥，自云心内干热，大便旁流，矢气下转，脉弦滑数。暑风湿热痰食交阻之邪。布于三焦者，正属不少，必须凉膈清心以分其势，再论吉否。", "8906": "又：汗收加热，舌尖光红，脉来弦数，尺部软弱，痉象略重，此暑伏营中，暗伤津液，似疟而作也。尚恐热极变端，必须天明以前微汗而解为正。", "8907": "又：左脉稍和，右仍数滑，风之动者虽轻大半，而心包部分，尚属若明若昧，身热微汗，黄昏则剧，小溲频数，肢体易痉，舌苔灰浊，胸脘不舒。显系手足厥阴之邪，欲归阳明中土，土中之暑邪湿热，结秘不开，气皆受病也。病在险途，未便小安为慰。", "8908": "又：小便频数等症，霍然而愈，毋庸论矣。就脉数，左小右大，舌尖稍红，口中干燥，夜频少寐，神亦少慧。阴虚邪恋之时，又值立秋大节，小心反复。清化余邪之法，参人养阴之中。", "8909": "又：神明已出，肢体更疲，言语亦觉无力，脉平而带小数，小寐妨食，舌色尖红，口时干燥。病渐退，正益虚。仿七虚三实例，拟甘寒除热法，仍不出暑邪调治之范围。", "8910": "张：（长兴。）失血之体宜补，前病之后，元虚不复亦宜补，正在虚则补之之候。小有寒热，虚更甚矣，尤宜大补。然脉形细小而按其至数则数，察其形象则滞，加以寒热分争，争于午后，胸前痞闷，舌苔满白，口中干腻，小溲色黄，大便或溏，咳嗽时作，头痛体酸，一派暑邪内伏，出入于少阳，阳明之界，又须提化时也。斟酌为宜。", "8911": "杨（上塘）咳嗽臭痰，口中辟辟燥，胸前隐隐痛，已经半载有余。脉形虽然变小而数疾有力，肺痈之根底不清，不宜再延，延则声音渐烁，反成肺痿，不可救药也。近来气息短促，肺金不能当令而旺，更恐其喘。", "8912": "孙（常熟）紫云风后上病于牙关，下病于腿骱，能溃而不能敛，元气因虚，余毒又走下腿，骱中强痛不和，脉弱色痿，神倦妨食，自汗嗌干心悸。虚证百出，必须大补。", "8913": "候（上海）舌乃心之苗，其所用事者包络，所主相火，升之于舌，舌自作疼。痛经百日之久，津液暗伤，舌色光绛而不生苔，甚至相火自戕根本。两目昏眩，右关脉息弦数，左寸关部更甚，恐其不愈，将口糜接踵而至。", "8914": "徐：（三乡庙。）脾为生痰之源，肺为贮痰之器。咳嗽久而未轻，晨起更重，所吐之痰，稠稀不一，舌苔薄白，脉息小弦。欲清贮痰之器，庶必先绝生痰之源。然乎？否乎？", "8915": "周（濮院）脉数而涩，阳络频伤之后，咳呛少痰，胸膈痞闷，喉痒干渴，少纳便结。酷暑内郁，化火伤阴，肺失清肃也。不宜久延，延则成损。损之所致，有外邪也，与本来劳怯者有间。燥令大行而遇此症，当以西昌法。", "8916": "马（无锡。）咳嗽久而已缓，尚易吐血，右关脉数且急，阳明伏热使然。", "8917": "吴（横泾。）培养脾肺，兼化火邪，夜来得寐，而其所患咳嗽减矣。然减不足言，尚形咳逆，吐出咸痰，喉痒口干，胸闷脉数，将泻白散加味用之。", "8918": "朱（海宁）咳嗽脉数，左关浮大，风邪深入肝经，化火伤肺也。咽痛音烁嗌干，恐其成损。", "8919": "又：血有所归，今日止矣。然石脉芤大，尚属气分大虚，不能摄血之象。血脱益气之法，正为此等证而设，当取之。", "8920": "吴（横泾）阳络频伤，咳嗽咽痛，脉形细数，神倦少纳。积损成痨，阴火已冲之象。", "8921": "六味合生脉加百合", "8922": "张（乐荣坊巷。）咳嗽一爽，经络之精夜润矣。润则所留之瘀血，从此而出，胸前闷痛，从此而轻，岂非美事！但漏疡日久，阴气下泄，阴火上升，肺金仍受其刑。脉形细数，口舌干燥。一损损于下，自下而损及于上之形，未有艾也。欲卜其旋元吉，未许稳成。", "8923": "裘（海门）形寒伤肺，传入大肠，咳嗽于上，外疡于下，久而不愈，咽烁嗌干，脉形弦紧带数。所谓一损损于肺，此症是也。", "8924": "郁（长安）时病中之咳嗽失血，经年未愈，加之以寒热，重之以盗汗，脉弦而数，肌肉暗削。积虚成损，恐至积损成劳。", "8925": "彭（通州）咳嗽已经四载未痊，然亦无大害，惟深秋病剧之余，常难脱体，轻则生痰，重则动血，胸或痛，口多干，脉形涩数，是肺病也。不宜再延，延久恐成一损。", "8926": "金（嘉兴）脉数，右部中按弦大，左部沉按细急。细急者，阴伤也；弦大者，伏邪也。阴伤则热，伏邪亦然。左右之至数，自然见数。据述去春咯出纯血，或带紫红之液，喉间从此黏痰，面部从此火升，口干津不到咽，亦从此而间作。肺胃两经，毫不介意；孰知二经一病，内热薰蒸于上，毛窍常开于外，或风或温，容易乘虚而入，阳络重叠受伤，秋间犹可，冬令加剧。然则伏邪之化热伤阴见证，而非阴虚不足，自内以生之弱症也。阴既伤矣，不能不养，邪热之伏留阳明，不能化尽，究属此病之根，不能不以清热为主。", "8927": "陈（崇明）咳伤血络，络伤之后，咳久不除，咳之所以不除，都为络伤也显然。然积虚成损，积损成劳，无怪乎脉形细数，内热蒸蒸，神昏言微，不耐炎蒸，已露一斑矣。速速退归林下，扶过三伏再商。", "8928": "沈（王江泾）咳嗽半载，寒热经月，苔白口腻，干不多饮，痰不畅出，小溲色黄，脉形弦细。此系阴虚受风，久而不化，又患以暑，病情加剧也。伤风成劳，伤暑成瘵。劳瘵之根，最难下手，而况阳络新伤，更难取效。", "8929": "诸（无锡）脉数右部涩小，左太浮弦。咳嗽两月有余，不独上伤阳络，且兼结肿肛门，便难口燥，显系阴亏之体，不耐燥气加临，肺气自戕，传及于肠，极易成损，速以食色之性慎之。", "8930": "又：温升与清降并行，上下之见症无一不和，各得其所也大妙，所嫌左关一部之脉，弦虽当令，过大过急，肝阳内旺，肾水暗虚，养肝之法，合入前方。", "8931": "钱（荡口）咳嗽哮喘，正在窃发之际，脘腹胀满，皮肤浮肿，四肢逆冷，脉息细小，舌苔白腻。元阳不足，肺本虚寒，外不耐风邪，内不耐浊气，交相为患也。恐其塞厥而败。", "8932": "程（臬桥）形寒饮冷则伤肺，所贮之痰，因此而动，动则呀呷有声，卧难著枕，哮喘作焉，愈发愈勤，甚至生痰之源，源源而来，已昭肾气下虚，不独肺病而已。现在右脉滑大，标病为急，宜先治之。", "8933": "钟（湖州）肺为娇脏，不耐邪侵，一伤于悲哀，二伤于发散。从此相传无权、清肃失司。木寡于畏，怒则为哮，毛窍常开，寒则亦发。当发之时，肺经所贮之痰，脾经所生之痰，无不攸归于窍，呀呷有声，卧难著枕，如是者数数矣。现在不发之时，脉静而细弦，元阳不足，非补不可，非温亦不可。", "8934": "金水六君生脉牛膝牡蛎胡桃肉杏仁金匮肾气丸、金水六君丸（二味和匀，清晨青铅一两，煎汤送下。）", "8935": "杨（安徽）哮喘时发，发则胸闷咳逆，卧难著枕，病之常也。惟所出之痰，或带红色，口中之味，亦作气秽，肩背酸痛，脉形小数。肺胃两经，必有伏热在里，蒸开毛窍，容易招风，最为累事。现在哮止二日，吐出之痰，黏而且黄，尚从咳出，不能不以清法。", "8936": "杨（关上）肺俞伏痰，招风则发哮喘，呀呷有声，卧难著枕，甚至寒热分争。近来平善之事，呼吸短气，痰声不利，脉象弦滑。肺胃两经都被痰所贮也，权以导涤法。", "8937": "又（丙转：）金实无声，金破亦无声。金声不外扬，两手脉小，责其肺气久虚，元府不闭，风邪得而袭之，是虚为本，实为标矣。", "8938": "张（平望）语声喑喑然不彻者，心膈间病。心膈之间肺也，肺病则次指无力，脉小而滑，滑则为痰，小则为虚，肺既虚矣，自易贮痰。", "8939": "荣（青浦）心痛彻背，是名胸痹。久而不化，适值燥气加临，咳嗽未了，咽喉干燥，痰内带红，脉形细小，理之不易。", "8940": "张（齐门）胸痛彻背，呕吐厥逆，脉左弦甚。想是中阳不旷，而肝风载痰上逆也。", "8941": "万（嘉兴）胸痹初愈，脉形弦滑，舌苔糙浊。脾胃阳虚，湿痰内阻。", "8942": "金（接驾桥）背痛彻之于胸，胸痛亦彻之于背，其中之阳气安在哉！然脉虚而弦，白苔满布，小溲短赤，气逆为噫，更有湿浊在里，郁而不化也。", "8943": "徐：（湖州）胸脘作痛，延及背胁，舌苔满布，脉象细弦。阳虚不旷，湿邪寒气凝结于中，无从化解也。从胸痹例治法。", "8944": "谭（侍其巷）动则气逆从胸膺之间，逆入两肩部分，作胀作酸，舌苔满白，脉息小弦。此系胸阳不旷，湿痰阻气也。", "8945": "又：脉形小数，小为病退，数为余邪。咳嗽虽轻，尚未了了，补阴之中，寓以消法。", "8946": "孙（东塘）不寐，阳跷脉满使然。", "8947": "施胃不和则卧不安。然胃本和也，必有所以不和之故。左寸脉沉，心气下郁；右关脉弦，湿气内阻。一阻一郁，无不归之于胃。胃虽欲和而不得和也，理所必然。", "8948": "陆（吴江）多病者必须药物，前病既多，服药不少，姑置勿论。就夜来不寐言之，是阳跷脉满也，然满则固然不寐，而夜间仍有寐时，即得寐时容易惊惕而醒，又属肝经伏热，不能藏魂所致。且先藏之。", "8949": "丁（乌镇）血痢日久，尚患溏泄、大腹胀满，按之如鼓，右脉弦滑而数，饮食递减，神情困倦，脐已平者防突。", "8950": "又：溏泄稍和，满痛时作，脉形弦滑，左亦太硬，三虫共食一器，且被肝木所乘。", "8951": "又：肝脉一和，腹痛自止，未始不佳。无如右脉弦滑，腹形硬满，脐突溺短，大便还溏，所患之邪，正属不少。", "8952": "包（海盐）酒之湿热，已积二十多年，曾经衄血，又患黄疸，现在单单腹胀，二便违和、口中干苦，脉形弦数，理之棘手，脐虽外突，食尚加餐，下夺之法，可以施行。", "8953": "又：土郁夺之，则单腹胀应手而平、然小便已长、尚兼黄色、左脉多弦、鼻衄易流。肝经之湿热未清、尚易传入中土而作反复也。", "8954": "石（横泾）血中有气，血脱气亦从而脱，脱则所主湿邪，不能运化，大腹胀满，日久不痊，脐突筋露，脉小色萎。如其一加喘息，不能下问矣。", "8955": "吴（夹铺桥）面肿曰风。肿退而变为一身胀满，咳嗽气塞，脉小左浮右沉，溲短肢冷。所感之邪风，自肺而传入脾也，恐为喘塞而败。", "8956": "汪（崇明）一身尽痛，变为浮肿，是风湿为病也。病已向愈，元气未充，所有余邪，容易招暑，季夏腹中作胀，胀极而满，甚至上下均见浮肿，脉形弦细，舌苔满白，小水不长，以昭阳气内亏。法当温化，以冀不喘。", "8957": "陈（吴江）男子以自下肿上为逆、究其所以致此之故，湿邪无路可出，气又自外而来，互相交结，故苔白口干，脉弦不能食也。幸未气喘。", "8958": "李（葑门）因于气为肿，肿之见症，未有不属于气也明矣。然气有虚实，右脉软弱，左关带弦，脾经不足，湿气有余，或因肝气内逆，风邪外触，皆可作也。", "8959": "周（松江）咳喘于前，浮肿于后，病经一载，脉息沉弦。肺之清肃不行、脾之健运失常、身中痰湿，犯于上焦，或行于下部，漫无向愈之期，非所宜也。", "8960": "蒋（无锡）面部浮肿，延及周身，甚至胀满，又增咳嗽，寒热气逆、不得卧下，二便失调，脉形弦细，此系风邪夹湿，脾肺两伤也。脐已外突，理之棘手。", "8961": "又：邪之浮肿于外，虽见日轻，胀满于中，仍然见重，口干且苦，溺短不长，咳嗽气短，四肢逆冷，脉形细小，一饮一食一汤一药，无一舒者，邪气填满脘中，正虚不克消化也。筋已露，脐已突，何从下手？", "8962": "又：风邪脱入湿中，脉来冲急，大便溏泄，浮肿，寒热头痛，势非轻者。", "8963": "又：太阴腹满，不惟寒湿有余，而且真阳不足，脉冲下体不温，干不能饮，妨食气满，其势颇险，未便以寒热余邪为主治。", "8964": "石（王家溪）阂疟之风留之于湿，曾经肿胀，今春又发，小有寒热、自汗不渴。右脉濡，左部弦，既无便溺之阳格，又无饮食之速和，其治在表，防脱。", "8965": "汪（上海）面肿曰风，足胫肿曰水。风邪从阳而亲上，面部先肿，引动湿邪而亲下，足跗亦肿。如是者前后轻重不齐、现在偏之于上，白苔带黄，脉弦带浮、溺黄不多、气短不长、风多于水是也，不喘乃吉。", "8966": "杨（宜兴）气上冲胸之候，颈脉动，时咳，阴股间寒，足胫肿，目下肿，腹乃大，卧不能正偃，小便不利，苔白气短，脉息沉微。脾肺肾三经阳气内虚、不能运化湿邪，垂成水肿也。恐其喘甚。", "8967": "钱（荆溪）湿邪从阴而侵下，下焦浮肿之时，失于调治，延及中焦，大腹胀满，脐已突，筋渐露，饮食作胀，小水短赤，右脉弦涩，左关独浮过于弦。湿郁为热，阴分已虚，近增咳嗽，防喘。", "8968": "马（无锡）浮肿咳嗽，继以呕吐恶心，曾经向愈。而肿之痞满，独不能除，后即因此而呕吐又作。浮肿又增，二便失调，脉形细小，苔白不渴，足部硬冷。阴虚寒饮使然，恐其喘甚而败。", "8969": "浦（嘉定）浮肿自上而下，自下而中，中即胀满，咳嗽不爽，无汗气短，胸痞妨食，脉息浮弦，风邪夹湿，由外而之内也。防喘。苔白便溏，溺短，感邪已欲为热，热亦宜清，不能独化风湿。", "8970": "又：胸之痞，便之溏，似属渐和，咳嗽不作，更为美事。而中宫之胀满、上下之浮肿。苔白气短，溺少口干，脉息沉弦，防食恶风等症，正属不轻。", "8971": "包（史家巷）湿郁之热，为浮为肿为胀，从下而延及上焦，日甚一日。苔白口腻，呕逆恶心，溺短便坚，加以耳鸣脉小，左关一部独见浮弦，更有风引动于上焦，容易增喘，不能不虑。", "8972": "又：脉浮已和，独形弦象，呕逆虽止，浮肿不消。必得小便清长，则上甚之湿热，或者下趋。", "8973": "又：小便不长，膀胱之气化失其常度也。既上之湿，难以下趋，徒增为热，口稍干，龈带疼，脉亦弦中见数也。", "8974": "吴（卢州）先肿后咳，其治在脾。脾虚不能制湿，反易生痰，不但脾家自肿，而且累及肺金为咳，势已不轻，加之形寒饮冷，肺气更伤，肿满按之作痛，咳逆不爽，惟见薄痰，饮食递减，溺短便溏，脉形郁小，病势有加无已。窃恐清肃不行，健运失常，陡然气喘而败。实必顾虚，泻必先补，昨日行之，毫无动静，想是虚处有益，实虚处无补。将开鬼门，洁净府两治立方。", "8975": "吴（山西）面部之肿，延及中下两焦，溺色短赤，舌苔黄浊，口味干甜，脉形弦数。风邪袭入湿热之中，不喘乃吉。", "8976": "刘（朱家角）胸脘痞塞，一身浮肿，咳逆少痰，不能卧下，舌苔薄白，小溲甚少，脉形沉小。此系痰食湿交结不解，其气易塞咽喉，恐其喘厥而败。且以降气法施之。", "8977": "张（江阴）风寒湿三气杂至，合而为痹，若风气胜者为行痹，若以春遇此为筋痹。此间之痹，四肢游行，发于仲春之候，指臂强而难举，左关脉息弦急，因风而成筋痹，不问可知。", "8978": "顾（光福）右肩臑酸痛，延及臂肩，左脉芤数而浮，血虚招风所致。右属肺，肺气所主，久贮之痰，从而和之为患，兼理为宜。", "8979": "秦（东山）疟中之风湿痰邪窜入经络，以致右肢酸痛，筋脉不舒，渐及于左，一手偏热，口中干苦，脉象弦数，肩背亦有不和之象，此名痹症。", "8980": "大师（长兴）肩臑臂痛之经络都在三阳，而其累及阴经者，不过十之一二，本非内病可知。然遗精日久，曾患痎疟，又值心力俱劳之体，阴血大伤，不免有血不养筋之义。经筋为患，漫无愈期，所以六脉细小，而左关一部独形浮大也。汤丸并进乃妥。", "8981": "陈（泉州会馆）痛痹偏之于左，且有痿而不举之形，脉息浮弦。血虚之体，风邪乘此而入也，理之不易。", "8982": "张（上海）大股红肿作痛，延及于膝，且至胫骨亦有所伤，本属风寒湿三气杂至合而为痹也。久而不愈，膝骨日大而重，伸而难屈，脉形沉细而弦，欲成鹤膝风，不可忽视。", "8983": "据述腰痛于前，咳嗽于后，肺与肾经先受风寒湿三气之邪，郁蒸为热，所以鼻流清涕，小溲常黄，脉形细小，左关独见弦数，右寸独形滑象，甚至身体偏侧肌肉暗削，行步无力，虚态百出。恐其难以支持，因病致虚而脱。", "8984": "徐（太仓）湿热不攘，大筋软短，小筋弛长，软短为拘，弛长为痿。此乃不痿而拘，拘之为病，湿热邪气，独在于大筋，不言而喻。然软短之拘，虽为湿热之不攘，而湿热之中，似乎湿胜乎热，所以脉弦濡小，带有数意，舌苔满布带些黄意，溺不变，口不渴，四肢酸软，经筋酸疼，甚至下病及上，以昭湿则下先受之之义。羌活胜湿汤一法，最为第一要著。", "8985": "周（吴江）三阴大疟，变为日作，阴经所伏之邪，从阴而出，大妙大妙。孰知疟发日晏一日，所感风邪，仍从风府而下，盖以三阴之阳衰而不旺，不能乘势托出其邪，反被邪乘虚入，虚者益虚，饮食大减，肌肉暗削，身热无力，大腹软满，足跗浮肿，脉微无神，所谓无阳则阴无以化也。际此冬至阳生之候，而有如此病情，危乎危乎！", "8986": "程（竹行头）但热不寒之疟，渴喜热饮，苔腻节疼，脉微自汗，邪盛阳虚，究恐不克支持而增昏喘。", "8987": "俞（台州）三阴疟后，小溲见红，又兼白浊，复为寒热似疟，日夜分争而作，左胁疟母，乘此升逆，口干脉弦，显系留邪于肝脾两经，不宜再厥。", "8988": "秦（海州）间疟变为三日一作，寒重热轻，脘腹胀闷，口鼻干燥而不发渴，脉形细弦，舌苔薄白。想是暑湿内伏，又有燥气加临。", "8989": "夏（上海）疟属脾寒。寒之为言，非温非热，乃阴象也。阴寒之气，聚于脾经，发于阳明，寒热往来，间日而作，喜饮热汤，舌上苔白腻而浊，脉息濡小之中隐隐带弦，面上之色黄中带白，汗出不少，小溲夜多，少纳少寐，嗳气不舒。际此冬至阳生之候，而患如是见证，阳之虚也甚矣。惟其阳虚，则阴寒之邪更不能消，所病之疟，无怪乎漫无愈期，急须温化。", "8990": "包（王天井巷）三阴大疟，名曰痎疟。阂者老也，言疟老于三阴之界，漫无愈期。近来自觉神呆，且形痞硬，苔白脉迟，阳气渐虚，不但不化疟邪，而疟邪反欲成臌也。急须大补脾阳。", "8991": "尤（光福）痎疟日久，黏汗头眩，脉形细而隐弦，此虚也，不可以作实治。", "8992": "吴（关上）进脾胃法，呕恶已止，纳食亦加，痎疟仍然，隐癖僭逆中宫，脉形弦细，舌苔干腻，暑邪正甚，阳气内伤。", "8993": "马（甘露）寒热如疟，久而不已，口中干苦，少寐少纳，咳逆，脉细弦数。阴血内亏，留邪于肝也。", "8994": "马（黎里）痎疟日久，右脉弦细，左部模糊，元阳元气，都被邪侵。", "8995": "王（沈店桥）痎疟日久，气阴两伤，右脉小，左脉弦数，口干舌红，神疲盗汗，少纳言微，养中寓化为主。", "8996": "秦（海门）三疟皆生于阴，阴经之邪，无阳以化，所以寒重热轻，汗多不渴，项痛腰疼，苔白气喘，脉形弦细，右尺上冲甚锐。恐其枝叶未害，本实先拔，而有不克支持之变。慎之慎之。", "8997": "陈（枫泾）但热不寒之疟，渴喜热饮，苔腻节疼，脉微自汗。邪盛阳虚，究恐不克支持，而增昏喘。", "8998": "郑（港口）湿热召暑，风亦随之。寒热往来，间日而作，舌苔满布而白，脉息浮弦，头痛口干，恶心多汗。", "8999": "汪（西汇）头痛之余，腰痛酸疼，始而小有寒热，后来变为间疟，苔白味辛，胸痞妨食，便溏溺黄，渴喜热饮，脉息浮弦。暑风外感使然。", "9000": "顾（青浦）痎疟皆生于阴，阴者肝脾肾三经也。脾肾之脉犹可，而肝之一部，见于左关者，弦而且浮，必有外感之风，留于肝部。良以风喜伤肝，肝为风脏，物以类聚耳！", "9001": "张（关上）寒热往来，既不能除，又无定时，变为痎疟，已经六五发矣。脉形弦细，痞闷不开，舌苔薄白，饮食甚少，近更咳嗽，口淡溺黄。暑风湿热，归并三阴，不言而喻。", "9002": "陈（南京）三阴痎疟，音烁于上，腹膨于中，便溏于下，三焦又病可知。三阴病于前，三焦病于后也。舌苔冷白，四肢厥冷，脉息全无，阳分比阴分更亏，且至有阴无阳而欲绝也。勉拟生阳一法，然恐鞭长莫及。", "9003": "又：一阳来复，脉尚模糊，虽无暴出之忧，而少微续之喜，不足恃也。", "9004": "生脉散煎送来复丹。", "9005": "张（太仓）三阴疟，右脉细软，左太弦急，脾湿有余，肝肾不足。", "9006": "沈（西汇）痎疟变为日作，邪从外向可知。然脉弱体酸，胸闷少纳，元气内虚，无力化邪之候，只宜养化，以冀虚波不起为妥。", "9007": "叶（周王庙弄）疟发四未先见酸疼，继以小热，然后寒大作，汗出渐解，舌苔多白，并不发渴，脉形濡小，一轻一重，已以一月有余。显系先患风湿，后患暑邪，气血同病也。", "9008": "张（上海）痎疟日久，一载有余，轻而未止，瘾疹外发，瘙痒异常，咳嗽日久，痰出不少，舌苔尚白，溺色犹黄，脉形弦数。所患风邪暑湿，欲从三阴传出肺经而不能畅达也。", "9009": "王（太仓）痎皆生于阴，阴经受湿招风，右脉小，左脉浮，足肿不退，脘痛时作，鼻衄易见，小溲色黄。所患风温之邪郁蒸为热，布满三焦，而不能从营卫以畅达也。邪发营卫之时，出入相争，寒热不重，亦不口干，亦不求救于水，是湿更重于风也。", "9010": "又：热重于寒，口干头痛，苔白舌红，脉形弦数，干咳少纳，阴血内亏，不能速化，留邪之兆。", "9011": "又：得汗则寒气先消，而暑湿热三气之邪，尚在三阴之界，无力以消，所以脉形细小之中而带隐弦。", "9012": "陆（嘉兴）痎疟皆生于阴，阴者，三阴也。三阴经深受风寒湿，老于其界，所以寒热往来，止而复作，口不渴，苔黄浊，脉弦而数，四肢微浮。扶正达邪，方为正治。", "9013": "李（花街巷）寒热有往来之意，口中干苦，舌苔薄白，脉细弦数，少阳见证也，当以少阳之法和之。但络伤之体，血分本亏，往往有营虚不能作汗之弊。将此意治，合而用之。至于咳嗽日久，不过兼治而已，未便为主。", "9014": "廖（奉贤）三阴疟邪，曾经归腹而肿，幸尔已结疟母，其邪窃踞于肝胆，所以身热又如疟状，似夹雌雄，脉形弦细，苔白不渴，温化为宜。", "9015": "又：疟之雌者已愈，雄者亦轻，岂非美事。无如脐之下旁有内结，按之则硬，动之隐痛，苔白且滑，脉弦而小，阴结阳虚所致。", "9016": "曹（湖州）痎疟变为日作，三阴之邪，移出阳经矣。然阳经所受之邪，尚属不少，小有寒热，寒热虽止，而营卫分争之象，仍未脱体。舌苔嫩黄，脘腹不舒，小溲短赤，夜寐少安，咳嗽吐痰，肢体无力，脉形细小。邪少虚多之候，扶正为先，积邪自去。", "9017": "陈（周庄）寒热往来，口中干苦，舌色光红，脉弦而数，此伏暑化燥而发，阴气早伤。如欲提出其邪，势必兼顾其阴。", "9018": "陆（浦庄）寒热往来，口中干苦，舌苔白腻，脉象弦数，伏暑见症也。久咳且嗽之体，兼理为宜。", "9019": "周（崇明）痎疟皆生于阴，阴者，三阴也。三阴之邪，孰多孰少。少阴虽虚，虚者遗精；太阴独实，实则面色黄滞；厥阴则虚实各半，寒热往来，渴喜热饮，动则两胁隐痛，所以左脉细小而带隐弦，右部弦急而滑。欲治其疟，先重清脾，兼和肝肾，不问可知。况浮肿之邪，尚有留于脘腹者，更宜著手。", "9020": "胡（光福司）人生之阴阳皆有枢机，邪从阳枢而出，则为痎疟；邪从阴机而入，则为泄利。此间三阴大症，虽经十有六发，尚属邪从外达。昨又加之以泄，日夜四、五十行，又属邪从内陷。疟痢并行，元气更乏。况六旬以外之年，精力久衰，何堪磨耐。假使中土皆旺者，犹可生生不息，乃一饮一食，大减于前，反有痰涎上泛，呕哕恶心，甚至疟歇两日，亦小有寒热，以昭脾胃营卫，无一不虚。无怪乎神昏遗溺于疟时，气坠肛门于痢前，即不热不痢之际，火升面赤，少寐多烦等症，不一而足。脉息芤弦者如此，大非所宜。病情既有出入，药饵自宜升降，然升则虚阳随疟而升，降则浊阴随痢而降，各有偏弊，则阴阳更加不固，斟酌其间，惟守中以和营卫，化气以通膀胱，出一理苓汤法。", "9021": "彭（上海）心肝所生所藏之血，不能统之于脾，渗入下焦，鲜者紫者尽从粪之前后而出，久而久之，面容黑瘦，脉息芤弦，饮食大减，将有浮喘之形。慎之慎之。", "9022": "又：芤弦之革脉稍和，所患诸症，自属安适，前方的对无疑。所嫌小溲浑浊，内痔作痛，亦须兼理。", "9023": "又：温通瘀血，革脉已和，独形芤象，腹痛已除，尚下渗血，痔痛溺浊，饮食虽增，口舌干痛。阴虚留热，暗伤营分可知，仿以黑止红意。", "9024": "郑（宁波）心生之血，脾气虚者失其统领之常，不能藏之于肝，反为渗入肠间，血从大便而出，谁曰不然。而不知渗之已久，不独气从下陷，而且阴络暗伤，暗伤所有之血，无不从穿处以行，有如轻车熟路，漫无止期，营卫肌肉，皮毛筋骨，有损无益，自知不觉支持，饮食减少，言语无神，脉形芤涩而数，归入虚劳重候也。劳者温之，虚者补之，原属一定章程，但血之下者，似属漏卮情状，如不以久塞其孔之法治之，虽日从事于温补，亦属徒然。", "9025": "马（上海）脾统血，肝藏血，统领失常，所藏者少，则左关脉息虽旺而芤，大便之余，带血不已，舌苔黄燥者如此，法当清养兼施。", "9026": "汪（北壕）气淋带浊，溺后更疼，左脉大，将见血之兆也。速宜静养。", "9027": "沈（青浦）热郁下焦，血淋久而不已，脉数，左部带大。肾水大亏，心火失其所济，下入小肠而出之膀胱经也。", "9028": "吴（吴江）阴亏之体，心火下郁小肠，传入膀胱之府，尿中带血，时作时止，左脉沉数，小溲不利。", "9029": "李（通州）肾虚乃膀胱受热，尿血成淋，脉形沉数，清养为宜。", "9030": "邵（乍浦）欲便不通，不通而痛，此淋也。脉细而见弦数，干不多饮，必有留热未清，不独下虚而已。若论咳嗽，又属新感。", "9031": "梁（长安）小便频数而赤，或浑浊，或紫块，脉象沉数，此淋症也。", "9032": "又：所下之膏，薄且少矣，然当便之时，尚属不利，已便之后，反觉隐疼，肢膝不温，脉小左弦，唇红嗌干，热未全愈，虚日益著。", "9033": "华（荡口）膏淋变为血淋，久而不已，脉数左弦，肾被热伤。", "9034": "钱（常熟）尿血成块，小溲作痛，脉数苔腻，湿热下注使然。", "9035": "严（东山）漏久头痛之体，水亏木旺，不问可知。迩年小便淋痛，其状如脓，迁延不已，衰而复盛，然其所出者，不过水湿浑浊，苔白口干，足冷转筋，左关脉硬，寸部浮急，右惟濡数而已。必有心火湿热，下注于肾与膀胱也。理之不易。", "9036": "裘（新街）血淋日久不痊，加以咳嗽时作，脉息左细右弦，俱见数象，口燥苔黄。想是中宫湿热，上下充斥，阴液受伤也。", "9037": "金（关上）尿血成淋，小便时无血亦疼，两月有余之病，脉数苔白，嗌干，湿热伤阴也。", "9038": "杨（专诸巷）曾患淋症，小便本难，近来小便又淋，变为癃闭，少腹硬满，小便肿胀，苔白不渴，脉小而沉。下焦湿热被寒所遏，膀胱之气化不洗，最为急症。恐其喘汗，慎之。", "9039": "周（平望）湿热不攘，大筋软短，小筋弛长，弛长为痿。痿病未痊，又来尿血，近更为淋，脉形细数，阴分更亏，丹溪法主之。", "9040": "朱（嘉兴）肝肾湿热，不留于中，必犯于下，下焦膏淋血淋，以及小便无端而痛之气淋，时发时止。现在膏淋独见，脉象弦数，白苔满布，加以气从少腹左升，仍不外胃家湿热袭入肝经，拢动精房也。", "9041": "陈（祟明）湿郁为热，变作沙淋，有如煮海为盐之义。病经半载，左尺脉浮，按之弦数，阴分已伤，正须兼理。", "9042": "林（南壕）阴虚湿热，膏淋带血带沙，沙与血淋已愈，而膏则仍然亏内，尚带血沙两意，脉弦细数，养化为宜。", "9043": "孔（鞠花亭）湿热伤精，梦遗不作，变为白浊下行，而其行之不畅者，留于海底，红热作疼，阴虚湿汗，加以疮疡外发，脉反郁小而数，舌苔腻白，理之必费周旋。", "9044": "施（松江）热淋变为血淋，脉形细数，细属阴亏，数为邪火，清补为宜。", "9045": "吴（嘉兴）疟邪与疔毒窜入大经小络，归并膏淋。膏淋不罢，邪又流入于肾，肛门前后之气盘旋酸痛，袭入于冲，左腿内廉之经脉麻木抽痛。病情自上而下，势必自下而上以出之，不惟化导而已。", "9046": "陈（海门）血因胬肉而瘀，瘀在海底，附在筋经，自幼作疼，至今未愈。脉形沉涩，理之不易。", "9047": "又：进桃仁承气汤，当便之时，海底已能不痛，阴茎尚带痒疼，涩脉渐有和意，显系所瘀之血，消者已多，而其留落者，一时未能扫除也。去瘀生新为治之中，仍以毒药寓之。", "9048": "周（松江）淋症有五，膏居其一，久而日甚一日，舌苔薄白，脉小左弦，俱见数象。此系湿热之邪传入膀胱，且有肝火窜入其中也。不增喘乃妥。", "9049": "又：小便似和而不能畅通，少腹似和而尚硬满，舌苔湿白，脉息微弦。阳气大虚，无力以通其痹也。", "9050": "又：病情如昨，湿白之苔渐变糙色，脉形带数，所结之邪，郁而为热，阳虚难化也。", "9051": "又：大便已通，瘀血食积未有不从此而去，然腹之坚者虽软，其形尚大，苔色嫩黄，口干溺热，脉形弦数，小溲通而不利。湿热郁结于膀胱，势所必致。", "9052": "章（江阴）肾者主蛰，封藏之本，精之处也。精者所以能处于肾者，全在肾气本足，封藏自不失其所职，如虚则反是，增出胫酸体倦，口苦耳鸣，便坚等症，势所必然。然左尺之脉，浮而不静，固昭肾气下虚。而关部独大、独弦、独数，舌苔黄燥，厥阴肝部又有湿热之邪，助其内火。火动乎中，必摇其精，所谓肝主疏泄是也。虚则补之，未始不合，实则泻之，更为要著。", "9053": "又：大便畅行，干苦亦愈，左关之脉大者已小，弦数仍然，尺亦未静，可以前方加减。", "9054": "又：大便已和，脉形弦数，数为有火，弦主乎肝，肝经既属有火，不但顺乘中土，而且容易摇精，精虽四日未动，究须小心。", "9055": "马（王庄）精浊日久，尚未了了，又梦遗见血，显系精血内亏，俱被湿热所伤，所以左脉细小，右脉弦数。", "9056": "施（芦店）梦遗日久，腰部作酸，是肾虚也。脉形濡小，左寸过大，舌苔白腻，湿热伤精而动者有之；心火太旺，不能下交于肾，肾气下泄者亦有之。此两端为要，不独填精补髓而已。", "9057": "彭（溧阳）肝主疏泄，肾主封藏，疏泄太过，封藏失职，梦遗时作，小便余沥，甚至腰背俱痛，足膝无力，苔白舌紫，脉形细小，左关独大独弦。久而久之，寒热温凉之品，备尝不愈，想是药之难得其宜也。", "9058": "又：肝肾两经都被湿热所伤，以致精房不固，所以左关脉息独大独弦，余则皆形细小也。", "9059": "徐（太仓）肾者主蛰，封藏之本，精之处也。精乃无梦而遗，肾失封藏之本，未有不用蛰方。蛰者，蛰其精也，然精之所遗，已有三年之久，阴分暗虚，虚者热从内起，蒸之于卫，则肌肤灼热；郁之于营，则手足心热。现在手足之心独热，口干多饮，脉来细数，甚至气不宣通，背脊疼，少腹不和，肢体无力，病势有加无已，窃恐夏至之一阴不生，而有多将熇熇，不可救药之叹。拟四物二连合清骨饮法，先化其热，后继之以补阴封髓，循循有序，则庶几焉。", "9060": "吴（四摆渡）遗精有三，每以瓶中贮水者为譬。此间脉息，不浮不沉，左关一部独见大弦，既非水满之覆，又非瓶破之漏，是肝经火旺，摇动其精，有如瓶中水，外被物所激而出也。", "9061": "施（崇明）途中遇风作痛，痛从胃脘之上，后及于背，旁及于臂，动则如此，静则可安，已经一载有余，不能向愈。脉小而沉弦，想是冷风中必有飞尸遁注之邪，附而和之为患。", "9062": "毕（洞桥圩）一阴一阳结，谓之喉痹，所痹所结，仍不离乎一阴一阳之界，然其所以致此，实系乎阳明湿热薰蒸于上，是以久而久之，地道渐形其闭，饮食难以下咽，甚至邪传奇经，带下赤白，气怯神倦，脉软头晕且眩，不克支持也。防脱。", "9063": "又：进前方一剂，饮食之下咽者稍易，夜来得寐，晨起畅吐浊痰。想是冲脉隶于阳明，阳明之湿热渐化，冲脉之逆气亦能稍和。然须日有起色，庶免喘脱。", "9064": "曹（太湖上）经期落后，带下绵绵，牙龈肿腐，心悸且嘈，两耳时鸣，口中干燥。血虚生热，湿郁为热，二者皆伤八脉也。当从八脉立方。", "9065": "朱（武进）血崩后寒热咳嗽，久而不已，腋下结核，足跗浮肿，脉细弦数，阴亏血弱之体，外感风邪，无力以消化，往往迁延日久，变作虚损，勿以吐血不多而忽之。", "9066": "陆（南浔）少腹之瘕聚及脘中胀痛，经年不愈，皮肤甲错，大便反溏，脉形细涩，饮食不思，难以支持也。防脱。", "9067": "周（平湖）女子以肝为先天，先天不足，月事不来，两目干涩，左关脉息弦而且数且浮。肝经气火，少降多升也。", "9068": "郁（江阴）寒热两月有余而愈，然热尚独留而不能退清者久矣，加之以腹大，重之以症结，攻痛夜剧，月事不来，饮食递减，大便或溏或结，脉象弦而带涩，带下绵绵，肌肉瘦削，口舌干苦。寒凝血滞，八脉皆虚，棘手之候也。奈何！", "9069": "又：症结渐消，攻痛自除，腹之大者，亦从此渐和，大快事也。然口舌之干苦仍然，身体之留热加剧，带下虽少，月事未来，饮食递减，大便带黑，脉形弦细。八脉交虚，余邪未尽，形神俱夺者如此，容易反复，慎之慎之。", "9070": "陈（枫桥）月事不来者，胞脉闭也。任主胞胎，任脉为病，女子得之，往往带下瘕聚。此间带下赤色，瘕聚攻痛，如是者久矣，已属重候。加之以内热口干，咳嗽音烁，痰曾带血，少纳肉削，右脉涩，左关弦数，自下而损及于上，何从下药乎！况因病而用药物，因药物而反增其病，变作真寒假热之体，自古以来，本无治法，作法治之，难又难矣。", "9071": "陆（江阴）经尽之年，月事尚来而无血色，是土败也，血枯也，气虚不能收摄也。无怪乎久而不止，面浮跗肿，嗌干心悸，饮食无味，脉息少神，接踵而来，以昭不克支持之兆。", "9072": "某月事不来者，胞脉闭也。胞脉者，属心而络于胞中。今气上迫肺，心气不得下通，故月事不来也。《内经》已言经闭者，上气迫肺而作干咳之形，无怪乎病经五月，加以营虚则发热，卫虚则恶寒，欲成「一损损于肺，二损损于心」之见证。拟复脉汤与加味泻白散。", "9073": "朱（王场河头）多气多血，莫甚于阳明。胃府每以下行为顺，滋乃逆而上行，血之盈盆盈盏，皆被气之上升，多且久矣，久则难免郁而为热，喉痹失音于上，当脐作痛于中，痹则恐其妨食，痛则更虑其喘厥。脉形细涩而数，中沉两按皆属有力，因病致虚，理之棘手。", "9074": "朱（王场河头）气者，血之帅也，气行则血亦行，气滞则血亦痹。阳明之气失其下行，阳明之血亦从此内痹。痹之既久，又郁为热，虽从咳嗽痰血分消，不足以泄其势，瘀塞于回肠曲折之处，当脐作痛，扪之觉热，二便不利，左足之经筋有时抽痛，脉来涩数，按之有力，肠间有壅塞成痈之象。将《金匮》法参入前方。", "9075": "又：逍遥者，消散其气滞，摇动其血郁也。既消既摇之下，少腹之上部已软，溺之淋痛可轻，滞欲散而郁欲开也。但毛际之间，尚属有形，按之坚硬作疼，溺时仍然滴沥，交睫又觉自遗，脉弦数小，气坠未升，经言淫气遗溺，痹聚在肾。痹聚者，湿气聚而为痹也。古人治此，必以辛润为主，盖辛能散湿，润能就下故也。", "9076": "江（兴化）右尺相火之脉，宜大而不宜小，小则相火必衰，焉能有子。年未四十，当从再索得男立法，然肝火偏旺，动则心君之火不能下交于肾，肾精尤易疏泄，所以左关一部，弦得太过也。两者不和，调之本非易易，权以荡涤法，然后缓以调之。", "9077": "先生之病，素禀湿热，又挟阴虚之症也。湿者何地之气也，热者何天之气也？天地郁蒸，湿热生焉；天地交泰，𬘡蕴生也。生生不息之机妙合于其间，禀而受者。湿热元气混合一家，出自先天，牢不可破，较之外感内伤之湿热属在后天者一扫而净，岂可同日而语哉！设使薄滋味，远房帏，不过生疮动血，幼年所患等症而已。惟事膏粱，更多嗜欲，外增湿热，内耗阴精，则脏腑荣卫常有春夏之情，而无秋冬之气，无怪乎其亥年之气风火相煽，耳苦于鸣，岂非阳气万物盛上而跃之一验乎？当斯时也，静以养之，则脐冷齿痛以下见症之外，犹可相安于无事，何乃火之添油喜功生事，陡然头昏面赤，一派炎炎之势。甚至火极似水，阳不成其为阳，热不成其为热，肝经之火、督脉之阳亦从而犯上，失其本来之面目。夫近闻引火归源，以为甘温能治火热之计。嗟乎！未闻道也。甘温能治大热者。良以下极阴寒，真阳上越，引其火归其源，则坎离交媾，太极自安。若太阴湿热蒸动而上者，投以清滋，尚难对待，断不敢以火济火，明犯一误不可再误之戒。然清已有法，滋亦不少，饮食能增，身体能胖，外有余矣。而色色不能久立久坐者，即病机中万物阴阳不定未有主也之条，际此外盛中空、下虚上实，用药实难尝见。", "9078": "细绎病源，阳分比阴分更亏之候也。阴亏而用十全养荣等法，责重乎阴，寓以阳药，本属和平之剂。良以秋分在即，燥气加临，不敢责重乎阳，以燥就燥反增燥病焉耳。然于膏方下之后，日可附桂斟酌用之，一语早已言之，非见不到也。盖天地之气清矣半月一更，人身之气亦半月一更。八月而至九月，气已二更，病势不除，饮食反减。明明阴得膏滋而无病，阳得膏滋而更衰，一月之间阴阳偏胜，一膏之内功过相抵。可叹补偏救弊，因时制宜，应接无暇也。所言念七念八九两日，霜降始寒，寒气外侵，痰饮内动，动见青黄绿色水，尚属阳明胃腑。至于黑这一色，已自阳明胃底而来，肾虚水泛，脾虚积饮，已见一班。然神气困倦，面色青浮，脉见双弦，以始阳气不充，痰饮内聚宜矣，而反忽然牙齿浮疼，加以口舌酸泔，呃忒于胃，卫逆于胁，变出一番火气者，肝火也，肝气也。气火之横逆，不外肾虚，无以涵木，木须顺乘脾土。此等气不足，即是寒之根柢；及见气有余便是火之形状，所谓本寒标热症是也。夫惟本寒标热，岂阳气之虚，较之阴气更进一层耶？此时论坎离，当然不定，始可阴霾四散，宗风虚则炽痰寒则壅之训而出一星附散法，以助脾阳。俾虚风寒痰不相互结，非独分解病情，而且土旺用事更合机宜。如一立冬，又不可以纯阳无阴之品施于久病阴血本亏之体。冬月宜藏之令者，以此方分两三次，一日进一服。参入前定滋方中，只取五钱，清晨服下，傍晚再服水泛金匮肾气丸钱半，淡盐汤送下，以占冬至阳生，弗药有喜。至于黑锡丹、控涎丹，本来合式因病处方，随机应变，相时而动者，须烦两先生权之。", "9079": "阴络伤则血溢，血内溢则后血。血之从后出者已经数载，时发时止，惟有盛于去年也。今春荣血日亏，卫气益虚。虚则气不摄血，亦因咳而来，阳络更伤，中焦失守，不独肝肾内虚，无怪乎其浮肿于前，喘促于后。甚至饮食不思，恶心欲吐，脉而数疾无伦，竟有阴从下脱，阳从上脱之意焉。急急大补，俾得抱一不离，已恐鞭长莫及。", "9080": "喘之一证，已得大补而平，可见肝脾肾三经亏之已极，姑置勿论。现在脉芤且弦，其名为革，以昭血络空虚元气难摄之意。夫惟元气难摄，所有温邪下注为便溏，外走为浮肿，上逆为咳痰；甚至阴络伤、血内溢之下，更有阳络伤、血外溢之症。似此中虚少纳者，遇之窃恐不堪磨耐，仍起风波而败，不可忽略。", "9081": "湿有五肥，人之湿多起于脾。脾主湿，又湿主土，土气不旺，湿邪无路可出，出则变而为痰，化而为热，所为湿生痰，痰生热是也。湿热痰体已既有年，姑置勿论，且论病经两候痛泻起因，继寒热往来，一日日三度发其间，呃忒频频，七日而止，显系冷风外感，内从少阳而入，里气不纳，上逆冲激，出入无定使然。当时汗出太多，虽有口舌呕恶等症，却难和以小柴胡汤。现在汗已不少，吐亦未除，下亦通矣，三法自尽，而疟疾仍作，胸前痞闷，右脉大虚，邪气还盛，汗吐下三法既不可施，惟有和寒温三例尚可以行。常见丹田有热，胸上有寒，白胎滑者，仲景曾有一方，喻氏师之以为和上下法之计；又见汗吐下三法之后，胸前作痞，噫气不舒者，用旋覆代赭石汤，通其阳，镇其逆。俾得呃不再起，想亦未始不合也。然以此治法不独为新病而设，即旧时之湿热生痰亦与焉。和方之制，和其不和也，不和于已虚之后。窃恐虚波暗起，不可忽略。候诸高明先生政。", "9082": "今晨寒热又作，来势颇轻，呕亦稍松，苔亦尖薄，所受风寒湿热却有暗化之机，似属佳兆。无如脉之弦滑都带空象，元气阳气实已内虚。虚而有邪，不得不扶正化邪为法。盖恐邪未尽而正先尽耳。", "9083": "二爷之病，风邪外感，内蒸湿热痰浊。古人所谓夹病，此等症是也。何以见之，风入少阳，则为寒热往来，半在表，半在里，出而与阳争则寒，寒宜不饮，入而与阴争则热，热宜发渴。今寒时喜热饮，热时反不渴，若无湿热痰浊，何以如是耶？是以舌苔满布，面已晦滞，脉已带滑，尽见空濡之象，欲去其风，必须化湿化痰化热，以除兼夹之邪，则风邪寻路而出，不被兼夹所持矣。然热自痰生，痰从湿化，即欲化痰化热，先宜化尽湿邪。嘉言云：舍助阳，别无驱湿之法。明示人以温通为主，将来附子理中连理辈一定章程。其中损益尤须临病斟酌，活法在诸高明公也。设使兼夹之邪日化一日，而疟机未脱，仍可用小柴胡汤和之，或寒热渐轻，但师其意不取其方，亦未为不可然，而诸高明自有见识，不必多言。此亦因主人之嘱，聊以应命焉。", "9084": "天之热气下，地之湿气上，人在气交之中，无隙可避，虚而受者，即名曰暑。暑之为言，有湿有热，不言而喻矣。夫暑先入心，暑必伤气，气分之湿不为之先除，则所蓄之热必不能外出。所以暑湿热三气交蒸之初，务须消去其湿，正合古人消暑在消其湿之旨也。然湿邪一去，热气即从外达，又名暑热，不名暑湿。一气而有两名，前后之用药有异。盖以热则阴伤，气亦更弱。无怪乎鼻衄旧恙上从清道而出，身体困惫，饮食渐减，脉转弦数，阳分更热，口内知干，种种见虚中有实之象。但暑邪一证，河间每论三焦。现在头额昏蒙，邪热偏于中上，惟衄去过多，虚在下焦阴液。如此细诊，断在少阴不足阳明有余，有何疑惑哉。拟张景岳玉女煎法，俾得中下焦热气上熏于肺者，悉从暗化，而下焦之阴气亦不再伤，仍不出乎刘氏三焦治例。未知是否？候西耕先生政之。", "9085": "左升太过，右降不及，何经之病？曰右肺，左肝，肺肝同病，自然升降失常。然肺为五脏华盖，肝脉布于两胁，此左升仅属肝，右降反属肺矣。何也？盖肝体在旁，肺体在上，只就位置而言。若论其作用，内经又曰：肝居人左，肺居人右，右之不降，正失其清肃之用也，左之过升，肝反多所生逆之用也。横逆之邪，加于清肃之所，木寡于畏，反侮于金，无怪乎半身以左之气旋于右，既不能透澈于上，亦不能归缩于下，有时邪之相争，盘旋胁部，直宜待得矢气，则快然。如衰者，木究不能上克于金，而仍下制于土地也。夫土曰稼穑，作甘者也；木曰曲直，作酸者也。口甘带酸，痰唾亦然何？莫非土受木乘之过，木亦太刚矣哉？谁能柔之，惟有左金一方，以为克木之制，则木正其体，金得其用，可患升降之不得其常耶？", "9086": "接续手札，荷蒙锦念。谢谢！细绎病源，所云气火益炽等症，即古语云气有余便是火。气从左边起者肝火也，左金丸主之，当归龙荟丸亦主之。然左金一丸，如水投石于前自宜，以当归龙荟丸继之于后，未常不可为法也。设使以当归龙荟丸即日为之，聊应台命宜矣，无如我先生有「为痈为血不可不预防也」一语，断非无稽之谈，出而高明者，弟始而骇然，继而茫然，自亦不知其笔从何处著也。然在望一方者如饥如渴，以速为贵。而弟亦刻无宁晷，不过夜以继日，有者求之，无者求之，必得左宜之右无不宜之要法，然覆书非敢缓也，盖有待也。端午日，下问者少，小徒聚在一堂，讲论百病皆生于气，遂有九气不同之说。气本一也，因所触而为九，怒与思为九气中之二焉。思则气结，《内经》自为注脚之。思则心有所存，神有所归，正气留而不行，故气结矣。先生有之不必言矣。至于怒则气上，甚则呕血，恐则气逆筋缓，发于外为痈疽。古人亦载气门，以昭邪郁必变，久病入络，非无意也。先生博学而预料之，小徒强志而问及之。弟即从此而领悟：怒有形于外者，亦有不形于外者。形于外者每出于暴怒，暴怒伤阴；不形于外者，名曰郁怒，郁怒伤肝。然视履考详，而阴伤于暴怒者，未必有之；言辞安定，而肝伤于郁怒者，岂曰无之。惟其郁也，木即不能畅茂条达，反来横逆，则气郁于中者，势必火炎于上，金受火刑，有升无降。痰血热辨，一病于肺；痞满闷塞，再病于脾。脾肺同病，则胃家之痰食无力消，胆经之水火从而和之，将来血溢于痈，痈肿于经络，增出一番新病。诚不能不未雨而绸缪者也。然为痈为血之枝叶，仍不外乎气郁之火为根，治病必求其本。因思「气从左边起者」条内，有「久患气结诸药不效者，先服沉香化气丸以开其结」之文，不独将来之变病可以预防，即现在之气火升腾亦为要著。而况右脉弦强则土郁夺之之法，本来郑重者乎，但沉香化气丸重剂也，权宜也，元虚久病之体不能不用，不可多用。清晨只服八分，晚服逍遥六君辈调之，以为实必顾虚之计，未知是否？", "9087": "大少爷之病，伏暑晚发之病也。暑邪者何？天之热气下，地之湿气上，人在气交之中，无隙可避，感而受者。假使发于当时，其邪易达，其气未深耳。惟深伏三焦，直至秋晚而发，道远气深自内达外，焉得见轻。所以病经十有三日，日重一日矣。然伏邪仅在三焦，不逢寒热分争之下，所见者无非胸前痞闷，口中甜腻，二便失调而已。兹乃肢麻不已，更见厥逆，显系所患之邪不从三焦而出，反入于肺肝。肝者将军之宫，其性横逆，上犯肺气则见为厥，傍流中土则见为麻，麻厥并至，不惟热盛，亦且肝伤逆矣。然肝阳之逆，暑气之侵，原非无故而作，良以风喜伤肝，未平之前先招风气，引动伏邪。加以阴气素虚，肝失所养，所谓最虚之处便是客邪之处。三焦久病累及乎肝，最为恶候，能不虑其虚不化邪、厥逆频频乎？所幸者，胆受暑。胆属少阳，其机不枢，有出入之意焉。是以寒热之势变为寒热往来，间日而作，俾得从此渐轻，不独肝脏之邪可以外传于腑，即溜在三焦者，亦可望其归并也。但少阴本虚，脉弦而芤，最怕欲化不能，亦恐半途而废，邪实正虚，用药最难入手。然就寤言不寐，多梦纷纭，邪在胆经为甚，惟有十味温胆汤加减，似属左右咸宜。未知是否？候政。", "9088": "四太爷之病，肝肾素虚，肺胃新感之病也。夫肝属乙，肾属癸，乙癸同源，病则本重。但病者多花甲之年，即使不病新邪，筋骨间早已空虚，何堪再经磨耐，又意寒热陡发，直至一候有余而解。解则急急补之，犹恐填而不足，乃又经复食消克等剂，在所必需。幸而外热遽减，里热不清，已虚而益著。其虚咳嗽更剧，渴，痰黏腻，出而不爽，气息短促，形神困顿，饮食不思，病势有加。无已因病致虚，因虚更病，互相为患者也。至于苔色，或黄或白，现在又多剥象，左胁曾疼，两膝常屈，卧床不起，小水仍黄，干而未渴，加以音不扬，睡中语，显系肺胃两经之热。既不能从外而泄，又不能从上而清，邪无出路，断无中道而立之理。势已逼入下焦，两伤肝肾。所谓最虚之处，是客邪之处是也。然邪之所凑，其气必虚，留而不去，其病为实。实则泻之，虚则补之。以使补不足，其邪泻，不伤其正，一举两得，方合实必因虚之计，此等之法，似属从证，而未言脉。然所诊之脉，岂有不合之理。右寸关部弦而且滑，左尺关部细而且数。数则为热，滑则为痰。弦主乎肝，细主乎肾，岂非肺胃两经之热痰正甚，肝肾两经之虚气大昭，无怪乎其气从左逆，卧不能，侧更著。上实下虚之症焉为日已久，肺失清肃之司，相传无权；肾失封藏之本，作强无主。而来喘息标本两治，否则气不归原，难卜其旋见吉兆，三才汤合十味温胆汤两经法加减。", "9089": "清养之下，弦滑脉象较昨颇缓，然肺受热伤每易成痿，不可不虑。", "9090": "喘出于肾，关于肺。标本同源，病始而邪甚，继以正衰，大非久病所宜。热在上焦者，因咳为肺痿，仲圣早已言之。非无意肺之一脏，外为热火所烁，内被肝火所逆，金不生水，水不涵木，木反侮金，其畏如虎。转与复脉汤治其下，苇茎汤治其上，以冀弋获。", "9091": "细绎病原，总不外乎燥之一字。燥万物者，莫燥乎火。火有虚实，火稍清而虚，火之上炎不能归缩于下也。是以黄痰之外，更见粉红，舌干糙燥，便结小坚，肌肤干热，甚至手震睡语，以昭热极生风，液涸风动之象焉。何必以脉之左者反浮、右者反细，而后知五志厥阳之火亦从而暗燥之其金乎？当此肺已虚矣，束手无策，然又不能坐视。惟有资液救焚汤，虽曰鞭长莫及，亦不得不以润万物者，莫悦乎泽之思，以冀吉人天相。", "9092": "夏问伏暑，直至秋末而发，亦云晚矣。晚则其道远，其气深，横连于膜原，外发于阳明。所以初发之时，仅见蒸热，难得汗泄，而不能解。今已二十日矣，曾经化火，发渴发干，阴分必伤。伤阴化燥，本属暑邪见症，而况阳明中土万物所归，尤易化火伤津者乎？然阳明化火伤津，不过清之养之而已，尚可有为。无如所患之症，火内挟饮食之积，结而不开，盘踞小肠，上升则口糜，下注则便泄，泄还不已，转而为痢，其色黄而带灰白，便则多痛，以昭邪盛则实之意焉。设使胃家气旺，肾脏不虚，而用攻克之剂，尚可以胜其任者，原为幸事然，而饮食不思，神情困倦，面白带青，肌肉暗削，小便不多，少阳阳明两经之正气索然，津液先涸，须急补助，已恐鞭长莫及也，岂能再用攻克？诊得右脉弦数，左脉细小。细小为虚，弦数为实，虚中有实。法补实则碍虚，补虚又碍实，用药实为两难。惟有猪苓汤一法，最为瘀后伤阴所合。然下焦可治，而中焦之结者、肝阴之亏者，仍未得以兼治，参入六一散方，佐以芍药甘草汤，为一方而三法备焉之计，以冀弋获。否则悠悠而脱矣。候诸高明先生政之。", "9093": "进猪苓汤后，所见下痢已减其半，所化之邪亦减其半。所以唇之肿者能消，齿之垢者能清，以及右脉之弦数者能缓能和，似属佳兆。然左脉细小，按之仍属无神，且兼关部带弦。弦主乎肝，细小无神又主乎真阴不足。惟以不足之真阴，难以涵养肝木，肝木顺乘土中，尤为易事。如土中尚属有权，往往于病邪消化之后，胃口渐开，生机可望。此乃胃中之津液早被热气所伤，又为下痢所劫，一伤一劫杳不思谷，干呕恶心，所为津劫病至，津竭祸来，此等症是也。若论上肠盘踞之邪，痛势仍然，按之未减，而其位置则已近于小腹，而不连于胁部，势欲下行，还未归并大肠。即使贻患将来，不过为痈为血，尚可徐图。惟此虚态百出，变生眉眼，能无惧乎？然则不得不宗七虚七实、扶正为先之训，回元气于无何有之乡，再图侥幸。候政。", "9094": "惊悸起因，传为颤振，继以寤寐不宁，左脉细软，右关弦数，数则为火，弦则为痰，细软又主乎虚。虚在肝肾，兼以痰火，结在脾胃，所以肢体软弱，口燥身疼也。连日固本，既属安适，可无更张。惟痰火内胜，不以十味温胆法加减佐之，以为标本兼顾之计，俾得虚不再虚，未知是否？同石盘竹香先生议。", "9095": "阴亏之体，肾家一水本来不胜两火。此《内经》仅道其常也。此间更有变者，烦劳之下，火从内起；炎暑之时，火自外加，内外两邪合而为一。以肾水久虚者当之，则阳络受伤，血从外溢，溢而未清，变为咳嗽。甚至有声有痰连连不已，饮食虽可，肌肉暗削。自秋徂冬，正属金水相生之候。是以见症尚和，自觉相安于无事，而不知仲春水旺亦反侮金。金者肺也，肺失清肃则音不扬，咽中痛，其喉为痹，以昭一阴一阳之火气内结，金受其累矣，渐成损症也。然脉形细数，尚未见促，阴火虽旺，阴液未竭，缓以图之，日进滋补，俾得夏至阴生，可卜其旋元吉。现在脉虚火甚，物虽下咽，最为吃紧之时。非清不可，非补亦不可，斟酌于二者之间，惟有钱氏阿胶散法可以加减用之，以合式。拟候政。", "9096": "红疹属血，白㾦属气，气血同病，㾦疹并发。发则病宜解矣，神必清矣。此乃既发白㾦，又发红疹，而神反昏沉，身热不退，气息短促，加以舌缩质红，其苔灰薄，遍身自汗，足胫逆冷，甚至下唇震动两手然。昨多喜笑，小便自遗，本来咳嗽，今反寂然，水饮与之则咽，不与亦不思。诊得右寸脉形滑数，关部濡软，左手皆见细小，按之模糊。想是风邪外感引动伏邪又被湿痰所阻，元气受伤，走入手足厥阴也。势已危笃，每易悠悠而脱，邪从汗出，元气亦与之俱出。正在势不两立之时，用药再为棘手，勉从虚羸少气之例立法，以冀邪尽而元气不与之俱尽，现为第一要著。", "9097": "胃脘当心而痛，继以形寒发热，如疟而作，甚至呃忒频频。此系温邪外感，秽邪内踞，加以湿痰食滞交结中宫也。今使中宫之阳气内旺，所受之邪容易化达。而此间元气本虚，诸邪又伤于后，无力消除，病延多日。所以脉象空弦，神情困倦，非补不可之时也。但舌苔白腻，干欲热饮，下体先痹。今更作麻，哕逆恶心，邪恋肺胃，而肾气亦衰，用药极难兼顾。然温养中宫，佐以上下之品，俾得一举而三善备焉，以冀即日见痊瘳为幸，否则气息易喘，恐增额汗。拟候诸高明先生政。", "9098": "进前剂，麻痹得和，四肢亦缓，且得吐出陈腐酸苦，其色若尘，此皆得温而通也。然呃忒频频，气自短促，呻吟不绝，哕逆呕恶之象仍不陡除。神情困倦，左脉细空，右脉弦急，大便溏黑，喜饮热汤，湿痰邪滞之外，更有瘀血在里。邪从上出，不自下行，已为逆症，而况呕吐之时，曾经额汗，能不虑其虚波暗起而胱乎？哕逆吐逆无不由乎气之所载，气若不平，诸症何从化解？前方加减，先使气平为要。", "9099": "呃忒日轻，呕恶日重，此即陈腐之邪内阻气机，为呃者都从呕出。所以一则见轻，一则见重也。然病根欲拔，而其所出之路逆而不顺，上而不下。失胃气下行为顺之理，却为累事。昨夜额虽无汗，今朝脉尚弦急，呻吟未绝，所留陈腐之邪尚在中宫。犯肺为咳，犯胃为呕，直从中道而出，又带呃逆。必须去尽宿邪，庶几有望。", "9100": "荡涤宿邪之下，呕恶大减，呃忒更缓，脉象稍和，呻吟渐除，大便叠通。无乃胃有下行为顺之兆乎？去痰莫如尽，尚须磨荡下行，继之于后，可卜其旋元吉。", "9101": "阳络伤，血外溢，溢之后，脉宜静。此乃脉细而数，数则为热，细则阴亏。所以气息短促，胸臆隐痛，面色痿黄，语言无力，小水清白，大便漆黑，心悸少寐，气逆或闷。动则火升，倦则阳举，无一而非虚阳上扰，阴血下虚，气不归源之象。气有余便是火，气不足即是寒，不足之气反见有余，此非真火，乃是虚寒。阴不恋阳，血难配气。欲降其气，必须补阴，不言而喻。拟方请政。", "9102": "胸胁闷痛，比之午间大减。良以上焦瘀血渐从活动而清，所进养阴利肺法似属合宜。然气息之短促未长，火升心悸，口燥颧红，脉细，仍数阳气外露，阴血内亏。若能呼吸调和，即是其旋元吉。请政。", "9103": "始而脚痛，继以头疼。陡然昏不知人，手振肉𥆧，动气故。筑牙关与两目上视，面黄颧红，唇上色青，其下亦然，呼吸痰声。左关已无脉，寸部甚微，右尺亦绝，关前独大且滑。其人不吐，鼻且不煽，汗亦不出，四肢厥冷，诸医束手，都以真珠母丸法应酬而剧，此痰祟附于肝经，扰乱不宁，以致地水火风无不上加于天也，古来无此成方，以意逆之，一剂而活动，二剂而舌伸，三剂而能言。归语门人。", "9104": "将欲施药施医施棺于郡邑之中，则必先解囊后劝善，劳心劳力，日费经营，乃可以有为也，然而求活人甚众之举不易得焉。备其药得医省其棺，昔之所难者，今于是乎见之，元和实推为善之乡。当年赈济尚有余赀，仍思设法以公诸贫民，有绅士焉忧上天之疫疠，有富贵者焉患生人之夭札。时维初夏，正暑湿热三气将蒸，又值乙运之岁金不及，亥年之风木偏淫。不惟木寡于畏，反侮其金，而且凶年秽乱之气亦被其扇动于中，人在气交，无隙可避，是一人中其气则为湿温、一方染其气即为时疫之候也。周邑尊既理荒政之余，望其气而异之，集医问乃病，答曰：乙为从革，炎火盛行，亥属厥阴，风淫所胜，风火相煽，则吴又可瘟疫论之见证，不一邪之盘踞于膜原者，势必从九窍传而出，即外起之因内兼之证，以末治之亦不能出此范围也。况吴又可论瘟疫及张石顽论时行疫气、周禹载论湿热暑疫，均值大挠甲子以来第七十三甲子，厥阴司天，少阳在泉，风火用事之时。后先阐发精义入神，会元之司天如斯，值之司天亦未必不如斯。于是邑庙为局，病者接踵而至，门庭若市，内外分科，大小异位。余时切一脉浮不沉而数，望一舌白苔满布，问其所苦，则凛寒发热，昏昏不爽，余曰：达原病。旁一后生曰：如用此法治之，苔必转黄，而邪达矣。服之果然。及问后生为谁，曰徐淡安先生之高弟徐铁峰也。伊父雪峰本属老医，家学渊源从于局中，可谓好学不倦者矣！可谓与人为善者矣！当如同善者如管佛容吴云门先生，冀百数十人分手而治，论表里分界者有人，大剂清凉者有人，下而再下者有人。或湿多而仿湿热混淆之治，或气异而采芳香逐秽之品，或败毒，或消毒，或解毒，粲乎隐隐，各得其所，畴不仰体，痌环在抱之心，共相逐疫，效技于堂庑之中哉！外之往视，诸徒一如局中论治，死生若判霍然而愈者，实不胜枚举已。乃设席延医，继以观剧，成赞且贺曰：见公之作，知公之志。爱民如子，岂不欲救民于衽席？绅之积善余庆，岂不欲周急而扶危？富之好义施财，岂不欲博施而济众？医之婆心一片，岂不欲起死而回心夫？然设是局也，岂博乐善好施之名欤？将使继公之理者，见其实惠知其真心也。", "9105": "皇上脉左三部静细，右动按仍弦、滑数。虽诸恙见成（减），而中焦消化甚迟。清浊相干，脘宇满闷，腹响始通大便，干稀不定，干则降浊，稀则气陷不和，以致神倦色㿠，头愈发眩，足愈无力，必得坐立移动，肢体酸软稍和，仍少寐，口浊咳嗽，恶寒胁痛，左右串作。以脉合证，访金匮之法，以饮食消息之，则药饵可以间服。伏乞圣裁。", "9106": "皇上脉，左右静软，寸关尺三部一律平和。按症体虚，药久未能复元。叠奉圣躬病单，原委分明，始知药有偏弊，中气反困。照金匮饮食消息之义，似乎和宜。谨拟固表和中，以备圣裁。", "9107": "皇上脉两手仍然细软，右关微见数象。大约天气阳不得潜藏，背足俱为酸痛，咳俱为酸痛，咳嗽不平，更牵引胸胁为痛。两日停药，寝食尚好，寒热不发，诸恙有减无增。谨拟肝肺两和调理。", "9108": "皇上脉细而带数，左甚于右。病虚，火浮上则阳不潜藏，下焦虚而不固，遗泄复发。亦属阴亏所致。尚头眩耳鸣，脑蒙发响，咳嗽频作，胸背牵引作痛，行动费力，夜睡微汗七日未发寒热，四日未曾复药，诸恙有减无增。可见多药，却有偏胜，惟原虚，不能不为调摄。仿徐洄溪食颐养法。恭呈圣裁。", "9109": "皇上脉左右各部均见静软。诸恙亦见向安，连日天气和暖，形寒恶风均得减轻，虚阳亦能潜藏；惟肝尚为升，肺少下降，咳嗽略为见紧，耳鸣头响，口渴难寐，胁痛肢酸，运食尚迟，以冀由渐而平。谨拟服食调理，亦能关涉诸病法。恭呈圣裁。", "9110": "皇上脉左三部仍然细软，右寸关弦浮。脾失健运，肝肺又有薄感。昨午腹痛，溏泻而兼糟粕，牵连诸恙，肢体酸软，胁背串痛，乏力软弱，惟咳嗽频。即属肝肺升降失司，脾土不能生金。谨拟调中和表，预防天凉寒暖反复。恭请圣裁。", "9111": "皇上脉左弦细，为水不涵木，木火上升之象；右细数，系脾运不健，湿热下走之征；木火上升，则右耳作堵，闻声不甚清楚；脾湿下走，则气肿作痛，食下运化迟钝。谨拟泄化分利，疏运为法。", "9112": "皇上脉左细弱带弦，右细软微数。右耳鸣响作堵，左足跟微肿作痛，饮食下行迟慢。良由营虚水亏，肝少滋养，气火未能下潜；脾虚气弱，转输窒滞，湿热遂致停顿。调理之法，寒凉则碍脾运，温燥易扰肝阳。谨拟潜阳疏利，以复肝脾升降运融之常。", "9113": "皇上脉左细软之中仍带弦象，右软，按久略有数状。是阴分不充，肝火不潜，脾运迟钝，湿随气滞之证。火浮所以耳鸣作堵，湿滞所以足跟痛，运化不能流利。推致病之由，当在肾阴不足，脾阳不振而论。积根源远，专务治标无益也。谨拟滋肾以柔肝，醒脾以化湿。恭呈圣裁。", "9114": "皇上脉左关细弦，右关微数，余部均细。右耳鸣响作堵，左足跟热痛连及足背，右腋间及腹中时觉窜痛，腰脊间或刺痛，饮食消化不速，头晕，屡有小泡。以脉和证，为水亏火浮，湿郁化热之象。谨拟上泄浮火，下利二便，使可水升火降，湿化气顺。以备圣裁。", "9115": "皇上脉左弦象稍加，右脉尚带微数，按久均细而少力。两耳鸣响，右耳作堵，左足背痈势较轻，跟间依然热痛。经曰：肾开窍于耳。足跟为肾亏，则火浮，阴虚则湿阻，湿火相博，热象渐来。谨拟标治。以期火潜湿化。", "9116": "皇上脉左细如昨，弦象较和。右部尚带渐数。两耳鸣响，右耳作堵，左足跟作痛，微觉焮热，食下运迟，大便不流利，脾肾不足，肝亢有余，火浮于上，湿聚于下，中间转输未能如常，湿热因之停顿。谨拟标本兼治为法。", "9117": "皇上脉左部较静，右部尚带微数。肝木上升较平，脾湿蒸热未解。耳堵稍松，鸣响尚甚，足跟热痛，时有盛衰。考经义：肾主闭藏，脾司运融，肾阴内虚，闭藏不足，肝逆上浮，脾运不健，则气化易滞，湿随下走。谨拟脾肾两治。使得火潜湿解，中运流利。候圣裁。", "9118": "皇上脉左细稍带弦象，右濡细，微微带数。肾不摄肝，肝火上升，所以耳鸣作堵；脾少健运，运迟生湿，所以胃纳式微。迩来左足跟痛引足背。良由气弱湿阻，营络失宣所致。谨拟柔肝醒脾，化湿宣络，标本并理。", "9119": "皇上脉右弦数左细数。属阴虚生风，气虚生湿，风从上扰，两耳鸣响，右耳作堵，湿随气陷，足跟作疼，牵引踝骨。气与阴亏则风与湿用事，饮食少运，大便或干或溏，热升、口舌起泡。症系半虚半实，实不能疏散，虚不能填纳。谨拟滋阴泄风，调中化湿。以呈圣裁。", "9120": "皇上脉弦象稍减，数仍未平。虚火尚炽，挟风则耳鸣未止，右耳堵塞，挟湿则足跟疼痛，牵连踝骨，中运不健，饮食不甚消化，大便今日见溏。虚实参半。谨拟潜阳和阴，借以熄风化湿。", "9121": "皇上脉浮弦，两手均数。虚火总属未平，火生风，耳鸣如昨。右耳堵闷轻减，火挟湿，足跟作痛。络脉仍未宣通，风从肝出。湿自脾生，中运欠健，食后运迟，早间便溏，因之头晕气怯，升降未和所致。谨拟潜阳以熄风，和络以化湿。恭呈圣裁。", "9122": "皇上脉弦象较和，数象未静。所以虚火煽烁，下关不固，腰酸气弱，尚是上盛下虚，耳闷稍减，仍然作响，足跟作痛，略见减轻，惟中焦运融未健，消化犹迟，便垢带溏。谨拟育阴摄阳，参以固养运中。", "9123": "皇上脉仍弦减而数未静。水亏木旺，木火上扰清空，耳鸣不减，木邪下注底极，足跟犹痛，虚实兼见，头晕运迟，脾胃不协。所以夜寐醒后顿觉痰泛，今日更衣，尚能调匀。谨拟上盛下虚。立方。", "9124": "皇上脉弦数之象渐减轻，耳堵较通，鸣响尚存，足痛已轻，筋酸尚留。向来脾胃虚弱，中之少冲和之气。中者，脾胃也，药饵未见备胜，所以治多日转觉气体痰软。似宜暂缓两日或三日。进以一剂醒其胃，而畅其脾，以观病机。拟调中而和上下。伏乞圣裁。", "9125": "皇上脉两关弦数如昨，尺部较软，寸部亦见不足之象。肾不济心，心不固肾。遗泄昨夜又发，所以肝不能潜，耳响未平，重听又甚，脾不能运，足跟仍痛，牵连旁筋，所有夜寐欠实，腰愈酸禁，大便不畅，种种见证。谨拟清心固肾，柔肝运脾。", "9126": "皇上脉弦数较平，虚象更见。遂致遗泄连作，有梦属心，无梦属肾。心肾两亏，诸证纷沓，耳鸣堵闷，略见减轻，足痛步艰，更见痰重，未免清升浊降，未能流利，腰间发酸，大便一时俱发。总核病机审审。下谨拟摄心肾而和肝脾。伏乞圣裁。", "9127": "皇上脉左右一律细软俱见数象。虚火非上扰即下迫，关门不固，叠次梦泄，其为之热，肾无虚已可概见，上热下热必及于中，胃不能容，脾不能运，以致食物消化迟缓，大便未克畅利，所有耳鸣足痛，右耳响闷稍减，足踝酸痛略轻。察病机，合脉用药。谨拟养心固肾，仍不窒碍中焦，以保脾胃。", "9128": "皇上脉左部仍见数象，右细，两尺皆软。营阴不足，气弱不能流利机关，足跟痛减而腰股酸软，耳响如初，且堵闷未和，气不蒸液，天凉口干，气少磨运，消化迟缓。种种见证，谨拟益气以利机关，养液以潜虚火。", "9129": "皇上脉弦象得减，渐转虚软，按之带数。以脉推病，大致肝烁肾，生风则耳窍鸣响，挟湿又为堵闭，肝乘脾，郁湿则足跟作痛，挟风牵及络脉，以致机关皆为不利，肩脾腰胯无处不为酸软，凡此种种脾肾两虚，肝郁独炽，便溏不实，食物消化迟缓。再三审量，拟泄风以宣窍，清热以和络。", "9130": "皇上脉弦数较减轻，所重按皆虚软无力。审察病由，耳响作堵，有增无减，足跟痛有减无增，现在腰痛不止，上连背部，下及胯间。考腰为肾府，封藏有亏，肝木上升，脾湿下陷，偏于右，血不流灌，风湿两邪窜经入络。谨拟从上盛下虚调治，可顾诸恙。伏乞圣裁。", "9131": "皇上脉弦数俱见轻减，按之仍虚软少力。显属有虚无邪，肝家主病面多。由于肾不养肝，肝木侮中，脾胃久而不复，纳食消化迟缓，大便溏结不一，所以肝火上炎，耳鸣作堵仍然未减；下焦不能摄纳，足跟酸痛与腰膝酸软尚未尽止，又为寐时体颤。谨拟滋肾泄热，柔肝熄风，兼顾中焦痰湿，不至腻膈。", "9132": "皇上脉又见弦数。弦为肝邪，数为火旺，水可涵木，木邪侮中，因之湿郁化火，火复生风，上扰下窜，耳鸣堵响未减，腰膝足牵连，痛势此重彼轻。现在足甚于腰，酸软无力，且似经络发热。脉证参详，谨拟解热泄风，通络化湿，为标本兼调。伏乞圣裁。", "9133": "皇上脉弦数，旋平旋起，弦两关为甚，数两尺为多。病情本在肝肾。考肝主筋，肾主骨，股足掣动之痛在于肝，酸重之痛在肾；耳亦属于肝肾，耳为肾窍，肝附胆经亦行耳侧，其耳之鸣响堵闷，由是来也。肝易侮土，肾为胃关，所以食物运迟，大便不调。种种病机，皆本肾肝两虚而起。用药之义，肝非清不安，肾如摄不固。谨拟数味以调诸恙。恭呈圣裁。", "9134": "皇上脉两尺见数，所以又发遗泄。两关仍弦。水亏木旺，木火内燃，上升则耳鸣堵塞，未见轻减，下扰则足跟痛减，又支窜腰胯。阴亏气痹，因之口觉微渴，食物运迟，大便不畅。统核诸证，合以脉情。谨拟调气和阴。", "9135": "皇上脉仍然细小，从中兼于带数。数属心肾两亏，虚火内炽，弦属肝脾不调，至于细小，又属体虚本脉。自调理以来，证情未见轻减。意欲兼顾上下。用镇坠则耳响作堵相宜，恐与下焦不合；用兜涩则遗泻足痛得益，又与上焦不符。既顾上下，又须中权运动，则饮食能运，大便令畅，不全湿热壅气。再之组织以求目的。拟济心肾而和肝脾。", "9136": "皇上脉数较减，尺部依然软弱，卫久虚不复，腰痛减而又增，肾为先天之根本，肾不涵木，木风挟湿蒙窍，耳鸣作堵，肾反克脾，脾湿鼓风入络足跟尚痛，仍然食物运迟，更衣不畅，以脉合证，必须标本兼顾为要。向来虚不受补而攻利亦非所宜。谨拟肝脾肾三阴同治。", "9137": "皇上脉数均减，重拨轻按气无力而软，以脉议证：头为诸阳之会，足为至阴之部，虚阳少潜，耳窍堵响未平，又为眩晕，真阴不充，足肢酸痛就轻，又移腰胯。先天之本虚，后天之气弱，胃之容物，脾之消滞，升降欠度，则清浊每易混淆。所以脘宇撑胀作暖，更衣溏结不调。处方用药，谨拟阴不能不养，借以解热熄风，气不能不调，借以运滞化湿。", "9138": "皇上脉细软如前，又起数象带弦。弦属阴虚火旺，数属阳不潜藏，所以诸纷叠而来，响作堵骤为眩晕，足跟尚痛，又觉酸软。种种上盛下虚，由于肾真亏弱，腰愈酸痛尤甚，咳嗽转动皆为牵引。应当填补相宜。惟心中虚气滞纳食消运为迟，大便溏结不定。向来虚不受补。斟酌于虚实之，谨拟镇肝泄热，安中和络。", "9139": "皇上脉左三关均细软无力，右寸关独濡浮。阴虚阳旺所致。经云：阴在内，阳之守也；阳在外，阴之使也。阴不敛阳，浮阳上越，阳不引阴，阴失下贯。遂致耳窍蒙听，鸣响不止，足跟酸痛，筋络肘掣，阴阳本在为其根，其禀承悉由于肾。封藏内虚，精关因之不固，遗泄后腰痛胯酸，有增无减。诸恙亦未见平，头晕口渴，纳食任酸，大便溏泄。按证调理。谨拟运水谷之精华，调气营之敷布，则合阳平阴秘，精神乃治。", "9140": "皇上脉左右皆静而和，关部不弦，寸尺平调。所见诸证无非虚发，耳响发堵，实者风与火，若虚主脑筋不得充盈也。腰酸足痛，实者湿与风，若虚者血管不流贯也。补脑补血，似乎相宜。惟现在当长夏气候，脾胃司令，著重在清升浊降。所以滋腻重浊诸品，在所不合，仍须调胃和脾。谨拟清煦汤饮，随时酌进。恭候圣裁。", "9141": "皇上脉左三部细软，属阴虚于下，各部均浮，属阳冒于上。以致耳蒙发堵，足跟酸痛，近后阴不敛阳，阳旺内延，关门失固，遗泄之后腰胯坠痛更增，甚至口干心烦，满闷交作，坐卧倦懒，现在脾胃当令，燥则生风，滞则酝湿，因之气与阴虚，风与湿，极为用事。谨拟简括数昧。伏乞圣裁。", "9142": "皇上脉左右皆软，两尺尤甚。由于夏季损气，气失运行，经云：百病生于气。表虚力气散，里滞为气阻，冲和之气致偏，气火上升则耳病，气痹不宣则足病，气之所以亏者，又归肾。肾关久不为固，所谓精生气，气化神之用，有所不足，腰胯之痛，有增少减，且神倦无力，心烦口渴，食物运迟，大便见溏，总核病机按以时令。拟甘温益气，参以柔肝养心。", "9143": "皇上脉右寸濡细，属肺气之虚；左寸细小，属心阴之弱；左关属肝，右属脾胃，见为细弦，系木邪侮中；两尺属肾，肾主火，肾主水，按之无力，当是水火两亏之象。三焦俱及，诸体欠舒，所以腰胯痛胀，大便溏稀，上起舌泡，下发遗泄，无非阳不潜，不藏生风郁热。现在耳窍蒙堵鸣响更甚。再谨拟和阳清阴之法。伏乞圣裁。", "9144": "皇上脉左右细涓，涓甚近数，尺部左软右细，属正气内亏，真阴失固，关键总在脾肾，大便不润，属脾不健化也。梦泄又发，属肾不坚守也。口渴心烦，头晕艰寐，气软体倦，归于脾肾之虚牵连所致。前年病由上而下，虚寒为多。此时病由下而上，虚热为甚。所以上热下寒，耳鸣发堵，腰胯酸重，累月不平，且两日间，食后恶心，卫汗津津。谨将详审原委，推究虚实。拟清上摄下，参以和络调气。", "9145": "皇上脉左部均静软，右三部细濡带数，仍属阴虚于下，阳冒于上，遗泄后阴虚更亏，气阳有升少降，挟心之热挟肝之风，所以耳鸣发堵，孔窍被次，腰酸胯痛，机关不利。考后天主乎脾胃，可以补益先天，乃纳食运迟，大便弗实数稍多，因之气怯神倦，嗜卧眩晕，种种见证，当湿天令，未免中气不和。谨拟调心为主，柔肝运脾佐之。恭呈圣裁。", "9146": "皇上脉左涩细，右濡带数，与昨相同，以脉合证，证情亦无增无减，惟天令溽闷，虚火虚风挟湿上升更盛，耳窍不清，且响且堵，上热愈炽下虚益见，腰胯依然酸痛，种种上下一盛一虚，又关中焦运行不健，所以化食见缓，大便勿匀，诸恙纷沓，口渴头晕，神倦嗜卧。谨拟养封藏为第一义，兼熄肝胆之火，并和心脾之气。伏乞圣裁。", "9147": "皇上脉息细软，身体本合，惟数象时平时起，所以关元不固，更衣频仍，显属少火不藏，而壮火转炽之证见于脾胃者，纷叠不一，耳窍堵响，起与眩晕，腰胯掣痛于步履，遂致精神疲倦，每为嗜卧。诸病未见减轻，元气更为亏乏，证同参，似宜滋水益火峻剂调理。而再三审度，又多有不合之处。谨拟养心以滋肾柔肝以和脾。恭候圣裁。", "9148": "皇上左三部皆静软，右关向来不和，或滑或弦。今诊脉象尚不失冲和之象，气分郁湿，阴虚生热逗留，所以虚不受补，脘宇运迟，大便不畅，中气不调，真阴不复，耳响发不见增减，腰痛胯掣较甚，近因濡暑郁闷，机关更为不利，下虚转为上热，头晕时起，口发小泡，以脉合证，谨协肝脾而化湿。湿化火。恭呈圣裁。", "9149": "皇上脉软数象平而未静，右部关中欠调，病本为气阴虚，脾肾不足，但眩晕为风，便溏为湿，风湿合化，虚热自生。此皆标病所致。昨今腰胯尤觉跳痛，仍鸣而作堵，补则碍标，泻则碍本。恭拟标本双合法。呈候圣裁。", "9150": "皇上脉，左部略缓，右部微数。舌苔淡。木乘土位，湿蕴中宫，上泛则耳鸣气堵头晕，中滞则饮食不运，下注则便溏，腰胯掣痛。宜清肝运脾，兼治下焦，清利湿热，谨拟按证拟方。恭呈圣裁。", "9151": "左湿邪痰滞交炽，热不扬，头晕腿酸，舌黄隐灰，溲少，便通。脉弦数。病经四月，防寒热转重，勿忽。", "9152": "左血液不能下润肠腑，大便难，浊气在上，乃生腹胀，口腻胸闷，溲少，脉细濡。体虚而有湿痰，当先治标分。", "9153": "左湿困中焦，神思困顿，胸闷不思纳，便溏，脉软数。兼之喉肿痛，红而碎。兼顾立方。", "9154": "左表热四日，盛衰不定，脉数便秘，痰多湿温痰滞交结。变迁方多，幸勿轻视。", "9155": "左触痧之后，乍寒乍热，舌黄，梦语、少寐烦躁，便秘溲少，脉弦数不畅。此系湿阻重症。今交四日，变迁易如反掌。", "9156": "左头痛目胀，胸闷连得大便而不多，口腻脉濡。体乏而有湿痰。未易奏效。", "9157": "左湿温病旬日。舌燥黄尖红，热甚于身，裹衣欲起，脉弦数滑，重按少力，大便旁流。积滞不下，溲赤口干，神识不清。湿温化热燥，阴之损则阳长，阳长则阴更竭矣。防猝厥不返，大危大危。", "9158": "左温邪病，正交三候，有汗，布白㾦。昨得大便，邪滞并无疏表攻里，现可无议。惟正气阴液，均已告乏。上拢肝木，下动卫（即肾也）气，气阻丹田，上逆，逆则不已。神思困惫，耳鸣头晕，舌干燥、无津液。脉左数而不调，已有根本欲离之势。右部滑数，痰热犹未全退，厥塞易如反掌。勉拟方以尽人谋，而希天佑。候诸名家正之。", "9159": "左温邪病交旬日，肺胃之邪化火劫阴，直逼厥少，昏蒙，坐卧不安，有汗热不解，气急旁流，渴饮，脉左不扬，右滑数，舌干糙。症情十分危险，防陡然厥变。", "9160": "右发热九日，气急口渴，糊语少寐，脉弦数，舌黄腻。温邪郁伏，恐正不胜病，骤然昏陷变端。", "9161": "右温邪病，有汗热不解，舌灰干，脉数少寐。形将化火，不可轻视。", "9162": "左整三日，有汗不解，渴不引饮。脉弦数，头胀胸闷，舌尖绛。火如燎原，理之不易奏功也。", "9163": "左湿温病一候，脉不扬，舌糙黄。势在转重，防昏陷。", "9164": "左脾阳湿困，得食作胀，舌苔淡黄而白，两脉濡数，大便日夜四五度，少腹沃涩而痛。有时知饥，以挟土化湿。", "9165": "左痰湿气机交阻，咽哽不畅，胸次不舒，中脘易阻。脉濡滑。宜再顺气疏中。", "9166": "右胸闷便泄，舌微黄，脉不畅。灼热气窒，吐痰不利。温邪内郁，表里相传，未可泛视。", "9167": "左形寒热不透，咳不畅，骨痛，舌白，脉不扬。表邪郁不能达之象。须透之。", "9168": "左酒湿积久，中阳被困，运化迟钝，大便易散，脉濡。宜从中焦立方。", "9169": "幼温邪内郁，表热。耳下肿，稍有咳，火升、脉数。法宜透达宣泄。", "9170": "左面垢油亮，目皆黄，头胀如束，胸脘痞闷，此暑湿热气内伏，因劳倦正气泄越而发。既非暴受风寒，发散取汗，徒伤阳气。按脉形濡涩，岂是表症。凡伤寒，必究六经，伏气须明三焦。论症参脉，壮年已非有余之质。当以劳倦伤伏邪例诊治。", "9171": "右脚气痛楚，不能履地。脉弦。宜疏肝宣络，祛风化湿。", "9172": "左脉左为火，腹中胀满，据述肛外臀间，均有豆大肿粒。此属湿热为病。法当内外两治。", "9173": "左热八日，肢麻胸闷，烦躁不安寐，口干。脉不畅。伏邪重症，变迁可虑。", "9174": "左伏暑病旬日，胸闷口干，夜来热壮，不寐烦躁。脉不扬。势在转重。勿忽。", "9175": "右向病风湿骨痛，至今不净，胸闷，心悸，寐不安，脉细数。宜宽中宁神，宣通经脉为法。", "9176": "左表热交八日，肠鸣胸闷，舌黄，脉数。伏暑为病，不可忽视。", "9177": "左日来夜寐稍安，寐中仍易惊惕，口干腻，胃纳呆顿，脉软弦微滑。肝亢脾弱，痰湿热逗留，须兼顾立方。", "9178": "右风火上升，病缠两旬余。头痛从后项而上，暮夜发热，脉弦。须速为解散。", "9179": "左伏暑病旬日。胸闷口干，夜来热壮，不寐烦躁。脉数不扬，热在转重，勿忽。", "9180": "右湿温痰滞交结，表热头胀晕，胸闷骨痛，便泄腹胀，脉不扬。表里相传，转重可虑。", "9181": "左形寒灼热，头胀干呕，咽痒欲咳，咳不畅。脉微数。湿痰中阻，外袭风温，宜宣泄涤邪主之。", "9182": "右乍寒乍热，胸闷头痛，口腻泛呕，脉不畅。宣先透达利湿兼进之。", "9183": "左寒战发热，得汗渐解，头痛如破，脉不扬。湿邪痰滞交结，极易转成连热，殊不可忽。", "9184": "左头晕，神倦胃呆。舌黄口溲，形寒灼热，脉濡。宜燥湿和中，疏解表邪。", "9185": "左湿温病，今交旬日。泛呕咳嗽，脉弦滑数，舌白黄，溲赤、便溏。邪滞交结，殊不可忽。", "9186": "右类疟寒轻热重，少寐口苦，舌黄，脉弦不畅，二便俱红。湿温痰滞蒸热，积滞不下。变迁可虑。", "9187": "左湿郁气阻，胸脘痞闷，舌滑脉濡。宜燥湿疏中。", "9188": "右表热间日而作，热不外透，头晕胸闷，腹中鸣响作胀，遍体百节烦疼。舌苔不清，不思，脉不畅。湿温内郁。延防转重，未可忽。", "9189": "左吸受秽邪，自口鼻而入，遂致清浊失常，吐泻交作，今虽渐止而邪未尽出。头胀重，胸闷腹胀膨大，脉微数，肢冷。病方外达，急当乘势而透达邪表，以防转重。", "9190": "幼热八日，得汗热缓，汗干热甚，胸闷，舌质红、口干，脉软弦。暑邪与阳明热交炽。防转重，毋忽。", "9191": "左形浮灼热胸闷，脉不畅，便溏溲少而赤，得食中阻。暑湿为寒凉所束，以防连热不退，殊不可忽。", "9192": "右腿酸便泄均减，寒热依然，胸闷口腻如昨，舌白，脉弦数不大。暑湿滞深重，变迁可惧。", "9193": "左身热甚衰无定，胸闷咳痰不利，舌白腻。腹痛便少，足冷，寐多梦，暑湿滞交阻气道。脉不畅。极易变迁，慎之。", "9194": "左发热旬日，胸闷大便复闭，不寐，脉弦数，舌黄垢。两候时届，昏痉厥变虑也。", "9195": "左表热七日，无汗，头晕胸闷，脘腹拒按，便闭，夜来糊语，脉数不扬，舌黄垢。邪滞积伏深重，骤变可虑也。", "9196": "左触痧之后，痰湿停阻中宫，二便不通，不思食，胸闷，脉不畅。防蒸成寒热，未可忽。", "9197": "右脉不畅，面浮头晕，脐下作痛，便溏，舌红。风伤于上，食滞中阻。延防转重，未可忽。", "9198": "左风水病，今交五日。寒热退，浮肿如昨，咳嗽较畅，寐则气急，头痛脉数浮。风湿热互郁。宜肝脾兼治。", "9199": "左脱力伤阳，阳气不能运湿，肌肤发黄，四肢无力，舌白无华，脉弦濡。二便俱通，防延腹满，未可忽。", "9200": "左舌黄垢腻，大便燥结艰行，茎中痛漏不少，又起血麻，脉软弦带数。湿郁化火，火势方张，一时不易奏效。", "9201": "左寒热退而复作，面浮渐退，咳嗽较稀，气急头晕而重，溲通便闭，脉浮数。风得温而化火，火性炎上，鼻衄色鲜。宜清化泄降。", "9202": "右形寒烘热均瘥，大便泄泻转溏，得食脘痛。脉弦濡，舌白腻。湿滞阻气，尚须疏通分利。", "9203": "左畏风，热不扬，胸痞头胀，遍体痛，脉数重按少力。湿温痰滞阻气。宜先表里分解。", "9204": "右饮食不节，寒暖不时，头胀口苦，肠如燥泄，脉不畅，舌白腻。脘部拒按，防蒸成下痢。殊不可忽。", "9205": "左形寒灼热，头晕口腻吐涎，舌微黄，脉弦数。湿温痰滞交结。变迁可惧。", "9206": "左表热七日，舌黄口干，音胸闷痰腻，咽间不易咯吐，脉不畅。病方转重，此属湿温，正在发越之时。勿忽。", "9207": "左头胀晕减而未愈，畏风亦较瘥，呼吸胸口牵痛，脉不畅，大息少力。宜泄风平肝、泄降主之。", "9208": "右壮热五日不退，胸闷头晕，舌黄，少寐糊语，脉弦数不畅。秋凉引动伏暑，病无出路，昏陷可虑。", "9209": "右耳鸣腹胀，头晕，脉不畅，溲赤。宜利湿疏中为法。", "9210": "左表热五日，头胀胸闷，咳不畅，腹痛，脉数。温邪内伏，急急透之。", "9211": "左（倪少兰出诊方）伏邪晚发，已交七日，热甚于夜，烦躁，寐中呻吟不已，指搐谵语，邪蒙。脉弦滑数，舌干黑无津，大便不通。症情十分险重，昏厥变幻，可立而待也。", "9212": "三方：表邪化热，热甚于日晡，继以呕逆，今通大便，结而且畅。腑邪渐有出路。惟经邪留恋尚多，脉滑数，舌糙黄。病在阳明，治宜存阴清热。", "9213": "四方：卧届一候，幸得腑气畅下，表热得解，但右脉未静，口味不清，舌津未全回，搐搦止而不净，余邪尚有逗留也。最易借因生端，饮食寒暖须慎之又慎。且本体虚弱，时近大节，用药须为预筹。", "9214": "五方：病缠一候，发热不退，不甚恶寒，焦寐不安，将寐自语喃喃，手指搐动。此温邪病也。虚体邪郁，不易外解而易传里，脉状细数而软，舌白黄少津。拟泄火以救阴，解肌以透邪，然风波易起，殊非寻常表症可比。至外症一层幸有松机。治当顾及之。候诸高明政之。", "9215": "六方：表热退净，流注得消，舌津已回，无一非佳象也。脉细软，胃纳微，体本不充，时近夏至，尚须珍重起居，俾可早日强健。今方宜参调理法。", "9216": "七方：表症全退，气阴稍得来复，寐中尚有惊惕自语。舌津不足，脉来濡，气弱易积痰湿，阴薄易动心肝。宜清理调理兼进之。", "9217": "八方：表症初得清解，气阴未能遽复，寐中惊惕、神思未振，舌津不足。脉状较昨稍畅和。所幸疡患得消。可无他虑。当再循法理之。", "9218": "九方：外疡已消，内热未尽，纳谷不多，胃气尚能知饥味。脉右弦，舌薄白。中气素弱，营分不和。治宜存阴养胃，以泄余热。", "9219": "十方：复病伤阴，表热得汗不解，神志似昧，间有谵语，指搐胸闷，便秘溲赤。舌苔薄、尖光干少液，咽关起有糜点，脉状弦数。邪滞郁阻未达，无如阴分先伤，势恐陷逼厥少而起风动之波，其势颇重。复病难从表达。拟以存阴泄热为法。", "9220": "十二方：复病发热，热不大壮而正气已疲惫，阴已告匮，惊惕抽掣，神倦嗜卧。舌干光有白糜点，有矢气无大便，脉右软左弦数。因虚生火，火甚劫阴，阴乏，生风变细幻极易。殊非寻常表症可比。格外慎护为要。", "9221": "十三方：复病发热，正不敌邪，邪火劫津动风，一身振惕搐搦不已，神昏，热壮舌缩而干。脉状模糊，病涉厥少，防内闭而转外脱，势实危急之至。候诸高明政之。", "9222": "十四方：复热幸已退清，肝风瘛疭，亦得平静，舌糜大减，津液尚未来复，脉状较昨为和。格外珍卫，勿令寒热往来为要。", "9223": "十五方：昨宵安寐，溱溱汗出，顷得热退，神清内风亦平，惟左脉弦而不散，右脉软数。营卫未能调畅，最防往来寒热，且舌糜不退，阴损已极，又虑胃气不复，格外慎护，以希渐渐应手。", "9224": "十六方：两次病缠，所虚已甚，表分不固则多汗，正气内乏则神思疲惫，运用不健。脉数舌光淡、少血色。须格外加慎，俾可日起有功。", "9225": "十七方：顷间起坐之后，肢冷畏寒，汗出不已。脉微数软，舌全光，头胀。一派虚象，即使小有感冒，仍以扶正为要务，否则猝起虚波，可虑之至也。不得不预为筹及。", "9226": "十八方：昨虚惫百出，进气阴两补法，幸合机宜。今诊脉仍软弱至甚，遍体骨痛。舌津得回，虚汗得定，头痛渐止，循法善调，以御风波复起。", "9227": "二十方：昨畅汗，肌灼头胀藉汗而解。今脉尚静，舌苔亦润。症情尚稍安和，惟本体素虚，一时不能复原。当溽暑薰逼，不得不加意慎调。", "9228": "二十一方：表热复来，虚体不能胜病，迷蒙嗜卧，舌干光无津液，有糜点，寐即指搐手动，脉左弦数、右软，均不甚调。大便不通，腹病非初病可比。颇有可虑之处。姑进救阴泄热以冀应手。", "9229": "匝月前，表热两作，旋即口渴不已，肩肋酸痛入腹，脉弦。温邪伤阴入络。当表里分解。", "9230": "左昨起寒热，头胀，脉数不畅。宜疏达法。", "9231": "老公祖（吴县正号）湿热未楚，舌苔黄，脉带弦数。尚须清化分利，务使肝胆之火与膀胱之湿，各得平靖为要。", "9232": "左（正号）三阴疟初止，脉状未静，营卫未和，所病未清也。须格外加慎，以防反复。兼之肝肾不足，风湿痹络，左腿痛而酸尤须速为解散，以防结疡。", "9233": "左头痛发热渐愈，肢冷畏寒尚甚，咳嗽痰多，脉数。拟六安煎加减法。", "9234": "左积滞已解，运化未醒，脉弦。本体不充，素有湿热，当标本两治。", "9235": "左头痛久不止，近增骨痛，脉数转弦。阴薄肝亢，外受风邪。拟清理之，再为培本。", "9236": "左频咳不畅，夜来寒热，脉数。风温留恋肺经，非透达不可。", "9237": "左曾病风痹，至今复原未足，脉濡。当和气血，解散风湿痰浊。", "9238": "右作寒发热，头痛无汗，咳嗽鼻塞，脉数而不畅。宜疏散表邪。", "9239": "左胁刺痛、温痛，病甫得解表，未净之邪壅气，作呃不止。脉弦细。病情尚在险途，仍防变迁。", "9240": "左湿痰咽腻，劳伤骨痛，脉濡。稍有感冒。治当兼顾。", "9241": "左恶寒发热，久不止，脉弦软。本体内乏，未可忽视。", "9242": "左病约五日，热势交暮为甚，头痛、遍体痛，舌白黄垢，口腻脉数，不甚鼓指，大便溏泄，溲少不寐，烦躁。病未双透，正转重之时也。", "9243": "右胃阳不振，时易泛酸，舌白黄。胃气呆木，大便溏，脉弦数。经郁气阻，未易奏效。", "9244": "左表热气急，气短，舌糙黄，口干胸次闷塞，便闭，不得寐，脉滑数。头痛邪滞，积伏不浅。防塞逆变幻。", "9245": "左脉软滑数。软为脏阴亏乏，滑数为痰热有余。舌中灰腻，口干咽燥，耳聋糊语，咳嗽痰白，便闭、溲少。邪正交病，风波易起，万勿忽。", "9246": "右昨宵形寒发热，头晕腹痛，呕吐。舌白黄，脉数。当表里两治。", "9247": "左头重胸闷，表热，脉不畅，肢冷。病方鸱张，变迁可虑。", "9248": "左内阻痰湿，外感表邪。恶寒胸闷，脉不畅，舌黄。防转重，勿忽。", "9249": "左表热颇壮，胸闷稍有咳，腹膨、便溏溲少，脉数。病方鸱张，变迁易如反掌也。", "9250": "热经一候，胸闷便薄，少寐糊语，气急，舌糙黄起刺，质红，口干脉数。此非轻症，不敢忽视。", "9251": "左头胀鼻塞，形寒。风邪伤卫，风性偏阳，卫亦属阳，以阳从阳，其气必浮，是以夜来惊惕，咽痒咳塞窒，脉微数。当专从上焦宣泄，勿使邪恋生波为要。", "9252": "左尺肤热脉盛躁者，病温也。温从热化，最易烁阴。舌白黄，边尖绛。头痛、胸次不适，少寐起经五日，正发越之时也。", "9253": "左温病由口鼻而入，首先犯肺，由肺达表，恶寒表热，热势不壮，头痛无汗，院腹痞闷，不耐拒按，二便俱少，脉数不甚鼓指，夜来烦躁少寐。舌黄、口干。遍体作痛，此系重症。已延五日。最防昏陷化燥。", "9254": "左恶寒发热，已起六日，热势午后为甚，头胀痛，胸闷，语言吃力，舌黄，四末不暖，脉数不大，二便俱通。温邪恰交一候，最防迁延转重。未敢轻视。", "9255": "右外寒内热，头晕胸闷，脉不畅，舌白黄，口干，二便俱少，夜少安寐，遍体痛，温湿逗留，热不外达。病势方张，变迁可虑。", "9256": "右湿郁困脾，遍体无力，知饥不能食，嗜卧，舌苔不清，脉状尚能流利。拟先顺气疏中。", "9257": "右阳胜则身热喘粗，不得寐，咽痒咳窒，头晕胸闷，脉数不甚大，脘次拒按，大便溏薄，小溲热，舌白黄，口干，时时作恶。病约八日，正发越之时，极易化燥昏陷。", "9258": "右脉数不大，舌黄，口干少津液，唇燥，脘腹拒按，二便俱少。病势十分险恶，发越之变，可立而待也。", "9259": "左神疲嗜卧，一身无力，咳逆气急，痰多，咳则汗来，舌根黄、前半少苔、多裂纹，脉软，寐则多梦纷纭，纳少。体虚病深，中挟痰湿，最防作喘。", "9260": "左热不退五日，汗得不足，咽间痰阻，舌黄垢，脉数，寐不安神。温邪逗留肺胃，最防逾后变幻。", "9261": "右表热两日，遇风形浮，头胀胸闷，遍体不适，脉数不大，舌黄，咳嗽痰多。宜肺胃两治，以防转重。", "9262": "左形寒表热，头晕口腻，胸闷腰痛，脉不大，溲通便闭。温邪湿滞交结，正在转重，勿忽。", "9263": "左尺肤热、脉盛躁者，病温也。温从口鼻而入，鼻通于肺，肺主皮毛，则憎寒发热，热已七日不退，头痛胸闷烦躁，舌糙黄。口干渴，急欲饮水求救，仍复吐出。脉弦数，寐则糊语。此系险重之症，昏厥易如反掌。", "9264": "左此方出于三月底之日令，势有寒痧挟滞之象。故附录于此，以便对照细看，庶不致临证蒙混。寒滞中阻，清浊相干，乱其中气。干呕水泻，舌黄脉数不大，溲少，时寒时热。病方鸱张，可虑。", "9265": "右热六日，痰鸣如曳锯，气急鼻煽，咳不止。脉弦数，溲少、口干，舌垢。温邪痰热熏蒸肺胃，极易痰升喘变，势实吃重之至。", "9266": "左湿温病六日，汗少热不退，胸闷，舌白口渴，渴不引饮，脉濡数，大便不畅，溲少，夜寐尚安。病交一候，正属风翔浪飞之时也。", "9267": "湿温病一候，表热解里蕴犹重，胸闷痞，大便溏泄，已下数次，溲少，抵暮时躁不安寐，汗出溱溱，脉濡数。症情尚在险途，小效恐不足恃也。", "9268": "左病延八日，热不退，胸闷略松，大便溏泄渐止，小溲较利，昨宵躁扰不宁，不得寐，有汗有矢气，舌薄白，脉濡数。温热为痰湿所裹。正属出入关头，风波迭起之时也。", "9269": "右病起旬日，表热不退，胸闷脘腹不适，大便溏薄，溲赤，脉数不大。温湿互郁转重可虑。", "9270": "左头痛头晕，胸闷、咽关红碎，夜来微热，当脐痛，大便溏，溲黄，脉数。百节烦疼，舌黄边尖绛，口渴引饮。湿温化热，防化燥昏陷。", "9271": "左发热十二日，热势颇甚，口干，舌黄、质绛，胸闷躁扰不宁，脉数溲少，汗得不足。温邪痰热熏蒸肺胃，极易化燥昏陷，刻属两候，风波易如反掌也。", "9272": "左因于寒，体若燔炭，头胀痛，发热不扬，舌糙白黄，汗少少寐，大便溏、溲少，脉濡。病延六日正，属发越之时也。", "9273": "右头晕胸闷，心宕纳少，气急，时时泛呕，腰酸带下，脉软，舌白。肝脾肾同病，中挟湿热，宜择要治之。", "9274": "左湿郁蒸热。舌灰垢，口苦，发热不壮，胸闷头晕，便通，脉小弦数。宜表里分治法。", "9275": "左病起六日，热壮不为汗裹，头晕气闷，舌黄垢。脘腹不适，大便溏而不畅，少寐，遍体痛，脉数。拟宗温痛银翘散主之。", "9276": "左温病九日，热炽千里。脉小弦数，舌糙黄带灰，垢厚边尖绛，口干渴饮，大便溏薄极臭，小溲赤少，糊语喃喃，彻夜不寐。邪滞痰热熏蒸肺胃，深恐陡然痉厥，未敢忽视。", "9277": "二方：昨服药后稍能得寐，糊语渐止，似乎较有起色，但热退不净，痰热犹甚。舌垢化薄，脉弦数，便闭，寐则多梦纷坛，小溲通利。邪热痰热犹多逗留，仍防猝然厥变，不敢以小效为恃也。", "9278": "左热一候，大汗淋漓，脉细数，胸闷头晕，舌白黄，两腿酸，寐则糊语。素体不足，湿热邪滞，逗留极易起波，毋忽。", "9279": "右表热三日，但头汗出，口淡腻，舌白黄垢，二便俱通，脉弦数。风温痰热互郁，防连热转重。", "9280": "左痰热上升，神思迷糊，脉滑而不畅。健忘心乱，急宜泄降主方。", "9281": "左发热五日，有汗不解，舌边糙、中根垢，脉数。宜解表疏里。", "9282": "右发热九日，夜半更重，胸闷不寐，气急，脉数不畅，舌黄。温邪痰滞交蒸，变迁可惧。", "9283": "左表热七日，暮夜更甚胸闷，脉数，二便不利。温邪痰滞交结，行将转重，勿忽。", "9284": "左发热六日，昼轻夜重，重则糊语，脉数。胸闷便溏，温邪交蒸，防转重。", "9285": "右（第一方后有第二方）表热气急，心不食。舌垢，脉数不扬。肝气而兼温邪，表里同病，不可忽。", "9286": "左（第一方后有一方）发热八日，汗出式微，遍体烦疼，胸闷头痛，咳嗽，脉数。温邪挟痰湿滞蕴蒸肺胃，势方转重。不可轻忽。", "9287": "右（此方因有寒字恰与热字相反故录入以便对看）寒湿滞中阻，胸脘闷塞，不欲食，脉不畅。防增寒热。", "9288": "左（昨已备过，今第二方）热九日，昨汗不少，仍无安寐，胸闷咳嗽，脉数，大便不行。温邪痰滞，蕴蒸肺胃，行将化火转重，不可泛视。", "9289": "右（昨已看过，今第二方）温邪、肝气为病，恶心发热不得寐，脉数不畅。势方转重，不可忽。", "9290": "左（第一方）发热八日，大便溏，少寐，脉数不畅。温邪痰湿交郁，防正不胜病。", "9291": "左发热九日，口干，溲少、便闭，脉数。邪滞交结，不可忽视。", "9292": "左（第二方）发热九日，胸闷不寐。脉细数。体虚病实。变迁可惧。", "9293": "左大便已通，气坠腰脊作酸，小溲不流利，脉细。阴分虚而湿热重。理之不易。", "9294": "右表热恶寒，胸闷头痛，病起旬日，舌灰黄，脉细数。温邪痰滞交结，转重可虑。", "9295": "左前病未清，昨又恶寒发热，至今不净，便溏腹痛，脉微数。宜解表疏里。", "9296": "湿温病十二日，头胀耳鸣，便秘，脉滑数。正交两候之际，防陡然昏陷。", "9297": "左旧病发热呕吐，遍体烦疼，便溏胸闷，脉滑数。防转重。", "9298": "左湿温病将两候，四肢易冷，头痛胸闷，不得寐，脉数。形将转重。弗忽。", "9299": "右发热畏风，头痛作泛，胸闷，脉数不畅。宜透达泄化。", "9300": "左本体不充，无力运融痰湿。脉弦。宜标本两治。", "9301": "左发热不净，呕吐稍愈，脉滑数。骨痛胸闷，湿温旧病，极易变迁", "9302": "右湿温病八日，热重于里，烦闷，脘肋痛，脉滑数，舌黑。正转重之时，勿忽。", "9303": "左昨寐较安，发热亦稍衰，大便未行，舌黄垢、质红，脉细数，右三部较大。邪伏伤阴，须由渐解散。", "9304": "复诊：湿热表邪，蒸久伤阴，发热止作不定，时易作咳、作呃，夜来口干，脉微弦而数，少寐。表病传里，未易速效。", "9305": "左湿温病十二日，热势夜甚，甚则神思模糊语言不清，大便未能续下，舌中心干燥，脉弦滑数，右部大于左，胸闷口渴，少安寐。正届两候，险关最防反复，变幻，不可以小效为恃。", "9306": "左昨寒战发热畅汗，所患便溏，胸闷呕吐均转松，但舌上灰、黄垢，脉滑数。仍防变迁。", "9307": "复诊方：湿温病两候，头晕耳聋，舌灰黄垢，疹㾦不多，脉数。风波方兴，勿以小效为恃。", "9308": "右头晕，心慌手振，胸闷夜来寒热，脉濡滑。延防转重。", "9309": "左痰火气机扰乱神明，语言不自主，脉左弦，甚于右。近有寒热，当治所急。", "9310": "乍寒乍热，已及旬日，汗少，胸闷头痛，脉数不畅。温邪内郁，变迁可惧。", "9311": "右乍寒乍热，约已十二日，胸闷头蒙，脉数。转重可虑。", "9312": "左作寒发热，胸闷，大便溏泄，脉数。宜表里两解。", "9313": "右湿温病十二日，表热内伏，便闭、脘次不通，舌黄，脉不畅。拟通导下法。", "9314": "左风邪入络，四肢骨节肿痛，脉细。曾经痰中带血，当泄风宣络主之。", "9315": "右作寒发热，解而不净，脘次不畅，腰痛，脉数。宜表里两治。", "9316": "右胃脘作痛，恶寒热不透，脉数不畅。宜解表疏里。", "9317": "左口味不醒，大便不下，脉弦，左半体作麻。拟养营润肠，泄风宣络。", "9318": "左发热旬日，胸闷脘阻，口干气急，舌灰白黄，脉数不畅。湿温痰滞交结。宜透㾦疏中。", "9319": "右作寒发热稍愈，胸闷、咳嗽恶心，心中热，脉数。重症勿忽。", "9320": "左表热旬日，神思迷蒙，糊语口干，咳不畅，脉数，舌灰黑。防正不胜病。", "9321": "左热半月，便秘，脉弦数。温湿蕴蒸，延防变迁", "9322": "左（陈伯英先生）脉弦，不时胸闷气短。此肝肺升降不调，痰湿气机未能流利也。", "9323": "左湿温病十二日，化火伤阴，舌焦干灰黄，脉数。无汗，糊语，便闭，防厥陷。", "9324": "左湿温内敛，大便溏，寒热不透，胸闷痰多，脉左弦、右濡。宜表里两解。", "9325": "左肚热四日，气急肋痛，脉数，舌灰黄。重症弗忽。", "9326": "左回病寒热复发，又经四日，脉滑数，大便又阻，胸闷少寐。阴伤邪恋，防陡然昏厥，万弗忽视。", "9327": "左表热胸闷，脉数。头胀湿温痰滞交结。其势方张，弗忽。", "9328": "幼风邪湿热，壅肺气阻，表热不达，气急一身尽肿，脉数。防喘塞生波。", "9329": "左风湿痰入络，左半体作麻，筋络之间不能速效，姑从缓议。刻下胃口呆滞，痰吐不流利，脉弦。宜先为清理之。", "9330": "左发热三日，汗少，胸闷恶心，头晕，脉濡数。势在转重，弗忽。", "9331": "左发热十二日，舌黑，体乏，病实，脉数。最防晕厥。", "9332": "左复发热，头痛恶心，腹痛、腰痛，脉数，腿络抽掣。重症毋忽。", "9333": "左身热作躁，自汗，脉数。温邪痰湿交蒸，势不可忽。", "9334": "幼壮热气急，脉数，口干弄舌，脚冷。时气郁不能达，防厥。", "9335": "右湿温遂病三日，胸闷、烦躁不寐，便三闭泄，口干，脉不扬。势极险重，毋忽。", "9336": "左身热暴躁，自汗、均能得愈。惟痰湿阻胃，不时作吐，脉状尚数。须作速导之下行。", "9337": "左寒热不净，舌白、带灰，咳嗽胸闷，心中烦热，脉细数微滑。正在出入之际，不可忽视。", "9338": "幼表热未净尽，小溲少，脉数。蕴热尚重，弗忽。", "9339": "幼温邪内闭，气急神蒙，口干壮热，脉数。势将厥变，危急非常。须多请幼科先生政之。", "9340": "左（十四岁）发热，起初畏风，今交四日，舌黄，脉数，便闭。湿温初起，转重可虑。", "9341": "右乍寒乍热，有汗不解，今交三日，脉数不畅。湿温重症，勿忽。", "9342": "左表热已解，里热未化，脉濡、舌白，胸闷。勿以热退为恃。", "9343": "左胸闷骨痛，发热便闭，脉数。湿温，痰滞交结。转重可虑。大豆卷（三钱）枳壳（三钱五分）六曲（四钱）猪苓（三钱五分）藿梗（三钱五分）橘红（一钱）楂炭（三钱）泽泻（三钱）白蒺藜（四钱，炒去刺）法半夏（三钱五分）莱菔子（四钱，炒）桑枝（一两）玉枢丹末三分、红灵丹（一分，枇杷露一两，调化温服）", "9344": "右还病四日，汗出不已，脉濡。体虚邪恋，不可忽视。", "9345": "左温邪为湿热所恋，发热不解胀神疲，脉实弦。延防转重，不可轻忽。", "9346": "幼肺闭，喘急稍平，神蒙口干，壮热尚甚，脉数。危阴已极，挽回不易。", "9347": "左（正号）肢体无力，胯间结核，背脊亦痛，脉弦，夜肌灼。阴气内乏，温湿互郁。当标本两治，俾可早日奏功。", "9348": "左胸次渐松，脉濡，小溲热而赤。宜疏利二便，以通湿热。", "9349": "右湿温病两候，胸闷神躁，糊语，脉数。势甚凶凶，不可忽视。", "9350": "右湿温病八日，适值经胸闷，脉数。正在转重，不可忽视。", "9351": "左骨痛稍愈，神甚疲乏，肌肤灼热，脉弦。阴气不足，风湿热互郁。当清化营热宣通络气。", "9352": "世兄风水病之后，两足易冷，行步少力，脉濡。宜清理之中，稍顾本原。", "9353": "左病逾两旬，表热渐解，足膝痛，大便闭，舌黄、脉数。防反复生波。", "9354": "右寒热复来，脉微弦。旧恙未楚，新邪复乘，须慎之。", "9355": "右脘腹痛，得饮食即吐，胸闷，作寒发热，脉数而不畅。势在转重，勿忽。", "9356": "左素易心慌惊悸，兹则四肢易麻木，溲短，脉滑。宜化湿痰，顺气机。", "9357": "左发热七日，夜热尤壮，咽痛口干，脉数。宜引邪外达，导热下行。", "9358": "左身热便闭，腹不舒，骨痛，舌干糙黄，脉数。今交十一日，防转重。", "9359": "左胸闷胃呆，腹胀，脉濡。拟流利气机，疏畅痰湿。", "9360": "左胸脘闷塞，不能食，恶寒少寐，脉濡。宜透达疏化。", "9361": "右肝气撑胀，风湿痰交郁，头痛胸闷，痰腻，神疲，脉软弦。防寒热，须加意慎养。", "9362": "右作寒止，胸闷减，头晕发热，口苦少寐均如昨，脉濡滑数。拟再治表。", "9363": "右右手举动作痛，肩臂尤痛，脉弦滑。营虚生风所致。", "9364": "左触痧之后，转为便泄不已，胃气不来，胸闷溲赤，表热不透，脉不畅。治宜疏化。", "9365": "右腹膨胀，得食痛，气攻心脘，脉重按带滑。宜顺气疏中。", "9366": "道士寒热，日暮为甚，口腻咳嗽，本体不充。湿滞留恋。脉软濡。一时不易奏功。", "9367": "右湿温病一候，新产四朝，瘀阻，热壮，舌干糙，脉弦数，糊语，腹痛下痢。十分危险。防厥变。", "9368": "右咽间干热，头痛痰腻，心中懊恼，脉软数，小溲热。郁火湿热为患也。", "9369": "左肝阳鼓动痰浊，不时头晕，心荡惊恐，脉不畅。宜平肝涤痰。", "9370": "左身热恶寒，头痛胸闷，大便闭，不寐，舌黄，脉弦数。湿温蒸热，防转重。", "9371": "左一身肿胀，脉濡。风湿相博，延防作喘。", "9372": "左湿温病一候，胸闷咳痰，不得寐，口干舌黄，脉滑数。重症毋忽。", "9373": "左肺胃伏热，脉数不畅。拟导热下行，俾不致火流为患。", "9374": "左（此方虽属寒症，不应录入温热部内。一因寒字恰与热字一对面，一因湿病甚重。故录在此部内，一阅。）寒湿蒙遏清阳，神疲腹胀，足肿滞，脉濡。延防中满。", "9375": "左发热十二日。脉软弦，舌黄、质红。暑湿重症，防厥。", "9376": "左脱力久不复，纳少，胸腹不舒，脉滑。宜疏运化湿。", "9377": "幼咳嗽便溏溲少，面浮，脉数。风湿尚非浅缈也。", "9378": "右腹胀胸闷，气短，右腿酸，脉细。拟疏肝和脾，化湿理气。", "9379": "右气短胸闷，自汗神疲，舌碎腐作痛，脉弦。气郁生火，易于转重，勿忽。", "9380": "右（出诊方）营虚阴薄，肝脾两病，湿阻气机，运化迟钝。由是大便不畅作泻，腹微痛，心胸微热，腰酸，日午头痛为甚，脉右濡、左实弦不畅。拟疏化并进，以复转运之机。", "9381": "右肝升胃热，头晕心荡，食下，脘腹胀，脉细。一时不易奏功也。", "9382": "右伏暑病旬日，耳聋胸闷，神躁不寐，便溏，舌黄、脉数。防昏陷。", "9383": "左头痛眩晕，食少易饱，肢节酸，胃气作痛，脉细。病繁当治所急。", "9384": "左痰湿中阻，脾胃交困，胸闷不食，舌垢，脉数不畅。拟疏化法。", "9385": "左转筋霍乱，肢冷，脉伏舌黄。大势危急，防厥闭。勉拟方以尽人事。", "9386": "左转筋霍乱，肢冷脉伏，音夺眶陷。即防内闭致脱，勉拟方以尽人事。", "9387": "右病九日，今幸泻止呕停，但胸次未畅，心中犹热，脉弦，舌灰黄。仍勿忽视。", "9388": "右转筋霍乱初停，口干胸闷，汗多，脉数，带软。仍防内闭外脱。", "9389": "左水泻三日不停，口干腹闷，脉左细、右弦数。防阴夺，不可忽。", "9390": "左转筋霍乱，外象似定，内暑未解，闷热如烧，脐肢痛，脉不扬，舌黄。防厥变。", "9391": "左还病壮热，约八日，脉模糊如伏，神昏，舌黄。防陡然厥陷。", "9392": "左伏邪病经久，恶款齐备，虚风大动，脉细如伏。危殆已极。勉拟方以尽人事。", "9393": "右胆胃痰热不平，甚致心无所依，神无所归，虑无所定，头胀蒙，惊惕，脉滑数。宜镇肝涤邪及痰。", "9394": "左肝胆痰热上亢，神机虚，语言易顿，夜少熟睡，惊惕，脉弦数。宜镇肝涤痰为法。", "9395": "右舌垢，发热不畅已旬日，糊语，不寐多梦，脉数。温邪痰湿交结蕴蒸。变迁可虑。", "9396": "右表热留恋，腹瘕攻逆作痛，大便溏，纳少神疲，脉软。劳乏积湿所致。", "9397": "左腹满䐜胀，瘕撑食下阻。脉濡。肌肤发热。宜疏畅肝脾，流利湿热。", "9398": "左暑湿病已十八日，神识模糊，脉数不调，头晕，舌白黄。势防厥陷骤变，毋忽。", "9399": "左（此病在春二月初如春疫之状）著凉停滞，加以春寒包里，阳邪外郁，遂致清不升、浊不降，悉被浑淆，吐泻交作，两腿弯转筋，舌垢，脉不扬。此属未至而至，殊不可忽。", "9400": "右风邪痰浊，鼓动肝阳，耳鸣重听，舌垢，口腻，遍体作酸，脉滑。宜平肝豁痰，兼散风邪。", "9401": "左头胀痛，表热不壮，喉关红，舌白黄，脉数，咽间干，便闭溲少。温邪郁肺，最虑转重。", "9402": "赤芍（三钱）石决明（一两，先煎）象贝（四钱，去心）鲜芦根（一两，去节）通草（一钱）淡豆豉（三钱、）鲜生地（一两，二味同打）白蒺藜（去刺，四钱）竹茹（三钱）黑山栀（三钱）白杏仁（四钱，去尖）连翘（三钱）右温邪外乘，湿热内阻，头胀蒙，遍体酸，胸闷，脉濡。因于湿，首如裹，湿热不攘，大筋软短，小筋弛长，神瘦嗜卧。起经多日，转重可虑。", "9403": "左表热不净，汗多、并起浆㾦，舌质红、少苔，口干脉数。稍有咳，温邪蒸郁化热，宜泄化透邪。", "9404": "幼发热得解，神思疲惫，痰嘶，四肢不暖，二便俱通，脉细软。病缠正乏，弱症渐著。责效殊非易易。", "9405": "幼表热神迷，哭窒无泪，舌白，口干，脉数，二便俱少。质小病重，波澜莫测。", "9406": "幼寒滞束伏肺胃，发热不扬，神迷气急，哭窒直喊，欲咳不出，脉不畅，脘部拒按，大便溏，小溲少。小舟重载，何堪胜此波浪。", "9407": "幼表热较淡，舌黄垢，四维不暖，腹膨便闭，脉数。邪滞交结，昏陷可虑。", "9408": "左头旋目花，有眩仆之状，脉弦，纳如常。即经所谓诸风掉眩，皆属于肝也。宜肝涤痰。", "9409": "左人暮发热，少汗泄，头胀，脉数，舌白黄。湿热温邪，逗留防转重。", "9410": "幼恶寒发热，头胀痛，胸闷，腹中不适，便闭溲少，舌微黄，口干咳嗽，脉数不畅，少寐。温邪挟滞交结。症属寒多热少，不可忽视。", "9411": "左湿郁气阻，胸脘痞闷，口腻头胀蒙，恶寒微热，大便不畅，脉濡。宜表里两治。", "9412": "左温邪不从表达，直陷厥少，神昏气鼾，舌黑而垢，扬手掷足，脉细小不大，脘部拒按，矢气极臭，大便不行，小溲自遗不禁，唇焦齿垢。表热不扬，邪伏深沉，险如朝露。勉拟方，以希天佑吉人。候诸高明政定。", "9413": "幼痉后表热不退，无泪，咳窒汗多，脉数，大便通，膝间肿硬，满口碎腐。质小任重，防其厥闭陡变。", "9414": "右吐泻六日，败象齐备，今日泻势稍减，肢冷得暖，气急亦平，脉软，舌乾红，神气迷蒙。终恐发厥骤变，小效不足恃也。", "9415": "幼泄泻起惊之后，满口口糜，舌灰黄、糙燥，胸闷肌灼，神蒙，脉数。胃阴大夺，肝火上亢，最防厥变，势甚险恶。", "9416": "真风斛青蒿茯苓银花石决明丹皮扁豆衣通草竹卷心赤芍甘草鲜稻叶左发热十七日，炽。阴气大损。白㾦布而不绽，舌薄白，口干，脉软弦数，夜寐得安，腑气未下，胃口不开，足冷。本体虚乏，须速为清理，以冀早日复元。", "9417": "左表热四日，头晕，胸闷烦躁不寐，舌糙黄，糊语，脉数，便闭，腹拒按。邪滞交结，极易昏陷骤变。", "9418": "左仲春腹痛，交夏失血，近增咳嗽、午后形寒发热，舌白黄，脉数。此复新暑也。当治所急。", "9419": "右转筋霍乱交三日，冷汗，脉如伏，指甲紫黑，舌黄。邪入三阴，防骤然变端。", "9420": "左病缠一候，发热不退，不甚恶热，寐不安，将自语喃喃，手指搐动，此湿邪病也。虚体邪郁，不易外解而易传里。脉状细数而软，舌白黄少津。宜泄火救阴，解肌以透邪热，风波易起，殊非寻常表症可比，至外症一层，幸有松机。治法当顾及之，候赋翁政之。", "9421": "又（其二）：昨届一候，幸得腑气畅下，表热得解，但右脉未静，口味不清，舌津未回，搐搦止而不净。余邪尚有逗留也。最易借因生端，饮食寒暖，均须慎之又慎。且本体虚弱，时近大节，用药须为预筹。", "9422": "又（其三）：表热复来，虚体不能胜病，迷蒙嗜卧，舌干光无津液，有糜点，寐即指搐手动，脉左弦数、右软，均不甚调，大便不通。复病可比，颇有可虑之处。姑进救阴泄热，以冀应手。", "9423": "又（其四）：复病发热，正不敌邪，邪火劫津，动风一身振惕，搐搦不已，神昏热壮，舌缩而干，脉状模糊。病涉厥少，防内闭而转外脱，势实危恶之至，候高明政之。", "9424": "又（其五）：昨宵安寐，溱溱汗出，顷得热退，神清、内风亦平，惟左脉弦而不静，右脉软数。营卫未能调畅，最防往来寒热，且舌糜不退，阴损已极，又虑胃气不复，格外慎护，以冀渐应手。", "9425": "又（其六）：复热幸已退清，肝风瘛疭亦得平静。舌糜大减，津液尚未来复。脉状较昨为和。格外珍卫，勿令寒热往来为要。", "9426": "又（其七）：复病发热热不大壮而正已疲惫，阴已告匮，惊惕抽掣，神倦嗜卧，舌光干有白糜点，有矢气，无大便，脉右软左弦数。因虚生火，火甚劫阴，阴乏生风。变幻极易，殊非寻常表症可比。格慎为要。", "9427": "又（其八）：顷间宿垢畅下，下后神识较清，然语言多，而气机促，所说尚多不轻，有微汗，仍壮热，舌光干至甚，脉左大于右，右软数。一派阴液为邪火劫夺之象，最怕正不胜病，猝然直陷变幻。", "9428": "又（其九）：两次病缠，所虚已甚，表分不固则多汗，正气内乏则神思疲惫。运融不健则得饮即肠鸣不已，此皆虚体病后之象。脉软，舌光淡、少血色。须格外加慎，俾可日起有功。", "9429": "又（其十）：顷间起坐，小溲之后肢冷畏寒，汗出不已，脉微软，舌全光胖。一派虚象，即使小有感冒，仍以扶正为要务。否则猝虚，波可虑也。不得不预为筹及。", "9430": "又（其十一）：昨虚惫百出。进气阴两补法，幸合机宜。今诊脉仍软弱至甚，遍体骨痛，舌津得回，虚汗得定，头痛渐止。循法善调，以御风波复起。", "9431": "文（另方，非接前也）昨畅汗，肌灼头胀，藉汗而解，今脉尚静，舌苔亦润。症情尚称安和。惟本体素虚，一时不能复原。当溽暑薰逼，不得不格外加慎。", "9432": "罗新凉外乘，伏暑内发，发热无汗，头胀甚，呕吐吐蛔，心脘烦热，舌黄带灰，脉数不畅。势正发越，未可泛视。", "9433": "又（其二）：昨呕恶，烦冤，竟夜不能安眠，今晨幸溏垢三下，胸腹较松，但汗少、热不解，脉右弦滑数，左细。尚是伏暑未达，邪滞交结之象。急急表里两解为要。", "9434": "其三：伏邪病五日，壮热无汗，热至语言谵妄，昼夜不寐，口干而碎破起泡，脉左弦数，右不大，舌绛苔少。邪火劫烁阴液，须从早化达，以防热入厥少。兹正吃紧之际，须格外加慎。", "9435": "其四：伏邪病六日，热甚无汗，神思昏糊，语多谵妄，夜来狂躁尤甚，唇燥齿干，口破起疳腐，舌绛中有干灰苔，脉数带弦。阳明邪热，痰滞，直逼厥少，实恐昏厥内传，十分吃重之至，候多延。高明政之。", "9436": "其五：热届一候，表分颇解，里蕴之痰热邪滞依然郁蒸不宣，从无汗泄，昏谵减，狂躁定而黎明烦冤，不可名状，唇燥齿干，口碎，舌糙干，白黄，脉弦数不调，耳聋目蒙。阴分已伤，深恐正不胜病，热陷变幻，不敢以小有松机为恃也。候高明政之。", "9437": "其六：伏邪化热，直逼厥少，神识昧多清少，掷足扬手。热深厥深，肢末发冷。口干，舌苔薄黄。病交八日，恶象毕集，最不宜者，莫如脉状不大。深恐厥陷陡变，势实棘手之至。同石翁议方。候诸方家政之。", "9438": "其七：伏邪病十一日，幸能渐渐转机，但痰热极重，阴分极薄，表热留恋不净，神乏，口干不引饮，脉数，重按少力，舌糙黄，质绛少津。两候已迫，尚须慎之又慎，不敢遂以小效为恃。候石翁诸方家政之。", "9439": "其八：伏邪初逾两候，中间波澜叠起，兹虽既汗、既下，而痰热犹重，阴乏已甚，午后壮热，夜来作躁，耳鸣畏烦，神识清中略昧。舌根尚未退清，脉弦数，左大于右。本虚标实，变幻易易。不敢以见松为恃。同石翁议方。", "9440": "其九：热缠两候，阴液大夺，邪火痰热进逼厥少，不寐烦躁，风动谵语，便溏极臭，时欲起坐，脉细数带弦，舌糙黄少津。正不胜病，厥陷可免，症情十分棘手。姑就拙见，拟方候彤石翁政之，并候高明酌夺。", "9441": "右风温客肺，肺气上逆，不能安卧，脉数。最防伤肺动营，须加意静养为要。", "9442": "咳逆，咽痒音闪，起经三月，脉不扬。防纠缠不已。", "9443": "左受风作咳，表热自汗，脉数。宜从上焦泄化。", "9444": "右作寒、咳逆均减，舌红、口碎，腰腿抽痛，脉数。宜标本两治。", "9445": "左咳痰如沫，脉来弦。宜泄化宣肺法。", "9446": "左阵呛、发热，脉软数。防喘塞生波。", "9447": "右寒微、热甚汗多，口干咽燥，咳嗽甚极，脉细软，形瘦色夺。本体亏损，理之不易。", "9448": "音闪稍畅，咽干头痛，火升形寒。脉不扬。宜即守前意增损。", "9449": "幼蕴热恋肺，肺失清肃，咳呛阵作，二便俱热，口干，晨起头晕，灼热，语声重滞，脉数带浮。一时不易速愈。", "9450": "左体虚易感，不时背寒发热，咽痒咳窒，腰酸背痛，脉濡。法当表里两治。", "9451": "右温邪客肺，咳嗽，稍有表热，脉数。法当泄化。", "9452": "左咳嗽稍平，满身痛，脉细。宜表里两治。", "9453": "右脉细数，右弦，咳逆气急痰多，耳失聪，胃不醒，少寐。肺肾两病。之不易。", "9454": "西洋参（三钱五分，生切）川贝（三钱，去心）橘白（一钱）白芍（三钱五分）朱麦冬（三钱五分，去心）生蛤壳（一两，杵，先煎）竹茹（二钱）紫石英（四钱，煅，先煎）川石斛（四钱）朱茯神（四钱）生草（四分）左咳逆音闪，脉数。气火上浮，法宜泄降。", "9455": "右温邪湿热，留恋阳明，表热，胸闷溲赤，脉数，咳嗽。宜从表分立方。", "9456": "左咳嗽三月不止，咽痒痰白，脉数，头胀形寒。温邪迭有出入。宜辛散宣泄。", "9457": "右日来寒止，热在肌肤之内，腰酸咳嗽，脉细。本症从感冒而起，未易速解。", "9458": "左进宣泄上焦法，咳声稍减，肢冷脉濡。尚宜清理表分。", "9459": "左咽哽积久，气升作咳不寐，脉细弦。体虚感温。理之不易。", "9460": "左寒热止，表病均解，惟咳嗽不已，脉数。向有肺痈之根。最防复发。", "9461": "左咳久，气阴两损，气冲痰多，脉数。体乏病深，不易奏功。", "9462": "右咳久，嗜食形瘦，脉细。阴损火浮，不可忽视。", "9463": "右努力伤气，气道失宣，由是行动气急，胸处作闷，干呛不已，脉细微数。渐渐近涉本原。须加意慎养。", "9464": "右木郁化火，火盛乘金。咳逆气急，山根肿胀，头晕耳鸣，脉软弦。标本同病，最防喘塞。", "9465": "左风邪上受，首先犯肺，肺邪不达，失其清肃下行之权，咳逆痰多，大便带血，头目不清，脉不畅。宜宣泄涤邪，以防转重，免伤肺气。", "9466": "左咳嗽内热，时易腰痛，腹膨胀，阴薄感风。脉微数。当先治所急。", "9467": "左脾为生痰之源，肺为贮痰之器，脾弱则生湿，湿蕴则蒸而为痰，二气涌肺则为喘粗咳呛，舌中黄、尖绛，口干不欲多饮，夜无安寐，二便俱通，暮则肢冷，火升有汗，脉弦数。痰湿热无从散布。痰者火之标，火者痰之本。今方拟润肺降气，涤痰安神并进之。", "9468": "右风温郁肺，肺气失宣，咳嗽咽痒，神疲脉数不扬。当疏泄治之。", "9469": "左咳嗽不畅，气急头痛，脉数。宜宣泄上焦。", "9470": "桑叶（二钱）白蒺藜（四钱，炒去刺）川石斛（四钱）橘白（一钱）白杏仁（四钱，去尖）冬瓜子（七钱）元参心（三钱五分，炒）竹茹（三钱五分）象贝（二钱，去心）生蛤壳（一两，先煎）茯苓（四钱）生草（三分）加生谷芽（五钱，绢包）左阴虚伏热烁肺作咳，咳久音哑，咽关红丝满布，脉细数。病道深远，须逐渐调理。", "9471": "桑白皮（三钱五分，蜜水炙）鲜沙参（五钱）川贝（三钱，去心）元参（三钱）橘络地骨皮（二钱）黛蛤散（一两，绢包）冬瓜子（一两）甘中黄（一钱）蝉衣（七分）海浮石（四钱）料豆衣（三钱）加枇杷露（一两，冲服）玉蝴蝶（三分）右晨间气升作咳，咳无痰，食下作酸，舌根黄白，脉弦。宜平肝润肺，疏畅脾运。", "9472": "左舌黑颇退，咳痰稍愈，精神仍疲乏，脉右软、左细弦。宜顾及本症。", "9473": "左咳痰腻，气急，动即喘，头痛，脉弦。宜平肝泄肺。", "9474": "右咳嗽气急，寒热胸痛，脉数，腹冷。温邪郁肺，防厥闭喉腐。", "9475": "左咳嗽不畅，音哑，脉不扬。风热痰浊交郁。不可忽。", "9476": "左痰喘咳逆，足膝软弱，脉软弦。延防喘甚生波，须加意慎养。", "9477": "左脉左软、右细，咳嗽积久，形瘦色夺，音哑，少安寐。肺肾交困，五液蒸为痰浊，虚损告成。理之棘手。", "9478": "左（正号）咳嗽气急，吐痰浓薄不定，足肿面浮，脉微弦。此属支饮，由脾经化湿生痰，上输于肺所致。防喘满并增。", "9479": "左（正号）恶寒作咳久不止，痰吐白腻，渐至胃纳日减，脉濡滑，夜寐咽干。寒郁化热，伤及阴分，须加意慎养。", "9480": "右（正号）咳嗽痰吐如沫，发则气急，不能安卧，脉左细、右软滑数。病根积深，不易速效。兼之腹瘕上逆，法当两顾。", "9481": "旋覆花（三钱五分，绢包）紫菀（三钱五分，蜜炙）冬瓜子（一两）瓜蒌皮（三钱）代赭石（四钱，先煎）款冬花（三钱五分，炙）白前（三钱五分）茯苓（四钱）煅瓦楞粉（一两，包）白杏仁（四钱，去尖）象贝（四钱，去心）生米仁（三钱）左（正号）咳嗽久不愈，音闪、咽燥口干，气急足肿，脉左细、右数，大便不实。亏损已久，理之棘手，须多请高明斟酌。", "9482": "左咳逆气急，畏寒，脉细。延防作喘。", "9483": "左温邪为痰湿所敛，咳嗽不已，音闪，脉滑数。宜泄肺化邪。", "9484": "右表邪郁肺，咳久不畅，咽干作痒，脉数不畅。宜宣泄上焦。", "9485": "左干咳音闪，胸前不畅，背脊胀，脉微数。延防失血。", "9486": "左咳嗽咽痒，头痛气急，腹痛，脉数。宜疏化宣泄。", "9487": "左脉弦。咳逆气急，动即作喘。上实下虚，理之不易。", "9488": "左热为寒束，肺失宣畅，咳嗽气逆，气短，脉弦数。治在上焦。", "9489": "右咳痰薄白，咽痒，脉数。", "9490": "右咳嗽复发，恶寒气急，腰肋痛，脉虚弦。肺肾两病。理之不易。", "9491": "左表热五日，咳嗽胁痛，脉数。防痰升气塞，骤生变端，不可轻视。", "9492": "右久咳阵来，畏寒痰少，脉细。亏损已甚，理之不易。", "9493": "左脉软，咳嗽气急，气逆，腰腿酸软。积虚已甚，治宜求本。", "9494": "左咳逆痰多，音哑、胸次微闷，脉滑数，咽关红。风温逗留，当从上焦宣泄。", "9495": "左咳逆痰沫，胸脘痞闷、纳少，舌白黄，脉弦数。宜泄肺下匀", "9496": "幼寒暖不调，表邪外束，午后发热，咳嗽多嚏，舌花白，脉数。宜表里两治。", "9497": "右干咳不已，咽痒无痰，胃纳减少，脉软弦，舌白黄。肺阴交困，最易见红，宜润肺止嗽。", "9498": "左温邪上受，首先犯肺，肺失清肃，咳嗽壮热，气粗无汗泄，头晕胸闷，腹部拒按，大便不行，舌垢脉数。邪热痰滞熏蒸肺胃，极易化燥痉厥，非轻症也。毋忽。", "9499": "右发热解，干呛不已，晨间鼻衄，脉软弦。气机拂逆，纳如常，宜择要治之。", "9500": "右咳嗽匝月不松，气逆不得安寐，手足心微热，脉左细、右滑。宜泄肺顺气。", "9501": "右（正号）夜来掌心热，咳嗽痰黏，心胸痛，肢节酸，鼻孔有血，脉弦。阴虚则热自内生。当标本两治。", "9502": "右咳痰如沫，乍寒乍热，咽痒曾失血，腹痛恶心，脉软。防成募损。", "9503": "方（世兄）咳嗽吐痰极多，脉数。风温郁肺胃。宜泄化主之。", "9504": "方（小姐）风郁化热，咳久渐转顿嗽，鼻衄，脉数。宜清润肺胃。", "9505": "右咳吐痰沫，经期少，脉左软、右数。脾肾两病，勿泛视之。", "9506": "左咳嗽痰多，表热，脉数。病势方张，毋忽。", "9507": "左咳嗽日久，乍寒乍热，脉细弦。阴损肺燥所致。", "9508": "右咳稍松，气仍塞，寒热、胸腹痛，咽哽，脉细。蓐损可虑。", "9509": "左咳嗽宿恙，近日呛剧，气急，脉弦。延防生波。", "9510": "右咳嗽复发，痰吐浓薄不一，脉左细、右滑，腰酸。湿为凉风所束，最防作喘。", "9511": "左脉左细涩、右数虚，两手均无神，咳嗽动则更咳，所吐之痰均臭秽白腻，舌上满糜，好于唾物，胸闷自汗，发热，大便溏泄。肺肾两竭，中土又夺，顾此失彼，如何援手，姑拟存阴泄火，培土生金。", "9512": "左咳嗽一年余，胁痛恶心，脉细数。肺病积久，理之不易。", "9513": "左咳嗽痰多，气短，脉软。疟邪痰湿郁肺，防作喘。", "9514": "左（正号）嗽后亡血已止，溲下尚未流利，脉软弦数。阴分虚，湿热重相火不潜，一时不易速效也。", "9515": "左咳嗽不畅，舌黄不清，脉濡。宜宣泄上焦。", "9516": "左咳嗽咽痒，脉弦。宜宣畅肺气。", "9517": "右咳嗽渐止，腰酸肢酸，脉左软、右微滑。宜即守前章进步。", "9518": "左咳嗽音哑，咽痛痰多恶心，脉弦数。阴薄火郁，最防失血。", "9519": "寒热得解，胸闷气急，咳嗽不流利，脉濡，口干腻。治在肺胃。", "9520": "右咳嗽不已，夜卧尤咳，头胀，胸肋痛，脉数右弦。防呛甚见红。", "9521": "右咳嗽匝月不止，咽喉肿碎作痛，脉数。宜泄肺胃之邪热。", "9522": "左（正号寿翁下再有一方）咳嗽年余，津液尽为痰浊，形瘦骨立，肤槁气短，脉软少神，且不调。病深矣，区区药石，能有几何力量。姑备方候高明酌用。", "9523": "左作寒发热胸闷，咳嗽。湿热为风邪所包。脉数不畅，宜透达宣泄。", "9524": "左因痰作咳，痰多神乏，脉软弦细。桔槁已甚，理之不易。", "9525": "左热旬日，咳嗽胸闷，脉数。邪滞交结，解散不易。", "9526": "左腹痛、胀闷，咳逆，脉弦数。宜宣泄疏中。", "9527": "左腹痛、胀闷，咳逆，脉弦数。宜宣泄疏中。", "9528": "左脱力，咳嗽身热，脉数。中挟风湿，延虑转重。", "9529": "左咳痰不流利，气急腹胀，口苦，大便溏，恶心，脉左细、右弦。拟流利气机，疏化痰湿。", "9530": "左咳嗽腰胁痛，身热神蒙糊语，正不胜病，防厥。脉弦，舌黄。不易为力。", "9531": "左咳嗽痰多，便泄少纳，脉细。肺脾同病，理之不易。", "9532": "左宿哮根深，适有感冒，脉弦。宜宣泄肺气。", "9533": "僧咳嗽腹满，面浮足肿，瘕逆，脉细数。肺脾同病，理之棘手。", "9534": "左咳嗽久不止，气急痰薄，脉弦。病道深远，理之不易。", "9535": "左气急干咳，夜不安寐，脉软弦。当镇肝泄肺。", "9536": "左劳乏之后，干咳吃力，脉细数。内热，延防失血。", "9537": "僧咳嗽腹满，面浮足肿，腹瘕胀逆，脉左细、右弦。肺脾交病，理之不易。", "9538": "左风热袭肺，咳嗽复发，脉微数。宜轻清泄化。", "9539": "左多年咳嗽，迩来转甚，胸闷，脉左细、右软弦。宜泄肺宽中。", "9540": "左咳嗽积久，甚则呕吐痰沫，脉软滑。治在肺胃。", "9541": "幼童哮，近日咳甚，痰中稍带红色，脉数。内热。宜清润肺胃。", "9542": "左肺主气，其状如钟。肺气失宣，鼻塞咽痒，咳窒、痰吐不利，音哑，脉数。当作金实无声治。", "9543": "左温邪为风所束，头胀鼻塞，咳嗽吐痰不利，脉数。当从上焦宣泄。", "9544": "右咳嗽交四日，黄痰白沫并吐，气急肌灼，脉濡。枯瘦已甚，理之不易。", "9545": "左哮咳五年未发，近又喘急不已，痰沫卧醒后痰浊较浓，舌薄白，脉弦数。防喘塞生波。", "9546": "左至夜少寐，气急、晨咳嗽舌干，脉左弦、右数。宜从阴引阳法。", "9547": "左头胀咳嗽，两腿酸，胸闷，脉数。宜表里两治。", "9548": "右三月前咳血涌吐，刻下痰红，头晕心恐，脉软，口腻。阴薄火浮，不可忽视。", "9549": "左失血咳嗽，形寒，脉右部大。防血随气升，勿以轻视。", "9550": "左痧后冒风乱食，咳嗽顿作呛，痰带血，面浮腹膨，午后身热，脉数。淹缠非宜。深防入怯。", "9551": "右素体劳乏，内伤营络。近日咳嗽已经见血，舌苔白腻，不渴脉来濡软。以泄降宣络，淹缠非宜。", "9552": "左失血之后，咳逆不已，脉数。延防肺痿，勿忽。", "9553": "右血虚，虚火煽烁，嘈杂如饥，曾失血，脉软数。宜甘润生阴。", "9554": "右失血之后，经少带多，心宕头晕，虚象层出，又以口干为最重，右寸脉及左关脉均不静。最防气火动发。", "9555": "左血后咳嗽，起肛痈，虚汗，脉数。肺移热于大肠，根蒂内乏，虚怯可虑。", "9556": "左咳痰如脓，甚则呛血，脉右滑数、左细。宜清润上焦。", "9557": "左用力受损，痰中带红，脉软弦。阴分受伤，须善为调理。", "9558": "右血后咳嗽，脉软滑数，纳少便溏，理之大非易易。", "9559": "左吐血旧恙，今夜发，三日不止，均系满口，且咳呛不已，咽痒，舌黄，脉弦数。毒火浮风，最防血随气升。", "9560": "右久咳肺虚，形瘦满口失血，脉数。拟清润泄降，以治所急。", "9561": "左吐血之后，腰痛神疲，足膝无力，脉左弦、右软。亏损已甚，勿忽。", "9562": "左咳嗽痰多，厚薄不定，时易胸痛气闷，脉弦。自失血起因，已及年半，肺损肝亢。延防失音。", "9563": "左咳呛不已，吐血满口，脉数。防涌冒。", "9564": "右大失血之后咳呛气急，脉细数。肺肾交困，殊不可忽。", "9565": "右抑郁不解，心肝交困，背寒鼻热，黎明虚汗，心痛如抽，少腹酸胀，腰痛不寐，脉细，吐血，不易见功。", "9566": "左痰红止，喘势渐平，浊泛口腻，咳即气升，脉弦。肺肾同病。最防反复。", "9567": "右产虚久不复，曾吐血。兹火升，薄暮微寒而热，脉软。咳嗽渐成蓐损，不易治。", "9568": "右吐血复发，脉不静。最防肺痈，急急泄火下气为要。", "9569": "左咳嗽白痰带血，脉软、弦，左肋背作痛。邪郁肺损，理之不易。", "9570": "左脉虚弦，咳嗽失血，音闪。阴损已甚，须加意慎养，不可忽视。", "9571": "左客腊呕吐，胃纳呆木，脉空弦。伤血积瘀。须善为调理。", "9572": "左吐血盈碗，气急咳呛，脉弦数。防壅冒。", "9573": "右向有咳嗽，近增吐血，舌光绛碎，腰痛腿热，脉弦数。阴虚火浮，静养为要。", "9574": "右吐血之后，脉软、神疲，气阴两亏。宜加意慎养。", "9575": "右吐血屡发，心胸咳嗽，脉细。阴损火浮，不可轻忽。", "9576": "左血上下溢，脉细，口干，面色不泽。阴气大损，理之不易。", "9577": "左满口失血较瘥，咳痰仍带血，脉软弦。肺阴大损，防壅冒。", "9578": "左失血后转为咳嗽，肺阴旱经所困，咳增音闪，咳痰厚薄不一，知饥不能食，脉软、弦。病深矣！不易治。", "9579": "左吐血咳嗽，互缠不已，甚则得食辄吐，脉细数。气阴同病，理之不易。", "9580": "左伤血复发，心荡骨痛，脉弦。本体受损，不可轻忽。", "9581": "左咳嗽不松，甚则带血，口干，脉数。宜清润上焦，宣泄肺气。", "9582": "右吐血复发，头胀痛，内热，脉数。本体不充，宜先治肝肺。", "9583": "左阵呛见红，胁痛，脉弦，稍有寒热。拟先宣泄上焦，以畅肺气。", "9584": "左吐血之后，咳嗽不净，气急便泄，脉细。此非轻症，不可忽视。", "9585": "左咳嗽痰中带红，口干不作渴，脉细。宜滋养阴分，清化痰热。", "9586": "左咳嗽较松，痰血不净，口干，脉数。此非细故，不可忽。", "9587": "左日前吐血复发，脉细数，咳嗽无痰，遍体无力。亏乏已甚，理之不易。", "9588": "右向病冬春咳嗽，近日忽增吐血，脉弦舌黄。体虚病实。诸须加慎。", "9589": "右（正号）脉尺部软，余弦，心肝部尤觉不静。自前年冬，至今失血屡发，所吐血点为多，神疲口干。阴薄火浮。须加意慎养。", "9590": "左吐血屡发，鲜红而多，脉软、弦。当此火令，尤易转重。", "9591": "左久咳络损，失血痰多，咳吐不流利，脉弦。积久肺痿。", "9592": "左白浊年余，日前失血，脉左软弦、右滑。宜存阴化湿热。", "9593": "左客冬失血，近日大发，咳嗽痰鸣，脉洪数而滑，发热口腻。防壅冒。", "9594": "左失血，十年未发，近因伤风作呛，痰中带红，脘下筑紧，一身疲乏，脉弦，右微数。肺阴受损，未可泛视。", "9595": "左十余年前，有红症。近因感冒，咳逆带出痰红，肋间微痛，脉状软数。宜以先治上焦。", "9596": "左倾跌之后，血上下溢，向有腹满癖块，脉弦，右如大。受损已甚，不易见功。", "9597": "左伤血，热血交作，脉微数。宜慎养。", "9598": "左吐血之后，干呛气急，胸闷，脉数。防陡然涌吐。", "9599": "左客冬起，咳嗽痰多，有血，脉数微弦。病深矣。不易奏功。", "9600": "左咳嗽吐血、音哑，脉软数。喉痹告成，理之不易。", "9601": "左咳嗽咽痒，吐血，脉数，心嘈。阴伤火炎，最防涌冒。", "9602": "右咳久肺胃两病。干呛甚则作吐，痰中带血，暮夜发热，脉数。此非细故，不可轻忽。", "9603": "右阵呛稍减，干咳尚甚，痰血得止。但夜热神疲，脉软数。阴损火郁，小效未可恃也。", "9604": "右客冬大失血，今腹大神疲，不时寒热。脉软。气阴两病，理之不易。", "9605": "左失血渐止，干咳尚甚，脉细数。宜润肺泄热。", "9606": "左久咳不已，上年失血，近吐痰薄而白，脉软。向患下痢，至今大便必痛。肝脾不调，肺肾两虚，理之不易。", "9607": "左咳嗽音散，失血，脉软弦数。满咽红，著枕即咳，防成虚损喉痹。", "9608": "左痰中带血，小溲浑浊，大便不实，咳嗽，脉细。肺脾两病，不可轻忽。", "9609": "左脉弦数，咽关红肿，咳久音散失血。暑天尤难奏功也。", "9610": "左（正号）咳嗽起于失血之后，音闪痰多，胃纳式微，脉软弦数。肺胃两损，渐及中土。病已深入重地，理之不易。", "9611": "左血止复来，干咳胁痛，心宕，脉细数。病易反复，诸须慎之。", "9612": "左客冬吐血、鼻衄，刻下胸闷神疲，脉弦右软，拟清理痰湿。", "9613": "左吐血纠缠，吐时头顶发热，脉软数。宜育阴潜阳，导热下行。", "9614": "左（正号）昔年吐血之后咳嗽不已，左胁痛，易寒易热，脉细弦、左软。肺肾阴亏，不能收摄肝木，木火烁金，最防血症反复。", "9615": "鲜沙参（四钱）桑白皮（三钱五分，蜜炙）黛蛤散（一两，绢包）川石斛（四钱）甜杏仁（去尖，三钱）地骨皮（三钱五分）橘络（一钱）茯神（五钱）川贝（去心，三钱）粉甘草（四分）丝瓜络（三钱）枇杷露（一两，温服）加白茅根（一两，去心）左肝木乘肺胃，咳嗽失血，兼之肾关不固，且脘次结硬，脉弦。宜先治所急。", "9616": "左曾病满口失血，迩来痰嗽带红，脉细数。阴伤火郁，不可忽视。", "9617": "左脉细数，满口失血，咳嗽胸闷。阴薄火浮，最防壅冒。", "9618": "左咳嗽带血，纳少神疲，脉细数。渐成虚损，勿忽。", "9619": "左咳嗽少松，痰多、血不净，脉弦微数。宜存阴泄火。", "9620": "左伤血后，咳嗽不已，骨节痛，食下腹中不适，脉弦。理之不易。", "9621": "川石斛（四钱）黛蛤散（七钱，绢包）仙鹤草（三钱五分）大腹皮（洗，三钱）陈皮（一钱）川贝（去心，三钱）十灰丸（吞服，三钱）炙鸡金（去垢，三钱）盐半夏（二钱）冬瓜子（一两）丝瓜络（二钱）冬瓜子（五钱）加鲜稻叶（三钱）藕节（五钱）右咳嗽四月不止，近日吐血，咳不畅，脉不畅。热郁肺伤，防吐血大作。", "9622": "左失血屡发，干呛无痰，面无华，胃呆，脉软弦。乍寒乍热，便通。子母同病。宜金水双调，以防延成本症。", "9623": "左咳嗽激痛胸次，失血止，痰仍厚，大便溏，脉弦。宜肺脾。", "9624": "右咳呛早暮为甚，甚则呕吐，曾经见红，乍寒乍热，脉软弦不思，舌薄白少苔，便溏。体虚病不易奏功。", "9625": "左咳嗽痰多，气急。脉微数。此属痰饮，治在肺脾。", "9626": "左积痰不出，咽痒痛，口干，脉弦。左如大。起于痰饮喘急之后，理之甚非易易。", "9627": "左脾湿蒸痰痰贮于肺，肺气上逆，咳逆气急，倚几不得卧，舌白黄。背恶寒少寐，脉软数，防作喘，毋忽。", "9628": "归身（三钱五分）苏子（三钱五分）旋覆花（三钱五分，绢包）盐半夏（三钱）款冬花（炙，三钱）白芥子（一钱）代赭石（四钱，煅，先煎）冬瓜子（七钱）白杏仁（去尖，四钱）海浮石（四钱）朱茯苓（四钱）玉蝴蝶（二分）生谷芽（五钱，绢包）左病久，阴阳并亏，无脏不虚，近日所最虑者，肾不纳，肺不降，浮阳上越，痰不化、自汗不已，气急不止，自觉胸闷，不能饮食，约已六昼夜，不能合目。病情危急已极，而又大便不实，畏热作躁，脉虚数促，脏真如失所司，理之颇非易易。", "9629": "左阴分不足，气火偏升，头晕易耳鸣，遍体作胀。以脉合证，似乎中有痰浊，痰壅无形之气，气灼有形之痰，夜来作躁多梦，痰黏。标本同病，宜择要先治。", "9630": "左痰湿阻碍气化，清不升、浊不降，清浊不分，致气少下达，脘次如隔。脉状细涩，舌白黄，少寐。病根实深，草木之功有限，图治洵非易易。", "9631": "左脾为生痰之源，肺为贮痰之器，脾湿蒸痰，上输于肺，肺气不降，至咳逆痰多，动即气急。舌薄白，脉濡。病根深远，理之。", "9632": "右积痰贮肺，肺失清肃，咳逆痰多而白，胸闷知饥，不能食，食则胸脘不适，舌白，大便不多，脉软。肺脾同病。肝木乘之，病实。宜择要治。", "9633": "左脾不健运则生痰，痰贮于肺，肺失肃降，咳逆气急，痰白，脉左细弦、右软，舌垢。胃呆，午后心中作躁。病深药浅，不易见功。", "9634": "左痰湿内阻，风寒外乘，中焦运融不宣，胸背彻痛，病属胸痹。音哑脉数而不畅，最防渐转噎膈。", "9635": "左痰饮气急。咳嗽，冬寒尤剧，腹中不舒，大便不实，脉软弦带滑。当宗《金匮》外饮治脾立方。", "9636": "左向患积饮作吐，客冬升塞胸痛，至今形瘦纳少，脉沉细，咳嗽带血。病道深远，不易治。", "9637": "左客冬背寒，今肠鸣濯濯如囊裹浆，小溲少，痰多胸闷，脉细。积饮阻遏中阳，一时不易速效也。", "9638": "左痰湿壅阻气分，气虚升降未能自如，足肿入腿，少腹胀，夜卧气升，脉濡。须速为解散。", "9639": "左（正号老公租）气不化湿湿郁蒸痰，痰气窒滞，腹中不能舒转自如，大便不流利，头蒙，脉软带微弦。三阴同病。当循序理之。", "9640": "右（正号）胃浊不降，积饮作吐，半月来饮食不思，脘腹作痛，痛至神思疲乏。脉软，不寐，寐则惊惕，舌黄。防积久成膈。", "9641": "左痰湿热尚多逗留。舌根苔不清，脉带弦，胃纳呆钝，脘次尚未全舒。拟再流利气机，舒畅中宫，以复升清降浊之常。", "9642": "左痰堵胸次，大便不行，昨宵发热，舌黄，脉数。急宜表里两治。", "9643": "左积痰作迷，迷则神蒙，兼之小溲色深，脉软弦滑数。宜先治痰湿。", "9644": "左脾为生痰之源，肺为贮痰之器。脾不运则生痰，肺不降则咳呛。吐出尽系白沫黏韧之痰，咳甚则头晕，脉弦滑，右耳鸣响失聪。拟宗金匮外饮治脾立方。", "9645": "左积痰积湿，肺脾受病。气急咳逆，吐痰不爽利，脉弦。宜泄肺下气，以防作喘。", "9646": "左痰饮肺脾病也。脾不化湿，由湿蒸痰痰输于肺，肺气不降，致咳逆不已，精微之气尽化为痰。舌垢，口干不多饮，气不致故燥，中无阳故不渴。脉软弦。宜标本两治。", "9647": "左肺虚久喘动肾，胃家痰热上亢，气急痰嘶，神识迷蒙。舌糙燥无津。气不至口燥，中无阳故不渴。脉至数不匀。肢振病深药浅，不易立方。", "9648": "左舌白根腻，右肋下痛，得食作泛，腹鸣小溲少，腰脊酸，脉濡滑。痰湿阻遏升降。防延噎膈。", "9649": "新阳县陈企南大令吾师出诊方痰饮为表邪所遏，肺胃之气不能前降下行，熏蒸旬日痰湿热无一不从火化，咳逆气粗、肌灼神躁，所吐尽是浓黄黏稠之痰，痰者火之标，火甚则逼动肝木，加以心营素亏，浮火益烈，已有抽搦糊语，喘急不寐等状。脉来弦动不调。病属上实下虚正不敌邪，正值攻补两碍，风波叠起之际，暂以徐之才轻可去实之法进之。以观动静，倘能即此应手，最为幸事。", "9650": "翌日再诊：考痰饮一症，《内经》只论饮而未言及痰，至汉张仲师始创论痰饮及悬饮、支饮，并留饮、伏饮之说。治其源，不外内饮治肾，外饮治脾。然病因非一端，病之牵涉亦无一定，就现在所病，昨日几有痰热内火，一齐升越，上扰神明，下激肾真之势，斟酌再三，以清金制木，下痰顺气进之，今脉状较能敛静，舌垢较能化薄，气急较平，形色较正，昨寐颇能宁谧。此皆病之有减无增之佳象也。但气阴已乏，痰火犹重肺降肾纳不充如循常度。惟有养阴分以敛浮游之火，清痰热以复肃降之令，加以息心养神，俾可气顺痰化，早得奏效为幸。", "9651": "再诊：经曰阳气者，烦劳则张，大恚心阳动则浮阳亦动，肝火升则气火亦升，火升则痰来。阳浮则易喘，所以息心涤虑，最为定喘降痰之妙法。刻下痰浓带黑，积饮蒸痰，邪火煅炼而然也。咳多即气急，肺失肃降，上实下虚也。夜来语多错杂，易有神思躁扰之象，阴不涵阳，痰火上扰神明也。脉左弦、右滑数，已无错综之状，舌垢退而底苔尚厚，痰热之重不言而喻。本元虽弱，尚不能骤求峻补。今方拟泄火化痰，为急则治标之法，佐以育阴安神，俾标本不致偏胜。", "9652": "翌日再诊：昨竟安和，夜来稍有烦躁，旋即安寐，又得大便，并无糊语不宁等状。且腹中自然之气已能由渐运动。此痰火解开，心肾交而肝肺升降得和之佳景也。今晨右脉滑数得减，左部尚觉弦疾上驶。上焦所蕴痰热较化，心营虚而肾不摄肝，肝木犹未遽平也。所病本非一朝一夕而得，所虚亦非一脏一经之损，药似治病，尤宜养息以治本。至用药一道，痰热必须清理也。不清则火易动痰、痰易壅气作喘也。阴分不得不养也，不养则水不济火，火辄上浮，反复易如反掌也。气分又不能不利，否则气不运痰，痰浊中阻，其升降之隧道又属可虑之至也。今方拟清上而不涉中下，养气而勿令动火，育阴而不滞痰浊，标本兼治，方有裨益。", "9653": "翌日再诊：病情化险为夷，转机迅速，甚为可喜之至。溯发病之始，风寒伤其外，烦虑困其中，停痰积饮为表邪触之而发因气弱不运而阻肺胃失宣中阳被遏以温药和之正合病机无如本体不充，既不能尽达表邪，复不能全撤病饮，日复一日，所谓痰饮也，风寒也，无一不蒸热化火，上壅肺气，下动肾真，既扰肝风，复乱心神，已致危象毕集，几难著手，斟酌再三，始以舍常求变之法应之，专以急则治标为宗旨，幸而日起有功，然所损已非浅少矣！今诊脉数象较退，弦象较和，已无鼓指上驶之象，而嫌和缓不足，且舌苔发黄，痰热尚多未解，不能不格外谨慎。至神思不振，夜安寐，间有不宁，皆属病后应有之象，循法善调，加以息心调养，自可日臻坦境矣！", "9654": "起翁先生湿痰生于脾，贮于肺，蒸为痰饮，已历四年。今发咳逆痰多，动即如喘，面浮足肿，脉软、尺更弱，右寸关滑数。气虚运迟，下摄不足，延属喘满并剧，未可忽视。", "9655": "翌日再诊：痰饮积久，肺经之病累及肝肾，上气喘急，胸次不宽，脉软弦、按之不调，舌尖中干、边灰余糙。上实下虚，攻补两不易，时正大节，尤为棘手之至。", "9656": "左久病咳嗽，下汲肾水，刻下由肺传脾，腿足肿，大便溏泄，脉细软。气急面浮，杏不思食。病深已甚，理之不易。", "9657": "朱左痰饮由脾传肺，肺病作咳，累及于肾，渐增气急，吐痰厚薄不定，小溲赤，脉濡弦。大便溏，腿足肿，舌垢，口渴不多饮。气不至故燥，中无阳，故不渴，胃纳不开，渐至脏真日竭，最虑腹满增喘。", "9658": "左噎膈重症，且吐血，脉右细、左弦。不易奏效。", "9659": "右气逆上塞，不能食，脉不畅。宜下气疏中。", "9660": "右得食作噎，噎甚则吐，脉弦，右不畅。延防成膈。", "9661": "左膈气之状稍愈，呕吐渐止，食下作痛亦得瘥，惟腹胀不已，肠鸣嘈杂，脉左濡、右滑。宜肝脾两治。", "9662": "右食下咽阻，呕吐腻痰黄水，脉软数。此上焦膈也。近增寒热当治所急。", "9663": "左上焦膈塞稍松，寒热稍愈，脉数，腮肿。当治所急。", "9664": "左食下，气顶作吐，脘肋胀，脉弦。便闭膈症渐著。理之不易。", "9665": "右（正号）两日未吐，胸脘腹痛不已，甚则腹满自汗，不安寐，寐即惊惕，脉细，大便不通。木土相攻，防成膈气。", "9666": "右肝木痰气不平，咽间哽噎，吞不下、吐不出，状如梅核气膈，舌黄，脉不畅。宜平肝涤痰。", "9667": "右肝胃不和，痰饮气机交郁，食下作暖，嗳久闷胀稍松，易泛酸，吐清沫痰，脉软弦。延防膈气，未可因循旁贷。", "9668": "左肝木犯胃，胃浊不降，得食作噎，脘次作痛，易于辄吐，舌白黄，脉细弦。中挟痰捉七，最防迁延成膈。急急通阳泄浊，镇逆疏中。", "9669": "右胃阳式微，肝木乘之，脘次作痛，泛吐酸水，得食辄吐，舌白黄，脉细软。大便旬日一行，少腹胀硬。痰湿气机互郁，中运无权。体乏病深，防成膈气，理之不易。", "9670": "左昨起寒热咽痛，痧子隐约，脉细数，口干。邪大方欲交透，阴分先已枯乏。殊非寻常表症可比，不可泛视。", "9671": "左温邪浊毒，乘劳而发，身热两日，丹痧隐约，面部较显，咽关红肿起腐，舌苔黄垢，不甚渴饮，脉弦数不畅。素来阴气虽薄，一派温邪夹痰浊交黏中焦。急须存阴之中而以透达治之。", "9672": "左病前劳乏不寐，少阴之气先伤，阳明厉毒窃发，身热三日，密布丹痧，咽关肿腐哽痛，脘闷形寒，大便欲泄，舌苔黄，脉弦数。唯素体阴气极薄，温邪厉毒阻中，欲达未达，恐化燥昏陷。", "9673": "又方：顷投剂后，面部痧子较显，身热似衰，但喉关肿势不退，舌苔白垢，脘窒腹鸣，脉弦。表分未解，浊阻中焦。姑拟泄肺化痰，以宣透上焦。", "9674": "又方：表热较衰，痧子渐回，喉关白腐也退，而紫肿依然如昨，舌苔边炎绛，脉弦数。邪恋阴伤，治宜兼顾。", "9675": "右痧子三日，面部见而不多，壮热烦闷，神思躁扰，经事先期而至，舌绛，中苔黄，渴饮干恶，脉弦数。温邪化热伤营，慎防传里。", "9676": "又方：昨宵安隐，今痧子渐回，舌苔转光红，脉弦数。阴薄火炽，变迁易易，未可忽。", "9677": "又方：痧子面部渐回，喉关白腐退而红肿尚甚，觉哽咽，舌绛红刺，脉弦数。经事先期而至，营液邪火消烁，最易热入血室之虑。拟以养营泄热法。", "9678": "又方：痧子已回，身热亦衰，经事先期而行，肝阳升动，头晕耳鸣，神疲不安寐，关节痛，脉弦数，舌绛满刺。咽肿较消，温邪化热伤营，胃阴日损，木火上升，尤易起波。", "9679": "左痧子隐约，喘咳壮热，脉数，便泄。邪厉深重，防厥闭陡变，十分危险，幸勿忽。", "9680": "左厉毒痰热，蒸郁上焦，满喉黑腐，腐肉堆起，并发紫黑斑，脉弦滑数。火势燎原，谨防痰涌喘闭。", "9681": "左烂喉丹痧，风火险证也。痧子甫透，邪已化火，满喉全白，表热脉数。喘厥骤变，易如反掌。", "9682": "左烂喉痧余毒熏蒸，表热口干骨痛，脉不大。非轻症，弗忽。", "9683": "幼痧后邪火郁肺，阵呛气急，脉数。防喘闭发厥。", "9684": "宝宝表热起，七日。热不甚，痧子不绽，寐醒后烦躁，咽关红碎，舌白，口干痰多，脉数。温邪痰热互郁肺气，防音闪骤变。", "9685": "左喉痧时疫，恶候也。当初起之时透不足以达其邪。刻已化火劫阴阴液受损。舌光红无液，唇燥，脉弦数。喉间红肿渐欲起腐，大厦闭、小溲少。邪热厉毒，蟠踞肺胃，即防痧缩变幻，未可泛视。", "9686": "左烂喉风腐甚大退，红肿尚甚，痧子盈体，脉数。防缩，须透达之。", "9687": "左第一方（此方乃徐勤安所立，备录阅之。因后来，吾师接手。）：温热袭郁肺胃，喉关红累密密；右咽起有白点，哽痛，舌黄脉浮数灼热，泛恶胸腹红晕，恐布丹痧。拟方候改。", "9688": "左第二方（此方乃曹南生另所立）：温厉痰湿滞交结，枢机阻塞，胸脘不舒，痧点不透，喉关紫肿，稍有腐点不甚，哽痛口燥，少寐恶心，脉郁数不扬。病方鸱张，未敢泛视。同筱岩世伯议方，并请主裁。", "9689": "左第三方（此方乃马筱岩所立）：喉关紫肿如昨，白点较退，丹痧透而不畅，身热入夜尤甚，干引饮，舌转绛色，脉左遏数、右弦大。有时神情若昧，邪已化热，尚见郁蒸，深恐内犯。方候南兄政定，并请主裁。", "9690": "左第四方（此方乃徐勤安所立）：丹痧夹斑渐见透发，惟热象仍属余炽。舌转光绛起刺，唇腐且肿，脉弦数，且不甚畅。阴虚之体最易劫陷。同勤翁议存阴涤燔法，候主裁。", "9691": "左第六方（此方乃徐勤安所立）（夜开）：喉痧透而渐回，无如邪火燥阴。舌绛碎痛，唇肿起腐，烦躁心慌无绪，痰多带血，目中妄见，脉象极弦极数。恐其痉厥险变。方候筱岩先生政之。", "9692": "左第七方（此方乃徐勤安所立）：时疠烂喉丹痧，今交六日，邪热内炽，扰动肝胆，蒸伤阴气，神躁不寐，心慌自汗，唇焦目赤，舌糜、质紫绛少液，两足酸楚，脉细弦数，痰中带血。肺胃热燔，势属燎原，深恐阴竭厥变之险同筱岩先生议方。", "9693": "左第八方（此方乃沈筱山所立）：丹痧面部已回，胸次依然统片，神识恍惚，微夜不寐，目赤唇燥，手指抽搐。舌绛糙而起刺，脉弦数。阴气大伤，深恐痉厥。同智涵老伯议方。候前诊诸法家正之。", "9694": "左第九方（吾师方也。何以来此迟乎？病家之不早请耳！）：阴涸于下，火炎于上，邪毒痰热又从而扰之。脉左细数、右带滑数，舌红而紫，目不交睫，语不停声，唇焦口烂。火状不一而作，势危矣。勉力图维，以希天佑吉人，候同诊诸高明再酌。", "9695": "左第十方（吾师方）：阴涸火炎，危殆已极。昨日几几沉脱，今得脉状，尚能如昨，症情似有一线生机。然舌津不复，浮火不敛，变幻易如反掌。姑再勉力图之。候筱翁诸高明政之。", "9696": "左第十一方（吾师方）：气阴略立定，邪火又复上炎。脉左细数较滑大，舌干绛密刺，唇燥裂起腐。虽能得寐，神清。而正不敌邪，水不济火，仍防猝起变端，不敢以小效为恃，同筱翁政之诸高明。", "9697": "左第十二方（吾师方）：痧后阴液内乏，火毒不泄，流走阳明络分，两手腕红肿热痛，手指抽掣不定。舌干前半少苔多刺，脉细数。极易节外生枝，不敢以小效为恃。候筱翁政之。", "9698": "左第十三方（此方乃沈筱山所立）：痧后余火燥阴，阳明脉络为风阳震动，手指不时抽搐，唇燥舌干，苔中心渐灰，边绛多刺，脉弦数，关节痛。气营皆伤，余火不能速化，仍恐起波。候智涵老伯正之。", "9699": "左第十四方（吾师方）：虚象渐定，余火复烈，两手红肿大痛，舌干燥，脉细数，大便不行。急急救阴泄火，以防反复变迁。候筱翁政之。", "9700": "左第十五方（此方乃沈筱山所立）：近来虽可得寐安，谷气营似可立定，但余火充斥阳时机关不利，两手腕红肿焮痛。唇燥、舌干，大便秘，脉弦细数。大有变迁。急须存阴泄热。候智涵伯正之。", "9701": "左第十六方（此方乃沈筱山所立）：痧后痰火扰络激动风阳，肝风大动，口目歪斜，手指震动而神识则时清时蒙，肌肤灼热，大便闭，两腕肿，脉细弦数。痉厥易如反掌。勉拟方候智涵老伯正之。", "9702": "右第一方（吾师方）昨起寒热咽痛，痧点隐约，脉细数，口干。邪火方欲外透，阴分先已枯乏。殊非寻常表症可比，不敢泛视。候筱翁政之、", "9703": "右第二方（此方乃沈筱山所立）：温邪厉毒，系劳而发。身热两日，丹痧隐约，面部较显，咽关红肿起腐，舌苔黄垢，不甚渴饮，脉弦滑不畅。素来阴气虽薄，一派温邪挟痰交黏中焦。急须存阴之中而以透达，治之。候智涵老伯政之。", "9704": "右第三方（此方乃沈筱山所立）：病前劳乏不寐，少阴阴气先伤，阳明厉毒窃发，身热三日，密布丹痧，咽关肿腐、哽痛。脘寒，大便欲泄，舌苔垢黄，脉弦数。素来阴气极薄，温邪厉毒中阻，欲达未达，恐化燥昏陷，同智涵老伯议方候正。", "9705": "右第四方（此方乃沈筱山所立）：顷投剂后，面部痧子较显，身热似衰，但喉关肿腐不退。舌苔垢白，脘窒腹鸣，脉弦滑。表分未解，痰浊中阻。拟泄肺化痰，以宣上焦，候智涵老伯正之。", "9706": "右第五方（此方乃沈筱山所立）：热较退，痧子渐回，咽关白腐较退而紫肿依然不退，舌黄边尖绛，脉弦数。邪恋阴伤。治宜兼顾。候智涵老伯正之。", "9707": "右第六方（此方乃沈筱山所立之方）：痧子三日，面部见而不多，壮热烦闷，神恩躁扰，经事先期而至，舌绛中苔黄，渴饮干恶，脉弦数。温邪化热伤营，慎防传里，同智涵老伯议方。候法家政之。", "9708": "右第七方（此方乃沈筱山所立）：痧子面部渐回，咽关白腐退而红肿尚盛，时觉哽咽，舌绛满布红刺，脉弦数。经事先期而行，营阴被邪火消烁，最易热入血室之虑。拟以养阴清营泄热，候智涵老伯正之。", "9709": "右第八方（吾师方）：昨宵安稳，今痧子渐回，舌苔转光红，脉弦数。阴薄火炽，变迁易易，未可忽。候筱翁政之。", "9710": "右第九方（此方乃沈筱山所立之方）：痧子已回，身热亦衰，经事先期而行，肝阳升动则眩晕耳鸣，神疲不安寐，关节痛，脉弦数，舌绛满刺，咽肿较消。温邪化热伤营，胃阴日损，木火上冲，犹易起波，备方。候智涵老伯正之。", "9711": "左表热痧子满布，脉数，舌白尖红，口干稍有咳，烦躁少寐，大便溏薄不多，溲少。温邪时气互郁肺胃，当清经泄化主之，以防痧缩变幻。", "9712": "右向病肝气，尽日脾损，易于便泄作胀，舌白，脉软弦。宜疏和并进。", "9713": "左肝胃气，攻逆作痛，脉濡滑。", "9714": "右肝郁困脾胃，清浊升降失常，胸腹胀满不食，脉濡。宜疏畅二焦。", "9715": "右恶心肌烁，脉弦滑数。治以肝胃。", "9716": "右肝营不足，肾气不摄，肋下撑胀无定，每易胀入腰背，上逆作咳，脉软弦，积深根远，未易速效。", "9717": "右肋瘕攻胀，昼夜无寐，脉弦。心肝不潜，气机上逆。非轻证也，勿忽。", "9718": "左左脉弦，右脉甚滑。阳明积饮，为肝木乘之而当上逆而吐，下气和中涤痰治之。", "9719": "左痰气中堵，肝木上亢，曾经头汗面麻，连及左半体，脉濡细，静养为要。", "9720": "左肝胃不和，积饮作泛，脉软弦。宜导之下行。", "9721": "右少腹胀，胀则气升晕，脉细。治在肝脾。", "9722": "右正宜培补，适有感冒伤风，扰动肝胃，头晕作泛，口苦，心烦，稍有表热，脉左细数、右较大。宜暂停补药。", "9723": "左胃强脾弱，能食不消，腹鸣溏泄，脉软弦。宜疏补并进。", "9724": "右仲春胎育之后，旋即腹痛至今，脘次闷塞，食下作胀，脉软弦不畅。宜疏肝和脾，气营两治。", "9725": "右脾为肝木所乘，中脘痛，不时呕吐，系酸苦黄水为多，脉软弦，小溲短赤。中运失宣，理之不易。", "9726": "右土被木乘，始病肝胃气，近转脘次胀满，小溲不利，脉软弦。宜疏化分利。", "9727": "右脘腹痛渐减，泛恶头晕，寒热甫止，脉软微弦，胸闷便溏，溲热。病道深远，不易旦夕奏功也。", "9728": "右肝痹气滞，得食腹胀，甚则遍体酸痛，头痛寒热，脉不畅。宜宗《内经》木郁达之立方。", "9729": "左肝脾不调，热自内生，腹膨硬，小溲少，舌糙，脉数。渐成疳积，不可轻视。", "9730": "左食下作饱，午后脘胀入腹，便闭，舌黄，脉弦濡。木土克贼，延防腹满未可忽。", "9731": "右干呛较前日稍愈。腹胀瘕逆病稍松，经居将三月，带下不已，腰痛，脉左弦，右软滑。肾虚肝亢。须循法善调。", "9732": "右脉弦，瘕攻作痛，治在肝脾。", "9733": "右阴虚肝亢，化风上升，满头体作痒如虫行，脉弦。再宜泻降主之。", "9734": "左日前肝升晕跌，今仍头晕目花，懊恼，脘腹胀，脉滑数，汗少。宜表里两治。", "9735": "右胸痞腹胀，得食尤甚，头晕，脉数。宜疏肝宣脾两进之。", "9736": "潞党参（三两，秋石三分泡汤炒）陈佛手（一两）朱天冬（一两五钱）上西耆（一两，淡蜜水炙）沉香曲（三两，去心）桑椹子（三两）大熟地（四两，春砂末三分拌炒）归身（一两五钱）宋半夏（三两）制首乌（四两）白芍（一两五钱）陈皮（一两）龟板胶（一两五钱，烊化）甘拘杞（二两，炒）怀山药（三两，炒黄）金毛脊（三两，炙）杜仲（三两，盐水炒）川断（三两，盐水炒）炒香枣仁（三两）如法熬膏。右禀赋不充，气阴俱乏，脉细带软弦，弦者，肝偏亢也，细为阴虚，软则气弱，当求本培养，俾水火相济，气血来复。", "9737": "右肾水亏，血分虚，肝木无所滋养，以致肝气横逆，乘胃则痞阻呕恶，入络则攻注作痛，上升则头晕而眩，下陷则带脉不固，余恙尚多，不外本元虚乏。当蛰藏司令，乘时峻补，以符治病求本之法。", "9738": "右心肝浮于上，脾胃亏于下，气血两乏，无以灌溉经脉，以致手足少力如重滞，恶寒如风吹。此皆本原之内虚，风痰遂乘虚而入阻也。须专力培养其根本，以臻太和。", "9739": "右脚肝气，前日痛甚，今日渐能转松，气火因痛而升，痛定火平，转觉神思疲乏，动作无力，大便未行，手心热，脉弦数。积湿未解，营络未通，气化尚多窒滞，须作速解散，以防痛甚生波。", "9740": "右水亏血少，肝木失养，肝气上亢，心脘作痛，甚则肢冷自汗，脉软弦，欲吐不吐，大便溏。土被木乘，理之非易。", "9741": "右肝气上逆，逆则心脘大痛，甚至肢冷汗淋，脉来弦。防痛剧致厥。", "9742": "右气顶塞咽，腰左酸软，夜来足肿，脉左大于右，当循序养之。", "9743": "右肝升太过，胃降不及，大便坠塞，午后腹胀，夜来热气冲咽，脉弦。上升之气，自汗而甚，非疏泄，并进不可。", "9744": "旋覆花（三钱五分，包）煅瓦楞壳（一两，先煎）陈皮（一钱）泽泻（三钱）代赭石（五钱，煅，先煎）左金丸（一钱，吞服）法半夏（一钱）陈佛手（三钱五分）沉香片（三分）枳壳（一钱）茯苓（四钱）台乌药（三钱五分）绿萼梅（一钱，绢包）左肝胃不和，胀闷不能多食，脉濡。治在中焦。", "9745": "右便闭小溲少，少腹痛，腰痛，脉弦。宜疏通导下，以解寒滞气机。", "9746": "右肝气乘胃，胃脘大痛不已，大便秘，脉细。防痛甚生波，勿忽。", "9747": "右体乏气阻，寒滞交结，少腹痛甚，大便闭，恶心，脉不畅。宜温通疏泄。", "9748": "右近日少腹瘕胀稍松，其气移至中脘，胃不醒，脉软弦。三阴同病，非温通疏泄不可。", "9749": "左肝肺络气失宣，右胁肋作痛，痛甚则纳减，甚则上及咽喉，下及足膝，脉弦。为日已多，未易解散。", "9750": "右脘腹痛，腰脊酸，少寐，呕恶，恶寒，脉细。宜标本两治。", "9751": "右肝木乘胃土，气痛顶心脘，痛及背脊，大便溏，脉细。拟先通阳泄浊，并宜顾及脾肾。", "9752": "右旗人据述痔疾纠缠，便后绕肛易肿，此气阴不足，湿热下陷所致。迩来肝脾不调，脘脐作痛，感冒咳嗽，脉沉滑，右带数。宜择要治之。", "9753": "右客冬经停血崩，肝脾克贼，气营交困，腹块上下冲突，胀时极甚，神疲形寒，脉细数，右微滑。病绪杂出，姑治所急。", "9754": "左气痛入肋，背脊胸次均痛，脉弦而不畅。宜下气疏泄。", "9755": "右脉左弦右滑，气营失调，满腹胀大攻撑无定，神疲形寒，自客春经停血崩以来，三阴俱乏，肝脾互乘，理之不易。", "9756": "前十年产后胀满，因泻得松，久不断根，兹则遍体肿，胃纳少，脉软弦。病根深远，未易速效。", "9757": "左胁痛呃逆，减而未尽，脉弦。宜守前意。", "9758": "左肝气升逆作痛，甚则呕吐，脉弦左软，齿痛。宜平肝泄风。", "9759": "右气急胀满，腰痛，吐沫，脉不畅。拟顺气疏中。", "9760": "右腰背痛，痛及心脘，腹瘕攻逆，脉弦细。治在三阴。", "9761": "右呕吐已，头痛如故，寒从背起，因寒作抽，抽入脘肋，腰痛，咳嗽，脉软弦细。肝肾两虚，伤及阳分。须逐渐调理。", "9762": "右肾亏肝升，发热头痛不已，筋络抽掣，舌黄，脉软。此非轻症，勿忽。", "9763": "左当脐痛，二便不流利，脉弦。宜调和肝脾，疏利二便。", "9764": "右肝气撑胀，腰背酸，咯痰不利，脉弦。宜标本两治。", "9765": "右肝胃不和，痰饮气机交郁，食下作嗳，嗳久闷胀稍松，易于泛酸，吐清痰，脉软弦。严防隔气，未可因循旁贷。", "9766": "右眩晕：阴不涵阳，阳升作晕烘热，阳有余，便是火，火降则畏寒，胸闷纳少，少寐，舌黄，咽干口燥，脉软弦数。带下病杂，宜治所急。", "9767": "脾弱运融不健，大便溏薄，纳少，不时腹痛，脉细。素体不充，须加意慎之。", "9768": "左肝木犯胃，胃浊不降，得食辄吐，舌白黄，脉软弦。宜肝胃两治。", "9769": "右虚汗遍体，少力纳少，食后不运，舌白，脉数。宜标本两治。", "9770": "左胸闷，食后腹中不适，多汗足酸，语言吃力，口甜，脉软弦。宜标本并治。", "9771": "右下摄不足，肝升有余，发时大病之后，至今不能遽，漫动即头旋、目花、耳鸣，舌黄，脉软弦。宜标本两治。", "9772": "右肝木犯胃，胃浊不降，得食作噎，脘次作痛，易于取吐，舌白黄，脉细弦。中挟痰浊，最防迁延成膈，急通阳泄浊，镇逆疏中。", "9773": "右肝木犯胃，胃为气逆，脘次作痛，泛吐涎沫，二便如常，脉弦数，舌白，胃纳不香。此肝胃病也，一时不易奏效。", "9774": "右胃阳式微，肝木乘之，脘次作痛，泛吐酸水，得食辄吐，舌白，脉细软，大便旬日一行，少腹胀硬。痰湿气机互郁，中运无权，体乏病深，防成膈气，理之不易。", "9775": "右下摄不足，肝升有余，每发必从少腹上冲心下，甚则气短，状如奔豚，脉弦。病根深远，理之不易。", "9776": "右肝郁气阻，得食胸次筑紧，脉弦，纳少，内热，舌苔少。宜顺气疏中。", "9777": "管谷臣太太眩晕：上升之气自肝而出，肝为刚脏，必得肾水以濡之，血液以养之，血脱气浮，肝木得以独亢，由是头旋、耳鸣、目花，火升之患，坐则心荡，食后不运，脉细软。宜守前法进步。", "9778": "右肝病积久，下汲肾水，水虚不能养木，木乘中土，脘次筑紧，痰多瘕逆撑胀，脉细软，大便燥结，遍体不适。病根深远，理之不易。", "9779": "右腹痛，大便溏薄不畅，溲少，舌白黄，脉濡。湿郁气阻，肝脾不知。宜疏化法。", "9780": "肝胃不和，中运易滞，气满纳减，不时举发，舌中少液，脉软弦。痰湿易于逗留。宜流利气机，疏畅三焦。", "9781": "右肝气纠缠，近增气急、头浑，心胸痛，食下运化不健，脉濡细。当先治所急。", "9782": "右肝脾不调，腹痛久不止，心中懊恼，脉濡。治在气分。", "9783": "右肝胃不和，脘痛久不止，脉细。宜通阳泄浊，疏运和中。", "9784": "左气机不通，中脘阻塞，脉濡。拟流利气化法。", "9785": "王右（正号朱家角）肝气郁结，心营不足，痰热气火乘之，遂有疑惑恐惧之状，绵延日久，莫可自解，脉左细数，右微滑。急须标本两治。", "9786": "右始病气郁，近增惊恐，脏气大为所困，肉脱面㿠，咳嗽气急，动作无力，脉虚弦。眼灼盛衰不定，七情为病，理之不易。", "9787": "右肝痛不已，痛则发热作躁，大便燥结，脉弦。肝亢肾虚。当标本两治。", "9788": "右肝胃不和，恶心作吐，已历年余，脉濡。宜平肝和胃，以化痰湿。", "9789": "右肝肾气化较前日稍和，少腹、腰间作痛渐减，惟胃气索然，饮食无味，脉弦。肾为胃关，肾病胃困。须标本两治。", "9790": "右脘次结块作胀，甚则上逆作恶，脉弦。当疏肝和胃。", "9791": "右腰痛渐止，夜寐较安，胃口略醒，脉软弦细。宜逐渐培补。", "9792": "右头晕、恶心得止，脘痛、腰痛、少腹痛如昨，溲热，脉弦。拟守前意增损。", "9793": "左肝木乘胃，呕吐，脘闷，兼之感冒寒热，脉来数。宜表里两解。", "9794": "左（正号）膈气之状颇解，呕吐渐止，食下作痛亦稍愈，惟腹胀不已，肠鸣、嘈杂，脉左濡、右滑。宜肝脾两治。", "9795": "左满腹䐜胀，小溲短少，大便闭，脉濡。宜疏化分利。", "9796": "右寒热得解，胃气不来，脘腹不舒，腰微痛，脉濡。治在肝胃。", "9797": "右胀满日松，酸气渐平，头痛、肢痛不净，脉濡。治在肝脾。", "9798": "左畏寒，腹痛，神疲，脉细。表邪郁，不能达，延防转重。", "9799": "左腹右结瘕，作痛攻逆，神疲，脉软弦，右部尤软，两足肿。拟和肝脾，利湿热，以防腹大成膨。", "9800": "右肝木乘脾胃，湿气无从解散，足肿，腹痛，易呕恶，大便不实，脉软。标本同病，理之不易。", "9801": "左脾胃不健，运化迟钝，胸脘不畅，饮食式微，脉尺部弱，余部弦。拟流利气机，疏畅中宫。", "9802": "左日前肠鸣，大便润而不畅，头蒙作抽，时易牙痛，脉濡稍带弦。肝强脾弱，不克运融湿热。宜疏和并进。", "9803": "右便溏稍愈，腿足仍痛，腹痛、呕恶均减，脉软。宜守前法增损。", "9804": "右肝气从心脘痛入少腹，骨节亦痛，脉左大、右软。本体不充，须慎之。", "9805": "左（正号）中运渐醒，气化较畅，胸脘渐能输转，胃纳得稍增，脉状尚带弦。脾升胃降，未能尽如常度，宜即守前意增损之。", "9806": "右脘次痞胀，头晕，不时咽痛，脉滑。宜肝肺胃并治。", "9807": "右（正号）肝气乘胃侮脾，胸脘腹作痛不已，大便坚塞，轰热寐中惊惕，脉左弦不静，右寸部为大。体虚病深，理之不易。", "9808": "右曾患表证，兹腹中宿患瘕作痛，脉微数。拟疏肝和脾主之。", "9809": "右左胁肋下结瘕，顶心脘，食下恶心，脉不畅。宜治肝胃。", "9810": "右胸痛由脘次上逆，近有寒热，脉软，体乏，理之不易。", "9811": "右腹瘕攻逆，面黄，脉濡。治在肝脾。", "9812": "右病后腹痛，右半硬，二便不畅，脉左软右滑。治在肝脾。", "9813": "左食下腹痛，脉软弦。宜疏肝和脾，泄热利湿。", "9814": "右心脘痛，头晕头痛，脉右濡细、左弦。宜流利气机。治在肝脾。", "9815": "右肝脾不和，胃纳久不醒，痛经，脉软弦，少寐。宜疏和并进。", "9816": "右营虚水亏，肝亢内热，脉软弦。病绪杂出，须由渐调养。", "9817": "右肝肾素薄，近日左胁痛，日有三次，脉软弦。肾不摄肝，未易速效。", "9818": "右心悸不得寐，腰痛，胃纳式微，脉软弦。本虚为病，须逐渐调养。", "9819": "右（正号）肝升作晕，脾弱腹胀，当溽暑熏蒸，气分受损，责效尤非易易，舌白垢，气短，脉软弦。本虚标实，非兼顾不可。", "9820": "右气营两虚，火浮湿郁，腰酸，面浮，心悸作闷，目花腹神疲，舌光，脉细软。宜择要调理。", "9821": "右肝脾不调，脘胀，面浮脂肿，脉濡左较大。拟疏和并进。", "9822": "复诊：两耳失聪，鸣响不已，偏右头痛，心荡，鼻塞，脉软弦。肝肺升降不和，病缠日久，延恐积虚成损，积损成怯。", "9823": "左肝胆痰热上亢，神机不灵，语言易顿，夜少熟睡，惊惕，脉弦数。宜镇肝涤痰为治。", "9824": "右脉软弦，胃阳式微，不复用事，食入则脘胀格拒，必吐清涎酸苦腻末，始得爽快。舌白，小溲不利，大便尚通，元气因病所损。拟宗昔贤苦以降之，辛以通之，佐以利痰清膈，勿以燥烈劫阴也。", "9825": "左阴分不足，气火易升，面赤戴阳，心中胆怯不宁，少寐惊惕，脉软弦，舌黄垢。宜镇肝涤痰。", "9826": "右头晕，胸闷，舌白，腹中不适，气机攻撑，心嘈不思食，脉软弦。肝脾同病。拟择要治之。", "9827": "右素体阴虚肝旺，复加畏于服药，致表邪逗留，背寒灼热，头重胸闷，脉小弦数，舌糙白。口干，纳呆，少寐，大便燥结不畅，小溲热，少腹瘕气撑胀。经谓邪之所凑，其气必虚。最虚之处，便是容邪之地，邪不去，虚更甚。拟先去其邪，稍参其本，候高明政之", "9828": "右肝病积久，下吸肾水，水虚无以制木，其气横肆不定，乘胃则泛吐酸水；乘脾则胀，中阻则脘痛。时易恶寒，形浮，心中懊恼，莫可名状，脉软弦。拟标本两治之。同守之世兄议方：", "9829": "左面浮足肿，胸脘阻塞，腹胀，脉濡。宜疏畅中宫，分利水道。", "9830": "右腹大，溲通便泄，得食中阻，口腻，脉濡。防肿甚作喘，殊不可忽。", "9831": "右脱力伤肠，阳气不能运经，肌肤发黄，四肢无力，舌白无华，口苦，脉弦濡，二便俱通。防延腹满，未可忽。", "9832": "右湿郁气阻，腹满足肿，溲少面黄，脉濡。延防喘塞变幻。", "9833": "左脱力不复，足肿神疲，近增胃呆，畏寒溲少，脉软右微弦。拟清理治。", "9834": "左胃气呆木，两足肿，一身无力，神乏，脉软弦。宜先治所急。", "9835": "左满腹胀大，大便燥结艰行，小溲少，舌黄腻，脉细。防涉膨。理之不易。", "9836": "左面浮口腻，动则气急，腿足酸软而肿，伏块上攻作痛，大便带血，溲通，脉弦数少力。病情繁多，不能以虚字括之，中挟湿热，法须兼顾。", "9837": "左浊气在上，则生䐜胀，得食腹中尤甚。大便燥结，不能畅行，溲少，舌黄，脉细。膨状渐著。宜疏利二便，以防迁延增剧。", "9838": "右百节烦疼，满腹肿胀，经居带多，脉状不畅。病绪繁丛，理之不易。", "9839": "左胀满腹大已久，自汗寒热，脉数。近增咽痛，标本同病，理之不易。", "9840": "左表解之后，神疲足肿，不欲食，少寐，大便不畅，脉软数。余溲不禁，须逐渐清理。", "9841": "右脉右软、左微弦，便血止，仍头晕，足肿入大腿，心悸，吃力面浮。以通阳泄浊，涤痰顺气。", "9842": "左（蒋姓）气升得平，腿足肿胀如昨，阳缩，脉濡。拟通阳泄浊，以通痰湿。", "9843": "左（其二）痰湿壅阻气分，气虚升降未能自如，足肿入腿，少腹胀，夜卧气升，脉濡。须速为解散。", "9844": "左黄疸：积湿蒸黄，食下脘阻，恶心，小溲赤短，脉弦。宜疏畅中宫，分利湿热。", "9845": "左面浮足肿，腹大，食下不适，大便溏，脉数。宜醒脾利湿。", "9846": "左黄疸：积湿蒸热，面目发黄，便溏纳少，脉濡右微滑，蒸之左踹红肿，急须内外两治。", "9847": "和尚病起四旬，有咳嗽，转腹满，面浮足肿，瘕胀，脉左不畅。延防成臌。", "9848": "左便泄之后，胸闷神疲，腿足肿甚，脉濡。宜疏运利湿。", "9849": "左胀满腹痛，大便溏，脉濡，不易疏通。", "9850": "小僧咳嗽腹满，面浮足肿，瘕逆，脉细数。肺脾同病。理之棘手。", "9851": "左脉细软，左尺带涩，舌白。连进通阳泄浊，并无火象，仍足肿，茎囊曾肿，延及少腹，气短，动则气急，小溲不流利，子夜以前，易于著枕气急。此中满之由于阴水来者，肺降、肾纳、脾运，各不能如常度。", "9852": "左黄疸：积湿蒸成黄疸，腹满撑胀，脉左细右弦。宜在中焦治之。", "9853": "右黄疸：黄疸胀满，腹胀不能食，脉左细右弦。宜燥湿疏运。", "9854": "左一身肿胀，脉濡。风湿相搏，延防作喘。", "9855": "左腹满腹胀，已五旬，脉濡。行将成臌，弗忽。", "9856": "左诸湿肿满，皆属于脾，脾阳不振，积湿泛滥，满腹胀硬，两腿俱肿，脉细，舌白，夜来溲多。肝脾交困，最防因肿增喘。", "9857": "幼黄疸：脉浮数，目白黄，神倦，舌黄，不思饮，表热时有时无，大便不畅，小溲少。湿热温邪留恋，蒸郁化热，由渐蒸黄，再当表里两治。", "9858": "杨左便血：少腹胀滞，阳痿，腿膝无力，大便后下血，脉软弱无力。内损为病，理之不易。", "9859": "右痢：湿热蒸化为痢，口苦，心中烦热，脉不畅。宜苦泄辛通。", "9860": "左痢：红白痢，腹痛肛坠，脉濡细，不欲食。防转噤口。", "9861": "右痢：下痢转为粪水，脉细数，舌灰黄，口干。正不胜病，变迁可惧。", "9862": "右泄：吐泻六日，败象齐备，今日得势稍减，肢冷得暖，败象气急不平，脉软，舌红干，神气迷蒙，终恐发厥骤变，小效，不足恃也。", "9863": "左便血：便血之后，面浮足肿，畏寒神疲，脉软。气营交困，理之不易。", "9864": "左便血：便血久不止，脉左软、右较大。拟养营化湿。", "9865": "左痢：脉弦数，便痢不止，里急后重，舌白，恶寒咳嗽。脱力伤脾，湿热蟠踞肠胃，不易奏功。", "9866": "左泄：素病脾泄，复多操劳，积虚积损由来已久，自从上年夏令湿阻，秋来患疟，病缠失调，今则气阴两乏，无脏不虚，形肉消瘦，神思疲惫，阴虚生内热，肌灼小溲赤短，阳虚生外寒，形体怯寒，加以气不化湿，湿痰作嗽，气不生津，口燥作渴，渐至肝肾不支，不能起于床。脉细小虚数，舌质红，中苔白。阴竭于下，火浮于上，虚脱一途已近，不能重用补药。汲深绠短，恐不易奏功也。", "9867": "左便血：大肠湿热下注，便后有血，此属远血，脉数，神乏，纳少。当清化分利。", "9868": "左痢：湿滞阻遏气机，大便断下不畅，溲少，舌垢，脉濡。宜疏通积滞，以防成痢疾。", "9869": "左肝脾不调，肠胃湿热，便溏带血，心脘腹均痛，脉右软左弦大，阴薄之体，须速为清理。", "9870": "幼饮食不慎，渐成疳积，脉软。近日少有伤风。法须两顾。", "9871": "右湿热蒸为肠辟，口苦腹胀，脉弦。须速为清解。", "9872": "左寒冬下痢，至今不止，近转血水，肠鸣肛痛，腹瘕攻撑，脉弦右细左反大。脾病肝升，不可再忽。", "9873": "左泄：运化不健，大便溏泄，脉细。治在中焦。", "9874": "左昨起寒热，便泄转为下痢，脉濡而带数。急当表里两解。", "9875": "左寒热，下痢便泄交作，咳嗽痰多，脉弦数。急当表里两解。", "9876": "右痢：溏泄约已匝月，支急腹痛，脉濡。延防转痢。", "9877": "左痢：红白痢七日，表热不净，舌黄垢，脉数。此非轻症，不可忽。", "9878": "左痢：湿热表邪，挟食滞内阻，由便泄转腹痛下痢，有表热，心嘈，脉微数。表里同病，须速为分解。", "9879": "左痢：下痢稍稀，少腹痛。表热不净，脉数舌垢。宜表里两解。", "9880": "左痢：下痢积久，土夺木摇，又增头痛、齿痛，脉弦。病道深远，理之不易。", "9881": "右痢：下痢起糜，脉细，舌黄，呕逆。病深矣，难治。", "9882": "右白痢：病缠两月余，形、色、脉无一不虚，先腰痛，旋即腹痛，痛不可耐，近日下白痢，舌花白腻，口燥。积虚之体，攻补两难。深恐猝然厥变。", "9883": "陈莲舫夫子方痢伤脾肾，积滞已除，遂为溏稀淹缠，昼夜尚有四五行，气坠转气，日来肾不化水，脾失堤防以致泛滥为肿。自足上升，渐及于腹，膀胱失通调之职，三焦失分化之权。脉右弦大，左弦滑。从中再有肝邪内扰，疏泄不灵，舌光，脾肾为病，不能滋补，较为曲折。拟崇土导水，至于春脏，尚须缓商，不能防到喘逐。", "9884": "右泄：乍寒乍热，咳痰，脉沉细而弦，舌白，脐腹痛，大便匀利。通体虚乏已极，加以抑郁燥劳，调理之法，洵非易易，必得扫尽思虑，以助药力所不逮。", "9885": "左脉滑数而软，乍寒发热，久不止，营卫失调，痰热内扰所致。", "9886": "左寒热类疟，有汗形冷，头痛泛呕，舌苔薄白，不渴，脉数。拟以达邪化湿。", "9887": "幼暑湿内阻，发疟旬余，有汗热退不清，腹膨面浮，两足不肿，舌苔黄，脉数，胃纳尚可。小儿症，易虚易实，淹缠非宜。", "9888": "右脉右细小，左微弦，三疟久缠，干咳，经不行。体虚邪恋，未可轻视。", "9889": "左三疟淹缠之症，便溏不畅，又增咳嗽，脉濡。勿忽。", "9890": "右疟邪中郁，气急头晕，胀满口干，表热溲少，脉数，肿甚增喘。", "9891": "右三疟延久，气营失和，脾肝交困，腹起之瘕时痛，脉左软、右微弦，攻胀不已。曾失血病深诸繁，理之不易。", "9892": "左往来寒热，止作不定，延至肝升阳浮，盗汗不得安寐，易作疟，轰热，遗精，脉弦左细。宜从本虚立方。", "9893": "右疟邪不净，日暮神倦火升，脉来濡。宜进调理法。", "9894": "左间疟来四日，转为灼热形寒，胸闷，头胀重，骨痛，脉不畅。邪滞交结，正属转重之时也。", "9895": "左疟久气营俱乏，四肢酸软，背后抽痛，脉软弦。病道深远，理之不易。", "9896": "左午后但热不寒，面㿠浮，大便不行，脉弦数。由来两月，不易奏效。", "9897": "右三疟后鼻衄，口干，脉细数。疟邪入阴分，随肝火上升，宜泄降化热。", "9898": "左疟后体乏，形瘦面浮，纳少神疲，时易腹痛，头鸣，脉数，而不知所戕本原，病不可忽。", "9899": "左三疟愈后营卫不调，易于恶寒出汗，兼之肝气不平，脉软。拟两顾法。", "9900": "左三疟后发面浮肢肿，便通溲少，脉弦濡。营卫失谐，中土受戕，须加意慎之。", "9901": "左往来寒热，头痛，胸闷，脉数。体虚邪恋，未可忽视。", "9902": "左三疟之后骨节酸，脘闷咳嗽，脉濡，寒热。病道深远，不可忽视。", "9903": "左暑湿类疟，汗出不足，胸闷水泻，脉弦数。暑湿凉滞交郁，转重可虑。", "9904": "左遗泄久不愈，肾气不固收。腰为肾之府，久坐觉腰酸，舌尖红刺满布，脉濡不畅，近来脘腹不舒拒按，大便溏薄，溲通龟赤。宜先治所急，以醒机轴。", "9905": "胡无梦而遗，肾家关健不固也，脉弦。宜从阴分立方。", "9906": "沈史家巷心脘痛，时如钻刺，小溲茎痛，并有浊下，脉细，腹胀。宜育阴利湿为法。", "9907": "顾（北坎）气弱阳衰，久病肾关不固，神疲，脘痛，脉濡。病道深远，理之不易。", "9908": "老公祖（金姓）湿热未楚，舌苔黄，脉滞弦数，尚须清化分利。务使肝胆之火与膀胱之湿各得平靖为要。", "9909": "汪（卫道观前）淋浊四旬余，浊色黄白不一，溲如痛，脉弦。阴分已伤，湿热犹阻。当先清化分利。", "9910": "汪（卫道观前）淋痛得瘥，浊下未已，脉细。宜标本两治。", "9911": "孟（大郎桥巷）肾虚湿热下陷，溲逡，有渴，腰酸，脉软数，舌白，头痛。宜清理主之。", "9912": "江（史家巷）水液浑浊，蕴热所致，溲时淋痛，脉细，脐腹痛。治所急。", "9913": "张（肃家巷）小溲淋痛已久，近日腰痛，脉数。防阴日损，不可轻忽。", "9914": "石（养育巷正号）齿痛从右而左，绵延年余，左半头痛麻木，脘不舒，易走泄，脉弦。肝肾病也，非育阴潜阳不可。", "9915": "胡（滚绣坊巷正号）嗽逡之血已止，溲下尚未流利，脉软弦数。阴分虚，湿热重，相火不潜，一时不易速效也。", "9916": "徐（大太平巷）少腹胀，小溲淋漓不畅，腰酸，脉濡。宜疏泄分利。", "9917": "顾（大郎桥巷）不时寒热，遍体烦痛，痰气急，夜来溲多，易遗泄，脉弦。当择要调理。", "9918": "张（乔司空巷）淋浊四月余，并不作痛，浊色带绿，脉软弦。此气不化湿，尤易伤阴也。宜标本两治。", "9919": "吴（常熟正号）心肾不足，肝阳独旺，少安寐易遗泄，惊惕头胀，无不由是而来，脉软。宜柔肝培本，参泄化痰热。", "9920": "孙（黄塘）白浊，湿热病也。两月不净，脉弦。阴分伤关，须加意慎调。", "9921": "施（吴江）素病遗泄，刻下头晕不已，腿膝软弱，脉软弦。法宜柔肝。", "9922": "方（常青巷）肾纳不足，易于下遗，刻下肾病及胃，胃气渐馁，大便不实，脉细软。宜标本两治。", "9923": "道士（只园庵）肝肾不足，易于梦遗，气短耳失聪，脉软弦。此属内损为病，未易奏功。", "9924": "沈（横塘）积虚下后，神疲遗泄，脉左弦、右软，舌质红。宜养阴醒胃。", "9925": "周（常熟）肾阴不足，易于梦遗，腰酸胸闷，胃不开，舌垢，脉软弦。肾为胃关，肾病及胃，胃气渐衰。宜补不足，损有余，循法调理，方能日起有功。", "9926": "钟湿热下走肝肾，营络内痹，睪丸偏大作胀，腰酸，脉微弦。当疏泄厥少。", "9927": "周咳嗽气急渐止，睪囊胀坠，尚甚寒，神疲，脉濡。防餐后生波。", "9928": "程睪丸偏大，时时腰痛而酸，脉细。肝肾不足，湿热兼虚下陷所致。", "9929": "陆向病疝气，近增胁痛，脉软弦。此属肾气不足，肝木失养，寒气遂横肆莫制。宜先急则治标。", "9930": "俞疝气胀大而长，年余不消，脉濡。此湿痰随气下注也。病在厥、少二经，病根深远，不易速解。", "9931": "方腰酸少腹胀，睪丸肿大，胸闷恶心，脉濡。宜疏泄厥少，宣畅痰湿。", "9932": "范经：经阻两月余，腹痛便溏，面无华，腰酸脉软。亏损已甚，理之不易。", "9933": "汪经：少腹宿瘕，近胸升窒，经至腹胀，骨酸，脉软。宜气营两治。", "9934": "沈经：癸水淋漓不断，色紫腰酸，纳减，神思疲乏，脉濡，头痛偏右，晨起面浮而肿，兼之伤风咳嗽。宜择要者先治。", "9935": "林经：痛经，经净痛止，乳块消而不净，脉濡。宜即守前意。", "9936": "顾产：产后热纠缠，气急咳嗽，脉软。宜表里两治。", "9937": "殷经：木土克贼，气不流利，晨间腹胀，癸水不多，脉软滑数。拟气营两治。", "9938": "朱经：经漏初止，腰酸较好，营阴一亏，肝气易发，纳少，少寐，头眩，手足心热，腰腹不舒。脉弦滑。宜标本两治。", "9939": "江经：屡患滑胎，冲任受伤已甚，今经居五月，而脉状尚满。须格外慎养。", "9940": "方胎：妊娠病吐泻，小溲不通，咽痛吐酸，脉浮大。势危殆，勉拟方以希万一。", "9941": "杨产：产虚久不复，曾吐血。兹火升，薄暮微寒而热，脉软。咳嗽渐成蓐损，不易治。", "9942": "邓带：日晡颧右发赤，寐则口舌干燥，脉软数，舌黄，带下不已。治在阴分。", "9943": "殷经：经至不畅，少腹痛甚，脉弦细。寒郁气阻，防因痛生波。", "9944": "又经至不多，胸闷口干，少腹痛，脉弦细。拟气营两治。", "9945": "谢（经崩并见之后）：脉左弦右滑，气营失调，满腹胀大，攻撑无定，神疲形寒。于客春经停血崩以来，三阴俱乏，肝脾互乘，理之不易。", "9946": "刘经：肝肾不足，气营失调，癸水不能如期，所下不多，脉软弦。拟顺气养营主之。", "9947": "蒋经：癸水未畅而止，腹痛恶寒，脉软。宜顺气养营。", "9948": "金经：癸水淋漓旬外，腰以下酸痛，脉软。拟气营两治。", "9949": "胡（正号当郎中巷）经：近日诸恙尚安，唯气营未能和畅，湿热尚有逗留，腿酸作胀，腹不舒。癸水不行，脉状较前为和畅。宜化湿养营两进之。", "9950": "余产：产后营虚肠燥，热自内生，气后下陷，大便不通，时觉支急如胀，脉轻取细软，重按寸关均弦。血不养肝，肝热素旺。今方拟养气营，平肝木，化内热并进之。", "9951": "朱经：经居三月余，药下三日不至，脉左细右滑颇有。", "9952": "方产：产逾四月，瘀带淋漓，色泽不一，脉微数。奇脉不摄，阳伤营热。须逐一调理。", "9953": "施经：经居三月，颇有恶阻见象，而脉状软弱，未能遽以孕断。当先养血顺气。", "9954": "钟经：血分不足，气分不畅，癸水少，腹胀恶心，少纳，腰痛，脉软弦。宜标本两治。", "9955": "金经：癸水不调，始时一月两行，兹则二月末至，脉左沉滑，右软。拟顺气养营。", "9956": "王经：少寐少纳约近两旬，经居两月余，腹痛作胀，脉濡滑。当先治所急。", "9957": "朱胎：脉稍有滑象，口甜腻，恶寒，神疲，恶心少纳，头晕。胃浊痰湿交阻。宜先疏化。", "9958": "陈经：胸闷不能食，食下撑胀，神疲兼有寒热，经漏腹痛，脉濡。气营失调，肝脾交困，不易治。", "9959": "郑经：癸水旬余后至，脉细。营阴内乏，最防崩漏。", "9960": "郁产：客腊产育后左手臂无力，不暖，汗出偏沮，脉弦。此血分亏也。", "9961": "陈经：经色紫滞，带下多，脉濡细。肝肾不充，带脉下陷所致。", "9962": "程经：带下，腰酸，癸水少，神思疲乏，肝气时作，脉软，头痛。宜由渐调理养。", "9963": "张经：经不调，胸闷，胃呆，往来寒热，脉数。延防涉怯。", "9964": "张经：寒热止作不定，胃不醒，经不调，右臂酸痛，脉微数。本原为病，不能旦夕计功也。", "9965": "吴胎：脉滑，左为主，甚须作速安胎药佑之外，尤宜善慎养。", "9966": "朱经：肝脾不和，胃纳久不醒，痛经，脉软弦，少寐。宜疏和兼进。", "9967": "朱产：产经五朝，壮热幸缓，瘀露仍阻，便泄，不寐糊语，舌干黄，数脉。防骤变。", "9968": "殷胎：肝气痛，腰酸，带下红白兼见，脉滑数。胎气不安，殊为可虑。", "9969": "顾经：血分不充，气失流畅，癸水先期，每至小腹作痛，痛甚有作寒之状，脉濡，胃纳减，微带下，腰痛。三阴内乏，累及奇经。拟先增调气养血。", "9970": "宋经：肝脾不调，少寐，少纳，虽有寒热，气血未能流利，经至作痛，脉软弦。宜疏化和中。", "9971": "尹产：冬腊未足月而产，当时尚可支持，而积虚不复，变为咳嗽，纳呆至今，人暮寒热汗出发潮，脉软。延恐积虚成损，积损成劳，药石之至，尚需善为调摄，以助不逮。", "9972": "陈产：产经十九朝，百脉空虚，遍体痛，头晕，胸闷，不思食，脉数，舌根不清，腹中不适，大便溏，少寐。防迁延生波不可忽。", "9973": "右满喉红肿，喉风。两关渐腐，咽燥口干，痰黏脉数。当从肺胃立方。", "9974": "右喉痛止，易少寐，腹胀，甚则上至巅顶，脉虚弦。阴虚肝升。宜循为理之。", "9975": "左烂喉风，肿腐，脉数。风温郁于肺胃，其势方张，弗泛视之。", "9976": "右喉风甫渍两日，已经舌上劫津，脉左数右细。表热壮，邪郁深重，势将风动，重症弗忽。", "9977": "其二：舌津回，喉风红肿，咽底腐，脉数。阴气虚，温毒盛，极易生波，弗以小效为恃。", "9978": "左喉风略松，头痛仍甚，脉数。宜内外两治。", "9979": "右烂喉风，肿腐，脉数，口干，躁不安寐。温邪化热，宜清透泄化。", "9980": "右烂喉风，满腐大退，红肿亦减，舌灰黄较化，脉数，音不扬。痰热壅肺，最防作喘。", "9981": "左烂喉风，肿腐，胸脘隐约有痧点，胸闷嗜卧，脉数不大。病交三日，此系时气重症，防痧隐猝变，万勿轻视。", "9982": "右表热，喉风红肿硬痛，唇燥心惕，脉软弦。宜育阴潜阳，涤痰泄热为法。", "9983": "右烂喉风肿腐，表热，脉数。防音闪变端，妊娠之体，尤不可忽。", "9984": "左脉右为大，咳嗽较稀，并起喉风红肿。内伏温邪，由渐外达。防腐甚音闪，未可忽。", "9985": "左寒热头痛，脉数。烂喉风肿腐。病重势速，千万弗忽。", "9986": "右喉风肿腐，痛不能咽，寒热脉数。温厉重症，防升塞变端。", "9987": "左烂喉风，白腐脱而未净，红肿全瘥，畏寒至甚，脉数。尚防反复，仍弗忽视。", "9988": "右双乳蛾，僵伏尚甚，消净不易，内热，脉数。防反复生波，千万勿忽。", "9989": "左冷热失调，肺胃受之，喉痛红肿，子舌坠，表热脉数，音微闪。当从上焦宣泄，以畅肺气。", "9990": "左缠喉痈，肿甚，肿连上腭，痛楚勺水难咽，形寒脉数。温疠痰浊蒸郁肺胃，其势不轻，防塞逆骤变，重症，无忽。", "9991": "幼表热，喉疳、舌疳、唇疳并起，作痛妨食，两腮下结核，脉数，二便不爽。花毒蕴热交织，当清化法。", "9992": "左表热较和，喉腐渐减，头痛脉数，溲少。其势未定，防音闪。勿忽。", "9993": "左咽关碎腐肿痛，作寒发热，脉数。温邪郁肺胃，不可泛视。", "9994": "右喉风红肿，子舌坠，痰痈肿硬，脉数。风热痰浊，交郁，其势方张，未可忽。", "9995": "幼烂喉风满腐，腐肉堆起，子舌已经腐去，表热不解，脉数。防音哑喘闭，十分险恶之至。", "9996": "左烂喉风，灰腐堆起，脉数不畅。本体虚而温邪重，势不可忽。", "9997": "左喉痈肿色非常，身热脉数，最防气逆痰壅。", "9998": "右咽关痈肿，乍寒乍热，痰多，脉数带滑。其势方张，勿忽。", "9999": "左表热两日，脉数不畅，烂喉风肿腐极甚。温疠深重，不可泛视。"});